--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: accept_battle_challenge(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_battle_challenge(p_challenge_id uuid, p_player_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_challenge battle_challenges%ROWTYPE;
  v_battle_id uuid;
BEGIN
  -- 1️⃣ Lock challenge (chống double accept)
  SELECT *
  INTO v_challenge
  FROM battle_challenges
  WHERE id = p_challenge_id
    AND target_id = p_player_id
    AND status = 'pending'
    AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge not found or not pending';
  END IF;

  -- 2️⃣ Create battle
  INSERT INTO battles (
    battle_type,
    status,
    player1_id,
    player2_id,
    player1_bet_amount,
    player2_bet_amount
  )
  VALUES (
    'challenge',
    'ready',
    v_challenge.challenger_id,
    v_challenge.target_id,
    v_challenge.bet_amount,
    v_challenge.bet_amount
  )
  RETURNING id INTO v_battle_id;

  -- 3️⃣ Update challenge → accepted
  UPDATE battle_challenges
  SET
    status = 'accepted',
    responded_at = now(),
    battle_id = v_battle_id
  WHERE id = p_challenge_id;

  -- 4️⃣ 🔔 Notify challenger (UX)
  INSERT INTO game_notifications (
    player_id,
    type,
    title,
    content,
    payload
  )
  VALUES (
    v_challenge.challenger_id,
    'challenge_accepted',
    'Thách đấu được chấp nhận',
    'Đối thủ đã chấp nhận lời thách đấu của bạn',
    jsonb_build_object(
      'battle_id', v_battle_id,
      'challenge_id', p_challenge_id,
      'opponent_id', v_challenge.target_id
    )
  );

  -- 5️⃣ 🚀 Enter battle – BOTH players (gộp)
  INSERT INTO game_notifications (
    player_id,
    type,
    title,
    content,
    payload
  )
  SELECT
    player_id,
    'challenge_enter_battle',
    'Vào chiến trường',
    content,
    jsonb_build_object(
      'battle_id', v_battle_id,
      'challenge_id', p_challenge_id,
      'opponent_id', opponent_id
    )
  FROM (
    SELECT
      v_challenge.challenger_id AS player_id,
      v_challenge.target_id     AS opponent_id,
      'Chuẩn bị chiến đấu!'     AS content

    UNION ALL

    SELECT
      v_challenge.target_id     AS player_id,
      v_challenge.challenger_id AS opponent_id,
      'Bạn đã chấp nhận thách đấu' AS content
  ) t;

  RETURN v_battle_id;
END;
$$;


ALTER FUNCTION public.accept_battle_challenge(p_challenge_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: accept_friend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_friend(p_player_id uuid, p_friend_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_success boolean;
    v_message text;
BEGIN
    -- Cập nhật trạng thái người gửi
    UPDATE friend_relationships
    SET status = 'accepted', accepted_date = NOW()
    WHERE player_id = p_friend_id
      AND friend_id = p_player_id
      AND status = 'pending';

    IF NOT FOUND THEN
        v_success := false;
        v_message := 'Không tìm thấy lời mời kết bạn đang chờ';
        RETURN jsonb_build_object(
            'success', v_success,
            'message', v_message
        );
    END IF;

    -- Tạo quan hệ ngược (nếu chưa có)
    INSERT INTO friend_relationships (player_id, friend_id, status, accepted_date)
    VALUES (p_player_id, p_friend_id, 'accepted', NOW())
    ON CONFLICT (player_id, friend_id) DO UPDATE
    SET status = 'accepted', accepted_date = NOW();

    v_success := true;
    v_message := 'Đã chấp nhận lời mời kết bạn';
    
    RETURN jsonb_build_object(
        'success', v_success,
        'message', v_message
    );
END;
$$;


ALTER FUNCTION public.accept_friend(p_player_id uuid, p_friend_id uuid) OWNER TO postgres;

--
-- Name: accept_match_popup(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_match_popup(p_player_id uuid, p_target_id uuid, p_battle_type text DEFAULT 'quick_match'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lock matchmaking_locks;
  v_battle_id uuid;
BEGIN
  -- 1️⃣ Kiểm tra lock còn hợp lệ và đúng người
  SELECT *
  INTO v_lock
  FROM matchmaking_locks
  WHERE player_id = p_target_id
    AND locked_by = p_player_id
    AND locked_until > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'accepted', false,
      'reason', 'lock_expired_or_invalid'
    );
  END IF;

  -- 2️⃣ Tạo battle (solo 1vs1)
  INSERT INTO battles (
    battle_type,
    status,
    player1_id,
    player2_id,
    created_at,
    started_at,
    last_turn_at
  )
  VALUES (
    p_battle_type,
    'ready',
    p_player_id,
    p_target_id,
    now(),
    now(),
    now()
  )
  RETURNING id INTO v_battle_id;

  -- 3️⃣ Xóa lock
  DELETE FROM matchmaking_locks
  WHERE player_id = p_target_id;

  -- 4️⃣ Trả kết quả
  RETURN jsonb_build_object(
    'accepted', true,
    'battle_id', v_battle_id
  );
END;
$$;


ALTER FUNCTION public.accept_match_popup(p_player_id uuid, p_target_id uuid, p_battle_type text) OWNER TO postgres;

--
-- Name: add_beauty(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_beauty(p_player_id uuid, p_beauty_id text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_id uuid;
BEGIN
    -- 1️⃣ Kiểm tra beauty tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM beauty_characters
        WHERE id = p_beauty_id
    ) THEN
        RAISE EXCEPTION 'Beauty % does not exist', p_beauty_id;
    END IF;

    -- 2️⃣ Kiểm tra player đã có beauty chưa
    IF EXISTS (
        SELECT 1
        FROM player_beauties
        WHERE player_id = p_player_id
          AND beauty_id = p_beauty_id
    ) THEN
        RAISE EXCEPTION 'Player already owns this beauty';
    END IF;

    -- 3️⃣ Chèn bản sao vào player_beauties
    INSERT INTO player_beauties (
        id,
        player_id,
        beauty_id,
        level,
        experience,
        status,
        current_mission,
        training_end_time,
        acquisition_date,
        last_used,
        mission_success_rate,
        intimacy_points,
        intimacy_level
    )
    SELECT
        gen_random_uuid(),  -- id là uuid
        p_player_id,
        id,                 -- beauty_id là text
        level,
        experience,
        status,
        current_mission,
        training_end_time,
        now(),
        NULL,
        mission_success_rate,
        0,
        1
    FROM beauty_characters
    WHERE id = p_beauty_id
    RETURNING id INTO v_new_id;  -- lưu uuid vào biến

  -- 4️⃣ Insert player activity
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        related_id,
        metadata
    )
    VALUES (
        p_player_id,
        'beauty.unlock',
        v_new_id::text,
        jsonb_build_object(
            'beauty_id', p_beauty_id,
            'player_beauty_id', v_new_id
        )
    );

    -- 4️⃣ RETURN text
    RETURN v_new_id::text;
END;
$$;


ALTER FUNCTION public.add_beauty(p_player_id uuid, p_beauty_id text) OWNER TO postgres;

--
-- Name: add_combat_log(text, text, text, text, uuid, uuid, uuid, integer, integer, jsonb, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_combat_log(p_icon_name text, p_title text, p_color_code text, p_log_type text, p_player_id uuid DEFAULT NULL::uuid, p_battle_id uuid DEFAULT NULL::uuid, p_opponent_id uuid DEFAULT NULL::uuid, p_damage_dealt integer DEFAULT 0, p_damage_received integer DEFAULT 0, p_resources_gained jsonb DEFAULT NULL::jsonb, p_resources_lost jsonb DEFAULT NULL::jsonb, p_territory_changed integer DEFAULT 0, p_victory_points_changed integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_log public.combat_logs%ROWTYPE;
BEGIN
    -- Nếu player_id được truyền vào nhưng không tồn tại
    IF p_player_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.players
           WHERE id = p_player_id
       ) THEN
        RETURN jsonb_build_object(
            'err', 'PLAYER_NOT_FOUND',
            'data', NULL
        );
    END IF;

    INSERT INTO public.combat_logs (
        player_id,
        icon_name,
        title,
        color_code,
        log_type,
        battle_id,
        opponent_id,
        damage_dealt,
        damage_received,
        resources_gained,
        resources_lost,
        territory_changed,
        victory_points_changed
    )
    VALUES (
        p_player_id,
        p_icon_name,
        p_title,
        p_color_code,
        p_log_type,
        p_battle_id,
        p_opponent_id,
        p_damage_dealt,
        p_damage_received,
        p_resources_gained,
        p_resources_lost,
        p_territory_changed,
        p_victory_points_changed
    )
    RETURNING * INTO v_log;

    RETURN jsonb_build_object(
        'err', NULL,
        'data', to_jsonb(v_log)
    );
END;
$$;


ALTER FUNCTION public.add_combat_log(p_icon_name text, p_title text, p_color_code text, p_log_type text, p_player_id uuid, p_battle_id uuid, p_opponent_id uuid, p_damage_dealt integer, p_damage_received integer, p_resources_gained jsonb, p_resources_lost jsonb, p_territory_changed integer, p_victory_points_changed integer) OWNER TO postgres;

--
-- Name: add_exp_to_quest(text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_exp_to_quest(p_quest_id text, p_experience_amount integer, p_description text DEFAULT NULL::text, p_amount integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_quest_exists BOOLEAN;
    v_reward_id UUID;
    v_result JSON;
    v_quest_type TEXT;
    v_quest_status TEXT;
BEGIN
    -- 1. Kiểm tra quest tồn tại
    SELECT EXISTS(
        SELECT 1 FROM public.quests 
        WHERE id = p_quest_id
    ) INTO v_quest_exists;
    
    IF NOT v_quest_exists THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Quest không tồn tại',
            'quest_id', p_quest_id
        );
    END IF;
    
    -- 2. Kiểm tra quest chưa hoàn thành (optional)
    -- SELECT status INTO v_quest_status FROM public.quests WHERE id = p_quest_id;
    -- IF v_quest_status = 'completed' THEN
    --     RETURN json_build_object(
    --         'success', false,
    --         'error', 'Quest đã hoàn thành, không thể thêm EXP',
    --         'quest_id', p_quest_id
    --     );
    -- END IF;
    
    -- 3. Kiểm tra experience_amount hợp lệ
    IF p_experience_amount <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Experience amount phải lớn hơn 0',
            'quest_id', p_quest_id,
            'experience_amount', p_experience_amount
        );
    END IF;
    
    -- 4. Kiểm tra không trùng lặp (optional)
    -- IF EXISTS(
    --     SELECT 1 FROM public.quest_rewards 
    --     WHERE quest_id = p_quest_id 
    --     AND reward_type = 'exp'
    --     AND item_id IS NULL
    -- ) THEN
    --     RETURN json_build_object(
    --         'success', false,
    --         'error', 'Quest đã có phần thưởng EXP',
    --         'quest_id', p_quest_id
    --     );
    -- END IF;
    
    -- 5. Insert EXP reward
    INSERT INTO public.quest_rewards (
        quest_id,
        item_id,
        amount,
        reward_type,
        currency_type,
        experience_amount,
        description,
        created_at
    ) VALUES (
        p_quest_id,
        NULL,  -- item_id = NULL cho EXP
        p_amount,
        'exp',  -- reward_type = 'exp'
        NULL,   -- currency_type = NULL
        p_experience_amount,
        COALESCE(p_description, 'EXP reward'),
        NOW()
    )
    RETURNING id INTO v_reward_id;
    
    -- 6. Return kết quả thành công
    RETURN json_build_object(
        'success', true,
        'message', 'Thêm EXP thành công',
        'reward_id', v_reward_id,
        'quest_id', p_quest_id,
        'experience_amount', p_experience_amount,
        'description', COALESCE(p_description, 'EXP reward')
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', SQLERRM,
            'detail', SQLSTATE,
            'quest_id', p_quest_id
        );
END;
$$;


ALTER FUNCTION public.add_exp_to_quest(p_quest_id text, p_experience_amount integer, p_description text, p_amount integer) OWNER TO postgres;

--
-- Name: add_general_skill(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_general_skill(p_player_id uuid, p_general_id text, p_general_skill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_general public.player_generals%ROWTYPE;
    v_skill public.general_skills%ROWTYPE;
    v_result public.player_general_skills%ROWTYPE;
BEGIN
    -- 1. Tìm player_general của player
    SELECT *
    INTO v_player_general
    FROM public.player_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Người chơi chưa sở hữu vị tướng này';
    END IF;

    -- 2. Kiểm tra skill thuộc đúng general
    SELECT gs.*
    INTO v_skill
    FROM public.general_skills gs
    WHERE gs.id = p_general_skill_id
      AND gs.general_id = p_general_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Kỹ năng không thuộc vị tướng này';
    END IF;

    -- 3. Kiểm tra skill đã được thêm chưa
    IF EXISTS (
        SELECT 1
        FROM public.player_general_skills
        WHERE player_general_id = v_player_general.id
          AND general_skill_id = p_general_skill_id
    ) THEN
        RAISE EXCEPTION 'Vị tướng đã có kỹ năng này';
    END IF;

    -- 4. Thêm skill
    INSERT INTO public.player_general_skills (
        player_general_id,
        general_skill_id,
        level,
        max_level,
        is_unlocked
    )
    VALUES (
        v_player_general.id,
        p_general_skill_id,
        v_skill.level,
        v_skill.max_level,
        true
    )
    RETURNING *
    INTO v_result;

    -- 5. Trả kết quả
    RETURN jsonb_build_object(
        'id', v_result.id,
        'playerGeneralId', v_result.player_general_id,
        'generalSkillId', v_result.general_skill_id,
        'level', v_result.level,
        'maxLevel', v_result.max_level,
        'isUnlocked', v_result.is_unlocked,
        'lastUsed', v_result.last_used
    );
END;
$$;


ALTER FUNCTION public.add_general_skill(p_player_id uuid, p_general_id text, p_general_skill_id uuid) OWNER TO postgres;

--
-- Name: add_gift_to_player(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_gift_to_player(p_player_id uuid, p_gift_id text, p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Kiểm tra gift có tồn tại trong gift_beauty
    IF NOT EXISTS (SELECT 1 FROM gift_beauty WHERE id = p_gift_id) THEN
        RAISE EXCEPTION 'Gift % does not exist in gift_beauty', p_gift_id;
    END IF;

    -- Thêm vào inventory hoặc cộng dồn nếu đã có
    INSERT INTO player_gift_beauty (player_id, gift_id, amount)
    VALUES (p_player_id, p_gift_id, p_amount)
    ON CONFLICT (player_id, gift_id)
    DO UPDATE SET amount = player_gift_beauty.amount + EXCLUDED.amount;

    -- Lấy thông tin gift vừa cập nhật và trả về JSON
    SELECT jsonb_build_object(
        'gift_id', pgb.gift_id,
        'gift_name', gb.name,
        'amount', pgb.amount
    )
    INTO v_result
    FROM player_gift_beauty pgb
    JOIN gift_beauty gb ON gb.id = pgb.gift_id
    WHERE pgb.player_id = p_player_id
      AND pgb.gift_id = p_gift_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.add_gift_to_player(p_player_id uuid, p_gift_id text, p_amount integer) OWNER TO postgres;

--
-- Name: add_gold_by_player_region_safe(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_gold_by_player_region_safe(p_player_id uuid, p_region_id text, p_amount integer) RETURNS TABLE(gold integer, max_gold integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
BEGIN
    -- 1️⃣ Validate input
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be positive: %', p_amount;
    END IF;

    -- 2️⃣ Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % does not own region %', p_player_id, p_region_id;
    END IF;

    -- 3️⃣ UPSERT gold: insert nếu chưa có, update nếu đã có
    INSERT INTO region_resources (
        player_region_id,
        resource,
        amount,
        max_amount,
        updated_at
    )
    VALUES (
        v_player_region_id,
        'gold',
        p_amount,
        10000,  -- default max_gold
        now()
    )
    ON CONFLICT (player_region_id, resource)
    DO UPDATE
    SET
        amount = LEAST(region_resources.amount + EXCLUDED.amount, region_resources.max_amount),
        updated_at = now()
    RETURNING amount, max_amount
    INTO gold, max_gold;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.add_gold_by_player_region_safe(p_player_id uuid, p_region_id text, p_amount integer) OWNER TO postgres;

--
-- Name: add_hero(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_hero(p_player_id uuid, p_general_id text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id uuid := gen_random_uuid();
BEGIN
    -- 1️⃣ Kiểm tra general tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM generals
        WHERE id = p_general_id
    ) THEN
        RAISE EXCEPTION 'General % does not exist', p_general_id;
    END IF;

    -- 2️⃣ Kiểm tra player đã có hero này chưa
    IF EXISTS (
        SELECT 1
        FROM player_generals
        WHERE player_id = p_player_id
          AND general_id = p_general_id
    ) THEN
        RAISE EXCEPTION 'Player already owns this hero';
    END IF;

    -- 3️⃣ Chèn bản sao hero vào player_generals
    INSERT INTO player_generals (
        id,
        player_id,
        general_id,
        "level",
        experience,
        star_level,
        max_star_level,
        awakening_level,
        bond_level,
        current_attack,
        current_defense,
        current_health,
        current_speed,
        current_intelligence,
        current_leadership,
        favorite,
        obtained_date,
        last_used,
        battle_count,
        win_rate
    )
    SELECT
        v_id,
        p_player_id,
        id,               -- id TEXT từ generals
        level,
        experience,
        star_level,
        max_star_level,
        awakening_level,
        bond_level,
        current_attack,
        current_defense,
        current_health,
        current_speed,
        current_intelligence,
        current_leadership,
        favorite,
        now(),
        NULL,
        battle_count,
        win_rate
    FROM generals
    WHERE id = p_general_id;
	  -- 4️⃣ Insert player activity
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        related_id,
        metadata
    )
    VALUES (
        p_player_id,
        'hero.recruit',
        v_id::text,
        jsonb_build_object(
            'general_id', p_general_id,
            'player_general_id', v_id
        )
    );
    -- 4️⃣ Trả về id của player_generals
    RETURN v_id;
END;
$$;


ALTER FUNCTION public.add_hero(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: add_intimacy_point_single(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_intimacy_point_single(p_player_id uuid, p_beauty_id text, p_points integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.player_beauties
    SET 
        intimacy_points = intimacy_points + p_points,
        intimacy_level = 1 + FLOOR((intimacy_points + p_points)::numeric / 100)
    WHERE player_id = p_player_id
      AND beauty_id = p_beauty_id;
END;
$$;


