-- Name: add_item(uuid, character varying, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_item(p_player_id uuid, p_item_id character varying, p_quantity integer DEFAULT 1, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO player_items (
    player_id,
    item_id,
    quantity,
    metadata
  )
  VALUES (
    p_player_id,
    p_item_id,
    p_quantity,
    p_metadata
  )
  ON CONFLICT (player_id, item_id)
  DO UPDATE SET
    quantity = player_items.quantity + EXCLUDED.quantity;

  -- Trả về success
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Item added successfully'
  );

EXCEPTION
  WHEN others THEN
    -- Trả về error
    RETURN jsonb_build_object(
      'success', false,
      'message', SQLERRM
    );
END;
$$;


