--
-- Name: add_loot_box(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_loot_box(p_player_id uuid, p_loot_box_id text, p_amount integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id uuid := gen_random_uuid();
    v_result uuid;
BEGIN
    BEGIN
        INSERT INTO player_loot_boxes (
            id,
            player_id,
            loot_box_id,
            amount,
            total_opens,
            current_streak,
            pity_counter,
            created_at,
            updated_at
        )
        VALUES (
            v_id,
            p_player_id,
            p_loot_box_id,
            p_amount,
            0,
            0,
            0,
            now(),
            now()
        )
        ON CONFLICT (player_id, loot_box_id)
        DO UPDATE SET
            amount = player_loot_boxes.amount + EXCLUDED.amount,
            updated_at = now();

        -- Lấy id sau khi insert hoặc update
        SELECT id INTO v_result 
        FROM player_loot_boxes 
        WHERE player_id = p_player_id AND loot_box_id = p_loot_box_id;

        -- Nếu không có id nào, ném lỗi
        IF v_result IS NULL THEN
            RAISE EXCEPTION 'Cannot insert or update loot box for player % and loot_box %', p_player_id, p_loot_box_id;
        END IF;

        RETURN v_result;

    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Error adding loot box for player % and loot_box %: %', p_player_id, p_loot_box_id, SQLERRM;
    END;
END;
$$;


ALTER FUNCTION public.add_loot_box(p_player_id uuid, p_loot_box_id text, p_amount integer) OWNER TO postgres;

--
-- Name: add_new_friend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_new_friend(p_player_id uuid, p_friend_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sender_name text;
BEGIN
  -- Không cho tự gửi cho chính mình
  IF p_player_id = p_friend_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Không thể gửi lời mời kết bạn với chính bạn'
    );
  END IF;

  -- Kiểm tra đã tồn tại quan hệ
  IF EXISTS (
    SELECT 1
    FROM public.friend_relationships
    WHERE player_id = p_player_id
      AND friend_id = p_friend_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Lời mời kết bạn đã tồn tại'
    );
  END IF;

  -- Tạo request
  INSERT INTO public.friend_relationships (
    player_id,
    friend_id,
    status
  )
  VALUES (
    p_player_id,
    p_friend_id,
    'pending'
  );

  -- Log activity friend.add
  INSERT INTO public.player_activities (
    player_id,
    activity_type,
    related_id,
    metadata
  )
  VALUES (
    p_player_id,
    'friend.add',
    p_friend_id::text,
    jsonb_build_object(
      'friend_id', p_friend_id
    )
  );

  -- Lấy tên người gửi
  SELECT name
  INTO v_sender_name
  FROM public.players
  WHERE id = p_player_id;

  -- Gửi notification cho người nhận
  PERFORM public.send_notification(
    p_friend_id,
    'friend_request',
    'Lời mời kết bạn mới',
    v_sender_name || ' đã gửi cho bạn lời mời kết bạn.',
    jsonb_build_object(
      'sender_id', p_player_id,
      'sender_name', v_sender_name
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Đã gửi lời mời kết bạn'
  );
END;
$$;


ALTER FUNCTION public.add_new_friend(p_player_id uuid, p_friend_id uuid) OWNER TO postgres;

--
-- Name: add_player_currency(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_player_currency(p_player_id uuid, p_currency_type text, p_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_amount numeric;
BEGIN
    -- Lấy số dư hiện tại
    SELECT amount INTO current_amount
    FROM public.player_wallets
    WHERE player_id = p_player_id AND currency_type = p_currency_type
    FOR UPDATE;

    -- Nếu chưa có record → insert
    IF NOT FOUND THEN
        INSERT INTO public.player_wallets(player_id, currency_type, amount)
        VALUES (p_player_id, p_currency_type, p_amount);
        RETURN p_amount;
    END IF;

    -- Cộng tiền
    UPDATE public.player_wallets
    SET amount = amount + p_amount,
        last_updated = CURRENT_TIMESTAMP
    WHERE player_id = p_player_id AND currency_type = p_currency_type;

    RETURN current_amount + p_amount;
END;
$$;


ALTER FUNCTION public.add_player_currency(p_player_id uuid, p_currency_type text, p_amount numeric) OWNER TO postgres;

--
-- Name: add_region_slot_by_player(uuid, text, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_region_slot_by_player(p_player_id uuid, p_region_id text, p_slot_index integer, p_allowed_building_type character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
    v_slot_id uuid;
    v_cost record;
BEGIN

    -- Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM public.player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
    LIMIT 1;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION
            'Region % not found for player %',
            p_region_id,
            p_player_id;
    END IF;


    -- Kiểm tra và trừ chi phí
    FOR v_cost IN
        SELECT
            cost_type,
            cost_amount
        FROM public.region_expansion_costs
        WHERE region_id = p_region_id
          AND slot_index = p_slot_index
    LOOP

        -- Kiểm tra đủ tài nguyên
        PERFORM 1
        FROM public.region_resources
        WHERE player_region_id = v_player_region_id
          AND resource_code = v_cost.cost_type
          AND amount >= v_cost.cost_amount
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Not enough % to unlock slot %',
                v_cost.cost_type,
                p_slot_index;
        END IF;

    END LOOP;


    -- Trừ chi phí
    FOR v_cost IN
        SELECT
            cost_type,
            cost_amount
        FROM public.region_expansion_costs
        WHERE region_id = p_region_id
          AND slot_index = p_slot_index
    LOOP

        UPDATE public.region_resources
        SET
            amount = amount - v_cost.cost_amount,
            updated_at = now()
        WHERE player_region_id = v_player_region_id
          AND resource_code = v_cost.cost_type;

    END LOOP;


    -- Tạo slot
    INSERT INTO public.region_slots (
        player_region_id,
        region_id,
        allowed_building_type
    )
    VALUES (
        v_player_region_id,
        p_region_id,
        p_allowed_building_type
    )
    RETURNING id INTO v_slot_id;


    RETURN v_slot_id;

END;
$$;


ALTER FUNCTION public.add_region_slot_by_player(p_player_id uuid, p_region_id text, p_slot_index integer, p_allowed_building_type character varying) OWNER TO postgres;

--
-- Name: add_region_troops(uuid, text, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_region_troops(p_player_id uuid, p_region_id text, p_unit_id character varying, p_quantity integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_total int;
BEGIN

-- Lấy giới hạn tối đa của unit
SELECT quantity
INTO v_max_total
FROM units
WHERE id = p_unit_id;

-- Insert hoặc cộng quân nếu đã tồn tại
INSERT INTO region_troops (
    region_id,
    player_id,
    unit_type,
    quantity,
    total_trained,
    last_trained_at
)
VALUES (
    p_region_id,
    p_player_id,
    p_unit_id,
    LEAST(p_quantity, v_max_total),
    p_quantity,
    now()
)

ON CONFLICT (region_id, player_id, unit_type)

DO UPDATE SET
    quantity = LEAST(region_troops.quantity + EXCLUDED.quantity, v_max_total),
    total_trained = region_troops.total_trained + EXCLUDED.total_trained,
    last_trained_at = now();

RETURN 'Đã cộng quân';
END;
$$;


ALTER FUNCTION public.add_region_troops(p_player_id uuid, p_region_id text, p_unit_id character varying, p_quantity integer) OWNER TO postgres;

--
-- Name: add_resource_by_player_region(uuid, text, public.resource_type, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource public.resource_type, p_amount integer, p_is_collect boolean DEFAULT true) RETURNS TABLE(out_resource public.resource_type, out_amount integer, out_max_amount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
BEGIN
    -- 1️⃣ Validate input
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be positive: %', p_amount;
    END IF;

    -- 2️⃣ Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % does not own region %', p_player_id, p_region_id;
    END IF;

    -- 3️⃣ UPSERT resource
    INSERT INTO region_resources (
        player_region_id,
        resource,
        amount,
        max_amount,
        updated_at,
        last_collected_at
    )
    VALUES (
        v_player_region_id,
        p_resource,
        p_amount,
        CASE
            WHEN p_resource = 'gold' THEN 10000
            WHEN p_resource = 'wood' THEN 8000
            WHEN p_resource = 'food' THEN 12000
            WHEN p_resource = 'troops' THEN 0
            ELSE 0
        END,
        now(),
        CASE WHEN p_is_collect THEN now() ELSE NULL END
    )
    ON CONFLICT (player_region_id, resource)
    DO UPDATE
    SET
        amount = LEAST(region_resources.amount + EXCLUDED.amount, region_resources.max_amount),
        updated_at = now(),
        last_collected_at = CASE WHEN p_is_collect THEN now() ELSE region_resources.last_collected_at END
    RETURNING resource AS out_resource,
              amount AS out_amount,
              max_amount AS out_max_amount
    INTO out_resource, out_amount, out_max_amount;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.add_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource public.resource_type, p_amount integer, p_is_collect boolean) OWNER TO postgres;

--
-- Name: analyze_region_troop_power(character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.analyze_region_troop_power(p_region_id character varying, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_overall JSONB;
    v_by_unit_type JSONB;
    v_strengths_weaknesses JSONB;
    v_total_quantity BIGINT;
    v_total_attack BIGINT;
    v_total_defense BIGINT;
    v_total_hp BIGINT;
    v_strongest_type TEXT;
    v_weakest_type TEXT;
    v_most_numerous TEXT;
    v_best_attack TEXT;
    v_best_defense TEXT;
BEGIN
    -- Get overall totals first
    SELECT 
        COALESCE(SUM(rt.quantity), 0),
        COALESCE(SUM(rt.quantity * u.atk), 0),
        COALESCE(SUM(rt.quantity * u.def), 0),
        COALESCE(SUM(rt.quantity * u.max_hp), 0)
    INTO v_total_quantity, v_total_attack, v_total_defense, v_total_hp
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id;
    
    -- Build overall stats
    v_overall := JSONB_BUILD_OBJECT(
        'total_troops', v_total_quantity,
        'total_attack_power', v_total_attack,
        'total_defense_power', v_total_defense,
        'total_hit_points', v_total_hp,
        'attack_per_troop', CASE 
            WHEN v_total_quantity > 0 THEN ROUND(v_total_attack::DECIMAL / v_total_quantity, 2)
            ELSE 0
        END,
        'defense_per_troop', CASE 
            WHEN v_total_quantity > 0 THEN ROUND(v_total_defense::DECIMAL / v_total_quantity, 2)
            ELSE 0
        END,
        'hp_per_troop', CASE 
            WHEN v_total_quantity > 0 THEN ROUND(v_total_hp::DECIMAL / v_total_quantity, 2)
            ELSE 0
        END
    );
    
    -- Get stats by unit type
    SELECT COALESCE(
        JSONB_OBJECT_AGG(
            unit_type,
            unit_stats
        ),
        '{}'::JSONB
    ) INTO v_by_unit_type
    FROM (
        SELECT 
            u.type::TEXT AS unit_type, -- Cast enum to text
            JSONB_BUILD_OBJECT(
                'unit_count', SUM(rt.quantity),
                'attack_power', SUM(rt.quantity * u.atk),
                'defense_power', SUM(rt.quantity * u.def),
                'hit_points', SUM(rt.quantity * u.max_hp),
                'units', COALESCE(
                    JSONB_AGG(
                        JSONB_BUILD_OBJECT(
                            'name', u.name,
                            'quantity', rt.quantity,
                            'individual_attack', u.atk,
                            'individual_defense', u.def,
                            'individual_hp', u.max_hp
                        ) ORDER BY rt.quantity DESC
                    ),
                    '[]'::JSONB
                )
            ) AS unit_stats
        FROM public.region_troops rt
        JOIN public.units u ON rt.unit_type = u.id
        WHERE rt.region_id = p_region_id 
            AND rt.player_id = p_player_id
        GROUP BY u.type
    ) AS type_stats;
    
    -- Get rankings using separate queries
    -- Strongest unit type (by attack power)
    SELECT COALESCE(u.type::TEXT, 'N/A') INTO v_strongest_type
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
    GROUP BY u.type
    ORDER BY SUM(rt.quantity * u.atk) DESC
    LIMIT 1;
    
    -- Weakest unit type (by attack power)
    SELECT COALESCE(u.type::TEXT, 'N/A') INTO v_weakest_type
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
    GROUP BY u.type
    ORDER BY SUM(rt.quantity * u.atk) ASC
    LIMIT 1;
    
    -- Most numerous unit
    SELECT COALESCE(u.name, 'N/A') INTO v_most_numerous
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
    ORDER BY rt.quantity DESC
    LIMIT 1;
    
    -- Best attack unit
    SELECT COALESCE(u.name, 'N/A') INTO v_best_attack
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
    ORDER BY u.atk DESC, rt.quantity DESC
    LIMIT 1;
    
    -- Best defense unit
    SELECT COALESCE(u.name, 'N/A') INTO v_best_defense
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
    ORDER BY u.def DESC, rt.quantity DESC
    LIMIT 1;
    
    -- Build strengths and weaknesses object
    v_strengths_weaknesses := JSONB_BUILD_OBJECT(
        'strongest_unit_type', COALESCE(v_strongest_type, 'N/A'),
        'weakest_unit_type', COALESCE(v_weakest_type, 'N/A'),
        'most_numerous_unit', COALESCE(v_most_numerous, 'N/A'),
        'best_attack_unit', COALESCE(v_best_attack, 'N/A'),
        'best_defense_unit', COALESCE(v_best_defense, 'N/A')
    );
    
    -- Return combined result
    RETURN JSONB_BUILD_OBJECT(
        'overall', v_overall,
        'by_unit_type', COALESCE(v_by_unit_type, '{}'::JSONB),
        'strengths_weaknesses', COALESCE(v_strengths_weaknesses, '{}'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.analyze_region_troop_power(p_region_id character varying, p_player_id uuid) OWNER TO postgres;

--
-- Name: approve_join_request(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_join_request(p_leader_id uuid, p_request_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alliance_id uuid;
    v_player_id uuid;
    v_is_leader boolean;
BEGIN
    SELECT alliance_id, player_id
    INTO v_alliance_id, v_player_id
    FROM alliance_join_requests
    WHERE id = p_request_id;

    -- check leader
    SELECT (leader = p_leader_id)
    INTO v_is_leader
    FROM alliances
    WHERE id = v_alliance_id;

    IF NOT v_is_leader THEN
        RETURN json_build_object('success', false, 'error', 'No permission');
    END IF;

    -- add member
    INSERT INTO alliance_members (alliance_id, player_id)
    VALUES (v_alliance_id, v_player_id);

    -- update request
    UPDATE alliance_join_requests
    SET status = 'approved'
    WHERE id = p_request_id;

    RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION public.approve_join_request(p_leader_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: assign_general_to_region(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_general_to_region(p_player_id uuid, p_region_id text, p_general_id text, p_battle_role text DEFAULT 'defense'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 1️⃣ Check player sở hữu region
    IF NOT EXISTS (
        SELECT 1
        FROM player_regions
        WHERE player_id = p_player_id
          AND region_id = p_region_id
          AND is_active = true
    ) THEN
        RAISE EXCEPTION 'Player does not own this region';
    END IF;

    -- 2️⃣ Check player sở hữu general
    IF NOT EXISTS (
        SELECT 1
        FROM player_generals
        WHERE player_id = p_player_id
          AND general_id = p_general_id
    ) THEN
        RAISE EXCEPTION 'Player does not own this general';
    END IF;

    -- 3️⃣ Xóa hero này khỏi region khác (nếu có)
    DELETE FROM region_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id;

    -- 4️⃣ Xóa hero khác đang giữ cùng role (toàn map)
    DELETE FROM region_generals
    WHERE player_id = p_player_id
      AND battle_role = p_battle_role
      AND is_active = true;

    -- 5️⃣ Insert hoặc replace hero tại region này
    INSERT INTO region_generals (
        region_id,
        player_id,
        general_id,
        battle_role,
        is_active,
        stationed_at
    )
    VALUES (
        p_region_id,
        p_player_id,
        p_general_id,
        p_battle_role,
        true,
        now()
    )
    ON CONFLICT (player_id, region_id)
    DO UPDATE SET
        general_id   = EXCLUDED.general_id,
        battle_role  = EXCLUDED.battle_role,
        is_active    = true,
        stationed_at = now(),
        updated_at   = now();

END;
$$;


ALTER FUNCTION public.assign_general_to_region(p_player_id uuid, p_region_id text, p_general_id text, p_battle_role text) OWNER TO postgres;

--
-- Name: block_friend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.block_friend(p_player_id uuid, p_friend_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Không được block chính mình
    IF p_player_id = p_friend_id THEN
        RETURN 'Cannot block yourself';
    END IF;

    -- Cập nhật trạng thái nếu quan hệ đã tồn tại
    INSERT INTO friend_relationships (player_id, friend_id, status)
    VALUES (p_player_id, p_friend_id, 'blocked')
    ON CONFLICT (player_id, friend_id) DO UPDATE
    SET status = 'blocked', accepted_date = NULL;

    RETURN 'Player blocked';
END;
$$;


ALTER FUNCTION public.block_friend(p_player_id uuid, p_friend_id uuid) OWNER TO postgres;

--
-- Name: build_building(uuid, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_building(p_player_id uuid, p_region_id text, p_building_type character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region RECORD;
    v_max_count INT;
    v_current_count INT;
BEGIN
    -- 1. Kiểm tra player sở hữu region
    SELECT * INTO v_region
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id;

    IF NOT FOUND THEN
        RETURN 'Player does not own this region';
    END IF;

    -- 2. Kiểm tra region cho phép building
    SELECT max_count INTO v_max_count
    FROM region_buildings
    WHERE region_id = p_region_id
      AND building_type = p_building_type;

    IF NOT FOUND THEN
        RETURN 'This building type is not allowed in this region';
    END IF;

    -- 3. Kiểm tra development_level
    IF v_region.development_level < (
        SELECT min_region_level 
        FROM region_buildings 
        WHERE region_id = p_region_id AND building_type = p_building_type
    ) THEN
        RETURN 'Region development level too low';
    END IF;

    -- 4. Kiểm tra số lượng hiện tại
    SELECT COUNT(*) INTO v_current_count
    FROM player_region_buildings
    WHERE player_region_id = v_region.id
      AND building_type = p_building_type;

    IF v_current_count >= v_max_count THEN
        RETURN 'Reached max number of this building type';
    END IF;

    -- 5. Insert building mới
    INSERT INTO player_region_buildings(player_region_id, building_type)
    VALUES (v_region.id, p_building_type);

    RETURN 'Building constructed successfully';
END;
$$;


ALTER FUNCTION public.build_building(p_player_id uuid, p_region_id text, p_building_type character varying) OWNER TO postgres;

--
-- Name: build_building_strict(uuid, text, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_building_strict(p_player_id uuid, p_region_id text, p_region_slot_id uuid, p_building_type character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_slot record;
    v_player_region record;
    v_rule record;
    v_current_count int;
    v_new_building_id uuid;
    v_cost record;
BEGIN
    -- 1. Lock slot
    SELECT *
    INTO v_slot
    FROM region_slots
    WHERE id = p_region_slot_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Region slot not found';
    END IF;

    IF v_slot.occupied_building_id IS NOT NULL THEN
        RAISE EXCEPTION 'Region slot already occupied';
    END IF;

    -- 2. Validate ownership
    SELECT *
    INTO v_player_region
    FROM player_regions
    WHERE id = v_slot.player_region_id
      AND player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player does not own this region or slot does not belong to region';
    END IF;

    -- 3. Slot rule
    IF v_slot.allowed_building_type IS NOT NULL
       AND v_slot.allowed_building_type <> p_building_type THEN
        RAISE EXCEPTION 'This slot does not allow building type %', p_building_type;
    END IF;

    -- 4. Region rule
    SELECT *
    INTO v_rule
    FROM region_buildings
    WHERE region_id = p_region_id
      AND building_type = p_building_type;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Building % is not allowed in region %', p_building_type, p_region_id;
    END IF;

    -- 5. Level check
    IF v_player_region.development_level < v_rule.min_region_level THEN
        RAISE EXCEPTION 'Region level too low to build %', p_building_type;
    END IF;

    -- 6. Max count
    SELECT COUNT(*)
    INTO v_current_count
    FROM player_region_buildings
    WHERE player_region_id = v_player_region.id
      AND building_type = p_building_type;

    IF v_current_count >= v_rule.max_count THEN
        RAISE EXCEPTION 'Max count reached for building %', p_building_type;
    END IF;

    -- 7. 💰 TRỪ RESOURCE (level 0 → 1)
    FOR v_cost IN
        SELECT resource_code, resource_amount
        FROM building_upgrade_cost
        WHERE building_type = p_building_type
          AND current_level = 0
          AND target_level = 1
    LOOP
        PERFORM subtract_resource_by_player_region(
            p_player_id,
            p_region_id,
            v_cost.resource_code,
            v_cost.resource_amount
        );
    END LOOP;

    -- 8. Create building
    INSERT INTO player_region_buildings (
        player_region_id,
        building_type,
        level
    )
    VALUES (
        v_player_region.id,
        p_building_type,
        1
    )
    RETURNING id INTO v_new_building_id;

    -- 9. Assign slot
    UPDATE region_slots
    SET occupied_building_id = v_new_building_id
    WHERE id = v_slot.id;

    RETURN v_new_building_id;
END;
$$;


ALTER FUNCTION public.build_building_strict(p_player_id uuid, p_region_id text, p_region_slot_id uuid, p_building_type character varying) OWNER TO postgres;

--
-- Name: build_equipment_json(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_equipment_json(p_item_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT
    CASE
        WHEN p_item_id IS NULL THEN NULL
        ELSE jsonb_build_object(
            'item_id', bi.id,
            'name', bi.name,
            'type', bi.type,
            'rarity', bi.rarity,
            'quality', bi.quality,
            'icon', bi.icon,
            'stats', jsonb_build_object(
                'attack', ist.attack,
                'defense', ist.defense,
                'health', ist.health,
                'speed', ist.speed,
                'intelligence', ist.intelligence,
                'leadership', ist.leadership
            )
        )
    END
FROM base_items bi
LEFT JOIN item_stats ist
    ON ist.base_item_id = bi.id
WHERE bi.id = p_item_id;
$$;


ALTER FUNCTION public.build_equipment_json(p_item_id text) OWNER TO postgres;

--
-- Name: build_rewards_json_from_requirement(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_rewards_json_from_requirement(p_requirement_id integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(
            'type',
                CASE
                    WHEN ar.item_id IS NOT NULL THEN 'item'
                    ELSE 'currency'
                END,
            'id', COALESCE(ar.item_id, ar.currency_type),
            'amount', ar.quantity,
            'probability', ar.probability
        )
    ),
    '[]'::jsonb
)
FROM achievement_rewards ar
WHERE ar.requirement_id = p_requirement_id;
$$;


ALTER FUNCTION public.build_rewards_json_from_requirement(p_requirement_id integer) OWNER TO postgres;

--
-- Name: buy_region_slot(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buy_region_slot(p_region_id text, p_player_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    slot_price numeric := 500;
    new_slot_id int;
BEGIN
    -- Trừ tiền (DÙNG HÀM CHẮC CHẮN TỒN TẠI)
    PERFORM public.subtract_player_currency(
        p_player_id,
        'gold',
        slot_price
    );

    -- Tạo slot mới
    INSERT INTO public.slot (
        region_id,
        player_id,
        status,
        building_type,
        building_level,
        created_at,
        updated_at
    )
    VALUES (
        p_region_id,
        p_player_id,
        'empty',
        NULL,
        1,
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP
    )
    RETURNING slot_id INTO new_slot_id;

    RETURN (
        SELECT json_build_object(
            'slot_id', s.slot_id,
            'region_id', s.region_id,
            'player_id', s.player_id,
            'status', s.status,
            'building_type', s.building_type,
            'building_level', s.building_level
        )
        FROM public.slot s
        WHERE s.slot_id = new_slot_id
    );
END;
$$;


ALTER FUNCTION public.buy_region_slot(p_region_id text, p_player_id uuid) OWNER TO postgres;

--
-- Name: buy_shop_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buy_shop_item(p_player_id uuid, p_shop_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cost_ops   jsonb;
    v_reward_ops jsonb;
BEGIN
    -- 1️⃣ Lấy cost & reward từ shop_item
    SELECT
        cost_ops,
        reward_ops
    INTO
        v_cost_ops,
        v_reward_ops
    FROM get_shop_item_transaction_json(p_shop_item_id);

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Shop item % không tồn tại', p_shop_item_id;
    END IF;

    -- 2️⃣ Thực hiện giao dịch (atomic)
    PERFORM public.execute_transaction(
        p_player_id,
        v_cost_ops,
        v_reward_ops
    );

    -- 3️⃣ Ghi activity sau khi giao dịch thành công
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        activity_subtype,
        related_id,
        metadata
    )
    VALUES (
        p_player_id,
        'transaction__player',
        'shop_purchase',
        p_shop_item_id::text,
        jsonb_build_object(
            'shop_item_id', p_shop_item_id,
            'cost', v_cost_ops,
            'reward', v_reward_ops
        )
    );

    -- 4️⃣ Trả kết quả
    RETURN jsonb_build_object(
        'status', 'success',
        'shop_item_id', p_shop_item_id,
        'cost', v_cost_ops,
        'reward', v_reward_ops
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION
            'Giao dịch shop thất bại | shop_item_id=% | lỗi=%',
            p_shop_item_id,
            SQLERRM;
END;
$$;


ALTER FUNCTION public.buy_shop_item(p_player_id uuid, p_shop_item_id uuid) OWNER TO postgres;

--
-- Name: calculate_combat_power(integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_combat_power(infantry integer, cavalry integer, archers integer, siege integer, navy integer, training_level integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        infantry * 1 +
        cavalry * 3 +
        archers * 2 +
        siege * 5 +
        navy * 4
    ) * training_level;
END;
$$;


ALTER FUNCTION public.calculate_combat_power(infantry integer, cavalry integer, archers integer, siege integer, navy integer, training_level integer) OWNER TO postgres;

--
-- Name: calculate_defense_power(integer, integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_defense_power(wall_level integer, gate_health integer, watchtowers integer, defense_bonus numeric) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN ROUND((
        (wall_level * 100) + 
        (gate_health * 0.5) + 
        (watchtowers * 50)
    ) * defense_bonus)::integer;
END;
$$;


ALTER FUNCTION public.calculate_defense_power(wall_level integer, gate_health integer, watchtowers integer, defense_bonus numeric) OWNER TO postgres;

--
-- Name: calculate_production(character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_production(building_type_param character varying, building_level integer DEFAULT 1) RETURNS TABLE(resource_type character varying, hourly_rate integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        bp.resource_type,
        ROUND(bp.base_rate * POWER(bp.level_multiplier, building_level - 1))::integer as hourly_rate
    FROM building_production bp
    WHERE bp.building_type = building_type_param;
END;
$$;


ALTER FUNCTION public.calculate_production(building_type_param character varying, building_level integer) OWNER TO postgres;

--
-- Name: calculate_production(text, integer, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_production(p_building_type text, p_level integer, p_last_collected_at timestamp with time zone, p_current_amount integer, p_max_amount integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_rate NUMERIC;
    v_efficiency NUMERIC;
    v_seconds NUMERIC;
    v_produced NUMERIC;
BEGIN
    -- 1. Lấy rate + efficiency
    SELECT production_rate_per_hour,
           COALESCE(efficiency_percent,100)
    INTO v_rate, v_efficiency
    FROM building_production
    WHERE building_type = p_building_type
      AND level = p_level
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    -- 2. Tính số giây đã trôi qua
    v_seconds := EXTRACT(EPOCH FROM (NOW() - p_last_collected_at));

    IF v_seconds <= 0 THEN
        RETURN 0;
    END IF;

    -- 3. Tính sản lượng
    v_produced :=
        v_rate
        * v_efficiency / 100
        * v_seconds / 3600;

    -- 4. Giới hạn max_amount
    v_produced := LEAST(
        v_produced,
        p_max_amount - p_current_amount
    );

    RETURN GREATEST(v_produced,0);
END;
$$;


ALTER FUNCTION public.calculate_production(p_building_type text, p_level integer, p_last_collected_at timestamp with time zone, p_current_amount integer, p_max_amount integer) OWNER TO postgres;

--
-- Name: calculate_region_production(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_region_production(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    production_data JSON;
BEGIN
    SELECT json_build_object(
        'region_id', region_id_param,
        'total_production', json_build_object(
            'gold', COALESCE(SUM(CASE WHEN bp.resource_type = 'gold' THEN rate END), 0),
            'wood', COALESCE(SUM(CASE WHEN bp.resource_type = 'wood' THEN rate END), 0),
            'food', COALESCE(SUM(CASE WHEN bp.resource_type = 'food' THEN rate END), 0)
        ),
        'buildings', json_agg(
            json_build_object(
                'slot_id', s.slot_id,
                'building_type', s.building_type,
                'building_level', s.building_level,
                'production', (
                    SELECT json_agg(
                        json_build_object(
                            'resource_type', bp.resource_type,
                            'hourly_rate', ROUND(bp.base_rate * POWER(bp.level_multiplier, s.building_level - 1))
                        )
                    )
                    FROM building_production bp
                    WHERE bp.building_type = s.building_type
                )
            )
        ) FILTER (WHERE s.building_type IS NOT NULL)
    ) INTO production_data
    FROM slot s
    LEFT JOIN building_production bp ON s.building_type = bp.building_type
    WHERE s.region_id = region_id_param 
      AND s.status = 'completed'
    GROUP BY s.slot_id, s.building_type, s.building_level;
    
    RETURN COALESCE(production_data, json_build_object('region_id', region_id_param, 'total_production', json_build_object('gold', 0, 'wood', 0, 'food', 0)));
END;
$$;


ALTER FUNCTION public.calculate_region_production(region_id_param text) OWNER TO postgres;

--
-- Name: calculate_region_total_troop_power(character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_region_total_troop_power(p_region_id character varying, p_player_id uuid) RETURNS TABLE(total_attack_power bigint, total_defense_power bigint, total_troop_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(SUM(rt.quantity * rt.attack_power), 0) AS total_attack_power,
        COALESCE(SUM(rt.quantity * rt.defense_power), 0) AS total_defense_power,
        COALESCE(SUM(rt.quantity), 0) AS total_troop_count
    FROM public.region_troops rt
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
        AND rt.location_type = 'region'
        AND rt.location_id IS NULL;
END;
$$;


ALTER FUNCTION public.calculate_region_total_troop_power(p_region_id character varying, p_player_id uuid) OWNER TO postgres;

--
-- Name: calculate_upgrade_cost(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_upgrade_cost(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_base RECORD;
    v_cost JSON;
BEGIN
    -- 1. Lấy building
    SELECT *
    INTO v_building
    FROM player_region_buildings
    WHERE id = p_player_building_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2. Lấy base building
    SELECT *
    INTO v_base
    FROM base_buildings
    WHERE "type" = v_building.building_type;

    IF v_building.level >= v_base.max_level THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building already at max level'
        );
    END IF;

    -- 3. Lấy cost upgrade (level hiện tại -> level kế tiếp)
    SELECT json_agg(
        json_build_object(
            'resource_code', buc.resource_code,
            'amount', buc.resource_amount
        )
    )
    INTO v_cost
    FROM building_upgrade_cost buc
    WHERE buc.building_type = v_building.building_type
      AND buc.current_level = v_building.level
      AND buc.target_level = v_building.level + 1;

    IF v_cost IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Upgrade cost not defined'
        );
    END IF;

    -- 4. Return preview
    RETURN json_build_object(
        'success', true,
        'player_building_id', p_player_building_id,
        'building_type', v_building.building_type,
        'current_level', v_building.level,
        'next_level', v_building.level + 1,
        'upgrade_cost', v_cost
    );
END;
$$;


ALTER FUNCTION public.calculate_upgrade_cost(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: can_build(uuid, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_build(p_player_id uuid, p_region_id text, p_building_type character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region RECORD;
    v_current_count INT;
    v_region_building RECORD;
BEGIN
    -- 1. Lấy region của player
    SELECT * INTO v_player_region
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Region not found for this player'
        );
    END IF;

    -- 2. Lấy thông tin rule của building trong region
    SELECT * INTO v_region_building
    FROM region_buildings
    WHERE region_id = p_region_id
      AND building_type = p_building_type;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'This building type cannot be built in this region'
        );
    END IF;

    -- 3. Kiểm tra min_region_level
    IF v_player_region.development_level < COALESCE(v_region_building.min_region_level,0) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Region development level too low to build this building'
        );
    END IF;

    -- 4. Kiểm tra số lượng hiện tại
    SELECT COUNT(*) INTO v_current_count
    FROM player_region_buildings
    WHERE player_region_id = v_player_region.id
      AND building_type = p_building_type;

    IF v_current_count >= COALESCE(v_region_building.max_count,1) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Maximum number of this building type reached in this region'
        );
    END IF;

    -- 5. Nếu tất cả ok
    RETURN json_build_object(
        'success', true,
        'message', 'Player can build this building'
    );
END;
$$;


ALTER FUNCTION public.can_build(p_player_id uuid, p_region_id text, p_building_type character varying) OWNER TO postgres;

--
-- Name: can_upgrade(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_upgrade(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_base_building RECORD;
    v_attr RECORD;
BEGIN
    -- 1. Lấy building
    SELECT * INTO v_building
    FROM player_region_buildings
    WHERE id = p_player_building_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2. Check đang upgrading
    IF v_building.upgrading THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building is already upgrading'
        );
    END IF;

    -- 3. Lấy max_level từ base_buildings
    SELECT * INTO v_base_building
    FROM base_buildings
    WHERE "type" = v_building.building_type;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Base building info not found'
        );
    END IF;

    IF v_building.level >= COALESCE(v_base_building.max_level,1) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building is already at max level'
        );
    END IF;

    -- 4. Kiểm tra attribute detail của level hiện tại
    SELECT * INTO v_attr
    FROM building_attribute_detail
    WHERE building_type = v_building.building_type
      AND level = v_building.level;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building attribute detail not found for current level'
        );
    END IF;

    -- 5. Nếu tất cả ok
    RETURN json_build_object(
        'success', true,
        'message', 'Building can be upgraded',
        'current_level', v_building.level,
        'max_level', v_base_building.max_level,
        'upgrade_time_seconds', COALESCE(v_attr.build_time_seconds,0)
    );
END;
$$;


ALTER FUNCTION public.can_upgrade(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: cancel_all_battle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_all_battle(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_battle_id uuid;
  v_cancelled_ids uuid[] := '{}';
  v_failed_ids uuid[] := '{}';
  v_result jsonb;
BEGIN
  -- Lặp qua tất cả trận đang active của player (player1_id)
  FOR v_battle_id IN
    SELECT id
    FROM public.battles
    WHERE player1_id = p_player_id
      AND status IN ('matchmaking', 'ready', 'in_progress')
  LOOP
    BEGIN
      -- Gọi hàm cancel_battle có sẵn
      v_result := public.cancel_battle(v_battle_id);

      -- Nếu thành công thì thêm vào danh sách
      IF (v_result->>'success')::boolean = true THEN
        v_cancelled_ids := array_append(v_cancelled_ids, v_battle_id);
      ELSE
        v_failed_ids := array_append(v_failed_ids, v_battle_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Bắt lỗi từng trận, không làm hỏng cả hàm
      v_failed_ids := array_append(v_failed_ids, v_battle_id);
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'player_id', p_player_id,
    'cancelled_count', array_length(v_cancelled_ids, 1),
    'failed_count', array_length(v_failed_ids, 1),
    'cancelled_ids', to_jsonb(v_cancelled_ids),
    'failed_ids', to_jsonb(v_failed_ids)
  );
END;
$$;


ALTER FUNCTION public.cancel_all_battle(p_player_id uuid) OWNER TO postgres;

--
-- Name: cancel_battle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_battle(p_battle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles;
BEGIN
    -- Lấy battle
    SELECT *
    INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id
    FOR UPDATE;

    IF v_battle.id IS NULL THEN
        RAISE EXCEPTION 'Battle % not found', p_battle_id;
    END IF;


    -- Chỉ hủy trận đang hoạt động
    IF v_battle.status NOT IN ('matchmaking', 'ready', 'in_progress') THEN
        RAISE EXCEPTION 'Cannot cancel battle with status %', v_battle.status;
    END IF;


    -- Rollback quân player 1
    IF v_battle.player1_region_id IS NOT NULL THEN
        PERFORM public.rollback_troops_from_combat(
            v_battle.id,
            v_battle.player1_region_id,
            v_battle.player1_id
        );
    END IF;


    -- Rollback quân player 2 nếu là PvP
    IF v_battle.player2_id IS NOT NULL
       AND v_battle.player2_region_id IS NOT NULL THEN

        PERFORM public.rollback_troops_from_combat(
            v_battle.id,
            v_battle.player2_region_id,
            v_battle.player2_id
        );

    END IF;


    -- Cập nhật trạng thái
    UPDATE public.battles
    SET
        status = 'cancelled',
        ended_at = now()
    WHERE id = p_battle_id
    RETURNING *
    INTO v_battle;


    RETURN jsonb_build_object(
        'battle', to_jsonb(v_battle)
    );
END;
$$;


ALTER FUNCTION public.cancel_battle(p_battle_id uuid) OWNER TO postgres;

--
-- Name: cancel_battle_challenge(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_battle_challenge(p_challenge_id uuid, p_player_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE battle_challenges
  SET status = 'cancelled',
      responded_at = now()
  WHERE id = p_challenge_id
    AND challenger_id = p_player_id
    AND status = 'pending';

  RETURN FOUND;
END;
$$;


