--
-- Name: cancel_friend_request(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_friend_request(p_player_id uuid, p_friend_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Xóa lời mời nếu tồn tại và đang ở trạng thái 'pending'
    DELETE FROM friend_relationships
    WHERE player_id = p_player_id
      AND friend_id = p_friend_id
      AND status = 'pending';

    IF FOUND THEN
        RETURN 'Friend request canceled';
    ELSE
        RETURN 'No pending friend request found';
    END IF;
END;
$$;


ALTER FUNCTION public.cancel_friend_request(p_player_id uuid, p_friend_id uuid) OWNER TO postgres;

--
-- Name: cancel_matchmaking_popup(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_matchmaking_popup(p_player_id uuid, p_target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_deleted int;
BEGIN
  DELETE FROM matchmaking_locks
  WHERE player_id = p_target_id
    AND locked_by = p_player_id
    AND locked_until > now();

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted = 0 THEN
    RETURN jsonb_build_object(
      'cancelled', false,
      'reason', 'lock_not_found_or_expired'
    );
  END IF;

  RETURN jsonb_build_object(
    'cancelled', true
  );
END;
$$;


ALTER FUNCTION public.cancel_matchmaking_popup(p_player_id uuid, p_target_id uuid) OWNER TO postgres;

--
-- Name: cancel_unit_training(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_unit_training(p_training_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row unit_training_queue%ROWTYPE;
BEGIN
  -- Lấy training (và lock nhẹ để tránh race)
  SELECT *
  INTO v_row
  FROM unit_training_queue
  WHERE id = p_training_id
    AND finish_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Training not found or already completed';
  END IF;

  -- Xóa queue
  DELETE FROM unit_training_queue
  WHERE id = p_training_id;

  -- Trả JSON cho client
  RETURN json_build_object(
    'training_id', v_row.id,
    'unit_type', v_row.unit_type,
    'quantity', v_row.quantity,
    'started_at', v_row.started_at,
    'finish_at', v_row.finish_at,
    'status', 'cancelled'
  );
END;
$$;


ALTER FUNCTION public.cancel_unit_training(p_training_id uuid) OWNER TO postgres;

--
-- Name: cancel_upgrade(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_upgrade(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_refund_rate DECIMAL := 0.5; -- 50% resource refund
BEGIN
    -- Get building
    SELECT * INTO v_building
    FROM player_region_buildings
    WHERE id = p_player_building_id;
    
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Building not found');
    END IF;
    
    IF NOT v_building.upgrading THEN
        RETURN json_build_object('success', false, 'message', 'Building not upgrading');
    END IF;
    
    -- Calculate elapsed time
    DECLARE
        v_elapsed_seconds DECIMAL;
        v_total_seconds DECIMAL;
        v_refund_percent DECIMAL;
    BEGIN
        v_elapsed_seconds := EXTRACT(EPOCH FROM (NOW() - (v_building.upgrade_finish_at - 
            (SELECT build_time_seconds 
             FROM building_attribute_detail 
             WHERE building_type = v_building.building_type 
               AND level = v_building.level))));
        
        v_total_seconds := (SELECT build_time_seconds 
                           FROM building_attribute_detail 
                           WHERE building_type = v_building.building_type 
                             AND level = v_building.level);
        
        v_refund_percent := GREATEST(0, 1 - (v_elapsed_seconds / v_total_seconds)) * v_refund_rate;
        
        -- Cancel upgrade
        UPDATE player_region_buildings
        SET upgrading = false,
            upgrade_finish_at = NULL
        WHERE id = p_player_building_id;
        
        -- TODO: Refund resources
        
        RETURN json_build_object(
            'success', true,
            'message', 'Upgrade cancelled',
            'refund_percent', ROUND(v_refund_percent * 100, 2)
        );
    END;
END;
$$;


ALTER FUNCTION public.cancel_upgrade(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: check_daily_quest_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_daily_quest_status(p_player_id uuid, p_quest_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_build_object(
        -- quest info
        'quest_id', q.id,
        'quest_name', q.name,
        'description', q.description,
        'type', q.type,
        'category', q.category,
        'difficulty', q.difficulty,
        'status', q.status,
        'min_level', q.min_level,
        'max_level', q.max_level,

        -- requirements with progress
        'requirements',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'requirement_id', qr.id,
                    'requirement_type', qr.requirement_type,
                    'target', qr.target,
                    'meta', qr.meta,
                    'progress',
                        (
                            SELECT COUNT(*)
                            FROM player_activities pa
                            WHERE pa.player_id = p_player_id
                              AND pa.quest_requirement_id = qr.id
                              AND pa.created_at::date = CURRENT_DATE
                        ),
                    'completed',
                        (
                            SELECT COUNT(*)
                            FROM player_activities pa
                            WHERE pa.player_id = p_player_id
                              AND pa.quest_requirement_id = qr.id
                              AND pa.created_at::date = CURRENT_DATE
                        ) >= qr.target
                )
            ),
            '[]'::jsonb
        ),

        -- rewards
        'rewards',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'reward_id', r.id,
                        'item_id', r.item_id,
                        'amount', r.amount,
                        'reward_type', r.reward_type,
                        'currency_type', r.currency_type,
                        'experience_amount', r.experience_amount,
                        'description', r.description
                    )
                )
                FROM quest_rewards r
                WHERE r.quest_id = q.id
            ),
            '[]'::jsonb
        ),

        -- quest status
        'is_completed',
            NOT EXISTS (
                SELECT 1
                FROM quest_requirements qr2
                WHERE qr2.quest_id = q.id
                  AND (
                      SELECT COUNT(*)
                      FROM player_activities pa2
                      WHERE pa2.player_id = p_player_id
                        AND pa2.quest_requirement_id = qr2.id
                        AND pa2.created_at::date = CURRENT_DATE
                  ) < qr2.target
            ),

        'is_claimed',
            EXISTS (
                SELECT 1
                FROM quest_completion_log qcl
                WHERE qcl.player_id = p_player_id
                  AND qcl.quest_id = q.id
                  AND qcl.completed_at::date = CURRENT_DATE
            )

    )
    INTO result
    FROM quests q
    LEFT JOIN quest_requirements qr ON qr.quest_id = q.id
    WHERE q.id = p_quest_id
      AND q.category = 'daily'
    GROUP BY q.id;

    RETURN result;
END;
$$;


ALTER FUNCTION public.check_daily_quest_status(p_player_id uuid, p_quest_id text) OWNER TO postgres;

--
-- Name: check_first_time_bonus(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_first_time_bonus(p_player_id uuid, p_loot_box_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
    SELECT jsonb_build_object(
        'is_first_time',
        EXISTS (
            SELECT 1
            FROM public.player_loot_boxes
            WHERE player_id = p_player_id
              AND loot_box_id = p_loot_box_id
              AND total_opens = 0
        ),

        'reward_items',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'first_time_reward_id', ftr.id,
                        'reward_item_id', ri.id,
                        'item_id', ri.item_id,
                        'reward_type', ri.reward_type,
                        'currency_type', ri.currency_type,
                        'amount_min', ri.amount_min,
                        'amount_max', ri.amount_max,
                        'rarity', ri.rarity,
                        'bound_type', ri.bound_type
                    )
                )
                FROM public.loot_box_first_time_bonuses ftb
                JOIN public.loot_box_first_time_rewards ftr
                    ON ftr.first_time_bonus_id = ftb.id
                JOIN public.loot_box_reward_items ri
                    ON ri.id = ftr.reward_item_id
                WHERE ftb.loot_box_id = p_loot_box_id
                  AND ftb.enabled = true
            ),
            '[]'::jsonb
        )
    );
$$;


ALTER FUNCTION public.check_first_time_bonus(p_player_id uuid, p_loot_box_id text) OWNER TO postgres;

--
-- Name: check_guaranteed(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_guaranteed(p_player_id uuid, p_loot_box_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_open_count integer := 0;
    v_result jsonb := '[]'::jsonb;
BEGIN

    -- Lấy số lần mở hiện tại của player
    SELECT total_opens
    INTO v_open_count
    FROM public.player_loot_boxes
    WHERE player_id = p_player_id
      AND loot_box_id = p_loot_box_id;

    v_open_count := COALESCE(v_open_count, 0);

    -- Lấy guaranteed rewards đã đạt mốc
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'guaranteed_drop_id', gd.id,
                'loot_box_id', gd.loot_box_id,
                'open_count', gd.open_count,
                'reset_after_claim', gd.reset_after_claim,

                'reward_item_id', gr.reward_item_id,

                'item_id', ri.item_id,
                'reward_type', ri.reward_type,
                'amount_min', ri.amount_min,
                'amount_max', ri.amount_max,
                'rarity', ri.rarity,
                'bound_type', ri.bound_type,
                'currency_type', ri.currency_type
            )
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM public.loot_box_guaranteed_drops gd

    JOIN public.loot_box_guaranteed_rewards gr
        ON gr.guaranteed_drop_id = gd.id

    JOIN public.loot_box_reward_items ri
        ON ri.id = gr.reward_item_id

    WHERE gd.loot_box_id = p_loot_box_id
      AND gd.open_count <= v_open_count;

    RETURN jsonb_build_object(
        'active', jsonb_array_length(v_result) > 0,
        'open_count', v_open_count,
        'reward_items', v_result
    );

END;
$$;


ALTER FUNCTION public.check_guaranteed(p_player_id uuid, p_loot_box_id text) OWNER TO postgres;

--
-- Name: check_loot_box_limits(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_loot_box_limits(p_player_id uuid, p_loot_box_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_limits RECORD;
    v_player_loot_box RECORD;
BEGIN
    -- 1. Get loot box limits
    SELECT
        daily_limit,
        weekly_limit,
        monthly_limit,
        total_limit
    INTO v_limits
    FROM public.loot_box_limits
    WHERE loot_box_id = p_loot_box_id
    LIMIT 1;

    -- Không có cấu hình limit → cho phép mở
    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- 2. Get player's loot box state
    SELECT
        total_opens,
        daily_opens,
        weekly_opens,
        monthly_opens
    INTO v_player_loot_box
    FROM public.player_loot_boxes
    WHERE player_id = p_player_id
      AND loot_box_id = p_loot_box_id;

    -- Chưa có record → tất cả counter = 0
    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- 3. Daily limit
    IF v_limits.daily_limit IS NOT NULL
       AND v_player_loot_box.daily_opens + 1 > v_limits.daily_limit
    THEN
        RAISE EXCEPTION
            'Daily loot box limit exceeded. Limit: %, Current: %',
            v_limits.daily_limit,
            v_player_loot_box.daily_opens;
    END IF;

    -- 4. Weekly limit
    IF v_limits.weekly_limit IS NOT NULL
       AND v_player_loot_box.weekly_opens + 1 > v_limits.weekly_limit
    THEN
        RAISE EXCEPTION
            'Weekly loot box limit exceeded. Limit: %, Current: %',
            v_limits.weekly_limit,
            v_player_loot_box.weekly_opens;
    END IF;

    -- 5. Monthly limit
    IF v_limits.monthly_limit IS NOT NULL
       AND v_player_loot_box.monthly_opens + 1 > v_limits.monthly_limit
    THEN
        RAISE EXCEPTION
            'Monthly loot box limit exceeded. Limit: %, Current: %',
            v_limits.monthly_limit,
            v_player_loot_box.monthly_opens;
    END IF;

    -- 6. Total limit
    IF v_limits.total_limit IS NOT NULL
       AND v_player_loot_box.total_opens + 1 > v_limits.total_limit
    THEN
        RAISE EXCEPTION
            'Total loot box limit exceeded. Limit: %, Current: %',
            v_limits.total_limit,
            v_player_loot_box.total_opens;
    END IF;

END;
$$;


ALTER FUNCTION public.check_loot_box_limits(p_player_id uuid, p_loot_box_id text) OWNER TO postgres;

--
-- Name: check_loot_box_limits(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_loot_box_limits(p_player_id uuid, p_loot_box_id text, p_quantity integer) RETURNS TABLE(check_result boolean, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_limits RECORD;
    v_player_stats RECORD;
    v_daily_opens INT;
    v_weekly_opens INT;
    v_monthly_opens INT;
    v_opened_today INT;
BEGIN
    -- Get limit configuration
    SELECT * INTO v_limits
    FROM loot_box_limits 
    WHERE loot_box_id = p_loot_box_id;

    -- Get player stats
    SELECT total_opens, last_opened_at INTO v_player_stats
    FROM player_loot_boxes 
    WHERE player_id = p_player_id AND loot_box_id = p_loot_box_id;

    -- Calculate opens for different periods
    SELECT COUNT(*) INTO v_opened_today
    FROM player_loot_box_rewards plr
    JOIN player_loot_boxes plb ON plr.player_loot_box_id = plb.id
    WHERE plb.player_id = p_player_id 
      AND plb.loot_box_id = p_loot_box_id
      AND DATE(plr.dropped_at) = CURRENT_DATE;

    -- Check daily limit
    IF v_limits.daily_limit IS NOT NULL THEN
        IF (v_opened_today + p_quantity) > v_limits.daily_limit THEN
            RETURN QUERY SELECT false, 
                format('Daily limit exceeded. Remaining: %s', 
                       GREATEST(0, v_limits.daily_limit - v_opened_today));
            RETURN;
        END IF;
    END IF;

    -- Check weekly limit (similar logic, need to calculate weekly opens)
    -- Check monthly limit
    -- Check total limit
    IF v_limits.total_limit IS NOT NULL THEN
        IF COALESCE(v_player_stats.total_opens, 0) + p_quantity > v_limits.total_limit THEN
            RETURN QUERY SELECT false, 
                format('Total limit exceeded. Remaining: %s', 
                       GREATEST(0, v_limits.total_limit - COALESCE(v_player_stats.total_opens, 0)));
            RETURN;
        END IF;
    END IF;

    -- Check per account limit
    IF v_limits.per_account_limit IS NOT NULL THEN
        -- Implementation depends on your account structure
        NULL;
    END IF;

    RETURN QUERY SELECT true, 'Limits check passed';
END;
$$;


ALTER FUNCTION public.check_loot_box_limits(p_player_id uuid, p_loot_box_id text, p_quantity integer) OWNER TO postgres;

--
-- Name: check_loot_box_requirements(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_loot_box_requirements(p_player_id uuid, p_loot_box_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_requirement RECORD;
    v_player_level integer;
    v_vip_level integer;
    v_last_opened_at timestamptz;
    v_current_time time;
    v_current_dow integer;
BEGIN
    -- 1. Check player
    SELECT level
    INTO v_player_level
    FROM public.players
    WHERE id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player not found: %', p_player_id;
    END IF;

    -- 2. Get VIP level
    SELECT COALESCE(vip_level, 0)
    INTO v_vip_level
    FROM public.user_vip
    WHERE user_id = p_player_id;

    v_vip_level := COALESCE(v_vip_level, 0);

    -- 3. Get last opened time
    SELECT last_opened_at
    INTO v_last_opened_at
    FROM public.player_loot_boxes
    WHERE player_id = p_player_id
      AND loot_box_id = p_loot_box_id;

    -- 4. Get requirement
    SELECT
        min_level,
        max_level,
        vip_level,
        time_restriction_start,
        time_restriction_end,
        days_of_week,
        cooldown_seconds
    INTO v_requirement
    FROM public.loot_box_requirements
    WHERE loot_box_id = p_loot_box_id
    LIMIT 1;

    -- No requirements configured
    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- 5. Minimum level
    IF v_requirement.min_level IS NOT NULL
       AND v_player_level < v_requirement.min_level
    THEN
        RAISE EXCEPTION
            'Loot box requires minimum level %. Player level: %',
            v_requirement.min_level,
            v_player_level;
    END IF;

    -- 6. Maximum level
    IF v_requirement.max_level IS NOT NULL
       AND v_player_level > v_requirement.max_level
    THEN
        RAISE EXCEPTION
            'Loot box requires maximum level %. Player level: %',
            v_requirement.max_level,
            v_player_level;
    END IF;

    -- 7. VIP level
    IF v_requirement.vip_level IS NOT NULL
       AND v_vip_level < v_requirement.vip_level
    THEN
        RAISE EXCEPTION
            'Loot box requires VIP level %. Player VIP level: %',
            v_requirement.vip_level,
            v_vip_level;
    END IF;

    -- 8. Current time/day
    v_current_time := CURRENT_TIME;
    v_current_dow := EXTRACT(DOW FROM CURRENT_DATE)::integer;

    -- 9. Day of week
    IF v_requirement.days_of_week IS NOT NULL
       AND NOT (
           v_requirement.days_of_week
           @> jsonb_build_array(v_current_dow)
       )
    THEN
        RAISE EXCEPTION
            'Loot box cannot be opened today';
    END IF;

    -- 10. Time restriction
    IF v_requirement.time_restriction_start IS NOT NULL
       AND v_requirement.time_restriction_end IS NOT NULL
    THEN

        -- Normal range: 08:00 -> 22:00
        IF v_requirement.time_restriction_start
           <= v_requirement.time_restriction_end
        THEN
            IF v_current_time < v_requirement.time_restriction_start
               OR v_current_time > v_requirement.time_restriction_end
            THEN
                RAISE EXCEPTION
                    'Loot box can only be opened between % and %',
                    v_requirement.time_restriction_start,
                    v_requirement.time_restriction_end;
            END IF;

        -- Overnight range: 22:00 -> 02:00
        ELSE
            IF v_current_time < v_requirement.time_restriction_start
               AND v_current_time > v_requirement.time_restriction_end
            THEN
                RAISE EXCEPTION
                    'Loot box can only be opened between % and %',
                    v_requirement.time_restriction_start,
                    v_requirement.time_restriction_end;
            END IF;
        END IF;

    END IF;

    -- 11. Cooldown
    IF v_requirement.cooldown_seconds IS NOT NULL
       AND v_requirement.cooldown_seconds > 0
       AND v_last_opened_at IS NOT NULL
    THEN
        IF now() <
           v_last_opened_at
           + make_interval(secs => v_requirement.cooldown_seconds)
        THEN
            RAISE EXCEPTION
                'Loot box is on cooldown. Last opened at: %',
                v_last_opened_at;
        END IF;
    END IF;

    -- All requirements passed
    RETURN;
END;
$$;


ALTER FUNCTION public.check_loot_box_requirements(p_player_id uuid, p_loot_box_id text) OWNER TO postgres;

--
-- Name: check_max_combat_ready_troops(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_max_combat_ready_troops() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count int;
BEGIN
    -- Chỉ kiểm tra khi set is_combat_ready = true
    IF NEW.is_combat_ready = true THEN
        SELECT COUNT(*)
        INTO v_count
        FROM region_troops
        WHERE region_id = NEW.region_id
          AND player_id = NEW.player_id
          AND is_combat_ready = true
          AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000');

        IF v_count >= 3 THEN
            RAISE EXCEPTION
                'Chỉ được tối đa 3 loại lính sẵn sàng chiến đấu cho mỗi khu vực';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_max_combat_ready_troops() OWNER TO postgres;

--
-- Name: check_pity_system(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_pity_system(p_player_id uuid, p_loot_box_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_pity_counter integer := 0;
    v_pity_counter_id text;
    v_threshold integer;
    v_rarity text;
    v_reward_items jsonb := '[]'::jsonb;
BEGIN
    -- 1. Lấy pity counter hiện tại của player
    SELECT COALESCE(plb.pity_counter, 0)
    INTO v_pity_counter
    FROM public.player_loot_boxes plb
    WHERE plb.player_id = p_player_id
      AND plb.loot_box_id = p_loot_box_id;

    -- Chưa có state
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'active', false,
            'pity_counter', 0,
            'pity_counter_id', null,
            'threshold', null,
            'rarity', null,
            'reward_items', '[]'::jsonb
        );
    END IF;

    -- 2. Tìm pity threshold cao nhất player đã đạt
    SELECT
        pc.id,
        pc.threshold,
        pc.rarity
    INTO
        v_pity_counter_id,
        v_threshold,
        v_rarity
    FROM public.loot_box_pity_counters pc
    JOIN public.loot_box_pity_systems ps
        ON ps.id = pc.pity_system_id
    WHERE ps.loot_box_id = p_loot_box_id
      AND ps.enabled = true
      AND v_pity_counter >= pc.threshold
    ORDER BY pc.threshold DESC
    LIMIT 1;

    -- Chưa đạt pity
    IF v_pity_counter_id IS NULL THEN
        RETURN jsonb_build_object(
            'active', false,
            'pity_counter', v_pity_counter,
            'pity_counter_id', null,
            'threshold', null,
            'rarity', null,
            'reward_items', '[]'::jsonb
        );
    END IF;

    -- 3. Lấy reward items của pity counter
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'pity_item_id', pi.id,
                'reward_item_id', ri.id,
                'reward_type', ri.reward_type,
                'item_id', ri.item_id,
                'currency_type', ri.currency_type,
                'amount_min', ri.amount_min,
                'amount_max', ri.amount_max,
                'weight', pi.weight,
                'rarity', ri.rarity,
                'bound_type', ri.bound_type
            )
            ORDER BY pi.id
        ),
        '[]'::jsonb
    )
    INTO v_reward_items
    FROM public.loot_box_pity_items pi
    JOIN public.loot_box_reward_items ri
        ON ri.id = pi.reward_item_id
    WHERE pi.pity_counter_id = v_pity_counter_id;

    -- 4. Trả kết quả
    RETURN jsonb_build_object(
        'active', true,
        'pity_counter', v_pity_counter,
        'pity_counter_id', v_pity_counter_id,
        'threshold', v_threshold,
        'rarity', v_rarity,
        'reward_items', v_reward_items
    );
END;
$$;


ALTER FUNCTION public.check_pity_system(p_player_id uuid, p_loot_box_id text) OWNER TO postgres;

--
-- Name: check_table_relationship(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_table_relationship(table1_name text, table2_name text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
BEGIN
  -- Kiểm tra quan hệ
  SELECT 
    json_build_object(
      'relationship_exists', TRUE,
      'constraint_name', tc.constraint_name,
      'source_table', tc.table_name,
      'source_column', kcu.column_name,
      'target_table', ccu.table_name,
      'target_column', ccu.column_name,
      'on_delete_action', rc.delete_rule,
      'on_update_action', rc.update_rule
    ) INTO result
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu 
    ON tc.constraint_name = kcu.constraint_name
  JOIN information_schema.constraint_column_usage ccu 
    ON ccu.constraint_name = tc.constraint_name
  LEFT JOIN information_schema.referential_constraints rc
    ON rc.constraint_name = tc.constraint_name
  WHERE tc.constraint_type = 'FOREIGN KEY'
  AND (
    (tc.table_name = table1_name AND ccu.table_name = table2_name)
    OR 
    (tc.table_name = table2_name AND ccu.table_name = table1_name)
  )
  LIMIT 1;

  -- Nếu không tìm thấy quan hệ
  IF result IS NULL THEN
    SELECT json_build_object(
      'relationship_exists', FALSE,
      'constraint_name', NULL,
      'source_table', NULL,
      'source_column', NULL,
      'target_table', NULL,
      'target_column', NULL,
      'on_delete_action', NULL,
      'on_update_action', NULL
    ) INTO result;
  END IF;

  RETURN result;
END;
$$;


ALTER FUNCTION public.check_table_relationship(table1_name text, table2_name text) OWNER TO postgres;

