--
-- Name: claim_achievement_tier_reward(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_achievement_tier_reward(p_player_id uuid, p_requirement_id integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_raw_rewards jsonb;
    v_full_rewards jsonb;
BEGIN
    -- 1️⃣ Claim atomically (anti double-claim)
    UPDATE player_achievement_tier_progress patp
    SET
        reward_claimed = true,
        updated_at = now()
    WHERE patp.player_id = p_player_id
      AND patp.requirement_id = p_requirement_id
      AND patp.completed = true
      AND patp.reward_claimed = false
      AND EXISTS (
          SELECT 1
          FROM achievement_requirements ar
          WHERE ar.id = patp.requirement_id
      );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tier not completed or already claimed';
    END IF;

    -- 2️⃣ Build reward JSON (semantic reward data)
    v_raw_rewards := build_rewards_json_from_requirement(p_requirement_id);

    -- 3️⃣ Grant reward (side-effect)
    v_raw_rewards := grant_rewards_from_json_full(
        p_player_id,
        v_raw_rewards
    );

    -- 4️⃣ Enrich metadata (name, description, icon...)
    v_full_rewards := enrich_reward_metadata(v_raw_rewards);

    RETURN v_full_rewards;
END;
$$;


ALTER FUNCTION public.claim_achievement_tier_reward(p_player_id uuid, p_requirement_id integer) OWNER TO postgres;

--
-- Name: claim_player_quest_reward_full(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_player_quest_reward_full(p_player_id uuid, p_quest_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_claimed boolean;
    v_rewards jsonb;
    v_result jsonb;
BEGIN
    -- 0️⃣ Đảm bảo có row trong player_quest_progress
    INSERT INTO player_quest_progress (
        player_id,
        quest_id,
        completed,
        claimed,
        updated_at
    )
    VALUES (
        p_player_id,
        p_quest_id,
        true,
        false,
        now()
    )
    ON CONFLICT (player_id, quest_id) DO NOTHING;

    -- 1️⃣ Claim quest (atomic)
    UPDATE player_quest_progress
    SET
        claimed = true,
        updated_at = now()
    WHERE player_id = p_player_id
      AND quest_id = p_quest_id
      AND completed = true
      AND claimed = false
    RETURNING true
    INTO v_claimed;

    -- 2️⃣ Nếu không claim được → trả rỗng
    IF NOT COALESCE(v_claimed, false) THEN
        RETURN '[]'::jsonb;
    END IF;

    -- 3️⃣ Build reward JSON
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'type', qr.reward_type,
                'id',
                    CASE qr.reward_type
                        WHEN 'item'     THEN qr.item_id
                        WHEN 'currency' THEN qr.currency_type
                        WHEN 'exp'      THEN 'experience'
                        WHEN 'region'   THEN qr.region_id
                        WHEN 'hero'     THEN qr.hero_id
                        WHEN 'lootbox'  THEN qr.lootbox_id
                        WHEN 'beauty'   THEN qr.beauty_id
                    END,
                'amount',
                    CASE
                        WHEN qr.reward_type = 'exp'
                            THEN qr.experience_amount
                        ELSE qr.amount
                    END
            )
        ),
        '[]'::jsonb
    )
    INTO v_rewards
    FROM quest_rewards qr
    WHERE qr.quest_id = p_quest_id;

    -- 4️⃣ Phát thưởng
    v_result := grant_rewards_from_json_full(
        p_player_id,
        v_rewards
    );

    -- 5️⃣ Kiểm tra và mở main quest tiếp theo
    PERFORM unlock_main_quest_by_condition(
        p_player_id
    );

    RETURN v_result;
END;
$$;


