--
-- Name: collect_all_resources(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.collect_all_resources(p_player_id uuid, p_region_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_player_region_id uuid;
  v_result json;
BEGIN
  /* 1. Resolve player_region_id */
  SELECT pr.id
  INTO v_player_region_id
  FROM player_regions pr
  WHERE pr.player_id = p_player_id
    AND pr.region_id = p_region_id;

  IF v_player_region_id IS NULL THEN
    RETURN json_build_object(
      'error', 'PLAYER_REGION_NOT_FOUND'
    );
  END IF;

  /* 2. Collect all resources and build JSON */
  WITH calc AS (
    SELECT
      rr.id,
      rr.resource_code,
      GREATEST(
        0,
        LEAST(
          (
            EXTRACT(EPOCH FROM (now() - rr.last_collected_at))
            * bp.production_rate_per_hour / 3600.0
            * bp.efficiency_percent / 100.0
          )::int,
          rr.max_amount - rr.amount
        )
      ) AS produced
    FROM region_resources rr
    JOIN player_region_buildings prb
      ON prb.player_region_id = rr.player_region_id
    JOIN building_production bp
      ON bp.building_type = prb.building_type
     AND bp.level = prb.level
    WHERE rr.player_region_id = v_player_region_id
      AND prb.upgrading = false
  ),
  updated AS (
    UPDATE region_resources rr
    SET
      amount = rr.amount + calc.produced,
      last_collected_at = now()
    FROM calc
    WHERE rr.id = calc.id
    RETURNING
      rr.resource_code,
      calc.produced
  )
  SELECT json_agg(
    json_build_object(
      'resource_code', resource_code,
      'collected', produced
    )
  )
  INTO v_result
  FROM updated;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.collect_all_resources(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: collect_building_resource(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.collect_building_resource(p_player_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_production RECORD;
    v_resource RECORD;
    v_resource_type RECORD;

    v_player_id uuid;

    v_seconds bigint;
    v_produced numeric;
    v_final_add numeric;
BEGIN
    -- 1️⃣ Lock building
    SELECT *
    INTO v_building
    FROM player_region_buildings
    WHERE id = p_player_building_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2️⃣ Resolve player_id from player_region
    SELECT pr.player_id
    INTO v_player_id
    FROM public.player_regions pr
    WHERE pr.id = v_building.player_region_id
    LIMIT 1;

    IF v_player_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Player region not found'
        );
    END IF;

    -- 3️⃣ Get production config
    SELECT *
    INTO v_production
    FROM building_production
    WHERE building_type = v_building.building_type
      AND level = v_building.level
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Building has no production config'
        );
    END IF;

    -- 4️⃣ Lock resource row
    SELECT *
    INTO v_resource
    FROM region_resources
    WHERE player_region_id = v_building.player_region_id
      AND resource_code = v_production.resource_code
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO region_resources(
            player_region_id,
            resource_code,
            amount,
            max_amount
        )
        VALUES (
            v_building.player_region_id,
            v_production.resource_code,
            0,
            v_production.production_capacity
        )
        RETURNING * INTO v_resource;
    END IF;

    -- 5️⃣ Calculate production time
    v_seconds :=
        EXTRACT(EPOCH FROM (
            NOW() - v_building.last_production_at
        ));

    -- 6️⃣ Calculate produced amount
    v_produced :=
        (
            v_production.production_rate_per_hour
            * COALESCE(v_production.efficiency_percent, 100) / 100
            * v_seconds / 3600
        );

    -- 7️⃣ Apply storage capacity limit
    v_final_add :=
        LEAST(
            v_produced,
            v_resource.max_amount - v_resource.amount
        );

    -- prevent negative values
    v_final_add := GREATEST(v_final_add, 0);

    -- 8️⃣ Update resource storage
    UPDATE region_resources
    SET amount = amount + v_final_add,
        last_collected_at = NOW()
    WHERE id = v_resource.id
    RETURNING * INTO v_resource;

    -- 9️⃣ Reset building production timer
    UPDATE player_region_buildings
    SET last_production_at = NOW()
    WHERE id = v_building.id;

    -- 🔟 Get resource display info
    SELECT *
    INTO v_resource_type
    FROM resource_types
    WHERE resource_code = v_production.resource_code
    LIMIT 1;

    -- 1️⃣1️⃣ Insert resource log
    INSERT INTO public.resource_logs (
        player_id,
        resource_code,
        amount,
        description,
        action_type,
        player_region_id,
        metadata
    )
    VALUES (
        v_player_id,
        v_production.resource_code,
        FLOOR(v_final_add)::int4,
        CONCAT(
            '+',
            FLOOR(v_final_add)::int4,
            ' ',
            COALESCE(
                v_resource_type.resource_name,
                v_production.resource_code
            )
        ),
        'collect',
        v_building.player_region_id,
        jsonb_build_object(
            'source', v_building.building_type,
            'building_id', v_building.id,
            'building_level', v_building.level
        )
    );

	    -- Insert player activity
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        activity_subtype,
        related_id,
        metadata
    )
    VALUES (
        v_player_id,
        'resource.collect',
        v_production.resource_code,
        v_building.id::text,
        jsonb_build_object(
            'building_type', v_building.building_type,
            'building_level', v_building.level,
            'resource_code', v_production.resource_code,
            'collected_amount', v_final_add,
            'player_region_id', v_building.player_region_id
        )
    );
    -- 1️⃣2️⃣ Return response
    RETURN jsonb_build_object(
        'success', true,
        'resource_code', v_production.resource_code,
        'collected_now', v_final_add,
        'current_amount', v_resource.amount,
        'capacity', v_resource.max_amount
    );
END;
$$;


ALTER FUNCTION public.collect_building_resource(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: collect_building_resource_by_slot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.collect_building_resource_by_slot(p_slot_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building_id uuid;
BEGIN
    -- Lock slot
    SELECT occupied_building_id
    INTO v_building_id
    FROM region_slots
    WHERE id = p_slot_id
    FOR UPDATE;

    IF v_building_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Slot is empty'
        );
    END IF;

    -- Gọi function collect bằng building_id
    RETURN collect_building_resource(v_building_id);
END;
$$;


