--
-- Name: collect_single_resource(uuid, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.collect_single_resource(p_player_id uuid, p_region_id text, p_resource_code character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_player_region_id uuid;
  v_collected int := 0;
BEGIN
  -- 1. Resolve player_region_id
  SELECT pr.id
  INTO v_player_region_id
  FROM player_regions pr
  WHERE pr.player_id = p_player_id
    AND pr.region_id = p_region_id;

  -- Không tồn tại region này cho player
  IF v_player_region_id IS NULL THEN
    RETURN json_build_object(
      'error', 'PLAYER_REGION_NOT_FOUND'
    );
  END IF;

  -- 2. Collect logic (y hệt trước)
  WITH calc AS (
    SELECT
      rr.id,
      GREATEST(
        0,
        LEAST(
          (
            EXTRACT(EPOCH FROM (now() - rr.last_collected_at))
            * bp.production_rate_per_hour / 3600.0
            * bp.efficiency_percent / 100.0
          )::int,
          rr.max_amount - rr.amount
        )
      ) AS produced
    FROM region_resources rr
    JOIN player_region_buildings prb
      ON prb.player_region_id = rr.player_region_id
    JOIN building_production bp
      ON bp.building_type = prb.building_type
     AND bp.level = prb.level
    WHERE rr.player_region_id = v_player_region_id
      AND rr.resource_code = p_resource_code
      AND prb.upgrading = false
    LIMIT 1
  )
  UPDATE region_resources rr
  SET
    amount = rr.amount + calc.produced,
    last_collected_at = now()
  FROM calc
  WHERE rr.id = calc.id
  RETURNING calc.produced INTO v_collected;

  -- 3. Return JSON
  RETURN json_build_object(
    'player_id', p_player_id,
    'region_id', p_region_id,
    'resource_code', p_resource_code,
    'collected', COALESCE(v_collected, 0),
    'collected_at', now()
  );
END;
$$;


ALTER FUNCTION public.collect_single_resource(p_player_id uuid, p_region_id text, p_resource_code character varying) OWNER TO postgres;

--
-- Name: complete_building_if_done(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_building_if_done() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Nếu completed_at <= now() và status vẫn là building
    IF NEW.status = 'building' AND NEW.completed_at <= CURRENT_TIMESTAMP THEN
        NEW.status := 'completed';
        NEW.updated_at := CURRENT_TIMESTAMP;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.complete_building_if_done() OWNER TO postgres;

--
-- Name: complete_login_quest(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_login_quest(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_quest_id uuid;
    v_completed_at timestamp;
    result jsonb;
BEGIN
    -- Lấy quest login phù hợp level player
    SELECT q.id
    INTO v_quest_id
    FROM public.players pl
    CROSS JOIN public.quests q
    WHERE pl.id = p_player_id
      AND q.category = 'daily'
      AND q.type = 'login'
      AND q.min_level <= pl.level
      AND q.max_level >= pl.level
    LIMIT 1;

    -- Hoàn thành quest: insert hoặc update
    v_completed_at := now();

    INSERT INTO public.player_quest_progress(player_id, quest_id, progress, target, completed, completed_at)
    VALUES (p_player_id, v_quest_id, 1, 1, true, v_completed_at)
    ON CONFLICT (player_id, quest_id) DO UPDATE
    SET progress = 1,
        completed = true,
        completed_at = v_completed_at;

    -- Lấy JSON quest vừa hoàn thành
    SELECT jsonb_build_object(
        'quest_id', q.id,
        'quest_name', q.name,
        'description', q.description,
        'type', q.type,
        'category', q.category,
        'difficulty', q.difficulty,
        'progress', COALESCE(pqp.progress, 1),
        'completed', COALESCE(pqp.completed, true),
        'claimed', COALESCE(pqp.claimed, false),
        'completed_at', COALESCE(pqp.completed_at, v_completed_at)
    )
    INTO result
    FROM public.quests q
    LEFT JOIN public.player_quest_progress pqp
      ON pqp.quest_id = q.id
      AND pqp.player_id = p_player_id
    WHERE q.id = v_quest_id;

    RETURN result;
END;
$$;


ALTER FUNCTION public.complete_login_quest(p_player_id uuid) OWNER TO postgres;

