--
-- Name: complete_training(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_training(p_queue_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_queue unit_training_queue%ROWTYPE;
    v_player_id uuid;
    v_region_id text;
BEGIN

-- lấy queue
SELECT *
INTO v_queue
FROM unit_training_queue
WHERE id = p_queue_id;

IF NOT FOUND THEN
    RETURN 'Queue không tồn tại';
END IF;

-- chưa tới thời gian
IF now() < v_queue.finish_at THEN
    RETURN 'Chưa hoàn thành đào tạo';
END IF;

-- lấy player + region
SELECT pr.player_id, pr.region_id
INTO v_player_id, v_region_id
FROM player_region_buildings b
JOIN player_regions pr
ON pr.id = b.player_region_id
WHERE b.id = v_queue.player_region_building_id;

-- cộng quân
PERFORM public.add_region_troops(
    v_player_id,
    v_region_id,
    v_queue.unit_type,
    v_queue.quantity
);

-- xóa queue (vì đã hoàn thành)
DELETE FROM unit_training_queue
WHERE id = p_queue_id;

RETURN 'Đào tạo hoàn thành';

END;
$$;


ALTER FUNCTION public.complete_training(p_queue_id uuid) OWNER TO postgres;

