CREATE FUNCTION public.create_alliance(p_player_id uuid, p_name character varying, p_tag character varying, p_description text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alliance_id uuid;
BEGIN
    -- tạo alliance
    INSERT INTO alliances (
        name, tag, description, leader
    )
    VALUES (
        p_name, p_tag, p_description, p_player_id
    )
    RETURNING id INTO v_alliance_id;

    -- add leader vào member
    INSERT INTO alliance_members (
        alliance_id, player_id, role
    )
    VALUES (
        v_alliance_id, p_player_id, 'leader'
    );

    RETURN json_build_object(
        'success', true,
        'allianceId', v_alliance_id
    );
END;
$$;


