--
-- Name: create_battle_challenge(uuid, uuid, text, jsonb, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_battle_challenge(p_challenger_id uuid, p_target_id uuid, p_challenge_type text, p_heroes jsonb, p_soldiers jsonb, p_bet_amount bigint DEFAULT 0, p_message text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- 🔹 Opportunistic expire: chỉ 1 pending gần nhất (nếu đã hết hạn)
  PERFORM expire_latest_pending_challenge_for_pair(
    p_challenger_id,
    p_target_id
  );

  -- 🔹 Create new challenge
  INSERT INTO battle_challenges (
    challenger_id,
    target_id,
    challenge_type,
    challenger_heroes,
    challenger_soldiers,
    bet_amount,
    message
  )
  VALUES (
    p_challenger_id,
    p_target_id,
    p_challenge_type,
    p_heroes,
    p_soldiers,
    p_bet_amount,
    p_message
  )
  RETURNING id INTO v_id;

  -- 🔔 Insert notification for target player
  INSERT INTO game_notifications (
    player_id,
    type,
    title,
    content,
    payload
  )
  VALUES (
    p_target_id,
    'challenge',
    'Chiến thư mới',
    'Bạn nhận được một lời thách đấu',
    jsonb_build_object(
      'challenge_id', v_id,
      'challenger_id', p_challenger_id,
      'challenge_type', p_challenge_type,
      'bet_amount', p_bet_amount
    )
  );

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.create_battle_challenge(p_challenger_id uuid, p_target_id uuid, p_challenge_type text, p_heroes jsonb, p_soldiers jsonb, p_bet_amount bigint, p_message text) OWNER TO postgres;

--
-- Name: create_battle_with_target(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_battle_with_target(p_challenger_id uuid, p_target_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_battle_id uuid;
BEGIN
  -- 1️⃣ Validate
  IF p_challenger_id = p_target_id THEN
    RAISE EXCEPTION 'Cannot create battle with self';
  END IF;

  -- 2️⃣ Create battle (solo vs bản sao)
  INSERT INTO battles (
    battle_type,
    status,
    player1_id,
    player2_id,
    player1_bet_amount,
    player2_bet_amount,
    created_at
  )
  VALUES (
    'challenge',     -- hoặc 'solo' nếu bạn muốn tách rõ
    'ready',
    p_challenger_id,
    p_target_id,     -- lưu để trace opponent gốc
    0,
    0,
    now()
  )
  RETURNING id INTO v_battle_id;

  -- 3️⃣ 🔔 Notify ONLY challenger
  PERFORM notify_enter_battle(
    p_challenger_id,   -- player
    v_battle_id,       -- battle
    p_target_id,       -- opponent (bản sao)
    'Chuẩn bị chiến đấu',
    NULL               -- challenge_id → "không có"
  );

  -- 4️⃣ Done
  RETURN v_battle_id;
END;
$$;


ALTER FUNCTION public.create_battle_with_target(p_challenger_id uuid, p_target_id uuid) OWNER TO postgres;

--
-- Name: create_boss_battle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_boss_battle(p_player_id uuid, p_boss_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles;
    v_region_id text;
    v_result jsonb;
BEGIN
    -- Lấy region attacker từ region_generals
    SELECT region_id
    INTO v_region_id
    FROM public.region_generals
    WHERE player_id = p_player_id
      AND battle_role = 'offense'
      AND is_active = true
    LIMIT 1;

    IF v_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % has no active offense region', p_player_id;
    END IF;


    -- Kiểm tra boss tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM public.bosses
        WHERE id = p_boss_id
    ) THEN
        RAISE EXCEPTION 'Boss % not found', p_boss_id;
    END IF;


    -- Tạo battle
    INSERT INTO public.battles (
        battle_type,
        status,
        player1_id,
        player1_region_id,
        boss_id
    )
    VALUES (
        'boss',
        'in_progress',
        p_player_id,
        v_region_id,
        p_boss_id
    )
    RETURNING *
    INTO v_battle;


    -- Chuyển quân vào combat
    PERFORM public.move_troops_to_combat(
        v_battle.id,
        v_region_id,
        p_player_id,
        'attacker'
    );


    -- Return JSON
    SELECT jsonb_build_object(
        'battle',
        to_jsonb(v_battle),

        'combat_troops',
        COALESCE(
            (
                SELECT jsonb_agg(ct)
                FROM public.combat_troops ct
                WHERE ct.battle_id = v_battle.id
            ),
            '[]'::jsonb
        )
    )
    INTO v_result;


    RETURN v_result;
END;
$$;


ALTER FUNCTION public.create_boss_battle(p_player_id uuid, p_boss_id uuid) OWNER TO postgres;

--
-- Name: create_pvp_battle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_pvp_battle(p_player1_id uuid, p_player2_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles;
    v_player1_region text;
    v_player2_region text;
    v_result jsonb;
BEGIN
    -- Lấy region attacker
    SELECT region_id
    INTO v_player1_region
    FROM public.region_generals
    WHERE player_id = p_player1_id
      AND battle_role = 'offense'
      AND is_active = true
    LIMIT 1;

    IF v_player1_region IS NULL THEN
        RAISE EXCEPTION 'Player % has no active offense region', p_player1_id;
    END IF;


    -- Lấy region defender
    SELECT region_id
    INTO v_player2_region
    FROM public.region_generals
    WHERE player_id = p_player2_id
      AND battle_role = 'defense'
      AND is_active = true
    LIMIT 1;

    IF v_player2_region IS NULL THEN
        RAISE EXCEPTION 'Player % has no active defense region', p_player2_id;
    END IF;


    -- Tạo battle
    INSERT INTO public.battles (
        battle_type,
        status,
        player1_id,
        player1_region_id,
        player2_id,
        player2_region_id
    )
    VALUES (
        'ranked',
        'in_progress',
        p_player1_id,
        v_player1_region,
        p_player2_id,
        v_player2_region
    )
    RETURNING *
    INTO v_battle;


    -- Chuyển quân player 1
    PERFORM public.move_troops_to_combat(
        v_battle.id,
        v_player1_region,
        p_player1_id,
        'attacker'
    );


    -- Chuyển quân player 2
    PERFORM public.move_troops_to_combat(
        v_battle.id,
        v_player2_region,
        p_player2_id,
        'defender'
    );


    -- Trả JSON
    SELECT jsonb_build_object(
        'battle',
        to_jsonb(v_battle),

        'combat_troops',
        COALESCE(
            (
                SELECT jsonb_agg(ct)
                FROM public.combat_troops ct
                WHERE ct.battle_id = v_battle.id
            ),
            '[]'::jsonb
        )
    )
    INTO v_result;


    RETURN v_result;
END;
$$;


ALTER FUNCTION public.create_pvp_battle(p_player1_id uuid, p_player2_id uuid) OWNER TO postgres;

