-- Name: decline_battle_challenge(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decline_battle_challenge(p_challenge_id uuid, p_player_id uuid, p_message text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE battle_challenges
  SET status = 'declined',
      response_message = p_message,
      responded_at = now()
  WHERE id = p_challenge_id
    AND target_id = p_player_id
    AND status = 'pending';

  RETURN FOUND;
END;
$$;


