--
-- Name: destroy_building_strict(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.destroy_building_strict(p_player_id uuid, p_region_id character varying, p_region_slot_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
    v_building_id uuid;
BEGIN
    -- 1️⃣ Lấy player_region
    SELECT pr.id
    INTO v_player_region_id
    FROM player_regions pr
    WHERE pr.player_id = p_player_id
      AND pr.region_id = p_region_id
      AND pr.is_active = true
    LIMIT 1;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player region not found';
    END IF;

    -- 2️⃣ Lấy building từ slot (lock row)
    SELECT rs.occupied_building_id
    INTO v_building_id
    FROM region_slots rs
    WHERE rs.id = p_region_slot_id
      AND rs.player_region_id = v_player_region_id
    FOR UPDATE;

    IF v_building_id IS NULL THEN
        RAISE EXCEPTION 'No building in this slot';
    END IF;

    -- 3️⃣ Xóa building
    DELETE FROM player_region_buildings
    WHERE id = v_building_id;

    -- 4️⃣ Clear slot
    UPDATE region_slots
    SET occupied_building_id = NULL
    WHERE id = p_region_slot_id;

    RETURN v_building_id;
END;
$$;


ALTER FUNCTION public.destroy_building_strict(p_player_id uuid, p_region_id character varying, p_region_slot_id uuid) OWNER TO postgres;

