--
-- Name: end_turn(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.end_turn(p_battle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles%ROWTYPE;
    v_next_player_id uuid;
    v_new_turn integer;
    v_new_job_id bigint := NULL;
BEGIN

    SELECT *
    INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION 'Battle not found';
    END IF;


    -- Hủy cron timeout cũ nếu có
    IF v_battle.timeout_job_id IS NOT NULL THEN
        PERFORM cron.unschedule(
            v_battle.timeout_job_id
        );
    END IF;


    v_new_turn := v_battle.current_turn + 1;


    -- Xác định lượt tiếp theo
    IF v_battle.player_id_turn = v_battle.player1_id THEN
        v_next_player_id := v_battle.player2_id;
    ELSE
        v_next_player_id := v_battle.player1_id;
    END IF;


    -- Hết giới hạn turn
    IF v_new_turn > 50 THEN

        UPDATE public.battles
        SET
            current_turn = v_new_turn,
            status = 'completed',
            ended_at = now(),
            player_id_turn = NULL,
            timeout_job_id = NULL,
            last_turn_at = now()
        WHERE id = p_battle_id;


        RETURN jsonb_build_object(
            'success', true,
            'battle_end', true,
            'reason', 'max_turn_reached',
            'current_turn', v_new_turn
        );

    END IF;


    -- Chuyển sang lượt mới
    UPDATE public.battles
    SET
        current_turn = v_new_turn,
        player_id_turn = v_next_player_id,
        last_turn_at = now(),
        timeout_job_id = NULL
    WHERE id = p_battle_id;


    /*
       Tạo timeout cron mới

       Tạm dùng cron chạy mỗi phút để test.
       Sau này thay bằng scheduler phù hợp hơn.
    */
    SELECT cron.schedule(
        'battle_timeout_' || p_battle_id::text,
        '* * * * *',
        format(
            'SELECT public.end_turn(''%s''::uuid);',
            p_battle_id
        )
    )
    INTO v_new_job_id;


    UPDATE public.battles
    SET timeout_job_id = v_new_job_id
    WHERE id = p_battle_id;


    RETURN jsonb_build_object(
        'success', true,
        'battle_end', false,
        'current_turn', v_new_turn,
        'next_player_id', v_next_player_id,
        'timeout_job_id', v_new_job_id
    );

END;
$$;


ALTER FUNCTION public.end_turn(p_battle_id uuid) OWNER TO postgres;

--
-- Name: enrich_reward_metadata(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enrich_reward_metadata(p_rewards jsonb) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT jsonb_agg(
    CASE r->>'type'
        WHEN 'item' THEN
            jsonb_build_object(
                'type', 'item',
                'id', r->>'id',
                'amount', (r->>'amount')::int,
                'name', bi.name,
                'description', bi.description,
                'rarity', bi.rarity,
                'icon', bi.svg_icon
            )
        WHEN 'currency' THEN
            jsonb_build_object(
                'type', 'currency',
                'id', r->>'id',
                'amount', (r->>'amount')::int,
                'name', c.name,
                'description', c.description,
                'icon', c.icon
            )
        ELSE
            r
    END
)
FROM jsonb_array_elements(p_rewards) r
LEFT JOIN base_items bi ON bi.id = r->>'id' AND r->>'type' = 'item'
LEFT JOIN currencies c ON c.currency_type = r->>'id' AND r->>'type' = 'currency';
$$;


ALTER FUNCTION public.enrich_reward_metadata(p_rewards jsonb) OWNER TO postgres;

--
-- Name: equip_general_item_by_player(uuid, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equip_general_item_by_player(p_player_id uuid, p_general_id text, p_item_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_player_general_id uuid;
    v_item_type public.item_type;
    v_slot_column text;
BEGIN
    BEGIN
        -- sanitize input
        p_item_id := trim(lower(p_item_id));

        -- 1. Resolve player_general_id
        SELECT id
        INTO v_player_general_id
        FROM player_generals
        WHERE player_id = p_player_id
          AND general_id = p_general_id;

        IF v_player_general_id IS NULL THEN
            RETURN jsonb_build_object('status', 'error', 'message', format('General % does not belong to player %', p_general_id, p_player_id));
        END IF;

        -- 2. Get item type
        SELECT type
        INTO v_item_type
        FROM base_items
        WHERE lower(id) = p_item_id;

        IF v_item_type IS NULL THEN
            RETURN jsonb_build_object('status', 'error', 'message', format('Item % does not exist', p_item_id));
        END IF;

        -- 3. Only allow general_*
        IF v_item_type::text NOT LIKE 'general_%' THEN
            RETURN jsonb_build_object('status', 'error', 'message', format('Item % is not a general equipment', p_item_id));
        END IF;

        -- 4. Map type → slot
        v_slot_column := CASE v_item_type::text
            WHEN 'general_weapon' THEN 'weapon_id'
            WHEN 'general_armor' THEN 'armor_id'
            WHEN 'general_helmet' THEN 'helmet_id'
            WHEN 'general_cloak' THEN 'cloak_id'
            WHEN 'general_boots' THEN 'boots_id'
            WHEN 'general_ring1' THEN 'ring_id'
            WHEN 'general_ring2' THEN 'ring_id'
            WHEN 'general_shield' THEN 'shield_id'
            WHEN 'general_accessory' THEN 'ring_id'
            ELSE NULL
        END;

        IF v_slot_column IS NULL THEN
            RETURN jsonb_build_object('status', 'error', 'message', format('Unsupported general item type: %', v_item_type));
        END IF;

        -- 5. Ensure equipment row exists
        INSERT INTO equipment_items (player_general_id, is_equipped)
        VALUES (v_player_general_id, true)
        ON CONFLICT (player_general_id) DO NOTHING;

        -- 6. Equip slot
        EXECUTE format(
            'UPDATE equipment_items
             SET %I = $1,
                 is_equipped = true,
                 updated_at = now()
             WHERE player_general_id = $2',
            v_slot_column
        )
        USING p_item_id, v_player_general_id;

        -- 7. Return success
        RETURN jsonb_build_object('status', 'success');

    EXCEPTION WHEN OTHERS THEN
        RETURN jsonb_build_object('status', 'error', 'message', SQLERRM);
    END;
END;
$_$;


ALTER FUNCTION public.equip_general_item_by_player(p_player_id uuid, p_general_id text, p_item_id character varying) OWNER TO postgres;

--
-- Name: equip_item(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equip_item(p_player_id uuid, p_general_id uuid, p_item_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    hero_id uuid;
    inserted_item jsonb;
BEGIN
    -- Lấy player_general_id dựa trên player_id và general_id
    SELECT id INTO hero_id
    FROM public.player_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id
    LIMIT 1;

    IF hero_id IS NULL THEN
        RAISE EXCEPTION 'No hero found for player % with general %', p_player_id, p_general_id;
    END IF;

    -- Thêm item mới cho hero
    INSERT INTO public.equipment_items (
        id,
        player_general_id,
        is_equipped,
        created_at,
        updated_at
    ) VALUES (
        p_item_id,
        hero_id,
        true,
        now(),
        now()
    )
    RETURNING to_jsonb(public.equipment_items.*) INTO inserted_item;

    RETURN inserted_item;
END;
$$;


ALTER FUNCTION public.equip_item(p_player_id uuid, p_general_id uuid, p_item_id character varying) OWNER TO postgres;

--
-- Name: equip_item_to_unit(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equip_item_to_unit(p_player_id uuid, p_unit_id character varying, p_item_id character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_player_unit player_units;
    v_item base_items;
    v_slot text;
BEGIN

    ------------------------------------------------------------------
    -- 1️⃣ Lock unit
    ------------------------------------------------------------------
    SELECT *
    INTO v_player_unit
    FROM player_units
    WHERE player_id = p_player_id
      AND unit_id = p_unit_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player does not own this unit';
    END IF;

    ------------------------------------------------------------------
    -- 2️⃣ Lock inventory item
    ------------------------------------------------------------------
    PERFORM 1
    FROM player_items
    WHERE player_id = p_player_id
      AND item_id = p_item_id
      AND quantity > 0
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player does not own this item';
    END IF;

    ------------------------------------------------------------------
    -- 3️⃣ Get base item
    ------------------------------------------------------------------
    SELECT *
    INTO v_item
    FROM base_items
    WHERE id = p_item_id
      AND status = 'active';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Item not found or inactive';
    END IF;

    ------------------------------------------------------------------
    -- 4️⃣ Whitelist allowed item types for soldier
    ------------------------------------------------------------------
    IF v_item.type NOT IN (
        'weapon',
        'armor',
        'soldier_weapon',
        'soldier_armor',
        'helmet',
        'cloak',
        'boots',
        'shield',
        'mount',
        'accessory',
        'ring1',
        'ring2',
        'soldier_special_item',
        'siege_equipment',
        'artifact',
        'relic',
        'totem'
    ) THEN
        RAISE EXCEPTION
            'Item type % cannot be equipped by soldier unit',
            v_item.type;
    END IF;

    ------------------------------------------------------------------
    -- 5️⃣ Check level requirement
    ------------------------------------------------------------------
    IF v_player_unit.level < v_item.level_requirement THEN
        RAISE EXCEPTION
            'Unit level % is lower than item requirement %',
            v_player_unit.level,
            v_item.level_requirement;
    END IF;

    ------------------------------------------------------------------
    -- 6️⃣ Map type → slot
    ------------------------------------------------------------------
    v_slot := CASE v_item.type

        -- Weapon group
        WHEN 'weapon' THEN 'weapon_item_id'
        WHEN 'soldier_weapon' THEN 'weapon_item_id'
        WHEN 'siege_equipment' THEN 'weapon_item_id'

        -- Armor group
        WHEN 'armor' THEN 'armor_item_id'
        WHEN 'soldier_armor' THEN 'armor_item_id'

        -- Specific slots
        WHEN 'helmet' THEN 'helmet_item_id'
        WHEN 'cloak' THEN 'cloak_item_id'
        WHEN 'boots' THEN 'boots_item_id'
        WHEN 'shield' THEN 'shield_item_id'
        WHEN 'mount' THEN 'mount_item_id'
        WHEN 'ring1' THEN 'ring1_item_id'
        WHEN 'ring2' THEN 'ring2_item_id'

        -- Accessory group
        WHEN 'accessory' THEN 'accessory_item_id'
        WHEN 'soldier_special_item' THEN 'accessory_item_id'
        WHEN 'artifact' THEN 'accessory_item_id'
        WHEN 'relic' THEN 'accessory_item_id'
        WHEN 'totem' THEN 'accessory_item_id'

        ELSE NULL
    END;

    IF v_slot IS NULL THEN
        RAISE EXCEPTION
            'No slot mapping for item type %',
            v_item.type;
    END IF;

    ------------------------------------------------------------------
    -- 7️⃣ Equip item
    ------------------------------------------------------------------
    EXECUTE format(
        'UPDATE player_units SET %I = $1 WHERE id = $2',
        v_slot
    )
    USING p_item_id, v_player_unit.id;

END;
$_$;


ALTER FUNCTION public.equip_item_to_unit(p_player_id uuid, p_unit_id character varying, p_item_id character varying) OWNER TO postgres;

--
-- Name: execute_transaction(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.execute_transaction(p_player_id uuid, p_cost_ops jsonb DEFAULT '[]'::jsonb, p_reward_ops jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validate JSON
    IF jsonb_typeof(p_cost_ops) <> 'array' THEN
        RAISE EXCEPTION 'p_cost_ops must be a JSON array';
    END IF;

    IF jsonb_typeof(p_reward_ops) <> 'array' THEN
        RAISE EXCEPTION 'p_reward_ops must be a JSON array';
    END IF;

    -- 1️⃣ Trừ tài nguyên (FAIL → ROLLBACK)
    IF jsonb_array_length(p_cost_ops) > 0 THEN
        PERFORM subtract_execute(p_player_id, p_cost_ops);
    END IF;

    -- 2️⃣ Grant reward (FAIL → ROLLBACK cả phần trừ)
    IF jsonb_array_length(p_reward_ops) > 0 THEN
        PERFORM grant_rewards_from_json_full(
            p_player_id,
            p_reward_ops
        );
    END IF;
END;
$$;


ALTER FUNCTION public.execute_transaction(p_player_id uuid, p_cost_ops jsonb, p_reward_ops jsonb) OWNER TO postgres;

--
-- Name: expire_battle_challenges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_battle_challenges() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE battle_challenges
  SET status = 'expired'
  WHERE status = 'pending'
    AND expires_at < now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.expire_battle_challenges() OWNER TO postgres;

--
-- Name: expire_latest_pending_challenge_for_pair(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_latest_pending_challenge_for_pair(p_challenger_id uuid, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE battle_challenges
  SET status = 'expired'
  WHERE id = (
    SELECT id
    FROM battle_challenges
    WHERE status = 'pending'
      AND expires_at < now()
      AND challenger_id = p_challenger_id
      AND target_id = p_target_id
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE
  );

  RETURN FOUND;
END;
$$;


