--
-- Name: fake_loot_box_rewards_json(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fake_loot_box_rewards_json() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    i int;
    rewards jsonb := '[]'::jsonb;
    reward_type text;
    rarity text;
    bound_type text;
    currency_type text;
    item_id text;
    item_name text;
    amount_min int;
    amount_max int;
    item_types text[] := ARRAY['item', 'currency', 'experience', 'vip_points', 'alliance_points', 'cosmetic', 'title', 'mount', 'pet', 'skill_point', 'stat_point'];
    rarities text[] := ARRAY['common', 'uncommon', 'rare', 'epic', 'legendary', 'mythic', 'ancient', 'divine'];
    bound_types text[] := ARRAY['none', 'account', 'character'];
    currency_types text[] := ARRAY['gold', 'silver', 'gems'];
BEGIN
    FOR i IN 1..50 LOOP  -- generate 50 fake rewards
        reward_type := item_types[1 + floor(random() * array_length(item_types,1))::int];
        rarity := rarities[1 + floor(random() * array_length(rarities,1))::int];
        bound_type := bound_types[1 + floor(random() * array_length(bound_types,1))::int];
        amount_min := 1 + floor(random() * 5)::int;
        amount_max := amount_min + floor(random() * 5)::int;

        -- generate fake item_id and item_name even for non-item rewards
        item_id := 'fake_item_' || (1 + floor(random() * 1000)::int);
        item_name := 'Fake Item Name ' || (1 + floor(random() * 1000)::int);

        -- currency_type only for non-item rewards
        IF reward_type = 'item' THEN
            currency_type := NULL;
        ELSE
            currency_type := currency_types[1 + floor(random() * array_length(currency_types,1))::int];
        END IF;

        rewards := rewards || jsonb_build_object(
            'reward_id', 'fake_reward_' || i,
            'reward_type', reward_type,
            'item_id', item_id,
            'item_name', item_name,
            'currency_type', currency_type,
            'amount_min', amount_min,
            'amount_max', amount_max,
            'rarity', rarity,
            'bound_type', bound_type
        );
    END LOOP;

    RETURN rewards;
END;
$$;


ALTER FUNCTION public.fake_loot_box_rewards_json() OWNER TO postgres;

--
-- Name: find_match_target_popup(uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_match_target_popup(p_player_id uuid, p_power bigint, p_level integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_target players;
  v_locked boolean;
BEGIN
  SELECT p.*
  INTO v_target
  FROM players p
  WHERE p.id != p_player_id
    AND p.status = 'offline'
    AND NOT EXISTS (
      SELECT 1 FROM matchmaking_locks l
      WHERE l.player_id = p.id
        AND l.locked_until > now()
    )
    AND NOT EXISTS (
      SELECT 1
      FROM battles b
      WHERE (b.player1_id = p.id OR b.player2_id = p.id)
        AND b.created_at >= now() - interval '1 hour'
    )
  ORDER BY abs(p.power - p_power)
  LIMIT 1;

  IF v_target.id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  INSERT INTO matchmaking_locks (player_id, locked_by, locked_until)
  VALUES (
    v_target.id,
    p_player_id,
    now() + interval '30 seconds'
  )
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_locked = ROW_COUNT;

  IF NOT v_locked THEN
    -- target bị người khác lock trước đó
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'player', to_jsonb(v_target),
    'expires_at', now() + interval '30 seconds'
  );
END;
$$;


ALTER FUNCTION public.find_match_target_popup(p_player_id uuid, p_power bigint, p_level integer) OWNER TO postgres;

--
-- Name: find_opponents(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_opponents(p_player_id uuid, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  my_power int;
BEGIN
  -- 1. Tổng sức mạnh tướng của player
  SELECT get_player_general_power(p_player_id)
  INTO my_power;

  IF my_power = 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  -- 2. Trả về danh sách đối thủ
  RETURN (
    SELECT jsonb_agg(
      jsonb_build_object(
        'opponent_id', p.id,
        'opponent_power', opp_power,
        'power_diff_percent',
          ROUND(((opp_power - my_power)::numeric / my_power) * 100, 2),
        'difficulty',
          CASE
            WHEN ((opp_power - my_power)::numeric / my_power) * 100 <= -10
              THEN 'easy'
            WHEN ((opp_power - my_power)::numeric / my_power) * 100 >= 10
              THEN 'hard'
            ELSE 'normal'
          END
      )
    )
    FROM (
      SELECT
        pl.id,
        get_player_general_power(pl.id) AS opp_power
      FROM players pl
      WHERE pl.id <> p_player_id
      ORDER BY abs(get_player_general_power(pl.id) - my_power)
      LIMIT p_limit
    ) p
  );
END;
$$;


ALTER FUNCTION public.find_opponents(p_player_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: find_views(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_views(search_text text) RETURNS TABLE(schema_name text, view_name text, definition text)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    schemaname::text as schema_name,
    viewname::text as view_name,
    definition::text
  from pg_views
  where schemaname = 'public'
    and (
      viewname ilike '%' || search_text || '%'
      or definition ilike '%' || search_text || '%'
    )
  order by viewname;
$$;


