--
-- Name: finish_all_upgrades(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_all_upgrades(p_player_id uuid, p_region_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_id UUID;
    v_upgraded_buildings JSONB;
    v_count INT := 0;
    v_building RECORD;
BEGIN
    -- 1. Lấy player_region_id
    SELECT id INTO v_region_id
    FROM player_regions
    WHERE player_id = p_player_id 
      AND region_id = p_region_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Region not found or player does not own this region'
        );
    END IF;

    -- 2. Hoàn thành tất cả upgrades đang tiến hành
    WITH updated_buildings AS (
        UPDATE player_region_buildings prb
        SET 
            level = level + 1,
            upgrading = false,
            upgrade_finish_at = NULL
        WHERE prb.player_region_id = v_region_id
          AND prb.upgrading = true
          AND prb.upgrade_finish_at IS NOT NULL
          -- Chỉ nâng cấp nếu chưa đạt max level
          AND prb.level < (
              SELECT bb.max_level 
              FROM base_buildings bb 
              WHERE bb.type = prb.building_type
          )
        RETURNING 
            prb.id,
            prb.building_type,
            prb.level - 1 as old_level,
            prb.level as new_level,
            prb.upgrade_finish_at as original_finish_time
    )
    SELECT 
        jsonb_agg(
            jsonb_build_object(
                'player_building_id', ub.id,
                'building_type', ub.building_type,
                'old_level', ub.old_level,
                'new_level', ub.new_level,
                'original_finish_time', ub.original_finish_time,
                'completed_at', NOW()
            )
        ),
        COUNT(*)
    INTO v_upgraded_buildings, v_count
    FROM updated_buildings ub;

    -- 3. Trả kết quả
    RETURN json_build_object(
        'success', true,
        'message', 
            CASE 
                WHEN v_count > 0 
                THEN format('%s công trình đã được hoàn thành nâng cấp', v_count)
                ELSE 'Không có công trình nào đang nâng cấp'
            END,
        'player_id', p_player_id,
        'region_id', p_region_id,
        'total_upgrades_completed', v_count,
        'upgraded_buildings', COALESCE(v_upgraded_buildings, '[]'::JSONB),
        'completed_at', NOW()
    );

EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'success', false,
        'message', 'Error finishing upgrades: ' || SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;


ALTER FUNCTION public.finish_all_upgrades(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: finish_upgrade_building(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_upgrade_building(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_base_building RECORD;
BEGIN
    -- 1. Lấy building
    SELECT * INTO v_building
    FROM player_region_buildings
    WHERE id = p_player_building_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2. Kiểm tra đang upgrading không
    IF NOT v_building.upgrading THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building is not currently upgrading',
            'level', v_building.level
        );
    END IF;

    -- 3. Kiểm tra đã đến thời gian kết thúc upgrade chưa
    IF v_building.upgrade_finish_at > now() THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Upgrade is not finished yet',
            'level', v_building.level,
            'upgrade_finish_at', v_building.upgrade_finish_at
        );
    END IF;

    -- 4. Lấy max_level từ base_buildings
    SELECT * INTO v_base_building
    FROM base_buildings
    WHERE "type" = v_building.building_type;

    -- 5. Update building: level++, upgrading = false
    IF v_building.level < v_base_building.max_level THEN
        UPDATE player_region_buildings
        SET level = level + 1,
            upgrading = FALSE,
            upgrade_finish_at = NULL
        WHERE id = p_player_building_id
        RETURNING id, level, upgrading, upgrade_finish_at
        INTO v_building;
    ELSE
        -- Nếu level đã max, chỉ reset upgrading
        UPDATE player_region_buildings
        SET upgrading = FALSE,
            upgrade_finish_at = NULL
        WHERE id = p_player_building_id
        RETURNING id, level, upgrading, upgrade_finish_at
        INTO v_building;
    END IF;

    -- 6. Trả JSON
    RETURN json_build_object(
        'success', true,
        'message', 'Upgrade finished successfully',
        'building_id', v_building.id,
        'level', v_building.level,
        'upgrading', v_building.upgrading,
        'upgrade_finish_at', v_building.upgrade_finish_at
    );
END;
$$;


ALTER FUNCTION public.finish_upgrade_building(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: finish_upgrades_by_type(uuid, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_upgrades_by_type(p_player_id uuid, p_region_id text, p_building_type character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_id UUID;
    v_upgraded_buildings JSONB;
    v_count INT := 0;
BEGIN
    -- 1. Lấy player_region_id
    SELECT id INTO v_region_id
    FROM player_regions
    WHERE player_id = p_player_id 
      AND region_id = p_region_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Region not found'
        );
    END IF;

    -- 2. Hoàn thành upgrades theo loại
    WITH updated_buildings AS (
        UPDATE player_region_buildings prb
        SET 
            level = level + 1,
            upgrading = false,
            upgrade_finish_at = NULL
        WHERE prb.player_region_id = v_region_id
          AND prb.building_type = p_building_type
          AND prb.upgrading = true
          AND prb.upgrade_finish_at IS NOT NULL
          AND prb.level < (
              SELECT bb.max_level 
              FROM base_buildings bb 
              WHERE bb.type = p_building_type
          )
        RETURNING 
            prb.id,
            prb.building_type,
            prb.level - 1 as old_level,
            prb.level as new_level
    )
    SELECT 
        jsonb_agg(
            jsonb_build_object(
                'player_building_id', ub.id,
                'building_type', ub.building_type,
                'old_level', ub.old_level,
                'new_level', ub.new_level
            )
        ),
        COUNT(*)
    INTO v_upgraded_buildings, v_count
    FROM updated_buildings ub;

    -- 3. Trả kết quả
    RETURN json_build_object(
        'success', true,
        'message', 
            CASE 
                WHEN v_count > 0 
                THEN format('%s công trình %s đã được hoàn thành nâng cấp', 
                           v_count, p_building_type)
                ELSE format('Không có công trình %s nào đang nâng cấp', p_building_type)
            END,
        'total_completed', v_count,
        'building_type', p_building_type,
        'upgraded_buildings', COALESCE(v_upgraded_buildings, '[]'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.finish_upgrades_by_type(p_player_id uuid, p_region_id text, p_building_type character varying) OWNER TO postgres;

