--
-- Name: generate_loot_box_reward(uuid, text, boolean, boolean, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_loot_box_reward(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_force_rare boolean, p_streak_multiplier numeric, p_pity_counter integer) RETURNS TABLE(reward_data jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reward_table_id TEXT;
    v_selected_pool_id TEXT;
    v_selected_item_id TEXT;
    v_reward JSONB;
    v_rarity TEXT;
BEGIN
    -- [1] Select reward table based on conditions
    v_reward_table_id := select_reward_table(
        p_loot_box_id,
        p_is_first_time,
        p_pity_force_rare,
        p_streak_multiplier
    );

    -- [2] Select reward pool from table
    v_selected_pool_id := select_reward_pool(
        v_reward_table_id,
        p_pity_force_rare,
        p_pity_counter
    );

    -- [3] Select item from pool
    SELECT reward_item_id, rarity INTO v_selected_item_id, v_rarity
    FROM select_reward_item(v_selected_pool_id);

    -- [4] Apply drop conditions
    v_selected_item_id := apply_drop_conditions(
        p_player_id,
        v_selected_item_id,
        v_reward_table_id
    );

    -- [5] Apply multipliers
    v_reward := jsonb_build_object(
        'item_id', v_selected_item_id,
        'rarity', v_rarity,
        'amount', calculate_reward_amount(v_selected_item_id, p_streak_multiplier),
        'is_guaranteed', p_pity_force_rare,
        'is_boosted', p_streak_multiplier > 1.0,
        'is_first_time', p_is_first_time,
        'pity_counter_reset', p_pity_force_rare,
        'timestamp', NOW()
    );

    RETURN QUERY SELECT v_reward;
END;
$$;


ALTER FUNCTION public.generate_loot_box_reward(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_force_rare boolean, p_streak_multiplier numeric, p_pity_counter integer) OWNER TO postgres;

--
-- Name: generate_random_event(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_random_event(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_types varchar[] := ARRAY['raid', 'harvest', 'rebellion', 'natural_disaster', 'trade_opportunity', 'diplomatic_visit'];
    random_type varchar;
    severity integer;
    duration_hours integer;
    effects_json JSONB;
BEGIN
    -- Chọn ngẫu nhiên loại sự kiện
    random_type := event_types[1 + floor(random() * array_length(event_types, 1))::integer];
    
    -- Xác định mức độ nghiêm trọng
    severity := 1 + floor(random() * 5)::integer;
    
    -- Xác định thời lượng
    duration_hours := CASE 
        WHEN random_type IN ('raid', 'trade_opportunity') THEN 2 + floor(random() * 6)::integer
        WHEN random_type = 'harvest' THEN 24 + floor(random() * 72)::integer
        ELSE 6 + floor(random() * 18)::integer
    END;
    
    -- Tạo effects dựa trên loại sự kiện
    effects_json := CASE random_type
        WHEN 'raid' THEN jsonb_build_object(
            'troop_loss_chance', 0.1 * severity,
            'resource_loss_chance', 0.2 * severity,
            'defense_bonus', 1.0 - (0.1 * severity)
        )
        WHEN 'harvest' THEN jsonb_build_object(
            'food_bonus', 0.2 * severity,
            'gold_bonus', 0.1 * severity,
            'loyalty_bonus', 0.05 * severity
        )
        WHEN 'rebellion' THEN jsonb_build_object(
            'production_penalty', 0.15 * severity,
            'troop_morale_penalty', 0.2 * severity,
            'loyalty_loss', 0.1 * severity
        )
        ELSE jsonb_build_object('effect', 'neutral')
    END;
    
    -- Tạo sự kiện
    INSERT INTO region_events (
        region_id, event_type, severity, 
        start_time, end_time, effects
    ) VALUES (
        region_id_param, random_type, severity,
        NOW(), NOW() + (duration_hours || ' hours')::interval, effects_json
    );
    
    RETURN json_build_object(
        'success', true,
        'event', json_build_object(
            'type', random_type,
            'severity', severity,
            'duration_hours', duration_hours,
            'description', get_event_description(random_type, severity),
            'effects', effects_json
        )
    );
END;
$$;


ALTER FUNCTION public.generate_random_event(region_id_param text) OWNER TO postgres;

--
-- Name: generate_table_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_table_ddl(target_table_name text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tbl text;
  v_cols text;
  v_pk   text;
  v_uq   text;
  v_ck   text;
  v_fk   text;
  v_ix   text;
  v_out  text;
  v_rec  record;
BEGIN
  -- Chỉ hỗ trợ bảng thường trong schema public
  SELECT quote_ident(c.relname)
    INTO v_tbl
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'public'
     AND c.relname = target_table_name
     AND c.relkind = 'r';

  IF v_tbl IS NULL THEN
    RETURN '-- Không tìm thấy bảng: ' || target_table_name || ' (chỉ hỗ trợ bảng thuộc public)';
  END IF;

  -- 1) Cột: tên + kiểu + NOT NULL + DEFAULT
  SELECT string_agg(
           '  ' || quote_ident(a.attname)
                || ' ' || pg_catalog.format_type(a.atttypid, a.atttypmod)
                || CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END
                || CASE WHEN d.adbin IS NOT NULL
                        THEN ' DEFAULT ' || pg_get_expr(d.adbin, d.adrelid)
                        ELSE '' END,
           E',\n' ORDER BY a.attnum)
    INTO v_cols
    FROM pg_attribute a
    JOIN pg_class c ON c.oid = a.attrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
   WHERE n.nspname = 'public'
     AND c.relname = target_table_name
     AND a.attnum > 0
     AND NOT a.attisdropped;

  -- 2) PRIMARY KEY
  SELECT string_agg(
           '  CONSTRAINT ' || quote_ident(con.conname)
                || ' PRIMARY KEY (' || cols || ')', E',\n')
    INTO v_pk
    FROM pg_constraint con
    CROSS JOIN LATERAL (
      SELECT string_agg(quote_ident(att.attname), ', ' ORDER BY array_position(con.conkey, att.attnum)) AS cols
      FROM pg_attribute att
      WHERE att.attrelid = con.conrelid
        AND att.attnum = ANY(con.conkey)
    ) cols
   WHERE con.conrelid = ('public.' || quote_ident(target_table_name))::regclass
     AND con.contype = 'p';

  -- 3) UNIQUE
  SELECT string_agg(
           '  CONSTRAINT ' || quote_ident(con.conname) 
                || ' UNIQUE (' || cols.cols || ')', E',\n')
    INTO v_uq
    FROM pg_constraint con
    CROSS JOIN LATERAL (
      SELECT string_agg(quote_ident(att.attname), ', ' ORDER BY array_position(con.conkey, att.attnum)) AS cols
      FROM pg_attribute att
      WHERE att.attrelid = con.conrelid
        AND att.attnum = ANY(con.conkey)
    ) cols
   WHERE con.conrelid = ('public.' || quote_ident(target_table_name))::regclass
     AND con.contype = 'u';

  -- 4) CHECK
  SELECT string_agg(
           '  CONSTRAINT ' || quote_ident(con.conname)
                || ' CHECK (' || pg_get_constraintdef(con.oid, true) || ')', E',\n')
    INTO v_ck
    FROM pg_constraint con
   WHERE con.conrelid = ('public.' || quote_ident(target_table_name))::regclass
     AND con.contype = 'c';

  -- 5) FOREIGN KEY
  WITH fk_data AS (
    SELECT 
      con.conname,
      con.confdeltype,
      con.confupdtype,
      string_agg(quote_ident(fa.attname), ', ' ORDER BY k.ord) AS cols_fk,
      string_agg(quote_ident(ra.attname), ', ' ORDER BY k.ord) AS cols_ref,
      quote_ident(rcl.relname) AS ref_table
    FROM pg_constraint con
    JOIN pg_class rcl ON rcl.oid = con.confrelid
    CROSS JOIN LATERAL unnest(con.conkey, con.confkey) WITH ORDINALITY AS k(fk, ref, ord)
    JOIN pg_attribute fa ON fa.attrelid = con.conrelid AND fa.attnum = k.fk
    JOIN pg_attribute ra ON ra.attrelid = con.confrelid AND ra.attnum = k.ref
   WHERE con.conrelid = ('public.' || quote_ident(target_table_name))::regclass
     AND con.contype = 'f'
   GROUP BY con.conname, con.confdeltype, con.confupdtype, rcl.relname
  )
  SELECT string_agg(
           '  CONSTRAINT ' || quote_ident(f.conname)
                || ' FOREIGN KEY (' || f.cols_fk || ')'
                || ' REFERENCES ' || f.ref_table
                || ' (' || f.cols_ref || ')'
                || CASE f.confdeltype
                     WHEN 'c' THEN ' ON DELETE CASCADE'
                     WHEN 'a' THEN ' ON DELETE NO ACTION'
                     WHEN 'r' THEN ' ON DELETE RESTRICT'
                     WHEN 'n' THEN ' ON DELETE SET NULL'
                     WHEN 'd' THEN ' ON DELETE SET DEFAULT'
                     ELSE '' END
                || CASE f.confupdtype
                     WHEN 'c' THEN ' ON UPDATE CASCADE'
                     WHEN 'a' THEN ' ON UPDATE NO ACTION'
                     WHEN 'r' THEN ' ON UPDATE RESTRICT'
                     WHEN 'n' THEN ' ON UPDATE SET NULL'
                     WHEN 'd' THEN ' ON UPDATE SET DEFAULT'
                     ELSE '' END,
           E',\n')
    INTO v_fk
    FROM fk_data f;

  -- 6) INDEX thường (bỏ index của constraint PK/UNIQUE để tránh trùng)
  SELECT string_agg(
           'CREATE INDEX ' || quote_ident(ic.relname)
                || ' ON public.' || quote_ident(tb.relname)
                || ' USING ' || am.amname
                || ' (' || pg_get_indexdef(i.indexrelid, 0, true) || ')',
           E';\n')
    INTO v_ix
    FROM pg_index i
    JOIN pg_class tb ON tb.oid = i.indrelid
    JOIN pg_class ic ON ic.oid = i.indexrelid
    JOIN pg_namespace n ON n.oid = tb.relnamespace
    JOIN pg_am am ON am.oid = ic.relam
   WHERE n.nspname = 'public'
     AND tb.relname = target_table_name
     AND NOT i.indisprimary
     AND NOT EXISTS (
       SELECT 1 FROM pg_constraint c
        WHERE c.conindid = i.indexrelid
          AND c.contype IN ('p', 'u')
     );

  -- Gộp script
  v_out := 'CREATE TABLE public.' || v_tbl || ' (' || E'\n';
  v_out := v_out || v_cols;

  IF v_pk IS NOT NULL THEN v_out := v_out || E',\n' || v_pk; END IF;
  IF v_uq IS NOT NULL THEN v_out := v_out || E',\n' || v_uq; END IF;
  IF v_ck IS NOT NULL THEN v_out := v_out || E',\n' || v_ck; END IF;
  IF v_fk IS NOT NULL THEN v_out := v_out || E',\n' || v_fk; END IF;

  v_out := v_out || E'\n);';

  IF v_ix IS NOT NULL THEN 
    v_out := v_out || E';\n\n' || v_ix || ';'; 
  END IF;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.generate_table_ddl(target_table_name text) OWNER TO postgres;

--
-- Name: generate_trigger_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_trigger_ddl(target_table_name text DEFAULT NULL::text) RETURNS TABLE(schema_name text, table_name text, trigger_name text, ddl text)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    n.nspname::text as schema_name,
    c.relname::text as table_name,
    t.tgname::text as trigger_name,
    pg_get_triggerdef(t.oid, true)::text || ';' as ddl
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and not t.tgisinternal
    and (
      target_table_name is null
      or c.relname = target_table_name
    )
  order by c.relname, t.tgname;
$$;


ALTER FUNCTION public.generate_trigger_ddl(target_table_name text) OWNER TO postgres;

--
-- Name: get_achievement_details(uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_achievement_details(p_player_id uuid, p_achievement_id character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
BEGIN
    WITH achievement_info AS (
        SELECT 
            a.*,
            COALESCE(lp.progress, 0) as player_progress,
            lp.unlocked_at,
            lp.reward_claimed as player_reward_claimed,  -- Đổi tên để tránh trùng
            COALESCE(lp.repeat_count, 0) as current_repeat_count,
            lp.metadata as player_metadata
        FROM achievements a
        LEFT JOIN LATERAL (
            SELECT 
                progress,
                unlocked_at,
                reward_claimed,
                repeat_count,
                metadata
            FROM player_achievements
            WHERE player_id = p_player_id
            AND achievement_id = a.id
            ORDER BY repeat_count DESC
            LIMIT 1
        ) lp ON TRUE
        WHERE a.id = p_achievement_id
        AND a.status = 'active'
    ),
    requirements AS (
        SELECT json_agg(
            json_build_object(
                'id', ar.id,
                'type', ar.requirement_type,
                'display_text', ar.display_text,
                'target_value', ar.target_value,
                'current_value', ar.current_value,
                'sort_order', ar.sort_order
            ) ORDER BY ar.sort_order
        ) as req_list
        FROM achievement_requirements ar
        WHERE ar.achievement_id = p_achievement_id
    ),
    rewards AS (
        SELECT json_agg(
            json_build_object(
                'id', r.id,
                'item_id', r.item_id,
                'item_name', COALESCE(bi.name, 'Unknown Item'),
                'item_rarity', COALESCE(bi.rarity, 'common'),
                'item_icon', COALESCE(bi.svg_icon, bi.icon),
                'quantity', r.quantity,
                'probability', r.probability,
                'is_claimed', CASE 
                    WHEN ai.player_reward_claimed = true THEN true  -- Sử dụng tên mới
                    ELSE false
                END
            ) ORDER BY COALESCE(bi.base_value, 0) DESC
        ) as reward_list
        FROM achievement_rewards r
        LEFT JOIN base_items bi ON r.item_id = bi.id
        CROSS JOIN achievement_info ai
        WHERE r.achievement_id = p_achievement_id
    ),
    completion_stats AS (
        SELECT 
            COUNT(*) as total_completions,
            COUNT(CASE WHEN pa.reward_claimed = false AND pa.progress >= ai.target_progress THEN 1 END) as pending_claims  -- Chỉ định rõ pa.reward_claimed
        FROM player_achievements pa
        CROSS JOIN achievement_info ai
        WHERE pa.player_id = p_player_id
        AND pa.achievement_id = p_achievement_id
    )
    SELECT json_build_object(
        'achievement', (
            SELECT json_build_object(
                'id', ai.id,
                'name', ai.name,
                'description', ai.description,
                'type', ai.type,
                'category', ai.category,
                'tier', ai.tier,
                'rarity', ai.rarity,
                'difficulty', ai.difficulty,
                'points', ai.points,
                'target_progress', ai.target_progress,
                'player_progress', ai.player_progress,
                'progress_percentage', 
                    CASE 
                        WHEN ai.target_progress = 0 THEN 0
                        ELSE ROUND((ai.player_progress::numeric / ai.target_progress * 100), 2)
                    END,
                'status', 
                    CASE 
                        WHEN ai.player_progress >= ai.target_progress THEN 'completed'
                        WHEN ai.unlocked_at IS NOT NULL THEN 'in_progress'
                        ELSE 'locked'
                    END,
                'unlocked_at', ai.unlocked_at,
                'reward_claimed', COALESCE(ai.player_reward_claimed, false),  -- Sử dụng tên mới
                'repeat_count', ai.current_repeat_count,
                'repeatable', ai.repeatable,
                'max_completions', ai.max_completions,
                'hidden', ai.hidden,
                'secret', ai.secret,
                'icon', ai.icon,
                'image', ai.image,
                'time_limit', ai.time_limit,
                'shareable', ai.shareable,
                'completion_rate', ai.completion_rate,
                'total_completions', ai.total_completions
            )
            FROM achievement_info ai
        ),
        'requirements', (SELECT req_list FROM requirements),
        'rewards', (SELECT reward_list FROM rewards),
        'player_stats', (
            SELECT json_build_object(
                'total_completions', cs.total_completions,
                'pending_claims', cs.pending_claims,
                'can_repeat', 
                    CASE 
                        WHEN ai.repeatable = true AND 
                             (ai.max_completions IS NULL OR 
                              cs.total_completions < ai.max_completions) 
                        THEN true
                        ELSE false
                    END,
                'player_metadata', ai.player_metadata
            )
            FROM completion_stats cs
            CROSS JOIN achievement_info ai
        )
    ) INTO result;
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.get_achievement_details(p_player_id uuid, p_achievement_id character varying) OWNER TO postgres;

--
-- Name: get_active_region_events(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_active_region_events(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(
            json_build_object(
                'id', re.id,
                'event_type', re.event_type,
                'severity', re.severity,
                'description', get_event_description(re.event_type, re.severity),
                'start_time', re.start_time,
                'end_time', re.end_time,
                'duration_remaining', EXTRACT(EPOCH FROM (re.end_time - NOW())),
                'effects', re.effects,
                'actions', get_event_actions(re.event_type)
            )
        )
        FROM region_events re
        WHERE re.region_id = region_id_param
          AND re.start_time <= NOW()
          AND re.end_time >= NOW()
        ORDER BY re.severity DESC, re.start_time
    );
END;
$$;


