--
-- Name: get_all_beauties_with_owner_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_beauties_with_owner_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT jsonb_agg(
  jsonb_build_object(
    'player_beauty_id', pb.id,
    'beauty_id', bc.id,
    'name', bc.name,
    'title', bc.title,
    'rarity', bc.rarity,

    'level', COALESCE(pb.level, bc.level),
    'experience', COALESCE(pb.experience, bc.experience),
    'status', COALESCE(pb.status, bc.status),

    'charm', bc.charm,
    'intelligence', bc.intelligence,
    'diplomacy', bc.diplomacy,
    'intrigue', bc.intrigue,
    'loyalty', pb.intimacy_points,

    'mission_success_rate',
      COALESCE(pb.mission_success_rate, bc.mission_success_rate),

    'avatar', bc.avatar,
    'full_image', bc.full_image,

    'acquisition_date',
      COALESCE(pb.acquisition_date, bc.acquisition_date),

    'last_used', pb.last_used,

    'owner', (pb.id IS NOT NULL)
  )
)
FROM beauty_characters bc
LEFT JOIN player_beauties pb
  ON pb.beauty_id = bc.id
 AND pb.player_id = p_player_id;
$$;


