--
-- Name: get_all_building_production(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_building_production() RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(
            json_build_object(
                'building_type', bp.building_type,
                'resource_type', bp.resource_type,
                'base_rate', bp.base_rate,
                'level_multiplier', bp.level_multiplier,
                'production_at_level', json_build_object(
                    'level_1', bp.base_rate,
                    'level_2', bp.base_rate * bp.level_multiplier,
                    'level_3', bp.base_rate * bp.level_multiplier * bp.level_multiplier,
                    'level_5', bp.base_rate * POWER(bp.level_multiplier, 4),
                    'level_10', bp.base_rate * POWER(bp.level_multiplier, 9)
                )
            )
        )
        FROM building_production bp
        ORDER BY bp.building_type, bp.resource_type
    );
END;
$$;


