--
-- Name: get_all_equipable_items_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_equipable_items_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql
    AS $$
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'player_item_id', pi.id,
                'item_id', bi.id,
                'name', bi.name,
                'equipment_type', bi.type,
                'rarity', bi.rarity,
                'quality', bi.quality,
                'level_requirement', bi.level_requirement,
                'quantity', pi.quantity,
                'equipped', pi.equipped,
                'condition', pi.condition,
                'icon', bi.icon,

                -- Item stats
                'stats', jsonb_build_object(
                    'attack', ist.attack,
                    'defense', ist.defense,
                    'health', ist.health,
                    'mana', ist.mana,
                    'strength', ist.strength,
                    'agility', ist.agility,
                    'intelligence', ist.intelligence,
                    'speed', ist.speed,
                    'leadership', ist.leadership,
                    'critical_chance', ist.critical_chance,
                    'critical_damage', ist.critical_damage,
                    'dodge', ist.dodge,
                    'block', ist.block,
                    'resistance', ist.resistance
                )
            )
        ),
        '[]'::jsonb
    )
    FROM public.player_items pi
    JOIN public.base_items bi
        ON bi.id = pi.item_id
    LEFT JOIN public.item_stats ist
        ON ist.base_item_id = bi.id
    WHERE pi.player_id = p_player_id
      AND bi.status = 'active'
      AND bi.type IN (
          'weapon',
          'armor',
          'accessory',
          'helmet',
          'cloak',
          'boots',
          'shield',
          'mount',
          'soldier_weapon',
          'soldier_armor',
          'soldier_special_item',
          'siege_equipment'
      )
      AND pi.quantity > 0;
$$;


