-- Name: get_all_regions_with_player_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_regions_with_player_status(p_player_id uuid) RETURNS TABLE(region_id text, lord_name character varying, created_at timestamp without time zone, updated_at timestamp without time zone, owned boolean, player_region_id uuid, acquired_at timestamp with time zone, is_active boolean, development_level integer, troops integer, resources integer)
    LANGUAGE sql
    AS $$
    SELECT
        r.id AS region_id,
        r.lord_name,
        r.created_at,
        r.updated_at,
        pr.id IS NOT NULL AS owned,
        pr.id AS player_region_id,
        pr.acquired_at,
        pr.is_active,
        pr.development_level,
        pr.troops,
        pr.resources
    FROM public.regions r
    LEFT JOIN public.player_regions pr
        ON pr.region_id = r.id
       AND pr.player_id = p_player_id
    ORDER BY r.id;
$$;


ALTER FUNCTION public.get_all_regions_with_player_status(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_all_regions_with_player_status_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_regions_with_player_status_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'region_id', r.id,
            'lord_name', r.lord_name,
            'created_at', r.created_at,
            'updated_at', r.updated_at,
            
            -- Thông tin player sở hữu
            'owned', pr.id IS NOT NULL,
            'player_region_id', pr.id,
            'acquired_at', pr.acquired_at,
            'is_active', COALESCE(pr.is_active, false),
            'development_level', COALESCE(pr.development_level, 1),
            
            -- Resources của region
            'resources', 
                CASE 
                    WHEN pr.id IS NOT NULL THEN
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                'resource_code', rr.resource_code,
                                'resource_name', rt.resource_name,
                                'category', rt.resource_category,
                                'amount', COALESCE(rr.amount, 0),
                                'max_amount', COALESCE(rr.max_amount, 2500),
                                'last_collected_at', rr.last_collected_at
                            )
                            ORDER BY rt.sort_order
                        )
                        FROM region_resources rr
                        JOIN resource_types rt ON rt.resource_code = rr.resource_code
                        WHERE rr.player_region_id = pr.id)
                    ELSE '[]'::jsonb
                END,
            
            -- Buildings trong region
            'buildings',
                CASE 
                    WHEN pr.id IS NOT NULL THEN
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', prb.id,
                                'building_type', prb.building_type,
                                'level', prb.level,
                                'upgrading', prb.upgrading,
                                'upgrade_finish_at', prb.upgrade_finish_at,
                                'upgrade_remaining_seconds',
                                    CASE 
                                        WHEN prb.upgrading AND prb.upgrade_finish_at > NOW()
                                        THEN EXTRACT(EPOCH FROM (prb.upgrade_finish_at - NOW()))::INT
                                        ELSE 0
                                    END
                            )
                            ORDER BY 
                                CASE 
                                    WHEN prb.upgrading THEN 0
                                    ELSE 1
                                END,
                                prb.created_at
                        )
                        FROM player_region_buildings prb
                        WHERE prb.player_region_id = pr.id)
                    ELSE '[]'::jsonb
                END,
            
            -- Thống kê
            'statistics', 
                CASE 
                    WHEN pr.id IS NOT NULL THEN
                        jsonb_build_object(
                            'buildings_count', (SELECT COUNT(*) FROM player_region_buildings WHERE player_region_id = pr.id),
                            'upgrades_in_progress', (SELECT COUNT(*) FROM player_region_buildings WHERE player_region_id = pr.id AND upgrading = true),
                            'total_power_score', COALESCE((
                                SELECT SUM(bad.power_score)
                                FROM player_region_buildings prb2
                                JOIN building_attribute_detail bad 
                                    ON bad.building_type = prb2.building_type 
                                    AND bad.level = prb2.level
                                WHERE prb2.player_region_id = pr.id
                            ), 0)
                        )
                    ELSE jsonb_build_object(
                        'buildings_count', 0,
                        'upgrades_in_progress', 0,
                        'total_power_score', 0
                    )
                END,
            
            -- Region available buildings (theo region_buildings)
            'available_buildings',
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'building_type', rb.building_type,
                        'max_count', rb.max_count,
                        'min_region_level', rb.min_region_level,
                        'current_count', 
                            CASE 
                                WHEN pr.id IS NOT NULL THEN
                                    (SELECT COUNT(*) 
                                     FROM player_region_buildings 
                                     WHERE player_region_id = pr.id 
                                       AND building_type = rb.building_type)
                                ELSE 0
                            END,
                        'building_name', bb.name,
                        'building_description', bb.description,
                        'max_level', bb.max_level
                    )
                    ORDER BY bb.name
                )
                FROM region_buildings rb
                JOIN base_buildings bb ON bb."type" = rb.building_type
                WHERE rb.region_id = r.id)
        )
        ORDER BY 
            CASE WHEN pr.id IS NOT NULL THEN 0 ELSE 1 END, -- Owned regions first
            r.id
    ) INTO v_result
    FROM public.regions r
    LEFT JOIN public.player_regions pr
        ON pr.region_id = r.id
       AND pr.player_id = p_player_id
    WHERE pr.id IS NOT NULL; -- Include owned regions even if not available

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_all_regions_with_player_status_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_all_tables(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_tables() RETURNS TABLE(schema_name text, table_name text, table_type text)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    table_schema::text as schema_name,
    table_name::text,
    table_type::text
  from information_schema.tables
  where table_schema = 'public'
    and table_type = 'BASE TABLE'
  order by table_name;
$$;


ALTER FUNCTION public.get_all_tables() OWNER TO postgres;

--
-- Name: get_all_tables_with_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_tables_with_columns() RETURNS TABLE(schema_name text, table_name text, table_type text, columns json)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    t.table_schema::text,
    t.table_name::text,
    t.table_type::text,
    (
      SELECT json_agg(
        json_build_object(
          'column_name', col.column_name,
          'data_type', col.data_type,
          'is_nullable', col.is_nullable,
          'column_default', col.column_default,
          'is_primary_key', col.is_primary_key,
          'is_foreign_key', col.is_foreign_key,
          'foreign_table', col.foreign_table,
          'foreign_column', col.foreign_column
        )
      )
      FROM public.get_table_columns_diagrams(t.table_name) col
    ) AS columns
  FROM information_schema.tables t
  WHERE t.table_schema = 'public'
    AND t.table_type = 'BASE TABLE'
  ORDER BY t.table_name;
END;
$$;


ALTER FUNCTION public.get_all_tables_with_columns() OWNER TO postgres;

--
-- Name: get_all_tables_with_trigger_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_tables_with_trigger_status() RETURNS TABLE(schema_name text, table_name text, table_type text, has_trigger boolean, trigger_count integer)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    t.table_schema::text as schema_name,
    t.table_name::text,
    t.table_type::text,

    count(trg.oid) > 0 as has_trigger,
    count(trg.oid)::int as trigger_count

  from information_schema.tables t

  left join pg_class c
    on c.relname = t.table_name

  left join pg_namespace n
    on n.oid = c.relnamespace
   and n.nspname = t.table_schema

  left join pg_trigger trg
    on trg.tgrelid = c.oid
   and not trg.tgisinternal

  where t.table_schema = 'public'
    and t.table_type = 'BASE TABLE'

  group by
    t.table_schema,
    t.table_name,
    t.table_type

  order by t.table_name;
$$;


ALTER FUNCTION public.get_all_tables_with_trigger_status() OWNER TO postgres;

--
-- Name: get_all_units_with_player_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_units_with_player_status(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$

DECLARE
    result jsonb;

BEGIN

    SELECT jsonb_agg(row_to_json(t))

    INTO result

    FROM (
        SELECT

            -- ============================================
            -- MASTER UNIT INFO
            -- ============================================

            u.id AS origin_unit_id,
            u.name AS unit_name,
            u.image_path,
            u.type AS unit_type,
            u.description,

            u.level AS base_level,
            u.max_hp AS base_max_hp,
            u.current_hp AS base_current_hp,
            u.atk AS base_atk,
            u.def AS base_def,
            u.speed AS base_speed,
            u.range AS base_range,
            u.is_vip AS base_is_vip,

            -- ============================================
            -- PLAYER UNIT INSTANCE
            -- ============================================

            CASE
                WHEN pu.id IS NULL THEN false
                ELSE true
            END AS owned,

            pu.id AS player_unit_id,
            pu.quantity,
            pu.level AS player_level,
            pu.current_hp AS player_current_hp,
            pu.max_hp AS player_max_hp,
            pu.experience,
            pu.formation_position,
            pu.is_in_garrison,
            pu.weapon_item_id,
            pu.armor_item_id,
            pu.accessory_item_id,
            pu.rank AS player_rank,
            pu.is_special,
            pu.join_date,

            -- ============================================
            -- PLAYER TROOP SUMMARY
            -- ============================================

            get_player_troop_summary(
                p_player_id,
                u.id
            ) AS troop_summary

        FROM public.units u

        LEFT JOIN public.player_units pu
            ON pu.unit_id = u.id
            AND pu.player_id = p_player_id

        WHERE u.is_boss_unit = false

        ORDER BY u.id

    ) t;

    RETURN COALESCE(
        result,
        '[]'::jsonb
    );

END;

$$;


ALTER FUNCTION public.get_all_units_with_player_status(p_player_id uuid) OWNER TO postgres;

