--
-- Name: get_alliance_members_with_total(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliance_members_with_total(alliance_uuid uuid) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    WITH member_count AS (
        SELECT COUNT(*)::bigint AS total
        FROM public.alliance_members am
        WHERE am.alliance_id = alliance_uuid
    ),
    members_list AS (
        SELECT 
            p.id AS player_id,
            p.username AS player_name,
            p.level AS player_level,
            am.role,
            am.joined_at
        FROM public.alliance_members am
        INNER JOIN public.players p ON am.player_id = p.id
        WHERE am.alliance_id = alliance_uuid
        ORDER BY 
            CASE am.role 
                WHEN 'leader' THEN 1 
                WHEN 'officer' THEN 2 
                WHEN 'member' THEN 3 
                ELSE 4 
            END,
            am.joined_at ASC
    )
    SELECT json_build_object(
        'total_members', COALESCE((SELECT total FROM member_count), 0),
        'members', COALESCE(
            (SELECT json_agg(row_to_json(members_list.*)) FROM members_list),
            '[]'::json
        )
    );
$$;


ALTER FUNCTION public.get_alliance_members_with_total(alliance_uuid uuid) OWNER TO postgres;

