-- Name: get_alliance_messages(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliance_messages(p_alliance_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(msg_id uuid, sender_id uuid, message_type text, content text, channel_type text, alliance_id uuid, created_date timestamp with time zone, is_edited boolean, is_deleted boolean, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        cm.id AS msg_id,
        cm.sender_id,
        cm.message_type,
        cm.content,
        cm.channel_type,
        cm.alliance_id,
        cm.created_date,
        cm.is_edited,
        cm.is_deleted,
        cm.metadata
    FROM public.chat_messages cm
    WHERE cm.channel_type = 'alliance'
      AND cm.alliance_id = p_alliance_id
      AND cm.is_deleted = false
    ORDER BY cm.created_date DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_alliance_messages(p_alliance_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_alliance_messages_json(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliance_messages_json(p_alliance_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(msg)
    INTO result
    FROM (
        SELECT jsonb_build_object(
            'id', cm.id,
            'sender_id', cm.sender_id,
            'message_type', cm.message_type,
            'content', cm.content,
            'channel_type', cm.channel_type,
            'alliance_id', cm.alliance_id,
            'created_date', cm.created_date,
            'is_edited', cm.is_edited,
            'is_deleted', cm.is_deleted,
            'metadata', cm.metadata
        ) AS msg
        FROM public.chat_messages cm
        WHERE cm.channel_type = 'alliance'
          AND cm.alliance_id = p_alliance_id
          AND cm.is_deleted = false
        ORDER BY cm.created_date ASC
        LIMIT p_limit
    ) sub;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_alliance_messages_json(p_alliance_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_alliance_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliance_metrics() RETURNS TABLE(totalalliances bigint, activealliances bigint, totalmembers bigint, totalpower bigint, avgwinrate numeric, totalvictorypoints bigint, avgmembersperalliance numeric, avgpowerperalliance numeric, growthrate numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::bigint AS totalAlliances,
    COUNT(*) FILTER (WHERE status = 'active')::bigint AS activeAlliances,
    COALESCE(SUM(members), 0)::bigint AS totalMembers,
    COALESCE(SUM(total_power), 0)::bigint AS totalPower,
    COALESCE(AVG(win_rate), 0)::numeric(5,2) AS avgWinRate,
    COALESCE(SUM(victory_points), 0)::bigint AS totalVictoryPoints,
    ROUND(COALESCE(SUM(members)::numeric / NULLIF(COUNT(*),0), 0), 2) AS avgMembersPerAlliance,
    ROUND(COALESCE(SUM(total_power)::numeric / NULLIF(COUNT(*),0), 0), 2) AS avgPowerPerAlliance,
    5.0::numeric AS growthRate
  FROM public.alliances;
END;
$$;


ALTER FUNCTION public.get_alliance_metrics() OWNER TO postgres;

--
-- Name: get_alliance_quests_for_player_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliance_quests_for_player_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    result jsonb;
BEGIN
    -- Lấy tất cả alliance quest + progress player
    WITH player AS (
        SELECT level
        FROM public.players
        WHERE id = p_player_id
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'quest_id', q.id,
            'quest_name', q.name,
            'description', q.description,
            'type', q.type,
            'category', q.category,
            'difficulty', q.difficulty,
            'min_level', q.min_level,
            'max_level', q.max_level,
            'target', q.completion_limit,
            'progress', COALESCE(pqp.progress, 0),
            'completed', COALESCE(pqp.completed, false),
            'claimed', COALESCE(pqp.claimed, false),
            'completed_at', pqp.completed_at
        )
    ) INTO result
    FROM public.quests q
    CROSS JOIN player
    LEFT JOIN public.player_quest_progress pqp
        ON pqp.quest_id = q.id
        AND pqp.player_id = p_player_id
    WHERE q.category = 'alliance'
      AND q.min_level <= player.level
      AND q.max_level >= player.level
    ;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_alliance_quests_for_player_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_alliances(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alliances(p_player_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(
            json_build_object(
                'id', a.id,
                'name', a.name,
                'tag', a.tag,
                'level', a.level,
                'members', a.members,
                'maxMembers', a.max_members,
                'leader', a.leader,
                'totalPower', a.total_power,
                'winRate', a.win_rate,
                'territory', a.territory,
                'status', a.status,
                'isMember', CASE 
                    WHEN am.player_id IS NOT NULL THEN true 
                    ELSE false 
                END
            )
        )
        FROM alliances a
        LEFT JOIN alliance_members am
            ON a.id = am.alliance_id
            AND am.player_id = p_player_id
    );
END;
$$;


