--
-- Name: get_available_player_generals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_available_player_generals(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_result jsonb;

BEGIN

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'general_id', pg.general_id,
                'name', g.name,
                'rarity', g.rarity,
                'element', g.element,
                'type', g.type,

                'level', pg.level,
                'star_level', pg.star_level,

                'current_attack', pg.current_attack,
                'current_defense', pg.current_defense,
                'current_health', pg.current_health,
                'current_speed', pg.current_speed,
                'current_intelligence', pg.current_intelligence,
                'current_leadership', pg.current_leadership,

                'favorite', pg.favorite,
                'is_representative', pg.is_representative,

                'image', g.image,
                'thumbnail', g.thumbnail,

                'unit_capacities',
                get_player_general_unit_capacities(
                    pg.player_id,
                    pg.general_id
                )
            )

            ORDER BY
                pg.level DESC,
                pg.star_level DESC
        ),
        '[]'::jsonb
    )

    INTO v_result

    FROM public.player_generals pg

    JOIN public.generals g
        ON g.id = pg.general_id

    LEFT JOIN public.region_generals rg
        ON rg.player_id = pg.player_id
       AND rg.general_id = pg.general_id
       AND rg.is_active = true

    WHERE pg.player_id = p_player_id
      AND rg.id IS NULL;

    RETURN v_result;

END;

$$;


ALTER FUNCTION public.get_available_player_generals(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_battle_combat_formations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_battle_combat_formations(p_battle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle RECORD;
    v_attacker jsonb;
    v_defender jsonb;
BEGIN
    -- 1️⃣ Lấy thông tin battle
    SELECT
        b.id,
        b.player1_id,
        b.player2_id,
        b.battle_type,
        b.status
    INTO v_battle
    FROM battles b
    WHERE b.id = p_battle_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Battle not found: %', p_battle_id;
    END IF;

    IF v_battle.player2_id IS NULL THEN
        RAISE EXCEPTION 'Battle % does not have opponent yet', p_battle_id;
    END IF;

    -- 2️⃣ Lấy đội hình tấn công (player1)
    SELECT get_player_combat_formation(
        v_battle.player1_id,
        'offense'
    )
    INTO v_attacker;

    -- 3️⃣ Lấy đội hình phòng thủ (player2)
    SELECT get_player_combat_formation(
        v_battle.player2_id,
        'defense'
    )
    INTO v_defender;

    -- 4️⃣ Trả kết quả
    RETURN jsonb_build_object(
        'battle_id', p_battle_id,
        'battle_type', v_battle.battle_type,
        'status', v_battle.status,

        'attacker', v_attacker,
        'defender', v_defender
    );
END;
$$;


ALTER FUNCTION public.get_battle_combat_formations(p_battle_id uuid) OWNER TO postgres;

--
-- Name: get_battle_combat_formations(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_battle_combat_formations(p_battle_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle RECORD;
    v_attacker jsonb;
    v_defender jsonb;

    v_self jsonb;
    v_enemy jsonb;
    v_role text;
BEGIN
    -- 1️⃣ Lấy battle
    SELECT id, player1_id, player2_id, battle_type, status
    INTO v_battle
    FROM battles
    WHERE id = p_battle_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Battle not found: %', p_battle_id;
    END IF;


    -- 2️⃣ Auto start battle nếu đang ready
    IF v_battle.status = 'ready' THEN
        UPDATE battles
        SET status = 'in_progress',
            started_at = now()
        WHERE id = p_battle_id
          AND status = 'ready';

        -- reload lại status
        SELECT status
        INTO v_battle.status
        FROM battles
        WHERE id = p_battle_id;
    END IF;

    -- 2️⃣ Lấy đội hình
    SELECT get_player_combat_formation(v_battle.player1_id, 'offense')
    INTO v_attacker;

    SELECT get_player_combat_formation(v_battle.player2_id, 'defense')
    INTO v_defender;

    -- 3️⃣ Xác định role
    IF p_player_id = v_battle.player1_id THEN
        v_self := v_attacker;
        v_enemy := v_defender;
        v_role := 'attacker';

    ELSIF p_player_id = v_battle.player2_id THEN
        v_self := v_defender;
        v_enemy := v_attacker;
        v_role := 'defender';

    ELSE
        v_self := NULL;
        v_enemy := NULL;
        v_role := 'viewer';
    END IF;

    -- 4️⃣ Return
    RETURN jsonb_build_object(
        'battle_id', p_battle_id,
        'battle_type', v_battle.battle_type,
        'status', v_battle.status,
        'role', v_role,
        'self', v_self,
        'enemy', v_enemy,
        'attacker', v_attacker,
        'defender', v_defender
    );
END;
$$;


ALTER FUNCTION public.get_battle_combat_formations(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_battle_history(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_battle_history(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
WITH soldier_stats AS (
  SELECT
    battle_id,
    player_id,
    SUM(initial_quantity)::int AS troops,
    SUM(casualties)::int AS losses
  FROM battle_soldiers
  GROUP BY battle_id, player_id
),
battle_rows AS (
  SELECT
    b.id AS battle_id,
    COALESCE(b.ended_at, b.created_at) AS battle_date,

    CASE
      WHEN b.player1_id = p_player_id THEN b.player2_id
      ELSE b.player1_id
    END AS opponent_id,

    op.username AS opponent_name,
    b.battle_type,

    CASE
      WHEN b.winner_id IS NULL THEN 'draw'
      WHEN b.winner_id = p_player_id THEN 'victory'
      ELSE 'defeat'
    END AS result,

    (b.battle_type IN ('ranked','tournament')) AS is_critical,

    COALESCE(ss_self.troops, 0) AS player_troops,
    COALESCE(ss_opp.troops, 0) AS opponent_troops,

    COALESCE(ss_self.losses, 0) AS player_losses,
    COALESCE(ss_opp.losses, 0) AS opponent_losses,

    br.currency_rewards
  FROM battles b
  LEFT JOIN soldier_stats ss_self
    ON ss_self.battle_id = b.id
   AND ss_self.player_id = p_player_id
  LEFT JOIN soldier_stats ss_opp
    ON ss_opp.battle_id = b.id
   AND ss_opp.player_id <> p_player_id
  LEFT JOIN battle_rewards br
    ON br.battle_id = b.id
   AND br.player_id = p_player_id
  LEFT JOIN players op
    ON op.id = CASE
      WHEN b.player1_id = p_player_id THEN b.player2_id
      ELSE b.player1_id
    END
  WHERE
    p_player_id IN (b.player1_id, b.player2_id)
    AND b.status = 'completed'
)
SELECT
  COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'battle_id', br.battle_id,
        'battle_date', br.battle_date,
        'opponent_id', br.opponent_id,
        'opponent_name', br.opponent_name,
        'battle_type', br.battle_type,
        'result', br.result,
        'is_critical', br.is_critical,
        'player_troops', br.player_troops,
        'opponent_troops', br.opponent_troops,
        'player_losses', br.player_losses,
        'opponent_losses', br.opponent_losses,
        'currency_rewards', br.currency_rewards
      )
      ORDER BY br.battle_date DESC
    ),
    '[]'::jsonb
  )
FROM battle_rows br;
$$;


ALTER FUNCTION public.get_battle_history(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_battle_players(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_battle_players(p_battle_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json JSONB;
BEGIN
    SELECT 
        jsonb_build_object(
            'player_id', p_player_id,
            'enemy_id', CASE 
                WHEN b.player1_id = p_player_id THEN b.player2_id
                WHEN b.player2_id = p_player_id THEN b.player1_id
                ELSE NULL
            END
        )
    INTO result_json
    FROM battles b
    WHERE b.id = p_battle_id
        AND (b.player1_id = p_player_id OR b.player2_id = p_player_id);
    
    -- Nếu không tìm thấy, trả về null
    RETURN result_json;
END;
$$;


ALTER FUNCTION public.get_battle_players(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_battle_troops(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_battle_troops(p_battle_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle_type text;
BEGIN
    SELECT battle_type
    INTO v_battle_type
    FROM public.battles
    WHERE id = p_battle_id;

    RETURN jsonb_build_object(
        'battle_id', p_battle_id,
        'battle_general', public.get_player_battle_general(
            p_battle_id,
            p_player_id
        ),
        'my_troops',
        public.get_player_battle_troops(
            p_battle_id,
            p_player_id
        ),

        'enemy_troops',
        CASE
            WHEN v_battle_type = 'boss' THEN
                public.get_boss_unit_from_battle(
                    p_battle_id
                )

            ELSE
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            to_jsonb(ct) ||
                            jsonb_build_object(
                                'unit_name', u.name,
                                'unit_description', u.description,
                                'unit_image_path', u.image_path,
                                'unit_type_enum', u.type,
                                'unit_rank', u.rank,
                                'base_level', u.level,
                                'base_atk', u.atk,
                                'base_def', u.def,
                                'base_max_hp', u.max_hp,
                                'base_speed', u.speed,
                                'base_range', u.range,
                                'is_vip', u.is_vip,
                                'is_special', u.is_special
                            )
                        )
                        FROM public.combat_troops ct
                        JOIN public.units u
                            ON u.id = ct.unit_type
                        WHERE ct.battle_id = p_battle_id
                          AND ct.player_id <> p_player_id
                    ),
                    '[]'::jsonb
                )
        END
    );
END;
$$;


ALTER FUNCTION public.get_battle_troops(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_boss_as_unit(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_boss_as_unit(p_boss_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json JSON;
BEGIN
    SELECT json_build_object(
        'player_unit_id', b.id::TEXT,
        'unit_name', b.name,
        'unit_type', 'general',
        'unit_type_enum', 'general',
        'unit_rank', 'elite',
        'is_vip', true,
        'status', 'healthy',
        'base_atk', b.base_attack,
        'base_def', b.base_defense,
        'base_level', 1,
        'base_speed', b.base_speed,
        'base_max_hp', b.base_hp,
        'battle_id', '',  -- Không có battle_id
        'battle_role', 'boss',
        'joined_at', TO_CHAR(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'player_id', '',
        'region_id', '',
        'experience', b.exp_reward,
        'updated_at', TO_CHAR(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'speed_bonus', 0,
        'troop_level', 1,
        'attack_bonus', 0,
        'attack_power', b.base_attack,
        'troop_max_hp', b.base_hp,
        'defense_bonus', 0,
        'defense_power', b.base_defense,
        'health_points', b.base_hp,
        'lost_quantity', 0,
        'is_in_garrison', false,
        'movement_speed', b.base_speed,
        'combat_troop_id', b.id::TEXT,
        'player_quantity', 1,
        'current_quantity', 1,
        'troop_current_hp', b.base_hp,
        'original_quantity', 1,
        'survived_quantity', 1,
        'formation_position', json_build_object(
            'x', 0,
            'y', 0,
            'row', 1
        )
    )
    INTO result_json
    FROM bosses b
    WHERE b.id = p_boss_id
        AND b.is_active = true;
    
    RETURN result_json;
END;
$$;


