--
-- Name: get_boss_full_info(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_boss_full_info(p_boss_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    boss_record RECORD;
    phases JSONB;
    skills JSONB;
    drops JSONB;
BEGIN
    -- Kiểm tra boss tồn tại
    SELECT * INTO boss_record
    FROM public.bosses b
    WHERE b.id = p_boss_id AND b.is_active = true;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Boss with ID % not found or inactive', p_boss_id;
    END IF;
    
    -- Lấy danh sách phases
    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'phase_number', bp.phase_number,
                'phase_name', bp.phase_name,
                'phase_description', bp.phase_description,
                'hp_threshold_percent', bp.hp_threshold_percent,
                'attack_multiplier', bp.attack_multiplier,
                'defense_multiplier', bp.defense_multiplier,
                'speed_multiplier', bp.speed_multiplier,
                'hp_multiplier', bp.hp_multiplier,
                'special_abilities', bp.special_abilities,
                'phase_color', bp.phase_color,
                'phase_icon', bp.phase_icon,
                'background_effect', bp.background_effect
            )
            ORDER BY bp.phase_number
        ),
        '[]'::JSONB
    )
    INTO phases
    FROM public.boss_phases bp
    WHERE bp.boss_id = p_boss_id;
    
    -- Lấy danh sách skills
    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', bs.id,
                'skill_name', bs.skill_name,
                'skill_description', bs.skill_description,
                'skill_type', bs.skill_type,
                'power', bs.power,
                'is_heal', bs.is_heal,
                'is_aoe', bs.is_aoe,
                'aoe_radius', bs.aoe_radius,
                'mp_cost', bs.mp_cost,
                'cooldown', bs.cooldown,
                'effects', bs.effects,
                'animation_name', bs.animation_name,
                'effect_color', bs.effect_color,
                'icon_url', bs.icon_url,
                'phase_id', bs.phase_id
            )
        ),
        '[]'::JSONB
    )
    INTO skills
    FROM public.boss_skills bs
    WHERE bs.boss_id = p_boss_id;
    
    -- Lấy danh sách drops
    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', bd.id,
                'item_id', bd.item_id,
                'drop_rate', bd.drop_rate,
                'min_quantity', bd.min_quantity,
                'max_quantity', bd.max_quantity,
                'is_guaranteed', bd.is_guaranteed,
                'required_phase', bd.required_phase,
                'requires_enrage', bd.requires_enrage
            )
        ),
        '[]'::JSONB
    )
    INTO drops
    FROM public.boss_drops bd
    WHERE bd.boss_id = p_boss_id;
    
    -- Tạo kết quả JSON
    result := JSONB_BUILD_OBJECT(
        'id', boss_record.id,
        'name', boss_record.name,
        'title', boss_record.title,
        'description', boss_record.description,
        'base_hp', boss_record.base_hp,
        'base_attack', boss_record.base_attack,
        'base_defense', boss_record.base_defense,
        'base_speed', boss_record.base_speed,
        'boss_type', boss_record.boss_type,
        'element', boss_record.element,
        'total_phases', boss_record.total_phases,
        'enrage_turn', boss_record.enrage_turn,
        'enrage_damage_multiplier', boss_record.enrage_damage_multiplier,
        'exp_reward', boss_record.exp_reward,
        'gold_reward', boss_record.gold_reward,
        'is_active', boss_record.is_active,
        'is_limited', boss_record.is_limited,
        'available_from', boss_record.available_from,
        'available_to', boss_record.available_to,
        'created_at', boss_record.created_at,
        'updated_at', boss_record.updated_at,
        'phases', phases,
        'skills', skills,
        'drops', drops
    );
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.get_boss_full_info(p_boss_id uuid) OWNER TO postgres;

--
-- Name: get_boss_max_duration(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_boss_max_duration(p_boss_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_boss_type text;
  v_duration int4;
BEGIN
  SELECT boss_type INTO v_boss_type FROM bosses WHERE id = p_boss_id;
  
  v_duration := CASE v_boss_type
    WHEN 'normal' THEN 300
    WHEN 'elite' THEN 400
    WHEN 'raid' THEN 600
    WHEN 'world' THEN 900
    ELSE 300
  END;
  
  RETURN v_duration;
END;
$$;


ALTER FUNCTION public.get_boss_max_duration(p_boss_id uuid) OWNER TO postgres;

--
-- Name: get_boss_turn_timeout(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_boss_turn_timeout(p_boss_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_boss_type text;
  v_timeout int4;
BEGIN
  SELECT boss_type INTO v_boss_type FROM bosses WHERE id = p_boss_id;
  
  v_timeout := CASE v_boss_type
    WHEN 'normal' THEN 30
    WHEN 'elite' THEN 25
    WHEN 'raid' THEN 20
    WHEN 'world' THEN 15
    ELSE 30
  END;
  
  RETURN v_timeout;
END;
$$;


