--
-- Name: get_boss_unit_from_battle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_boss_unit_from_battle(p_battle_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(
            'id', NULL,
            'battle_id', p_battle_id,
            'player_id', NULL,

            'unit_type', u.id,
            'quantity', bu.quantity,

            'current_hp', u.max_hp,
            'max_hp', u.max_hp,

            'unit_name', u.name,
            'unit_description', u.description,
            'unit_image_path', u.image_path,
            'unit_type_enum', u.type,
            'unit_rank', u.rank,

            'base_level', u.level,
            'base_atk', u.atk,
            'base_def', u.def,
            'base_max_hp', u.max_hp,
            'base_speed', u.speed,
            'base_range', u.range,

            'is_vip', u.is_vip,
            'is_special', u.is_special,
            'original_quantity', bu.original_quantity,
			'current_quantity', bu.current_quantity
        )
    ),
    '[]'::jsonb
)
FROM public.battles b
JOIN public.boss_units bu
    ON bu.boss_id = b.boss_id
JOIN public.units u
    ON u.id = bu.unit_id
WHERE b.id = p_battle_id
  AND b.boss_id IS NOT NULL;
$$;


ALTER FUNCTION public.get_boss_unit_from_battle(p_battle_id uuid) OWNER TO postgres;

--
-- Name: get_building_detail(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_building_detail(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_attr RECORD;
    v_prod RECORD;
    v_resource RECORD;
    v_preview NUMERIC := 0;
BEGIN
    -- 1. Lấy building
    SELECT prb.*, pr.id AS region_id
    INTO v_building
    FROM player_region_buildings prb
    JOIN player_regions pr ON pr.id = prb.player_region_id
    WHERE prb.id = p_player_building_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2. Attribute theo level
    SELECT *
    INTO v_attr
    FROM building_attribute_detail
    WHERE building_type = v_building.building_type
      AND level = v_building.level;

    -- 3. Production (nếu có)
    SELECT *
    INTO v_prod
    FROM building_production
    WHERE building_type = v_building.building_type
      AND level = v_building.level
    LIMIT 1;

    -- 4. Region resource (nếu có production)
    IF v_prod.resource_code IS NOT NULL THEN
        SELECT *
        INTO v_resource
        FROM region_resources
        WHERE player_region_id = v_building.player_region_id
          AND resource_code = v_prod.resource_code;

        IF NOT FOUND THEN
            v_resource.amount := 0;
            v_resource.max_amount := 2500;
            v_resource.last_collected_at := now() - interval '1 hour';
        END IF;

        -- preview collect
        v_preview :=
            v_prod.production_rate_per_hour
            * COALESCE(v_prod.efficiency_percent,100) / 100
            * EXTRACT(EPOCH FROM (now() - v_resource.last_collected_at)) / 3600;

        v_preview := LEAST(
            v_preview,
            COALESCE(v_resource.max_amount,0) - COALESCE(v_resource.amount,0)
        );
        v_preview := GREATEST(v_preview,0);
    END IF;

    -- 5. Return JSON
    RETURN json_build_object(
        'success', true,
        'player_building_id', v_building.id,
        'building_type', v_building.building_type,
        'level', v_building.level,
        'upgrading', v_building.upgrading,
        'upgrade_finish_at', v_building.upgrade_finish_at,
        'upgrade_remaining_seconds',
            CASE
                WHEN v_building.upgrading AND v_building.upgrade_finish_at > now()
                THEN EXTRACT(EPOCH FROM (v_building.upgrade_finish_at - now()))::INT
                ELSE 0
            END,

        -- attribute
        'attribute', json_build_object(
            'hit_points', v_attr.hit_points,
            'power_score', v_attr.power_score,
            'troop_capacity', v_attr.troop_capacity,
            'population_capacity', v_attr.population_capacity,
            'population_growth_per_hour', v_attr.population_growth_per_hour,
            'special_abilities', v_attr.special_abilities
        ),

        -- production
        'production', CASE
            WHEN v_prod.resource_code IS NOT NULL THEN
                json_build_object(
                    'resource_code', v_prod.resource_code,
                    'rate_per_hour', v_prod.production_rate_per_hour,
                    'efficiency_percent', v_prod.efficiency_percent,
                    'current_amount', COALESCE(v_resource.amount,0),
                    'max_amount', COALESCE(v_resource.max_amount,0),
                    'preview_collect', v_preview
                )
            ELSE NULL
        END
    );
END;
$$;


ALTER FUNCTION public.get_building_detail(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: get_building_production_info(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_building_production_info(p_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'building_id', b.id,
        'building_type', b.building_type,
        'level', b.level,
        'resource_code', bp.resource_code,
        'rate_per_hour', bp.production_rate_per_hour,
        'capacity', bp.production_capacity,
        'seconds_elapsed',
            EXTRACT(EPOCH FROM (now() - b.last_production_at))::bigint,
        'producible_amount',
            (bp.production_rate_per_hour *
                (EXTRACT(EPOCH FROM (now() - b.last_production_at)) / 3600)
            ),
        'capped_amount',
            LEAST(
                bp.production_capacity,
                (bp.production_rate_per_hour *
                    (EXTRACT(EPOCH FROM (now() - b.last_production_at)) / 3600)
                )
            )
    )
    INTO v_result
    FROM player_region_buildings b
    JOIN building_production bp
        ON bp.building_type = b.building_type
        AND bp.level = b.level
    WHERE b.id = p_building_id
      AND b.upgrading = false;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_building_production_info(p_building_id uuid) OWNER TO postgres;

--
-- Name: get_building_trainable_units(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_building_trainable_units(p_player_region_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH building_info AS (
        SELECT building_type, level
        FROM public.player_region_buildings
        WHERE id = p_player_region_building_id
    ),
    latest_training AS (
        SELECT DISTINCT ON (but.unit_type)
            but.building_type,
            but.unit_type,
            but.level AS training_level,
            but.training_rate_per_hour,
            but.training_capacity,
            but.efficiency_percent
        FROM building_info bi
        JOIN public.building_unit_training but
            ON bi.building_type = but.building_type
           AND bi.level >= but.level
        ORDER BY but.unit_type, but.level DESC
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'unit_id', u.id,
            'unit_name', u.name,
            'image_path', u.image_path,
            'unit_type', u.type,
            'description', u.description,
            'level', u.level,
            'max_hp', u.max_hp,
            'atk', u.atk,
            'def', u.def,
            'speed', u.speed,
            'range', u.range,
            'rank', u.rank,

            'training_rate_per_hour',
                lt.training_rate_per_hour,

            'training_capacity',
                lt.training_capacity,

            'efficiency_percent',
                lt.efficiency_percent,

            'required_building_level',
                lt.training_level,

            'training_time_per_unit',
                (1.0 / lt.training_rate_per_hour)
                * interval '1 hour',

            'training_cost',
                public.get_unit_training_cost(u.id)
        )
    )
    INTO v_result
    FROM latest_training lt
    JOIN public.units u
        ON u.id = lt.unit_type;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_building_trainable_units(p_player_region_building_id uuid) OWNER TO postgres;

--
-- Name: get_building_upgrade_preview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_building_upgrade_preview(p_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building_type varchar;
    v_current_level int;
    v_next_level int;

    v_cost json;
    v_upgrade_time int; -- 👈 đổi sang int (seconds)
    v_training_benefits json;
    v_production_benefits json;
BEGIN
    -- 1. Get building info
    SELECT building_type, level
    INTO v_building_type, v_current_level
    FROM player_region_buildings
    WHERE id = p_building_id;

    IF v_current_level IS NULL THEN
        RAISE EXCEPTION 'Building not found';
    END IF;

    v_next_level := v_current_level + 1;

    -- 2. Cost + upgrade_time (FIX theo range + convert seconds)
    SELECT 
        json_agg(
            json_build_object(
                'resource_code', resource_code,
                'amount', resource_amount
            )
        ),
        COALESCE(MAX(EXTRACT(EPOCH FROM upgrade_time)), 0)::int
    INTO v_cost, v_upgrade_time
    FROM building_upgrade_cost
    WHERE building_type = v_building_type
      AND v_current_level >= current_level
      AND v_current_level < target_level;

    -- 3. TRAINING BENEFITS
    SELECT json_agg(
        json_build_object(
            'unit_type', curr.unit_type,
            'current', json_build_object(
                'rate', curr.training_rate_per_hour,
                'capacity', curr.training_capacity,
                'efficiency', curr.efficiency_percent
            ),
            'next', json_build_object(
                'rate', next.training_rate_per_hour,
                'capacity', next.training_capacity,
                'efficiency', next.efficiency_percent
            ),
            'delta', json_build_object(
                'rate', next.training_rate_per_hour - curr.training_rate_per_hour,
                'capacity', next.training_capacity - curr.training_capacity,
                'efficiency', next.efficiency_percent - curr.efficiency_percent
            )
        )
    )
    INTO v_training_benefits
    FROM building_unit_training curr
    JOIN building_unit_training next
      ON curr.unit_type = next.unit_type
     AND curr.building_type = next.building_type
    WHERE curr.building_type = v_building_type
      AND curr.level = v_current_level
      AND next.level = v_next_level;

    -- 4. PRODUCTION BENEFITS
    SELECT json_agg(
        json_build_object(
            'resource_code', curr.resource_code,
            'current', json_build_object(
                'rate', curr.production_rate_per_hour,
                'capacity', curr.production_capacity,
                'efficiency', curr.efficiency_percent
            ),
            'next', json_build_object(
                'rate', next.production_rate_per_hour,
                'capacity', next.production_capacity,
                'efficiency', next.efficiency_percent
            ),
            'delta', json_build_object(
                'rate', next.production_rate_per_hour - curr.production_rate_per_hour,
                'capacity', next.production_capacity - curr.production_capacity,
                'efficiency', next.efficiency_percent - curr.efficiency_percent
            )
        )
    )
    INTO v_production_benefits
    FROM building_production curr
    JOIN building_production next
      ON curr.resource_code = next.resource_code
     AND curr.building_type = next.building_type
    WHERE curr.building_type = v_building_type
      AND curr.level = v_current_level
      AND next.level = v_next_level;

    -- 5. RETURN
    RETURN json_build_object(
        'building_type', v_building_type,
        'current_level', v_current_level,
        'next_level', v_next_level,

        'upgrade_time', v_upgrade_time, -- 👈 seconds

        'cost', COALESCE(v_cost, '[]'::json),

        'training_benefits', COALESCE(v_training_benefits, '[]'::json),
        'production_benefits', COALESCE(v_production_benefits, '[]'::json)
    );
END;
$$;


ALTER FUNCTION public.get_building_upgrade_preview(p_building_id uuid) OWNER TO postgres;

--
-- Name: get_buildings(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_buildings(p_player_id uuid, p_region_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_resource RECORD;
    v_resource_code TEXT;
    v_preview NUMERIC;
    v_result JSONB := '[]'::JSONB;
BEGIN
    FOR v_building IN
        SELECT prb.*
        FROM player_region_buildings prb
        JOIN player_regions pr ON pr.id = prb.player_region_id
        WHERE pr.player_id = p_player_id
          AND pr.region_id = p_region_id
    LOOP
        -- resource building sản xuất (nếu có)
        SELECT bp.resource_code
        INTO v_resource_code
        FROM building_production bp
        WHERE bp.building_type = v_building.building_type
          AND bp.level = v_building.level
        LIMIT 1;

        -- region resource
        IF v_resource_code IS NOT NULL THEN
            SELECT * INTO v_resource
            FROM region_resources
            WHERE player_region_id = v_building.player_region_id
              AND resource_code = v_resource_code;

            IF NOT FOUND THEN
                v_resource.amount := 0;
                v_resource.max_amount := 2500;
                v_resource.last_collected_at := now() - interval '1 hour';
            END IF;

            -- preview collect
            SELECT (bp.production_rate_per_hour * COALESCE(bp.efficiency_percent,100)/100 *
                    EXTRACT(EPOCH FROM (NOW() - v_resource.last_collected_at))/3600)
            INTO v_preview
            FROM building_production bp
            WHERE bp.building_type = v_building.building_type
              AND bp.level = v_building.level
              AND bp.resource_code = v_resource_code
            LIMIT 1;

            v_preview := LEAST(
                v_preview,
                COALESCE(v_resource.max_amount,0) - COALESCE(v_resource.amount,0)
            );
            v_preview := GREATEST(v_preview,0);
        ELSE
            v_preview := 0;
        END IF;

        -- append result
        v_result := v_result || jsonb_build_array(
            jsonb_build_object(
                'player_building_id', v_building.id,
                'building_type', v_building.building_type,
                'level', v_building.level,
                'upgrading', v_building.upgrading,
                'upgrade_finish_at', v_building.upgrade_finish_at,
                'upgrade_remaining_seconds',
                    CASE
                        WHEN v_building.upgrading AND v_building.upgrade_finish_at > now()
                        THEN EXTRACT(EPOCH FROM (v_building.upgrade_finish_at - now()))::INT
                        ELSE 0
                    END,
                'resource_code', v_resource_code,
                'current_amount', COALESCE(v_resource.amount,0),
                'max_amount', COALESCE(v_resource.max_amount,0),
                'preview_collect', COALESCE(v_preview,0)
            )
        );
    END LOOP;

    RETURN v_result::JSON;
END;
$$;


ALTER FUNCTION public.get_buildings(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: get_claimable_achievements(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_claimable_achievements(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
BEGIN
    WITH claimable_achievements AS (
        SELECT 
            a.id,
            a.name,
            a.description,
            a.tier,
            a.points,
            a.target_progress,
            pa.progress as player_progress,
            pa.unlocked_at,
            pa.repeat_count,
            json_agg(
                json_build_object(
                    'reward_id', r.id,
                    'item_id', r.item_id,
                    'item_name', COALESCE(bi.name, 'Unknown Item'),
                    'item_rarity', COALESCE(bi.rarity, 'common'),
                    'quantity', r.quantity,
                    'value', COALESCE(bi.base_value * r.quantity, 0)
                ) ORDER BY COALESCE(bi.base_value, 0) DESC
            ) as rewards
        FROM achievements a
        INNER JOIN player_achievements pa ON a.id = pa.achievement_id
        LEFT JOIN achievement_rewards r ON a.id = r.achievement_id
        LEFT JOIN base_items bi ON r.item_id = bi.id
        WHERE pa.player_id = p_player_id
        AND pa.progress >= a.target_progress
        AND pa.reward_claimed = false
        AND a.status = 'active'
        GROUP BY a.id, a.name, a.description, a.tier, a.points, a.target_progress, 
                 pa.progress, pa.unlocked_at, pa.repeat_count
    ),
    summary AS (
        SELECT 
            COUNT(*) as total_claimable,
            SUM(ca.points) as total_points,
            SUM(
                (SELECT SUM(bi.base_value * r.quantity)
                 FROM achievement_rewards r
                 LEFT JOIN base_items bi ON r.item_id = bi.id
                 WHERE r.achievement_id = ca.id)
            ) as total_rewards_value
        FROM claimable_achievements ca
    )
    SELECT json_build_object(
        'player_id', p_player_id,
        'summary', (
            SELECT json_build_object(
                'total_claimable', total_claimable,
                'total_points', total_points,
                'total_rewards_value', COALESCE(total_rewards_value, 0)
            )
            FROM summary
        ),
        'achievements', COALESCE(
            json_agg(
                json_build_object(
                    'id', ca.id,
                    'name', ca.name,
                    'tier', ca.tier,
                    'points', ca.points,
                    'completed_at', ca.unlocked_at,
                    'repeat_count', ca.repeat_count,
                    'rewards', ca.rewards
                ) ORDER BY ca.tier DESC, ca.points DESC
            ),
            '[]'::json
        )
    ) INTO result
    FROM claimable_achievements ca;
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.get_claimable_achievements(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_combat_logs_by_player(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_combat_logs_by_player(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', t.id,
                'player_id', t.player_id,
                'icon_name', t.icon_name,
                'title', t.title,
                'color_code', t.color_code,
                'log_type', t.log_type,
                'battle_id', t.battle_id,
                'opponent_id', t.opponent_id,
                'damage_dealt', t.damage_dealt,
                'damage_received', t.damage_received,
                'resources_gained', t.resources_gained,
                'resources_lost', t.resources_lost,
                'territory_changed', t.territory_changed,
                'victory_points_changed', t.victory_points_changed,
                'timestamp', t.event_timestamp,
                'is_read', t.is_read
            )
        )
        FROM (
            SELECT *
            FROM public.combat_logs
            WHERE player_id = p_player_id
            ORDER BY event_timestamp DESC
            LIMIT 20
        ) AS t
    );
END;
$$;


