--
-- Name: get_combat_troops_json(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_combat_troops_json(p_region_id text, p_player_id uuid, p_battle_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(row_to_json(t))
        FROM (
            SELECT 
                ct.id AS combat_troop_id,
                ct.battle_id,
                ct.player_id,
                ct.region_id,
                ct.unit_type,
                ct.original_quantity,
                ct.current_quantity,
                ct.lost_quantity,
                ct.survived_quantity,
                ct.battle_role,
                ct.attack_power,
                ct.defense_power,
                ct.health_points,
                ct.movement_speed,
                ct.status,
                ct.joined_at,
                ct.updated_at,
                ct.resolved_at,
                ct.returned_to_region,
                ct.returned_at,
                ct.return_quantity,
                ct.recovery_quantity,
                
                -- Thông tin từ units
                u.name AS unit_name,
                u.type AS unit_type_enum,
                u.level AS base_level,
                u.max_hp AS base_max_hp,
                u.atk AS base_atk,
                u.def AS base_def,
                u.speed AS base_speed,
                u.is_vip,
                u.rank AS unit_rank,
                
                -- Thông tin từ player_units
                pu.id AS player_unit_id,
                pu.quantity AS player_quantity,
                pu.level AS troop_level,
                pu.current_hp AS troop_current_hp,
                pu.experience,
                pu.formation_position,
                pu.is_in_garrison,
                pu.attack AS attack_bonus,
                pu.defense AS defense_bonus,
                pu.speed AS speed_bonus,
                pu.max_hp AS troop_max_hp
            FROM combat_troops ct
            INNER JOIN units u ON ct.unit_type = u.id
            INNER JOIN player_units pu ON ct.player_id = pu.player_id AND ct.unit_type = pu.unit_id
            WHERE ct.region_id = p_region_id
              AND ct.player_id = p_player_id
              AND (p_battle_id IS NULL OR ct.battle_id = p_battle_id)
        ) t
    );
END;
$$;


ALTER FUNCTION public.get_combat_troops_json(p_region_id text, p_player_id uuid, p_battle_id uuid) OWNER TO postgres;

--
-- Name: get_current_events(timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_events(p_current_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP) RETURNS TABLE(id character varying, title character varying, subtitle character varying, banner_height integer, image_url character varying, link_url character varying, event_type character varying, week_days character varying, week_of_month character varying, month_days character varying, quarter_number integer, holiday_date date, holiday_name character varying, start_date timestamp without time zone, end_date timestamp without time zone, repeat_yearly boolean, repeat_monthly boolean, priority integer, status character varying, match_type text)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_current_day INTEGER;
    v_current_month_day INTEGER;
    v_current_month INTEGER;
    v_current_year INTEGER;
    v_current_date DATE;
    v_current_quarter INTEGER;
    v_week_of_month INTEGER;
BEGIN
    -- Lấy các giá trị từ thời gian hiện tại
    v_current_day := EXTRACT(ISODOW FROM p_current_time);
    v_current_month_day := EXTRACT(DAY FROM p_current_time);
    v_current_month := EXTRACT(MONTH FROM p_current_time);
    v_current_year := EXTRACT(YEAR FROM p_current_time);
    v_current_date := p_current_time::DATE;
    v_current_quarter := EXTRACT(QUARTER FROM p_current_time);
    
    -- Tính tuần trong tháng (1-5)
    v_week_of_month := CEIL(v_current_month_day::FLOAT / 7);
    
    RETURN QUERY
    SELECT 
        e.id,
        e.title,
        e.subtitle,
        e.banner_height,
        e.image_url,
        e.link_url,
        e.event_type,
        e.week_days,
        e.week_of_month,
        e.month_days,
        e.quarter_number,
        e.holiday_date,
        e.holiday_name,
        e.start_date,
        e.end_date,
        e.repeat_yearly,
        e.repeat_monthly,
        e.priority,
        e.status,
        CASE 
            WHEN e.event_type = 'daily' THEN 'daily_recurring'
            WHEN e.event_type = 'weekly' AND e.week_days LIKE '%' || v_current_day || '%' THEN 'weekly_match'
            WHEN e.event_type = 'week_of_month' AND 
                 e.week_of_month LIKE '%' || v_week_of_month || '%' AND
                 e.week_days LIKE '%' || v_current_day || '%' THEN 'week_of_month_match'
            WHEN e.event_type = 'monthly' AND e.month_days LIKE '%' || v_current_month_day || '%' THEN 'monthly_match'
            WHEN e.event_type = 'quarterly' AND e.quarter_number = v_current_quarter THEN 'quarterly_match'
            WHEN e.event_type = 'yearly' THEN 'yearly_recurring'
            WHEN e.event_type = 'holiday' AND (
                (e.holiday_date = v_current_date) OR 
                (e.repeat_yearly = TRUE AND 
                 EXTRACT(MONTH FROM e.holiday_date) = v_current_month AND 
                 EXTRACT(DAY FROM e.holiday_date) = v_current_month_day)
            ) THEN 'holiday_match'
            WHEN e.event_type = 'custom_range' AND 
                 p_current_time BETWEEN e.start_date AND e.end_date THEN 'custom_range_match'
            ELSE NULL
        END AS match_type
    FROM events e
    WHERE 
        e.status = 'active'
        AND (
            -- 1. Sự kiện hàng ngày
            (e.event_type = 'daily')
            
            -- 2. Sự kiện hàng tuần (theo ngày trong tuần)
            OR (e.event_type = 'weekly' AND e.week_days LIKE '%' || v_current_day || '%')
            
            -- 3. Sự kiện theo tuần trong tháng
            OR (e.event_type = 'week_of_month' AND 
                e.week_of_month LIKE '%' || v_week_of_month || '%' AND
                e.week_days LIKE '%' || v_current_day || '%')
            
            -- 4. Sự kiện hàng tháng (theo ngày trong tháng)
            OR (e.event_type = 'monthly' AND e.month_days LIKE '%' || v_current_month_day || '%')
            
            -- 5. Sự kiện hàng quý
            OR (e.event_type = 'quarterly' AND e.quarter_number = v_current_quarter)
            
            -- 6. Sự kiện hàng năm
            OR (e.event_type = 'yearly')
            
            -- 7. Sự kiện ngày lễ
            OR (e.event_type = 'holiday' AND (
                e.holiday_date = v_current_date
                OR (e.repeat_yearly = TRUE AND 
                    EXTRACT(MONTH FROM e.holiday_date) = v_current_month AND 
                    EXTRACT(DAY FROM e.holiday_date) = v_current_month_day)
            ))
            
            -- 8. Sự kiện trong khoảng thời gian
            OR (e.event_type = 'custom_range' AND 
                p_current_time BETWEEN e.start_date AND e.end_date)
        )
    ORDER BY 
        e.priority DESC,
        e.created_at DESC;
END;
$$;


ALTER FUNCTION public.get_current_events(p_current_time timestamp without time zone) OWNER TO postgres;

--
-- Name: get_daily_quests_complete_login(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_quests_complete_login(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_completed_at timestamp;
    v_login_quest_id uuid;
    result jsonb;
BEGIN
    -- Lấy thời điểm hiện tại
    v_completed_at := now();

    -- Hoàn thành quest login hôm nay nếu chưa làm
    SELECT q.id
    INTO v_login_quest_id
    FROM public.players pl
    CROSS JOIN public.quests q
    WHERE pl.id = p_player_id
      AND q.category = 'daily'
      AND q.type = 'login'
      AND q.min_level <= pl.level
      AND q.max_level >= pl.level
    LIMIT 1;

    IF v_login_quest_id IS NOT NULL THEN
        INSERT INTO public.player_quest_progress(player_id, quest_id, progress, target, completed, completed_at)
        VALUES (p_player_id, v_login_quest_id, 1, 1, true, v_completed_at)
        ON CONFLICT (player_id, quest_id) DO UPDATE
        SET progress = 1,
            completed = true,
            completed_at = v_completed_at;
    END IF;

    -- Lấy tất cả daily quest + progress hôm nay
    WITH player AS (
        SELECT level
        FROM public.players
        WHERE id = p_player_id
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'quest_id', q.id,
            'quest_name', q.name,
            'description', q.description,
            'type', q.type,
            'category', q.category,
            'difficulty', q.difficulty,
            'min_level', q.min_level,
            'max_level', q.max_level,
            'target', q.completion_limit,
            'progress', COALESCE(pqp.progress, 0),
            'completed', COALESCE(pqp.completed, false),
            'claimed', COALESCE(pqp.claimed, false),
            'completed_at', pqp.completed_at
        )
    ) INTO result
    FROM public.quests q
    CROSS JOIN player
    LEFT JOIN public.player_quest_progress pqp
        ON pqp.quest_id = q.id
        AND pqp.player_id = p_player_id
        AND (pqp.completed_at::date = current_date OR pqp.completed_at IS NULL)
    WHERE q.category = 'daily'
      AND q.min_level <= player.level
      AND q.max_level >= player.level
    ;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_daily_quests_complete_login(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_daily_quests_for_player(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_quests_for_player(p_player_id uuid) RETURNS TABLE(quest_id uuid, quest_name text, description text, type text, category text, difficulty text, min_level integer, max_level integer, target integer, progress integer, completed boolean, claimed boolean, completed_at timestamp without time zone)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH player AS (
        SELECT level
        FROM public.players
        WHERE id = p_player_id
    )
    SELECT 
        q.id AS quest_id,
        q.name AS quest_name,
        q.description,
        q.type,
        q.category,
        q.difficulty,
        q.min_level,
        q.max_level,
        q.completion_limit AS target,
        COALESCE(pqp.progress, 0) AS progress,
        COALESCE(pqp.completed, false) AS completed,
        COALESCE(pqp.claimed, false) AS claimed,
        pqp.completed_at
    FROM public.quests q
    CROSS JOIN player
    LEFT JOIN public.player_quest_progress pqp
        ON pqp.quest_id = q.id
        AND pqp.player_id = p_player_id
    WHERE q.category = 'daily'
      AND q.min_level <= player.level
      AND q.max_level >= player.level
    ORDER BY q.difficulty, q.name;
END;
$$;


ALTER FUNCTION public.get_daily_quests_for_player(p_player_id uuid) OWNER TO postgres;

