--
-- Name: get_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_dashboard_stats() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total_players          bigint;
  v_new_players_today      bigint;
  v_new_players_this_week  bigint;
  v_active_players_today   bigint;
  v_active_players_this_week bigint;

  v_total_alliances        bigint;
  v_new_alliances_today    bigint;
  v_total_alliance_members bigint;
  v_avg_alliance_size      numeric;

  v_total_battles          bigint;
  v_battles_today          bigint;
  v_battles_this_week      bigint;
  v_completed_battles      bigint;

  v_daily jsonb;
  v_weekly jsonb;

  r jsonb;
begin
  -- ============================ PLAYERS ============================
  select count(*) into v_total_players          from public.players;
  select count(*) into v_new_players_today      from public.players
    where registration_date >= date_trunc('day', now());
  select count(*) into v_new_players_this_week  from public.players
    where registration_date >= date_trunc('day', now()) - interval '7 days';

  select count(distinct pid) into v_active_players_today
  from (
    select player1_id as pid from public.battles
      where created_at >= date_trunc('day', now())
    union
    select player2_id from public.battles
      where created_at >= date_trunc('day', now())
  ) t where pid is not null;

  select count(distinct pid) into v_active_players_this_week
  from (
    select player1_id as pid from public.battles
      where created_at >= (date_trunc('day', now()) - interval '7 days')
    union
    select player2_id from public.battles
      where created_at >= (date_trunc('day', now()) - interval '7 days')
  ) t where pid is not null;

  -- ============================ ALLIANCES ============================
  select count(*) into v_total_alliances from public.alliances;
  select count(*) into v_new_alliances_today from public.alliances
    where created_date >= date_trunc('day', now());
  select count(*) into v_total_alliance_members from public.alliance_members;

  select case
           when v_total_alliance_members = 0
                or count(distinct alliance_id) = 0
           then 0
           else round(v_total_alliance_members::numeric / count(distinct alliance_id), 0)
         end
  into v_avg_alliance_size
  from public.alliance_members;

  -- ============================ BATTLES ============================
  select count(*) into v_total_battles    from public.battles;
  select count(*) into v_battles_today    from public.battles
    where created_at >= date_trunc('day', now());
  select count(*) into v_battles_this_week from public.battles
    where created_at >= (date_trunc('day', now()) - interval '7 days');
  select count(*) into v_completed_battles from public.battles
    where status = 'completed';

  -- ============================ DAILY STATS (30 ngày) ============================
  select coalesce(jsonb_agg(j), '[]'::jsonb)
  into v_daily
  from (
    select jsonb_build_object(
             'date',    to_char(d.day, 'YYYY-MM-DD'),
             'players', (select count(*) from public.players
                          where registration_date >= d.day
                            and registration_date <  d.day + interval '1 day'),
             'battles', (select count(*) from public.battles
                          where created_at >= d.day
                            and created_at <  d.day + interval '1 day'),
             'revenue', 0
           ) as j
    from generate_series(
           (date_trunc('day', now())::date - 29)::timestamptz,
           date_trunc('day', now())::timestamptz,
           interval '1 day'
         ) as d(day)
  ) t;

  -- ============================ WEEKLY STATS (4 tuần) ============================
  select coalesce(jsonb_agg(j), '[]'::jsonb)
  into v_weekly
  from (
    select jsonb_build_object(
             'week', 'Tuan ' || (4 - w.offset_week),
             'players', (select count(*) from public.players
                          where registration_date >= w.start_d
                            and registration_date <  w.start_d + interval '7 days'),
             'battles', (select count(*) from public.battles
                          where created_at >= w.start_d
                            and created_at <  w.start_d + interval '7 days'),
             'revenue', 0
           ) as j
    from (
      select
        offs as offset_week,
        (date_trunc('day', now()) - (offs * 7 + 7) * interval '1 day') as start_d
      from generate_series(0, 3) as offs(offs)
    ) w
  ) t;

  -- ============================ ASSEMBLE ============================
  r := jsonb_build_object(
    'totalPlayers',           v_total_players,
    'newPlayersToday',        v_new_players_today,
    'newPlayersThisWeek',     v_new_players_this_week,
    'activePlayersToday',     v_active_players_today,
    'activePlayersThisWeek',  v_active_players_this_week,

    'totalAlliances',         v_total_alliances,
    'newAlliancesToday',      v_new_alliances_today,
    'totalAllianceMembers',   v_total_alliance_members,
    'avgAllianceSize',        v_avg_alliance_size,

    'totalBattles',           v_total_battles,
    'battlesToday',           v_battles_today,
    'battlesThisWeek',        v_battles_this_week,
    'battleCompletionRate',   case when v_total_battles = 0 then 0
                                   else ceil(v_completed_battles::numeric / v_total_battles * 100)::int end,
    'battlesByStatus',        coalesce((
      select jsonb_agg(jsonb_build_object('status', status, 'count', cnt))
      from (select status, count(*) as cnt from public.battles group by status) s
    ), '[]'::jsonb),

    'dailyStats',             v_daily,
    'weeklyStats',            v_weekly
  );

  return r::json;
end;
$$;


ALTER FUNCTION public.get_dashboard_stats() OWNER TO postgres;

--
-- Name: get_equipment_stats_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_equipment_stats_json(p_player_general_id uuid) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT jsonb_build_object(
    'attack', COALESCE(SUM(s.attack),0),
    'defense', COALESCE(SUM(s.defense),0),
    'health', COALESCE(SUM(s.health),0),
    'mana', COALESCE(SUM(s.mana),0),
    'strength', COALESCE(SUM(s.strength),0),
    'agility', COALESCE(SUM(s.agility),0),
    'intelligence', COALESCE(SUM(s.intelligence),0),
    'speed', COALESCE(SUM(s.speed),0),
    'leadership', COALESCE(SUM(s.leadership),0),
    'critical_chance', COALESCE(SUM(s.critical_chance),0),
    'critical_damage', COALESCE(SUM(s.critical_damage),0),
    'dodge', COALESCE(SUM(s.dodge),0),
    'block', COALESCE(SUM(s.block),0),
    'resistance', COALESCE(SUM(s.resistance),0)
)
FROM equipment_items e
CROSS JOIN LATERAL unnest(ARRAY[
    e.weapon_id,
    e.armor_id,
    e.helmet_id,
    e.cloak_id,
    e.boots_id,
    e.ring_id,
    e.shield_id
]) AS item_id
JOIN item_stats s
    ON s.base_item_id = item_id
WHERE e.player_general_id = p_player_general_id;
$$;


ALTER FUNCTION public.get_equipment_stats_json(p_player_general_id uuid) OWNER TO postgres;

--
-- Name: get_equipped_items_of_unit(uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_equipped_items_of_unit(p_player_id uuid, p_unit_id character varying) RETURNS TABLE(slot_name text, item_id character varying, item_name character varying, item_type public.item_type, rarity public.rarity_type, quality public.quality_type, level_requirement integer, icon character varying)
    LANGUAGE sql
    AS $$
    SELECT
        slot_name,
        bi.id AS item_id,
        bi.name AS item_name,
        bi.type AS item_type,
        bi.rarity,
        bi.quality,
        bi.level_requirement,
        bi.icon
    FROM (
        SELECT 'weapon'    AS slot_name, weapon_item_id    AS item_id FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'armor',    armor_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'helmet',   helmet_item_id                  FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'cloak',    cloak_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'boots',    boots_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'shield',   shield_item_id                  FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'mount',    mount_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'accessory',accessory_item_id               FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'ring1',    ring1_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
        UNION ALL
        SELECT 'ring2',    ring2_item_id                   FROM player_units WHERE player_id = p_player_id AND unit_id = p_unit_id
    ) slots
    JOIN base_items bi ON bi.id = slots.item_id
    WHERE slots.item_id IS NOT NULL;
$$;


ALTER FUNCTION public.get_equipped_items_of_unit(p_player_id uuid, p_unit_id character varying) OWNER TO postgres;

--
-- Name: get_event_actions(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_actions(event_type character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN CASE event_type
        WHEN 'raid' THEN json_build_array(
            json_build_object('action', 'defend', 'cost', 'troops', 'effect', 'reduce damage'),
            json_build_object('action', 'negotiate', 'cost', 'gold', 'effect', 'end event early'),
            json_build_object('action', 'counter_attack', 'cost', 'troops', 'effect', 'gain loot')
        )
        WHEN 'harvest' THEN json_build_array(
            json_build_object('action', 'celebrate', 'cost', 'food', 'effect', 'increase loyalty'),
            json_build_object('action', 'store', 'cost', 'none', 'effect', 'extra food storage'),
            json_build_object('action', 'trade', 'cost', 'none', 'effect', 'bonus gold')
        )
        WHEN 'rebellion' THEN json_build_array(
            json_build_object('action', 'suppress', 'cost', 'troops', 'effect', 'end rebellion'),
            json_build_object('action', 'negotiate', 'cost', 'gold', 'effect', 'reduce severity'),
            json_build_object('action', 'reform', 'cost', 'resources', 'effect', 'long-term loyalty')
        )
        ELSE json_build_array()
    END;
END;
$$;


ALTER FUNCTION public.get_event_actions(event_type character varying) OWNER TO postgres;

--
-- Name: get_event_description(character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_description(event_type character varying, severity integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN CASE event_type
        WHEN 'raid' THEN 
            CASE severity
                WHEN 1 THEN 'Small bandit raid'
                WHEN 2 THEN 'Organized bandit attack'
                WHEN 3 THEN 'Enemy scouting party'
                WHEN 4 THEN 'Full-scale enemy raid'
                WHEN 5 THEN 'Major military invasion'
            END
        WHEN 'harvest' THEN 
            CASE severity
                WHEN 1 THEN 'Bumper crop harvest'
                WHEN 2 THEN 'Excellent harvest season'
                WHEN 3 THEN 'Record-breaking harvest'
            END
        WHEN 'rebellion' THEN 
            CASE severity
                WHEN 1 THEN 'Minor civil unrest'
                WHEN 2 THEN 'Local rebellion'
                WHEN 3 THEN 'Regional uprising'
                WHEN 4 THEN 'Full-scale civil war'
                WHEN 5 THEN 'Revolution'
            END
        WHEN 'natural_disaster' THEN 'Natural disaster strikes'
        WHEN 'trade_opportunity' THEN 'Trade caravan arrives'
        WHEN 'diplomatic_visit' THEN 'Diplomatic envoy visits'
        ELSE 'Unknown event'
    END;
END;
$$;


ALTER FUNCTION public.get_event_description(event_type character varying, severity integer) OWNER TO postgres;

--
-- Name: get_friend_requests(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friend_requests(p_player_id uuid) RETURNS TABLE(request_id uuid, sender_id uuid, sender_username text, created_date timestamp with time zone, nickname text, favorite boolean, notes text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        f.id,
        f.player_id AS sender_id,
        p.username AS sender_username,
        f.created_date,
        f.nickname,
        f.favorite,
        f.notes
    FROM friend_relationships f
    JOIN players p ON p.id = f.player_id
    WHERE f.friend_id = p_player_id
      AND f.status = 'pending'
    ORDER BY f.created_date DESC;
END;
$$;


ALTER FUNCTION public.get_friend_requests(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_friend_requests_detailed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friend_requests_detailed(p_player_id uuid) RETURNS TABLE(request_id uuid, from_player_id uuid, from_username text, from_level integer, from_power bigint, from_alliance text, from_specialization text, from_victory_points integer, from_win_rate numeric, from_battles integer, request_status text, created_date timestamp with time zone, nickname text, notes text, days_since_registration integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        fr.id as request_id,
        p.id as from_player_id,
        p.username as from_username,
        p.level as from_level,
        p.power as from_power,
        p.alliance as from_alliance,
        p.specialization as from_specialization,
        p.victory_points as from_victory_points,
        p.win_rate as from_win_rate,
        p.battles as from_battles,
        fr.status as request_status,
        fr.created_date,
        fr.nickname,
        fr.notes,
        EXTRACT(DAYS FROM (NOW() - p.registration_date))::INTEGER as days_since_registration
    FROM friend_relationships fr
    INNER JOIN players p ON fr.player_id = p.id
    WHERE fr.friend_id = p_player_id
    AND fr.status = 'pending'
    ORDER BY fr.created_date DESC;
END;
$$;


ALTER FUNCTION public.get_friend_requests_detailed(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_friend_requests_with_info(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friend_requests_with_info(p_receiver_id uuid) RETURNS TABLE(request_id uuid, requester_name text, avatar text, level integer, time_ago text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        f.id AS request_id,
        p.username AS requester_name,
        p.level AS level,
        -- tính "time ago" dạng text, ví dụ: '5 minutes ago'
        CASE 
            WHEN now() - f.created_date < interval '1 minute' THEN 'just now'
            WHEN now() - f.created_date < interval '1 hour' THEN concat(EXTRACT(MINUTE FROM now() - f.created_date)::int, ' minutes ago')
            WHEN now() - f.created_date < interval '24 hour' THEN concat(EXTRACT(HOUR FROM now() - f.created_date)::int, ' hours ago')
            ELSE concat(EXTRACT(DAY FROM now() - f.created_date)::int, ' days ago')
        END AS time_ago
    FROM friend_relationships f
    JOIN players p ON p.id = f.player_id
    WHERE f.friend_id = p_receiver_id
      AND f.status = 'pending'
    ORDER BY f.created_date DESC;
END;
$$;


ALTER FUNCTION public.get_friend_requests_with_info(p_receiver_id uuid) OWNER TO postgres;

--
-- Name: get_friend_suggestions(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friend_suggestions(p_player_id uuid, p_limit integer DEFAULT 10) RETURNS TABLE(suggested_id uuid, username text, level integer, country text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT p.id, p.username, p.level, p.country
    FROM players p
    WHERE p.id <> p_player_id
      -- Bỏ qua bạn bè đã accept hoặc lời mời pending
      AND NOT EXISTS (
          SELECT 1
          FROM friend_relationships f
          WHERE (
                 (f.player_id = p_player_id AND f.friend_id = p.id)
              OR (f.player_id = p.id AND f.friend_id = p_player_id)
          )
          AND f.status IN ('accepted', 'pending')
      )
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_friend_suggestions(p_player_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_friend_suggestions_json(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friend_suggestions_json(p_player_id uuid, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(jsonb_build_object(
        -- Fake friend_relationships fields
        'relationship_id', NULL,
        'friendship_status', 'suggested',
        'created_date', NULL,
        'accepted_date', NULL,
        'nickname', NULL,
        'favorite', false,
        'notes', NULL,

        -- players table fields
        'friend_id', p.id,
        'username', p.username,
        'avatar', p.avatar,
        'level', p.level,
        'power', p.power,
        'status', p.status,
        'online', (p.status = 'online'),
        'alliance', p.alliance,
        'role_in_alliance', COALESCE(p.role_in_alliance,'member'),
        'title', p.title,
        'specialization', p.specialization,
        'victory_points', p.victory_points,
        'win_rate', p.win_rate,
        'country', p.country,
        'last_login', p.last_login
    ))
    INTO result
    FROM (
        SELECT p.*
        FROM players p
        WHERE p.id <> p_player_id
          AND NOT EXISTS (
              SELECT 1
              FROM friend_relationships f
              WHERE (
                     (f.player_id = p_player_id AND f.friend_id = p.id)
                  OR (f.player_id = p.id AND f.friend_id = p_player_id)
              )
              AND f.status IN ('accepted', 'pending')
          )
        ORDER BY p.level DESC, p.power DESC
        LIMIT p_limit
    ) p;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_friend_suggestions_json(p_player_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_friends_list(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_friends_list(p_player_id uuid) RETURNS TABLE(friend_id uuid, username text, status text, nickname text, favorite boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        f.friend_id,
        p.username,
        p.status,
        f.nickname,
        f.favorite
    FROM friend_relationships f
    JOIN players p ON p.id = f.friend_id
    WHERE f.player_id = p_player_id
      AND f.status = 'accepted'
    ORDER BY p.username;
END;
$$;


