--
-- Name: get_general_details(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_general_details(p_player_id uuid DEFAULT NULL::uuid) RETURNS TABLE(general_json json)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
WITH general_data AS (
SELECT
g.id,
pg.id AS player_general_id,
g.name,
g.type::text,
        COALESCE(pg.level, g.level, 1) AS level,

        ROUND(
            g.base_health *
            (1 + ((COALESCE(pg.level, g.level, 1) - 1) * 0.05))
        )::integer AS maxHp,

        COALESCE(
            pg.current_health,
            g.current_health
        ) AS currentHp,

        ROUND(
            g.base_attack *
            (1 + ((COALESCE(pg.level, g.level, 1) - 1) * 0.05))
        )::integer AS atk,

        ROUND(
            g.base_defense *
            (1 + ((COALESCE(pg.level, g.level, 1) - 1) * 0.05))
        )::integer AS def,

        ROUND(
            g.base_speed *
            (1 + ((COALESCE(pg.level, g.level, 1) - 1) * 0.05))
        )::integer AS speed,

        ROUND(
            g.base_leadership *
            (1 + ((COALESCE(pg.level, g.level, 1) - 1) * 0.05))
        )::integer AS leadership,

        g.is_vip AS isVIP,
        g.biography AS description,
        g.title AS faction,
        (pg.id IS NOT NULL) AS owned,
        g.rarity

    FROM public.generals g

    LEFT JOIN public.player_generals pg
        ON g.id = pg.general_id
        AND (
            p_player_id IS NULL
            OR pg.player_id = p_player_id
        )
),

skills_data AS (
    SELECT
        gd.id,

        json_agg(
            json_build_object(
                'id', s.id,
                'name', s.name,
                'description', s.description,
                'type', s.type,
                'level', COALESCE(ps.level, s.level),
                'max_level', s.max_level,
                'cooldown', s.cooldown,
                'mana_cost', s.mana_cost,
                'icon', s.icon,
                'is_unlocked', COALESCE(ps.is_unlocked, false)
            )
        ) FILTER (
            WHERE s.id IS NOT NULL
        ) AS skills

    FROM general_data gd

    LEFT JOIN public.general_skills s
        ON gd.id = s.general_id

    LEFT JOIN public.player_general_skills ps
        ON s.id = ps.general_skill_id
        AND ps.player_general_id = gd.player_general_id

    GROUP BY gd.id
)

SELECT
    json_build_object(
        'general',
        json_build_object(
            'id', gd.id,
            'player_general_id', gd.player_general_id,
            'name', gd.name,
            'type', gd.type,
            'level', gd.level,
            'maxHp', gd.maxHp,
            'currentHp', LEAST(gd.currentHp, gd.maxHp),
            'atk', gd.atk,
            'def', gd.def,
            'speed', gd.speed,
            'leadership', gd.leadership,
            'isVIP', gd.isVIP,
            'description', gd.description,
            'faction', gd.faction,
            'owned', gd.owned
        ),
        'skills',
        COALESCE(sd.skills, '[]'::json),
        'stats',
        get_equipment_stats_json(p_player_id)
    ) AS general_json

FROM general_data gd

LEFT JOIN skills_data sd
    ON gd.id = sd.id

ORDER BY
    gd.rarity DESC,
    gd.name ASC;

END;
$$;


ALTER FUNCTION public.get_general_details(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_general_skill_cost(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_general_skill_cost(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_general_id text;
    v_skill_level int;
    v_max_level int;
    v_is_unlocked boolean;
    v_target_level int;
    v_action text;
    v_cost jsonb;
BEGIN

    -- =========================================================
    -- 1. Kiểm tra tướng thuộc player
    -- =========================================================
    SELECT
        pg.general_id
    INTO
        v_general_id
    FROM public.player_generals pg
    WHERE pg.id = p_player_general_id
      AND pg.player_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tướng không tồn tại hoặc không thuộc về người chơi';
    END IF;


    -- =========================================================
    -- 2. Kiểm tra skill thuộc đúng tướng
    -- =========================================================
    SELECT
        gs.max_level
    INTO
        v_max_level
    FROM public.general_skills gs
    WHERE gs.id = p_general_skill_id
      AND gs.general_id = v_general_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Kỹ năng không thuộc về tướng này';
    END IF;


    -- =========================================================
    -- 3. Lấy trạng thái skill của player
    -- =========================================================
    SELECT
        pgs.level,
        pgs.is_unlocked
    INTO
        v_skill_level,
        v_is_unlocked
    FROM public.player_general_skills pgs
    WHERE pgs.player_general_id = p_player_general_id
      AND pgs.general_skill_id = p_general_skill_id;


    -- =========================================================
    -- 4. Xác định action và target level
    -- =========================================================
    IF v_skill_level IS NULL OR NOT COALESCE(v_is_unlocked, false) THEN

        -- Chưa unlock
        v_action := 'unlock';
        v_target_level := 1;

    ELSIF v_skill_level >= v_max_level THEN

        -- Đã max level
        v_action := 'max';
        v_target_level := NULL;

    ELSE

        -- Upgrade
        v_action := 'upgrade';
        v_target_level := v_skill_level + 1;

    END IF;


    -- =========================================================
    -- 5. Lấy cost
    -- =========================================================
    IF v_target_level IS NOT NULL THEN

        SELECT
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'type',
                        CASE
                            WHEN gsc.currency_type IS NOT NULL
                                THEN 'currency'
                            ELSE 'item'
                        END,
                        'currency_type', gsc.currency_type,
                        'item_id', gsc.item_id,
                        'amount', gsc.amount
                    )
                    ORDER BY gsc.id
                ),
                '[]'::jsonb
            )
        INTO v_cost
        FROM public.general_skill_costs gsc
        WHERE gsc.general_skill_id = p_general_skill_id
          AND gsc.target_level = v_target_level;

    ELSE

        v_cost := '[]'::jsonb;

    END IF;


    -- =========================================================
    -- 6. Trả kết quả
    -- =========================================================
    RETURN jsonb_build_object(
        'success', true,
        'general_skill_id', p_general_skill_id,
        'player_general_id', p_player_general_id,
        'is_unlocked', COALESCE(v_is_unlocked, false),
        'current_level', COALESCE(v_skill_level, 0),
        'max_level', v_max_level,
        'action', v_action,
        'target_level', v_target_level,
        'cost', v_cost
    );

END;
$$;


ALTER FUNCTION public.get_general_skill_cost(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) OWNER TO postgres;

--
-- Name: get_general_upgrade_transaction_data(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_general_upgrade_transaction_data(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_level INTEGER;
    v_from_level INTEGER;
    v_to_level INTEGER;
    v_required_exp INTEGER;
    v_currency_type TEXT;
    v_currency_amount INTEGER;
    v_scaled_exp INTEGER;
    v_scaled_currency INTEGER;
BEGIN
    -- Lấy dữ liệu upgrade cost
    SELECT 
        pg.level,
        guc.from_level,
        guc.to_level,
        guc.required_exp,
        guc.currency_type,
        guc.currency_amount
    INTO 
        v_level,
        v_from_level,
        v_to_level,
        v_required_exp,
        v_currency_type,
        v_currency_amount
    FROM public.player_generals pg
    JOIN public.general_upgrade_costs guc
        ON guc.general_id = pg.general_id
    WHERE pg.player_id = p_player_id
      AND pg.general_id = p_general_id
      AND pg.level >= guc.from_level
      AND pg.level < guc.to_level
    LIMIT 1;

    -- Ném exception nếu không tìm thấy
    IF v_required_exp IS NULL THEN
        RAISE EXCEPTION 'Upgrade cost not found for general "%"', p_general_id;
    END IF;

    -- Tính scaled values
    v_scaled_exp := ROUND(v_required_exp * POWER(1.10, (v_level - v_from_level)))::INTEGER;
    v_scaled_currency := ROUND(v_currency_amount * POWER(1.10, (v_level - v_from_level)))::INTEGER;

    -- Trả về JSON đúng format subtract_execute: dùng 'type' và 'currency'
    RETURN jsonb_build_object(
        'required_exp', v_scaled_exp,
        'transaction_data', jsonb_build_object(
            'p_player_id', p_player_id,
            'p_cost_ops', jsonb_build_array(
                jsonb_build_object(
                    'type', 'currency',
                    'currency', v_currency_type,
                    'amount', v_scaled_currency
                )
            ),
            'p_reward_ops', jsonb_build_array(
                jsonb_build_object(
                    'type', 'general_level',
                    'resource_id', p_general_id,
                    'amount', 1
                )
            )
        )
    );
END;
$$;


ALTER FUNCTION public.get_general_upgrade_transaction_data(p_player_id uuid, p_general_id text) OWNER TO postgres;

