--

CREATE FUNCTION public.get_group_members(p_group_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result json;
BEGIN
    SELECT json_agg(
        json_build_object(
            'member_id', cgm.id,
            'group_id', cgm.group_id,
            'player_id', cgm.player_id,
            'role', cgm.role,
            'joined_date', cgm.joined_date,
            'is_muted', cgm.is_muted,
            'muted_until', cgm.muted_until,
            'nickname', cgm.nickname,
            'last_read_message_id', cgm.last_read_message_id,

            'player', json_build_object(
                'id', p.id,
                'username', p.username,
                'email', p.email,
                'level', p.level,
                'power', p.power,
                'status', p.status,
                'alliance', p.alliance,
                'avatar', p.avatar,
                'title', p.title,
                'win_rate', p.win_rate,
                'victory_points', p.victory_points
            )
        )
    )
    INTO result
    FROM public.chat_group_members cgm
    INNER JOIN public.players p
        ON p.id = cgm.player_id
    WHERE cgm.group_id = p_group_id;

    RETURN COALESCE(result, '[]'::json);
END;
$$;


