    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(
jsonb_agg(
jsonb_build_object(
'message_id', m.id,
'group_id', m.group_id,
'sender_id', m.sender_id,
'sender_username', p.username,
'sender_level', p.level,
'content', m.content,
'created_date', m.created_date
)
ORDER BY m.created_date ASC
),
'[]'::jsonb
)
