--
-- Name: get_guaranteed_rewards_by_trigger(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_guaranteed_rewards_by_trigger(p_loot_box_id text, p_trigger_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_guaranteed jsonb := '[]'::jsonb;
    t_g RECORD;
BEGIN
    FOR t_g IN
        SELECT rbi.item_id, rbi.rarity, rbi.bound_type
        FROM public.loot_box_guaranteed_drops gd
        JOIN public.loot_box_guaranteed_rewards rgr
          ON gd.id = rgr.guaranteed_drop_id
        JOIN public.loot_box_reward_items rbi
          ON rgr.reward_item_id = rbi.id   -- lấy đúng item_id
        WHERE gd.loot_box_id = p_loot_box_id
          AND gd.open_count <= p_trigger_count
    LOOP
        v_guaranteed := v_guaranteed || jsonb_build_object(
            'item_id', t_g.item_id,
            'reward_type', 'item',
            'amount', 1,
            'rarity', t_g.rarity,
            'bound_type', t_g.bound_type,
            'source', 'guaranteed'
        );
    END LOOP;

    RETURN v_guaranteed;
END;
$$;


ALTER FUNCTION public.get_guaranteed_rewards_by_trigger(p_loot_box_id text, p_trigger_count integer) OWNER TO postgres;

