--
-- Name: get_latest_version(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_latest_version(p_os text DEFAULT NULL::text) RETURNS json
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_os is null then
      (select coalesce(json_agg(row_to_json(t)), '[]'::json)
       from (
         select distinct on (gv.os)
           gv.os, gv.version, gv.build_number, gv.is_mandatory,
           gv.download_url, gv.release_notes, gv.created_at
         from public.game_versions gv
         where gv.is_active = true
         order by gv.os, gv.build_number desc
       ) t)
    else
      (select row_to_json(t)
       from (
         select gv.os, gv.version, gv.build_number, gv.is_mandatory,
                gv.download_url, gv.release_notes, gv.created_at
         from public.game_versions gv
         where gv.is_active = true and gv.os = p_os
         order by gv.build_number desc
         limit 1
       ) t)
  end;
$$;


ALTER FUNCTION public.get_latest_version(p_os text) OWNER TO postgres;

--
-- Name: get_login_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_login_profile() RETURNS TABLE(player_id uuid, username text, alliance jsonb)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  WITH player AS (
    SELECT
      p.id,
      p.username
    FROM public.players p
    WHERE p.user_id = auth.uid()
    LIMIT 1
  ),
  alliance_data AS (
    SELECT
      jsonb_build_object(
        'id', a.id,
        'tag', a.tag,
        'name', a.name,
        'role', am.role,
        'is_member', CASE WHEN am.alliance_id IS NOT NULL THEN true ELSE false END
      ) AS alliance_json
    FROM player p
    LEFT JOIN public.alliance_members am ON am.player_id = p.id
    LEFT JOIN public.alliances a ON a.id = am.alliance_id
    LIMIT 1
  ),
  log_login AS (
    INSERT INTO public.player_activities (
      player_id,
      activity_type
    )
    SELECT
      id,
      'system.login'
    FROM player
    RETURNING player_id
  )
  SELECT
    p.id               AS player_id,
    p.username         AS username,
    ad.alliance_json   AS alliance
  FROM player p
  CROSS JOIN alliance_data ad;
$$;


ALTER FUNCTION public.get_login_profile() OWNER TO postgres;

