--
-- Name: get_loot_box_pity_system(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_loot_box_pity_system(lb_id text) RETURNS json
    LANGUAGE sql STABLE
    AS $$
  SELECT row_to_json(s)
  FROM (
    SELECT 
      s.*,
      (
        SELECT json_agg(
          json_build_object(
            'id', c.id,
            'threshold', c.threshold,
            'items', (
              SELECT json_agg(i.*)
              FROM loot_box_pity_items i
              WHERE i.pity_counter_id = c.id
            )
          )
        )
        FROM loot_box_pity_counters c
        WHERE c.pity_system_id = s.id
      ) AS counters
    FROM loot_box_pity_systems s
    WHERE s.loot_box_id = lb_id
  ) s;
$$;


ALTER FUNCTION public.get_loot_box_pity_system(lb_id text) OWNER TO postgres;

--
-- Name: get_loot_box_rewards_json(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_loot_box_rewards_json(p_loot_box_id text) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result JSON;
BEGIN
    WITH pool_total AS (
        SELECT 
            rp.id AS pool_id,
            SUM(ri.weight) AS total_pool_weight
        FROM loot_box_reward_pools rp
        JOIN loot_box_reward_items ri ON ri.reward_pool_id = rp.id
        WHERE rp.reward_table_id IN (
            SELECT id FROM loot_box_reward_tables WHERE loot_box_id = p_loot_box_id
        )
        GROUP BY rp.id
    ),
    table_total AS (
        SELECT 
            rt.id AS table_id,
            SUM(rp.weight) AS total_table_weight
        FROM loot_box_reward_tables rt
        JOIN loot_box_reward_pools rp ON rp.reward_table_id = rt.id
        WHERE rt.loot_box_id = p_loot_box_id
        GROUP BY rt.id
    ),
    reward_data AS (
        SELECT 
            ri.id AS reward_item_id,
            COALESCE(
                CASE 
                    WHEN ri.reward_type = 'item' THEN bi.name
                    WHEN ri.reward_type = 'currency' THEN c.name
                    ELSE ri.reward_type
                END,
                'Unknown'
            ) AS reward_name,
            ri.reward_type,
            CASE 
                WHEN ri.reward_type = 'item' THEN 'Vật phẩm'
                WHEN ri.reward_type = 'currency' THEN 'Tiền tệ'
                ELSE ri.reward_type
            END AS reward_type_label,
            ri.amount_min,
            ri.amount_max,
            ri.rarity,
            ROUND((ri.weight * 100.0 / pt.total_pool_weight), 2) AS percent_in_pool,
            ROUND((ri.weight * 100.0 / tt.total_table_weight * rp.weight / 100.0), 2) AS percent_in_box,
            rp.name AS pool_name,
            rp.weight AS pool_weight,
            ROUND((rp.weight * 100.0 / tt.total_table_weight), 2) AS pool_percent,
            ri.bound_type,
            ri.weight,
            ri.item_id,
            ri.currency_type,
            ROW_NUMBER() OVER (
                PARTITION BY 
                    COALESCE(
                        CASE 
                            WHEN ri.reward_type = 'item' THEN bi.name
                            WHEN ri.reward_type = 'currency' THEN c.name
                            ELSE ri.reward_type
                        END,
                        'Unknown'
                    ),
                    ri.rarity,
                    ri.amount_min,
                    ri.amount_max
                ORDER BY ri.id
            ) AS rn
        FROM loot_box_reward_items ri
        LEFT JOIN base_items bi ON bi.id = ri.item_id
        LEFT JOIN currencies c ON c.currency_type = ri.currency_type
        JOIN loot_box_reward_pools rp ON rp.id = ri.reward_pool_id
        JOIN loot_box_reward_tables rt ON rt.id = rp.reward_table_id
        JOIN pool_total pt ON pt.pool_id = rp.id
        JOIN table_total tt ON tt.table_id = rt.id
        WHERE rt.loot_box_id = p_loot_box_id
    )
    SELECT COALESCE(
        json_agg(
            json_build_object(
                'reward_item_id', reward_item_id,
                'reward_name', reward_name,
                'reward_type', reward_type,
                'reward_type_label', reward_type_label,
                'amount_min', amount_min,
                'amount_max', amount_max,
                'rarity', rarity,
                'percent_in_pool', percent_in_pool,
                'percent_in_box', percent_in_box,
                'pool_name', pool_name,
                'pool_weight', pool_weight,
                'pool_percent', pool_percent,
                'bound_type', bound_type,
                'weight', weight,
                'item_id', item_id,
                'currency_type', currency_type
            )
            ORDER BY percent_in_box DESC  -- 👈 ORDER BY ở đây là đúng
        ),
        '[]'::json
    ) INTO v_result
    FROM reward_data
    WHERE rn = 1;  -- 👈 Lọc bỏ trùng lặp

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_loot_box_rewards_json(p_loot_box_id text) OWNER TO postgres;

--
-- Name: get_next_general_upgrade_cost_json(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_next_general_upgrade_cost_json(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'player_id', pg.player_id,
        'general_id', pg.general_id,
        'current_level', pg.level,

        'upgrade_range', jsonb_build_object(
            'from_level', guc.from_level,
            'to_level', guc.to_level
        ),

        'required_exp',
            ROUND(
                guc.required_exp *
                POWER(1.10, (pg.level - guc.from_level))
            )::int,

        'currency', jsonb_build_object(
            'type', guc.currency_type,  -- Giả sử DB lưu 'gold', 'diamond',...
            'amount',
                ROUND(
                    guc.currency_amount *
                    POWER(1.10, (pg.level - guc.from_level))
                )::int
        )
    )
    INTO v_result
    FROM public.player_generals pg
    JOIN public.general_upgrade_costs guc
        ON guc.general_id = pg.general_id
    WHERE pg.player_id = p_player_id
      AND pg.general_id = p_general_id
      AND pg.level >= guc.from_level
      AND pg.level < guc.to_level
    LIMIT 1;

    RETURN COALESCE(
        v_result,
        jsonb_build_object(
            'error', 'upgrade_cost_not_found'
        )
    );
END;
$$;


ALTER FUNCTION public.get_next_general_upgrade_cost_json(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: get_online_players_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_online_players_count() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    online_count INTEGER;
    result_json JSON;
BEGIN
    -- Get count of online players
    SELECT COUNT(*)
    INTO online_count
    FROM public.players
    WHERE status = 'online';
    
    -- Build JSON response
    result_json := json_build_object(
        'status', 'success',
        'online_players_count', online_count,
        'timestamp', NOW(),
        'message', CASE 
            WHEN online_count = 0 THEN 'No players currently online'
            WHEN online_count = 1 THEN '1 player is online'
            ELSE online_count || ' players are currently online'
        END
    );
    
    RETURN result_json;
END;
$$;


ALTER FUNCTION public.get_online_players_count() OWNER TO postgres;

