-- Name: get_pending_sent_requests(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pending_sent_requests(p_player_id uuid) RETURNS TABLE(request_id uuid, to_player_id uuid, to_username text, to_avatar text, to_level integer, to_power bigint, to_alliance text, to_status text, to_specialization text, to_victory_points integer, to_win_rate numeric, to_battles integer, created_date timestamp with time zone, nickname text, notes text, hours_since_sent integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        fr.id as request_id,
        p.id as to_player_id,
        p.username as to_username,
        p.avatar as to_avatar,
        p.level as to_level,
        p.power as to_power,
        p.alliance as to_alliance,
        p.status as to_status,
        p.specialization as to_specialization,
        p.victory_points as to_victory_points,
        p.win_rate as to_win_rate,
        p.battles as to_battles,
        fr.created_date,
        fr.nickname,
        fr.notes,
        EXTRACT(HOURS FROM (NOW() - fr.created_date))::INTEGER as hours_since_sent
    FROM friend_relationships fr
    INNER JOIN players p ON fr.friend_id = p.id
    WHERE fr.player_id = p_player_id
    AND fr.status = 'pending'
    ORDER BY fr.created_date DESC;
END;
$$;


