--
-- Name: get_player_achievements(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_achievements(p_player_id uuid) RETURNS TABLE(id text, name text, description text, type text, category text, tier text, rarity text, points integer, difficulty text, target_progress integer, currentprogress integer, iscompleted boolean, isclaimed boolean)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        a.id,           -- <- bỏ ::uuid
        a.name::text,
        a.description::text,
        a.type::text,
        a.category::text,
        a.tier::text,
        a.rarity::text,
        a.points,
        a.difficulty::text,
        a.target_progress,
        COALESCE(pa.progress, 0) AS currentProgress,
        CASE 
            WHEN COALESCE(pa.progress, 0) >= a.target_progress THEN TRUE
            ELSE FALSE
        END AS isCompleted,
        COALESCE(pa.reward_claimed, FALSE) AS isClaimed
    FROM achievements a
    LEFT JOIN player_achievements pa 
        ON pa.achievement_id = a.id 
        AND pa.player_id = p_player_id
    WHERE a.status = 'active'
    ORDER BY a.points DESC, a.tier DESC;
$$;


ALTER FUNCTION public.get_player_achievements(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_achievements1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_achievements1(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result json;
BEGIN
    WITH requirement_targets AS (
        SELECT achievement_id, SUM(target) AS target_progress
        FROM achievement_requirements
        GROUP BY achievement_id
    ),
    latest_progress AS (
        SELECT 
            ar.achievement_id,
            SUM(COALESCE(patp.progress,0)) AS player_progress,
            MAX(pa.unlocked_at) AS unlocked_at,
            bool_or(COALESCE(pa.reward_claimed,false)) AS reward_claimed
        FROM achievement_requirements ar
        LEFT JOIN player_achievement_tier_progress patp 
            ON patp.requirement_id = ar.id AND patp.player_id = p_player_id
        LEFT JOIN player_achievements pa 
            ON pa.achievement_id = ar.achievement_id AND pa.player_id = p_player_id
        GROUP BY ar.achievement_id
    ),
    requirement_with_rewards AS (
        SELECT ar.achievement_id,
               json_build_object(
                   'requirement_id', ar.id,
                   'display_text', ar.display_text,
                   'target', ar.target,
                   'player_progress', COALESCE(patp.progress,0),
                   'completed', COALESCE(patp.completed,false),
                   'reward_claimed', COALESCE(pa.reward_claimed,false),
                   'rewards', COALESCE(
                       (SELECT json_agg(
                           json_build_object(
                               'item_id', r.item_id,
                               'name', bi.name,
                               'description', bi.description,
                               'svg_icon', bi.svg_icon,
                               'base_item_rarity', bi.rarity,
                               'quantity', r.quantity,
                               'probability', r.probability,
                               'currency_type', r.currency_type
                           )
                       )
                       FROM achievement_rewards r
                       LEFT JOIN base_items bi ON r.item_id = bi.id
                       WHERE r.requirement_id = ar.id), '[]'::json)
               ) AS current_requirement
        FROM achievement_requirements ar
        LEFT JOIN player_achievement_tier_progress patp 
            ON patp.requirement_id = ar.id AND patp.player_id = p_player_id
        LEFT JOIN player_achievements pa
            ON pa.achievement_id = ar.achievement_id AND pa.player_id = p_player_id
    )
    SELECT json_build_object(
        'player_id', p_player_id,
        'summary', (
            SELECT json_build_object(
                'total_achievements', COUNT(a.*),
                'unlocked_achievements', COUNT(lp.achievement_id),
                'completed_achievements', COUNT(
                    CASE WHEN COALESCE(lp.player_progress,0) >= COALESCE(rt.target_progress,0) THEN 1 END
                ),
                'total_points', SUM(
                    CASE WHEN COALESCE(lp.player_progress,0) >= COALESCE(rt.target_progress,0) THEN a.points ELSE 0 END
                ),
                'completion_rate', ROUND(
                    COUNT(
                        CASE WHEN COALESCE(lp.player_progress,0) >= COALESCE(rt.target_progress,0) THEN 1 END
                    )::numeric / GREATEST(COUNT(*),1) * 100,2
                )
            )
            FROM achievements a
            LEFT JOIN latest_progress lp ON a.id = lp.achievement_id
            LEFT JOIN requirement_targets rt ON a.id = rt.achievement_id
            WHERE a.status = 'active'
        ),
        'achievements', (
            SELECT json_agg(
                json_build_object(
                    'id', a.id,
                    'name', a.name,
                    'description', a.description,
                    'type', a.type,
                    'category', a.category,
                    'tier', a.tier,
                    'rarity', a.rarity,
                    'difficulty', a.difficulty,
                    'points', a.points,
                    'target_progress', COALESCE(rt.target_progress,0),
                    'player_progress', COALESCE(lp.player_progress,0),
                    'progress_percentage', 
                        CASE WHEN COALESCE(rt.target_progress,0)=0 THEN 0
                             ELSE ROUND(COALESCE(lp.player_progress,0)::numeric / rt.target_progress * 100,2)
                        END,
                    'status', CASE WHEN lp.unlocked_at IS NOT NULL THEN 'unlocked' ELSE 'locked' END,
                    'unlocked_at', lp.unlocked_at,
                    'reward_claimed', COALESCE(lp.reward_claimed,false),
                    'hidden', a.hidden,
                    'secret', a.secret,
                    'repeatable', a.repeatable,
                    'icon', a.icon,
                    'image', a.image,
                    'current_requirement', COALESCE(rwr.current_requirement,'{}'::json)
                )
                ORDER BY a.tier ASC, a.difficulty ASC, a.points ASC
            )
            FROM achievements a
            LEFT JOIN latest_progress lp ON a.id = lp.achievement_id
            LEFT JOIN requirement_targets rt ON a.id = rt.achievement_id
            LEFT JOIN LATERAL (
                SELECT current_requirement
                FROM requirement_with_rewards rwr
                WHERE rwr.achievement_id = a.id
                ORDER BY current_requirement->>'requirement_id' ASC
                LIMIT 1
            ) rwr ON true
            WHERE a.status = 'active'
        )
    ) INTO result;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_player_achievements1(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_achievements_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_achievements_json(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result json;
BEGIN
    SELECT json_build_object(
        'player_id', p_player_id,
        'summary', json_build_object(
            'total_achievements', COUNT(*),
            'unlocked_achievements', COUNT(CASE WHEN lp.status = 'unlocked' THEN 1 END),
            'completed_achievements', COUNT(
                CASE WHEN lp.player_progress >= lp.target_progress THEN 1 END
            ),
            'total_points', SUM(
                CASE WHEN lp.player_progress >= lp.target_progress THEN lp.points ELSE 0 END
            ),
            'completion_rate', ROUND(
                COUNT(CASE WHEN lp.player_progress >= lp.target_progress THEN 1 END)::numeric 
                / GREATEST(COUNT(*),1) * 100, 2
            )
        ),
        'achievements', json_agg(
            json_build_object(
                'id', lp.achievement_id,
                'name', lp.name,
                'description', lp.description,
                'type', lp.type,
                'category', lp.category,
                'tier', lp.tier,
                'rarity', lp.rarity,
                'difficulty', lp.difficulty,
                'points', lp.points,
                'target_progress', lp.target_progress,
                'player_progress', lp.player_progress,
                'progress_percentage', lp.progress_percentage,
                'status', lp.status,
                'unlocked_at', lp.unlocked_at,
                'reward_claimed', lp.reward_claimed,
                'hidden', lp.hidden,
                'secret', lp.secret,
                'repeatable', lp.repeatable,
                'icon', lp.icon,
                'image', lp.image,
                'current_requirement', lp.current_requirement
            )
            ORDER BY lp.tier ASC, lp.difficulty ASC, lp.points ASC
        )
    ) INTO result
    FROM player_achievements_view_full lp
    WHERE lp.player_id = p_player_id OR lp.player_id IS NULL;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_player_achievements_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_achievements_ready(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_achievements_ready(p_player_id uuid) RETURNS TABLE(id text, name text, description text, type text, category text, tier text, rarity text, points integer, difficulty text, target_progress integer, currentprogress integer, iscompleted boolean, isclaimed boolean, displaystatus text, canclaimnow boolean, displaypriority integer)
    LANGUAGE sql STABLE
    AS $$
    SELECT *
    FROM (
        SELECT
            a.id,
            a.name::text,
            a.description::text,
            a.type::text,
            a.category::text,
            a.tier::text,
            a.rarity::text,
            a.points,
            a.difficulty::text,
            a.target_progress,
            COALESCE(pa.progress, 0) AS currentProgress,
            CASE WHEN COALESCE(pa.progress,0) >= a.target_progress THEN TRUE ELSE FALSE END AS isCompleted,
            COALESCE(pa.reward_claimed, FALSE) AS isClaimed,
            
            -- Tính trạng thái hiển thị
            CASE
                WHEN COALESCE(pa.progress,0) >= a.target_progress AND COALESCE(pa.reward_claimed,FALSE) = FALSE THEN 'ready_to_claim'
                WHEN COALESCE(pa.progress,0) >= a.target_progress AND COALESCE(pa.reward_claimed,FALSE) = TRUE THEN 'claimed'
                WHEN COALESCE(pa.progress,0) > 0 AND COALESCE(pa.progress,0) < a.target_progress THEN 'in_progress'
                ELSE 'not_started'
            END AS displayStatus,

            -- Có thể nhận thưởng ngay
            CASE
                WHEN COALESCE(pa.progress,0) >= a.target_progress AND COALESCE(pa.reward_claimed,FALSE) = FALSE THEN TRUE
                ELSE FALSE
            END AS canClaimNow,

            -- Đặt thứ tự hiển thị
            CASE
                WHEN COALESCE(pa.progress,0) >= a.target_progress AND COALESCE(pa.reward_claimed,FALSE) = FALSE THEN 1
                WHEN COALESCE(pa.progress,0) > 0 AND COALESCE(pa.progress,0) < a.target_progress THEN 2
                WHEN COALESCE(pa.progress,0) >= a.target_progress AND COALESCE(pa.reward_claimed,FALSE) = TRUE THEN 3
                ELSE 4
            END AS displayPriority

        FROM achievements a
        LEFT JOIN player_achievements pa
            ON pa.achievement_id = a.id
            AND pa.player_id = p_player_id
        WHERE a.status = 'active'
    ) AS sub
    ORDER BY displayPriority ASC, points DESC, tier DESC;
$$;


ALTER FUNCTION public.get_player_achievements_ready(p_player_id uuid) OWNER TO postgres;

