-- Name: get_player_activation_status(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_activation_status(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_build_object(
            'playerId', p.id,
            'userId', u.id,
            'email', u.email,
            'username', p.username,
            'activated', p.activated
        )
        FROM auth.users u
        JOIN public.players p ON p.user_id = u.id
        WHERE u.email = p_email
    );
END;
$$;


