--
-- Name: get_player_active_event_quests_status_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_active_event_quests_status_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    result jsonb;
BEGIN
    WITH active_events AS (
        ----------------------------------------------------------------
        -- Reuse centralized event matching logic
        ----------------------------------------------------------------
        SELECT
            e.id,
            e.title,
            e.subtitle,
            e.banner_height,
            e.image_url,
            e.link_url,
            e.event_type,
            e.week_days,
            e.week_of_month,
            e.month_days,
            e.quarter_number,
            e.holiday_date,
            e.holiday_name,
            e.start_date,
            e.end_date,
            e.repeat_yearly,
            e.repeat_monthly,
            e.priority,
            e.status,
            e.match_type
        FROM public.get_current_events(CURRENT_TIMESTAMP::timestamp) e
    ),

    ----------------------------------------------------------------
    -- Requirement progress of player
    ----------------------------------------------------------------
    req_progress AS (
        SELECT
            qr.id AS requirement_id,
            qr.quest_id,
            qr.requirement_type,
            qr.target,
            qr.meta,
            COALESCE(qrp.progress, 0) AS progress,
            COALESCE(qrp.completed, false) AS completed
        FROM quest_requirements qr
        LEFT JOIN quest_requirement_progress qrp
            ON qrp.quest_requirement_id = qr.id
           AND qrp.player_id = p_player_id
    ),

    ----------------------------------------------------------------
    -- Rewards
    ----------------------------------------------------------------
    rewards AS (
        SELECT
            r.quest_id,
            jsonb_build_object(
                'reward_id', r.id,
                'item_id', r.item_id,
                'amount', r.amount,
                'reward_type', r.reward_type,
                'currency_type', r.currency_type,
                'experience_amount', r.experience_amount,
                'description', r.description
            ) AS reward_json
        FROM quest_rewards r
    ),

    ----------------------------------------------------------------
    -- Event quests only
    ----------------------------------------------------------------
    quests_json AS (
        SELECT
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'event_id', q.event_id,
                'quest_nav_action', q.quest_nav_action,

                'requirements',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'requirement_id', rp.requirement_id,
                                'requirement_type', rp.requirement_type,
                                'target', rp.target,
                                'meta', rp.meta,
                                'progress', rp.progress,
                                'completed', rp.completed
                            )
                        )
                        FROM req_progress rp
                        WHERE rp.quest_id = q.id
                    ),
                    '[]'::jsonb
                ),

                'rewards',
                COALESCE(
                    (
                        SELECT jsonb_agg(r.reward_json)
                        FROM rewards r
                        WHERE r.quest_id = q.id
                    ),
                    '[]'::jsonb
                ),

                'is_completed',
                COALESCE(
                    (
                        SELECT bool_and(rp.completed)
                        FROM req_progress rp
                        WHERE rp.quest_id = q.id
                    ),
                    false
                ),

                'is_claimed',
                EXISTS (
                    SELECT 1
                    FROM player_quest_progress pq
                    WHERE pq.player_id = p_player_id
                      AND pq.quest_id = q.id
                      AND pq.claimed = true
                )
            ) AS quest_json
        FROM quests q
        INNER JOIN active_events ae
            ON ae.id = q.event_id
        WHERE q.category = 'event'
          AND q.status = 'active'
          AND q.event_id IS NOT NULL
    )

    ----------------------------------------------------------------
    -- Final JSON response
    ----------------------------------------------------------------
    SELECT jsonb_build_object(
        'active_events',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'event_id', ae.id,
                        'title', ae.title,
                        'subtitle', ae.subtitle,
                        'banner_height', ae.banner_height,
                        'image_url', ae.image_url,
                        'link_url', ae.link_url,
                        'event_type', ae.event_type,
                        'week_days', ae.week_days,
                        'week_of_month', ae.week_of_month,
                        'month_days', ae.month_days,
                        'quarter_number', ae.quarter_number,
                        'holiday_date', ae.holiday_date,
                        'holiday_name', ae.holiday_name,
                        'start_date', ae.start_date,
                        'end_date', ae.end_date,
                        'repeat_yearly', ae.repeat_yearly,
                        'repeat_monthly', ae.repeat_monthly,
                        'priority', ae.priority,
                        'status', ae.status,
                        'match_type', ae.match_type
                    )
                    ORDER BY ae.priority DESC
                )
                FROM active_events ae
            ),
            '[]'::jsonb
        ),

        'quests',
        COALESCE(
            (
                SELECT jsonb_agg(qj.quest_json)
                FROM quests_json qj
            ),
            '[]'::jsonb
        )
    )
    INTO result;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_player_active_event_quests_status_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_alliance_chat_read_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_alliance_chat_read_state(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'alliance_id', a.id,
                'alliance_name', a.name,

                'last_read_at', rs.last_read_at,

                'is_read_last_message',
                CASE
                    WHEN lm.id IS NULL THEN true
                    WHEN rs.last_read_at IS NULL THEN false
                    ELSE lm.created_date <= rs.last_read_at
                END
            )
            ORDER BY
                lm.created_date DESC NULLS LAST,
                a.created_date DESC
        ),
        '[]'::jsonb
    )

    FROM public.alliance_members am

    INNER JOIN public.alliances a
        ON a.id = am.alliance_id

    LEFT JOIN public.player_chat_read_states rs
        ON rs.player_id = p_player_id
        AND rs.channel_type = 'alliance'
        AND rs.channel_key = a.id::text

    LEFT JOIN LATERAL (
        SELECT
            cm.id,
            cm.created_date
        FROM public.chat_messages cm
        WHERE cm.alliance_id = a.id
          AND cm.channel_type = 'alliance'
          AND cm.is_deleted = false
          AND cm.sender_id != p_player_id
        ORDER BY cm.created_date DESC
        LIMIT 1
    ) lm ON true

    WHERE am.player_id = p_player_id
      AND a.status = 'active';

$$;


ALTER FUNCTION public.get_player_alliance_chat_read_state(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_alliance_quests_status_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_alliance_quests_status_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    ----------------------------------------------------------------
    -- 1️⃣ Reset alliance quest cũ (khác nửa tháng hiện tại)
    ----------------------------------------------------------------
    UPDATE quest_requirement_progress qrp
    SET progress = 0,
        completed = false,
        completed_at = NULL,
        updated_at = now()
    FROM quest_requirements qr
    JOIN quests q ON q.id = qr.quest_id
    WHERE qrp.quest_requirement_id = qr.id
      AND q.category = 'alliance'
      AND qrp.player_id = p_player_id
      AND (
            date_trunc('month', qrp.updated_at)
              <> date_trunc('month', CURRENT_DATE)
         OR
            (
              CASE
                WHEN extract(day from qrp.updated_at) <= 15 THEN 1 ELSE 2
              END
              <>
              CASE
                WHEN extract(day from CURRENT_DATE) <= 15 THEN 1 ELSE 2
              END
            )
      );

    ----------------------------------------------------------------
    -- 2️⃣ Build JSON alliance quests kỳ hiện tại
    ----------------------------------------------------------------
    WITH req_progress_half_month AS (
        SELECT 
            qr.id AS requirement_id,
            qr.quest_id,
            qr.requirement_type,
            qr.target,
            qr.meta,
            COALESCE(qrp.progress, 0) AS progress,
            COALESCE(qrp.completed, false) AS completed
        FROM quest_requirements qr
        LEFT JOIN quest_requirement_progress qrp
            ON qrp.quest_requirement_id = qr.id
            AND qrp.player_id = p_player_id
            AND date_trunc('month', qrp.updated_at)
                = date_trunc('month', CURRENT_DATE)
            AND (
                CASE
                  WHEN extract(day from qrp.updated_at) <= 15 THEN 1 ELSE 2
                END
                =
                CASE
                  WHEN extract(day from CURRENT_DATE) <= 15 THEN 1 ELSE 2
                END
            )
    ),
    rewards AS (
        SELECT 
            r.quest_id,
            jsonb_build_object(
                'reward_id', r.id,
                'item_id', r.item_id,
                'item_name', bi.name,
                'rarity', bi.rarity,
                'amount', r.amount,
                'reward_type', r.reward_type,
                'currency_type', r.currency_type,
                'experience_amount', r.experience_amount,
                'description', r.description
            ) AS reward_json
        FROM quest_rewards r
        LEFT JOIN base_items bi ON bi.id = r.item_id
    ),
    quests_json AS (
        SELECT
            q.id AS quest_id,
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'min_level', q.min_level,
                'max_level', q.max_level,

                -- requirements nửa tháng hiện tại
                'requirements', COALESCE(
                    (SELECT jsonb_agg(jsonb_build_object(
                        'requirement_id', rp.requirement_id,
                        'requirement_type', rp.requirement_type,
                        'target', rp.target,
                        'meta', rp.meta,
                        'progress', rp.progress,
                        'completed', rp.completed
                    ))
                    FROM req_progress_half_month rp
                    WHERE rp.quest_id = q.id), '[]'::jsonb),

                -- rewards
                'rewards', COALESCE(
                    (SELECT jsonb_agg(r.reward_json)
                     FROM rewards r
                     WHERE r.quest_id = q.id), '[]'::jsonb),

                -- quest completed kỳ này
                'is_completed', COALESCE(
                    (SELECT bool_and(rp.completed)
                     FROM req_progress_half_month rp
                     WHERE rp.quest_id = q.id), false),

                -- quest claimed kỳ này
                'is_claimed', EXISTS (
                    SELECT 1
                    FROM player_quest_progress pq
                    WHERE pq.player_id = p_player_id
                      AND pq.quest_id = q.id
                      AND date_trunc('month', pq.updated_at)
                          = date_trunc('month', CURRENT_DATE)
                      AND (
                          CASE
                            WHEN extract(day from pq.updated_at) <= 15 THEN 1 ELSE 2
                          END
                          =
                          CASE
                            WHEN extract(day from CURRENT_DATE) <= 15 THEN 1 ELSE 2
                          END
                      )
                      AND pq.claimed = true
                )
            ) AS quest_json
        FROM quests q
        WHERE q.category = 'alliance'
          AND q.status = 'active'
    )
    SELECT jsonb_agg(qj.quest_json ORDER BY qj.quest_json->>'quest_name')
    INTO result
    FROM quests_json qj;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_alliance_quests_status_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_battle_general(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_battle_general(p_battle_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_build_object(
            'player_general', to_jsonb(pg),
            'general', to_jsonb(g),
            'skills',
            (
                SELECT COALESCE(
                    jsonb_agg(
                        jsonb_build_object(
                            'player_skill', to_jsonb(pgs),
                            'skill', to_jsonb(gs)
                        )
                    ),
                    '[]'::jsonb
                )
                FROM player_general_skills pgs
                INNER JOIN general_skills gs
                    ON gs.id = pgs.general_skill_id
                WHERE pgs.player_general_id = pg.id
            )
        )
        FROM battles b

        INNER JOIN players p
            ON p.id = p_player_id

        INNER JOIN region_generals rg
            ON rg.player_id = p.id
           AND rg.is_active = true
           AND (
                (b.player1_id = p_player_id
                    AND rg.region_id = b.player1_region_id)
                OR
                (b.player2_id = p_player_id
                    AND rg.region_id = b.player2_region_id)
           )

        INNER JOIN player_generals pg
            ON pg.player_id = p.id
           AND pg.general_id = rg.general_id

        INNER JOIN generals g
            ON g.id = pg.general_id

        WHERE b.id = p_battle_id
          AND (
                b.player1_id = p_player_id
                OR
                b.player2_id = p_player_id
          )
        LIMIT 1
    );
END;
$$;


ALTER FUNCTION public.get_player_battle_general(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_battle_history(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_battle_history(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(jsonb_agg(jsonb_build_object('battle',to_jsonb(b),'player1_username',p1.username,'player2_username',p2.username) ORDER BY COALESCE(b.ended_at,b.started_at,b.created_at) DESC),'[]'::jsonb)
FROM public.battles b
LEFT JOIN public.players p1 ON p1.id=b.player1_id
LEFT JOIN public.players p2 ON p2.id=b.player2_id
WHERE b.player1_id=p_player_id OR b.player2_id=p_player_id;
$$;


ALTER FUNCTION public.get_player_battle_history(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_battle_troops(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_battle_troops(p_battle_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT
COALESCE(
    jsonb_agg(
        to_jsonb(ct) ||
        jsonb_build_object(
            'unit_name', u.name,
            'current_hp', u.current_hp,
            'unit_description', u.description,
            'unit_image_path', u.image_path,
            'unit_type_enum', u.type,
            'unit_rank', u.rank,
            'base_level', u.level,
            'base_atk', u.atk,
            'base_def', u.def,
            'max_hp', u.max_hp,
            'base_speed', u.speed,
            'base_range', u.range,
            'is_vip', u.is_vip,
            'is_special', u.is_special
        )
    ),
    '[]'::jsonb
)
FROM public.combat_troops ct
JOIN public.units u
  ON u.id = ct.unit_type
WHERE ct.battle_id = p_battle_id
  AND ct.player_id = p_player_id;
$$;


ALTER FUNCTION public.get_player_battle_troops(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

