-- Name: get_player_beauties_full_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_beauties_full_json(p_player_id uuid) RETURNS json
    LANGUAGE sql
    AS $$
    SELECT json_agg(
        json_build_object(
            'beauty_id', bc.id,
            'name', bc.name,
            'title', bc.title,
            'rarity', bc.rarity,
            'level', COALESCE(pb.level, 1),
            'experience', COALESCE(pb.experience, 0),
            'status', COALESCE(pb.status, 'available'),
            'charm', bc.charm,
            'intelligence', bc.intelligence,
            'diplomacy', bc.diplomacy,
            'intrigue', bc.intrigue,
            'loyalty', bc.loyalty,
            'mission_success_rate', COALESCE(pb.mission_success_rate, 0),
            'avatar', bc.avatar,
            'full_image', bc.full_image,
            'acquisition_date', COALESCE(pb.acquisition_date, now()),
            'last_used', pb.last_used,
            'owner', CASE WHEN pb.id IS NULL THEN false ELSE true END
        )
    )
    FROM public.beauty_characters bc
    LEFT JOIN public.player_beauties pb
        ON pb.beauty_id = bc.id AND pb.player_id = p_player_id;
$$;


