--
-- Name: get_player_chat_groups(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_chat_groups(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'group_id', g.id,
                'group_name', g.name,
                'group_description', g.description,
                'group_type', g.type,
                'group_avatar_url', g.avatar_url,
                'group_owner_id', g.owner_id,

                'member_role', gm.role,
                'joined_date', gm.joined_date,

                'last_message',
                CASE
                    WHEN lm.id IS NULL THEN NULL
                    ELSE jsonb_build_object(
                        'id', lm.id,
                        'content', lm.content,
                        'message_type', lm.message_type,
                        'sender_id', lm.sender_id,
                        'sender_name', lm.sender_name,
                        'created_date', lm.created_date
                    )
                END,

                'last_read_at',
                rs.last_read_at,

                'is_read_last_message',
                CASE
                    WHEN lm.id IS NULL THEN true
                    WHEN rs.last_read_at IS NULL THEN false
                    ELSE lm.created_date <= rs.last_read_at
                END
            )
            ORDER BY
                lm.created_date DESC NULLS LAST,
                g.created_date DESC
        ),
        '[]'::jsonb
    )

    FROM public.chat_group_members gm

    INNER JOIN public.chat_groups g
        ON g.id = gm.group_id

    LEFT JOIN public.player_chat_read_states rs
        ON rs.player_id = p_player_id
        AND rs.channel_type = 'group'
        AND rs.channel_key = g.id::text

    LEFT JOIN LATERAL (
        SELECT
            cm.id,
            cm.content,
            cm.message_type,
            cm.sender_id,
            cm.sender_name,
            cm.created_date
        FROM public.chat_messages cm
        WHERE cm.group_id = g.id
          AND cm.channel_type = 'group'
          AND cm.is_deleted = false
          AND cm.sender_id != p_player_id
        ORDER BY cm.created_date DESC
        LIMIT 1
    ) lm ON true

    WHERE gm.player_id = p_player_id
      AND g.is_active = true;

$$;


ALTER FUNCTION public.get_player_chat_groups(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_combat_formation(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_combat_formation(p_player_id uuid, p_battle_role text DEFAULT 'defense'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_id text;
    v_general_id text;
    v_general_json jsonb;
    v_units_json jsonb;
BEGIN
    -- 1. Lấy tướng active theo role
    SELECT rg.region_id, rg.general_id
    INTO v_region_id, v_general_id
    FROM region_generals rg
    WHERE rg.player_id = p_player_id
      AND rg.battle_role = p_battle_role
      AND rg.is_active = true
    LIMIT 1;

    IF v_region_id IS NULL THEN
        RETURN jsonb_build_object(
            'player_id', p_player_id,
            'battle_role', p_battle_role,
            'region_id', NULL,
            'general', NULL,
            'units', '[]'::jsonb
        );
    END IF;

    -- 2. Lấy hero stats
    SELECT get_player_general_with_stats(p_player_id, v_general_id)
    INTO v_general_json;

    -- 3. Lấy unit combat stats trong region
    SELECT get_region_combat_units_json(p_player_id, v_region_id)
    INTO v_units_json;

    -- 4. Trả đội hình
    RETURN jsonb_build_object(
        'player_id', p_player_id,
        'battle_role', p_battle_role,
        'region_id', v_region_id,
        'general', v_general_json,
        'units', COALESCE(v_units_json, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION public.get_player_combat_formation(p_player_id uuid, p_battle_role text) OWNER TO postgres;

--
-- Name: get_player_daily_quests_status_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_daily_quests_status_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    ----------------------------------------------------------------
    -- 1️⃣ Reset progress của player cho daily quest cũ (không phải hôm nay)
    ----------------------------------------------------------------
    UPDATE quest_requirement_progress qrp
    SET progress = 0,
        completed = false,
        completed_at = NULL,
        updated_at = now()
    FROM quest_requirements qr
    JOIN quests q ON q.id = qr.quest_id
    WHERE qrp.quest_requirement_id = qr.id
      AND q.category = 'daily'
      AND qrp.player_id = p_player_id
      AND qrp.updated_at::date < CURRENT_DATE;

    ----------------------------------------------------------------
    -- 2️⃣ Build JSON quest hôm nay
    ----------------------------------------------------------------
    WITH req_progress_today AS (
        SELECT 
            qr.id AS requirement_id,
            qr.quest_id,
            qr.requirement_type,
            qr.target,
            qr.meta,
            COALESCE(qrp.progress, 0) AS progress,
            COALESCE(qrp.completed, false) AS completed
        FROM quest_requirements qr
        LEFT JOIN quest_requirement_progress qrp
            ON qrp.quest_requirement_id = qr.id
            AND qrp.player_id = p_player_id
            AND qrp.updated_at::date = CURRENT_DATE
    ),
    rewards AS (
        SELECT 
            r.quest_id,
            jsonb_build_object(
                'reward_id', r.id,
                'item_id', r.item_id,
                'item_name', bi.name,
                'item_rarity', bi.rarity,
                'amount', r.amount,
                'reward_type', r.reward_type,
                'currency_type', r.currency_type,
                'experience_amount', r.experience_amount,
                'description', r.description
            ) AS reward_json
        FROM quest_rewards r
        LEFT JOIN base_items bi ON r.item_id = bi.id
    ),
    quests_json AS (
        SELECT
            q.id AS quest_id,
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'min_level', q.min_level,
                'max_level', q.max_level,
                'quest_nav_action', q.quest_nav_action,  -- 👈 Added this line
                -- requirements hôm nay
                'requirements', COALESCE(
                    (SELECT jsonb_agg(jsonb_build_object(
                        'requirement_id', rp.requirement_id,
                        'requirement_type', rp.requirement_type,
                        'target', rp.target,
                        'meta', rp.meta,
                        'progress', rp.progress,
                        'completed', rp.completed
                    ))
                    FROM req_progress_today rp
                    WHERE rp.quest_id = q.id), '[]'::jsonb),
                -- rewards với name và rarity
                'rewards', COALESCE(
                    (SELECT jsonb_agg(r.reward_json)
                     FROM rewards r
                     WHERE r.quest_id = q.id), '[]'::jsonb),
                -- quest completed hôm nay
                'is_completed', COALESCE(
                    (SELECT bool_and(rp.completed)
                     FROM req_progress_today rp
                     WHERE rp.quest_id = q.id), false),
                -- quest claimed hôm nay
                'is_claimed', EXISTS (
                    SELECT 1
                    FROM player_quest_progress pq
                    WHERE pq.player_id = p_player_id
                      AND pq.quest_id = q.id
                      AND pq.claimed = true
                )
            ) AS quest_json
        FROM quests q
        WHERE q.category = 'daily'
          AND q.status = 'active'
    )
    SELECT jsonb_agg(qj.quest_json ORDER BY qj.quest_json->>'quest_name') INTO result
    FROM quests_json qj;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_daily_quests_status_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_friends_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_friends_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(friend)
  INTO result
  FROM (
    SELECT DISTINCT ON (p.id)
      jsonb_build_object(
        -- relationship info
        'relationship_id', fr.id,
        'friendship_status', fr.status,
        'created_date', fr.created_date,
        'accepted_date', fr.accepted_date,
        'nickname', fr.nickname,
        'favorite', fr.favorite,
        'notes', fr.notes,

        -- friend player info
        'friend_id', p.id,
        'username', p.username,
        'avatar', p.avatar,
        'level', p.level,
        'power', p.power,
        'status', p.status,
        'online', (p.status = 'online'),
        'alliance', p.alliance,
        'role_in_alliance', p.role_in_alliance,
        'last_login', p.last_login,
        'country', p.country,
        'title', p.title,
        'specialization', p.specialization,
        'victory_points', p.victory_points,
        'win_rate', p.win_rate
      ) AS friend
    FROM public.friend_relationships fr
    JOIN public.players p
      ON p.id = CASE
        WHEN fr.player_id = p_player_id THEN fr.friend_id
        ELSE fr.player_id
      END
    WHERE
      (fr.player_id = p_player_id OR fr.friend_id = p_player_id)
      AND fr.status = 'accepted'
    ORDER BY
      p.id,                     -- MUST match DISTINCT ON
      fr.favorite DESC,
      fr.accepted_date DESC,
      fr.created_date DESC
  ) t;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_friends_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_general_equipment(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_equipment(p_player_id uuid, p_general_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    hero_id uuid;
    result jsonb;
BEGIN
    -- Get player_general_id from player_id + general_id
    SELECT id
    INTO hero_id
    FROM public.player_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id
    LIMIT 1;

    IF hero_id IS NULL THEN
        -- Hero does not exist or does not belong to player
        RETURN '[]'::jsonb;
    END IF;

    -- Get all equipped items of this hero
    SELECT jsonb_agg(
        jsonb_build_object(
            'equipment_id', ei.id,
            'is_equipped', ei.is_equipped,

            -- from base_items
            'name', bi.name,
            'description', bi.description,
            'type', bi.type,
            'rarity', bi.rarity,          -- ✅ added
            'quality', bi.quality,
            'level_requirement', bi.level_requirement,
            'stackable', bi.stackable,
            'max_stack', bi.max_stack,
            'base_value', bi.base_value,
            'icon', bi.svg_icon
        )
    )
    INTO result
    FROM public.equipment_items ei
    INNER JOIN public.base_items bi
        ON bi.id = ei.id
    WHERE ei.player_general_id = hero_id
      AND ei.is_equipped = true;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_general_equipment(p_player_id uuid, p_general_id uuid) OWNER TO postgres;

--
-- Name: get_player_general_equipment_full_json(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_equipment_full_json(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(
            jsonb_build_object(
                'slot', s.slot,
                'item_id', s.item_id,
                'name', bi.name,
                'description', bi.description,
                'type', bi.type,
                'rarity', bi.rarity,
                'quality', bi.quality,
                'level_requirement', bi.level_requirement,
                'stackable', bi.stackable,
                'max_stack', bi.max_stack,
                'base_value', bi.base_value,
                'icon', bi.icon,

                'stats', jsonb_build_object(
                    'attack', ist.attack,
                    'defense', ist.defense,
                    'health', ist.health,
                    'mana', ist.mana,
                    'strength', ist.strength,
                    'agility', ist.agility,
                    'intelligence', ist.intelligence,
                    'speed', ist.speed,
                    'leadership', ist.leadership,
                    'critical_chance', ist.critical_chance,
                    'critical_damage', ist.critical_damage,
                    'dodge', ist.dodge,
                    'block', ist.block,
                    'resistance', ist.resistance
                )
            )
        )
        FROM player_generals pg
        JOIN equipment_items ei
            ON ei.player_general_id = pg.id

        LEFT JOIN LATERAL (
            VALUES
                ('weapon',  ei.weapon_id),
                ('armor',   ei.armor_id),
                ('helmet',  ei.helmet_id),
                ('cloak',   ei.cloak_id),
                ('boots',   ei.boots_id),
                ('ring',    ei.ring_id),
                ('shield',  ei.shield_id)
        ) AS s(slot, item_id)
            ON s.item_id IS NOT NULL

        LEFT JOIN base_items bi
            ON bi.id = s.item_id

        LEFT JOIN item_stats ist
            ON ist.base_item_id = bi.id

        WHERE pg.player_id = p_player_id
          AND pg.general_id = p_general_id
    );
END;
$$;


ALTER FUNCTION public.get_player_general_equipment_full_json(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: get_player_general_power(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_power(p_player_id uuid) RETURNS integer
    LANGUAGE sql
    AS $$
  SELECT COALESCE(SUM(
    current_attack
  + current_defense
  + current_health
  + current_speed
  + current_intelligence
  + current_leadership
  ), 0)
  FROM player_generals
  WHERE player_id = p_player_id;
$$;


ALTER FUNCTION public.get_player_general_power(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_general_unit_capacities(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_unit_capacities(p_player_general_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'unit_id', gum.unit_id,
            'mastery_level', gum.mastery_level,
            'base_capacity', gum.base_capacity,
            'capacity_per_level', gum.capacity_per_level,
            'capacity_per_star', gum.capacity_per_star,
            'max_capacity',
                gum.base_capacity
                + (pg.level - 1) * gum.capacity_per_level
                + (pg.star_level - 1) * gum.capacity_per_star
        )
        ORDER BY gum.mastery_level DESC
    )
    INTO v_result
    FROM player_generals pg
    JOIN general_unit_masteries gum
        ON gum.general_id = pg.general_id
    WHERE pg.id = p_player_general_id;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_general_unit_capacities(p_player_general_id uuid) OWNER TO postgres;

--
-- Name: get_player_general_unit_capacities(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_unit_capacities(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

SELECT COALESCE(
    jsonb_build_object(
        'player_general_id', pg.id,
        'general_id', pg.general_id,
        'general_name', g.name,
        'level', pg.level,
        'star_level', pg.star_level,

        'units',
        (
            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'unit_id', u.id,
                        'unit_name', u.name,
                        'unit_type', u.type,
                        'unit_image_path', u.image_path,

                        'mastery_level', gum.mastery_level,

                        'base_capacity', gum.base_capacity,
                        'capacity_per_level', gum.capacity_per_level,
                        'capacity_per_star', gum.capacity_per_star,

                        'max_capacity',
                        (
                            gum.base_capacity
                            + (
                                (gum.mastery_level - 1)
                                * gum.capacity_per_level
                            )
                            + (
                                (pg.star_level - 1)
                                * gum.capacity_per_star
                            )
                        )
                    )
                    ORDER BY u.name ASC
                ),
                '[]'::jsonb
            )
            FROM public.general_unit_masteries gum

            JOIN public.units u
                ON u.id = gum.unit_id

            WHERE gum.general_id = pg.general_id
        )
    ),
    '{}'::jsonb
)

FROM public.player_generals pg

JOIN public.generals g
    ON g.id = pg.general_id

WHERE pg.player_id = p_player_id
  AND pg.general_id = p_general_id;

$$;


ALTER FUNCTION public.get_player_general_unit_capacities(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: get_player_general_with_stats(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_general_with_stats(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT jsonb_build_object(
    'player_general_id', pg.id,
    'player_id', pg.player_id,
    'general_id', pg.general_id,
    'level', pg.level,
    'star_level', pg.star_level,

    'base_stats', jsonb_build_object(
        'attack', pg.current_attack,
        'defense', pg.current_defense,
        'health', pg.current_health,
        'speed', pg.current_speed,
        'intelligence', pg.current_intelligence,
        'leadership', pg.current_leadership
    ),

    'equipment_stats', jsonb_build_object(
        'attack', ves.equip_attack,
        'defense', ves.equip_defense,
        'health', ves.equip_health,
        'speed', ves.equip_speed,
        'intelligence', ves.equip_intelligence,
        'leadership', ves.equip_leadership
    ),

    'total_stats', jsonb_build_object(
        'attack', pg.current_attack + ves.equip_attack,
        'defense', pg.current_defense + ves.equip_defense,
        'health', pg.current_health + ves.equip_health,
        'speed', pg.current_speed + ves.equip_speed,
        'intelligence', pg.current_intelligence + ves.equip_intelligence,
        'leadership', pg.current_leadership + ves.equip_leadership
    ),

    'equipment_detail', jsonb_build_object(
        'weapon', build_equipment_json(ei.weapon_id),
        'armor',  build_equipment_json(ei.armor_id),
        'helmet', build_equipment_json(ei.helmet_id),
        'cloak',  build_equipment_json(ei.cloak_id),
        'boots',  build_equipment_json(ei.boots_id),
        'ring',   build_equipment_json(ei.ring_id),
        'shield', build_equipment_json(ei.shield_id)
    )
)
FROM player_generals pg
LEFT JOIN equipment_items ei
    ON ei.player_general_id = pg.id
   AND ei.is_equipped = true
LEFT JOIN v_player_general_equipment_stats ves
    ON ves.player_general_id = pg.id
WHERE pg.player_id = p_player_id
  AND pg.general_id = p_general_id;
$$;


ALTER FUNCTION public.get_player_general_with_stats(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: get_player_generals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_generals(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT jsonb_build_object(

        'generals',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'player_general_id', pg.id,
                        'general_id', pg.general_id,
                        'name', g.name,
                        'rarity', g.rarity,
                        'element', g.element,
                        'type', g.type,
                        'level', pg.level,
                        'max_level', g.max_level,
                        'experience', pg.experience,
                        'star_level', pg.star_level,
                        'max_star_level', pg.max_star_level,
                        'awakening_level', pg.awakening_level,
                        'favorite', pg.favorite,
                        'is_representative', pg.is_representative,

                        'units',
                        COALESCE(
                            (
                                SELECT jsonb_agg(
                                    jsonb_build_object(
                                        'unit_id', u.id,
                                        'name', u.name,
                                        'type', u.type,
                                        'mastery_level', gum.mastery_level,
                                        'base_capacity', gum.base_capacity,
                                        'capacity_per_level', gum.capacity_per_level,
                                        'capacity_per_star', gum.capacity_per_star
                                    )
                                    ORDER BY u.id
                                )
                                FROM public.general_unit_masteries gum
                                INNER JOIN public.units u
                                    ON u.id = gum.unit_id
                                WHERE gum.general_id = pg.general_id
                            ),
                            '[]'::jsonb
                        )
                    )
                    ORDER BY
                        pg.is_representative DESC,
                        pg.favorite DESC,
                        pg.level DESC
                )
                FROM public.player_generals pg
                INNER JOIN public.generals g
                    ON g.id = pg.general_id
                WHERE pg.player_id = p_player_id
            ),
            '[]'::jsonb
        ),

        'offense',
        (
            SELECT jsonb_build_object(
                'player_general_id', pg.id,
                'general_id', pg.general_id,
                'name', g.name,
                'rarity', g.rarity,
                'element', g.element,
                'type', g.type,
                'level', pg.level,
                'star_level', pg.star_level
            )
            FROM public.region_generals rg
            INNER JOIN public.player_generals pg
                ON pg.player_id = rg.player_id
                AND pg.general_id = rg.general_id
            INNER JOIN public.generals g
                ON g.id = rg.general_id
            WHERE rg.player_id = p_player_id
                AND rg.battle_role = 'offense'
                AND rg.is_active = true
            LIMIT 1
        ),

        'defense',
        (
            SELECT jsonb_build_object(
                'player_general_id', pg.id,
                'general_id', pg.general_id,
                'name', g.name,
                'rarity', g.rarity,
                'element', g.element,
                'type', g.type,
                'level', pg.level,
                'star_level', pg.star_level
            )
            FROM public.region_generals rg
            INNER JOIN public.player_generals pg
                ON pg.player_id = rg.player_id
                AND pg.general_id = rg.general_id
            INNER JOIN public.generals g
                ON g.id = rg.general_id
            WHERE rg.player_id = p_player_id
                AND rg.battle_role = 'defense'
                AND rg.is_active = true
            LIMIT 1
        )

    );
$$;


ALTER FUNCTION public.get_player_generals(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_generals_with_rep(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_generals_with_rep(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'representative_id',
    (
      SELECT pg.general_id
      FROM public.player_generals pg
      WHERE pg.player_id = p_player_id
        AND pg.is_representative = true
      LIMIT 1
    ),

    'generals',
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', g.id,
          'name', g.name,
          'title', g.title,
          'rarity', g.rarity,
          'element', g.element,
          'image', g.image,
          'thumbnail', g.thumbnail,

          'owned',
          EXISTS (
            SELECT 1
            FROM public.player_generals pg2
            WHERE pg2.player_id = p_player_id
              AND pg2.general_id = g.id
          ),

          'is_representative',
          EXISTS (
            SELECT 1
            FROM public.player_generals pg3
            WHERE pg3.player_id = p_player_id
              AND pg3.general_id = g.id
              AND pg3.is_representative = true
          ),

          'player_stats',
          (
            SELECT jsonb_build_object(
    'level', pg4.level,
    'star_level', pg4.star_level,

    'power_attack',
        ROUND(
            pg4.current_attack *
            (1 + ((pg4.level - 1) * 0.05))
        ),

    'power_defense',
        ROUND(
            pg4.current_defense *
            (1 + ((pg4.level - 1) * 0.05))
        ),

    'power_health',
        ROUND(
            pg4.current_health *
            (1 + ((pg4.level - 1) * 0.05))
        ),

    'win_rate', pg4.win_rate,
    'battle_count', pg4.battle_count
)
            FROM public.player_generals pg4
            WHERE pg4.player_id = p_player_id
              AND pg4.general_id = g.id
            LIMIT 1
          )
        )
      )
      FROM public.generals g
    )
  )
  INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION public.get_player_generals_with_rep(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_gifts_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_gifts_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'gift_id', pgb.gift_id,
            'gift_name', gb.name,
            'amount', pgb.amount,
            'rarity', gb.rarity
        )
        ORDER BY gb.rarity, gb.name
    )
    INTO v_result
    FROM player_gift_beauty pgb
    JOIN gift_beauty gb ON gb.id = pgb.gift_id
    WHERE pgb.player_id = p_player_id;

    -- Nếu không có gift nào, trả về mảng rỗng
    IF v_result IS NULL THEN
        v_result := '[]'::jsonb;
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_player_gifts_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_hero_items_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_hero_items_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            -- player item
            'player_item_id', pi.id,
            'item_id', pi.item_id,
            'quantity', pi.quantity,
            'equipped', pi.equipped,
            'condition', pi."condition",
            'acquired_at', pi.acquired_at,
            'metadata', pi.metadata,

            -- base item
            'name', bi.name,
            'description', bi.description,
            'type', bi.type,
            'rarity', bi.rarity,
            'quality', bi.quality,
            'level_requirement', bi.level_requirement,
            'icon', bi.icon,
            'svg_icon', bi.svg_icon,

            -- stats (subquery, không lặp)
            'stats', (
                SELECT jsonb_build_object(
                    'attack', ist.attack,
                    'defense', ist.defense,
                    'health', ist.health,
                    'mana', ist.mana,
                    'strength', ist.strength,
                    'agility', ist.agility,
                    'intelligence', ist.intelligence,
                    'speed', ist.speed,
                    'leadership', ist.leadership,
                    'critical_chance', ist.critical_chance,
                    'critical_damage', ist.critical_damage,
                    'dodge', ist.dodge,
                    'block', ist.block,
                    'resistance', ist.resistance
                )
                FROM item_stats ist
                WHERE ist.base_item_id = bi.id
                LIMIT 1
            )
        )
    )
    INTO result
    FROM player_items pi
    JOIN base_items bi ON bi.id = pi.item_id
    WHERE pi.player_id = p_player_id
      AND pi.equipped = false
      AND bi.status = 'active'
      AND bi.type IN (
          'general_weapon',
          'general_armor',
          'general_mount',
          'general_special_item',
          'artifact',
          'relic',
          'totem'
      );

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_hero_items_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_inventory_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_inventory_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    WITH equipped_items AS (
        SELECT
            pg.player_id,
            x.item_id,
            COUNT(*)::int AS equipped_quantity
        FROM public.equipment_items ei
        JOIN public.player_generals pg
            ON pg.id = ei.player_general_id
        CROSS JOIN LATERAL (
            VALUES
                (ei.weapon_id),
                (ei.armor_id),
                (ei.helmet_id),
                (ei.cloak_id),
                (ei.boots_id),
                (ei.ring_id),
                (ei.shield_id)
        ) AS x(item_id)
        WHERE ei.is_equipped = true
          AND x.item_id IS NOT NULL
          AND pg.player_id = p_player_id
        GROUP BY pg.player_id, x.item_id
    ),

    inventory AS (
        SELECT
            pi.id AS player_item_id,
            pi.player_id,
            pi.item_id,
            pi.quantity,
            pi."condition",
            pi.acquired_at,
            pi.metadata,

            bi.name,
            bi.description,
            bi.type,
            bi.rarity,
            bi.quality,
            bi.level_requirement,
            bi.icon,
            bi.stackable,
            bi.max_stack,

            COALESCE(ei.equipped_quantity, 0)::int AS equipped_quantity,

            GREATEST(
                pi.quantity - COALESCE(ei.equipped_quantity, 0),
                0
            )::int AS available_quantity,

            (
                SELECT jsonb_build_object(
                    'attack', ist.attack,
                    'defense', ist.defense,
                    'health', ist.health,
                    'mana', ist.mana,
                    'strength', ist.strength,
                    'agility', ist.agility,
                    'intelligence', ist.intelligence,
                    'speed', ist.speed,
                    'leadership', ist.leadership,
                    'critical_chance', ist.critical_chance,
                    'critical_damage', ist.critical_damage,
                    'dodge', ist.dodge,
                    'block', ist.block,
                    'resistance', ist.resistance
                )
                FROM public.item_stats ist
                WHERE ist.base_item_id = bi.id
                LIMIT 1
            ) AS stats
        FROM public.player_items pi
        JOIN public.base_items bi
            ON bi.id = pi.item_id
        LEFT JOIN equipped_items ei
            ON ei.player_id = pi.player_id
           AND ei.item_id = pi.item_id
        WHERE pi.player_id = p_player_id
          AND pi.quantity > 0
          AND bi.status = 'active'
    ),

    inventory_json AS (
        SELECT
            *,
            jsonb_build_object(
                'player_item_id', player_item_id,
                'player_id', player_id,
                'item_id', item_id,

                'quantity', quantity,
                'equipped_quantity', equipped_quantity,
                'available_quantity', available_quantity,

                'has_equipped', equipped_quantity > 0,
                'has_available', available_quantity > 0,

                'condition', "condition",
                'acquired_at', acquired_at,
                'metadata', metadata,

                'name', name,
                'description', description,
                'type', type,
                'rarity', rarity,
                'quality', quality,
                'level_requirement', level_requirement,
                'icon', icon,
                'stackable', stackable,
                'max_stack', max_stack,

                'stats', stats
            ) AS item_json
        FROM inventory
    )

    SELECT jsonb_build_object(
        'total_quantity', COALESCE(SUM(quantity), 0),
        'total_item_types', COUNT(*),

        'total_equipped_quantity', COALESCE(SUM(equipped_quantity), 0),
        'total_equipped_item_types', COUNT(*) FILTER (WHERE equipped_quantity > 0),

        'total_available_quantity', COALESCE(SUM(available_quantity), 0),
        'total_available_item_types', COUNT(*) FILTER (WHERE available_quantity > 0),

        'rare_quantity', COALESCE(SUM(quantity) FILTER (
            WHERE rarity::text IN ('rare', 'epic', 'legendary', 'mythic')
        ), 0),

        'rare_item_types', COUNT(*) FILTER (
            WHERE rarity::text IN ('rare', 'epic', 'legendary', 'mythic')
        ),

        'items', COALESCE(
            jsonb_agg(item_json ORDER BY acquired_at DESC),
            '[]'::jsonb
        ),

        'equipped_items', COALESCE(
            jsonb_agg(item_json ORDER BY acquired_at DESC)
                FILTER (WHERE equipped_quantity > 0),
            '[]'::jsonb
        ),

        'available_items', COALESCE(
            jsonb_agg(item_json ORDER BY acquired_at DESC)
                FILTER (WHERE available_quantity > 0),
            '[]'::jsonb
        ),

        'rare_items', COALESCE(
            jsonb_agg(item_json ORDER BY acquired_at DESC)
                FILTER (
                    WHERE rarity::text IN ('rare', 'epic', 'legendary', 'mythic')
                ),
            '[]'::jsonb
        )
    )
    INTO result
    FROM inventory_json;

    RETURN COALESCE(
        result,
        jsonb_build_object(
            'total_quantity', 0,
            'total_item_types', 0,
            'total_equipped_quantity', 0,
            'total_equipped_item_types', 0,
            'total_available_quantity', 0,
            'total_available_item_types', 0,
            'rare_quantity', 0,
            'rare_item_types', 0,
            'items', '[]'::jsonb,
            'equipped_items', '[]'::jsonb,
            'available_items', '[]'::jsonb,
            'rare_items', '[]'::jsonb
        )
    );
END;
$$;


ALTER FUNCTION public.get_player_inventory_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_items_by_type(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_items_by_type(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'player_item_id', pi.id,
            'item_id', pi.item_id,
            'quantity', pi.quantity,
            'equipped', pi.equipped,
            'condition', pi.condition,
            'acquired_at', pi.acquired_at,
            'metadata', pi.metadata,

            -- thông tin base_items
            'name', bi.name,
            'description', bi.description,
            'type', CASE bi.type
                        WHEN 'weapon' THEN 'Vũ khí'
                        WHEN 'armor' THEN 'Áo giáp'
                        WHEN 'helmet' THEN 'Mũ'
                        WHEN 'boots' THEN 'Giày'
                        WHEN 'accessory1' THEN 'Bảo vật'
                        WHEN 'accessory2' THEN 'Phù chú'
                        ELSE bi.type
                    END,
            'rarity', bi.rarity,
            'quality', bi.quality,
            'level_requirement', bi.level_requirement,
            'stackable', bi.stackable,
            'max_stack', bi.max_stack,
            'base_value', bi.base_value,
            'icon', bi.icon
        )
    )
    INTO result
    FROM public.player_items pi
    INNER JOIN public.base_items bi
        ON bi.id = pi.item_id
    WHERE pi.player_id = p_player_id;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_items_by_type(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_level_info_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_level_info_json(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_level int;
    v_exp bigint;
    v_required bigint;
BEGIN
    SELECT p.level, p.exp
    INTO v_level, v_exp
    FROM public.players p
    WHERE p.id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player not found: %', p_player_id;
    END IF;

    v_required := public.get_required_exp_by_level(v_level);

    RETURN json_build_object(
        'level', v_level,
        'current_exp', v_exp,
        'required_exp', v_required,
        'progress', CASE 
            WHEN v_required = 0 THEN 1
            ELSE round(v_exp::numeric / v_required, 4)
        END
    );
END;
$$;


ALTER FUNCTION public.get_player_level_info_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_loot_boxes(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_loot_boxes(p_player_id uuid) RETURNS TABLE(player_loot_box_id uuid, loot_box_id text, loot_box_name text, loot_box_description text, loot_box_type text, loot_box_tier text, loot_box_category text, amount integer, total_opens integer, last_opened_at timestamp with time zone, current_streak integer, pity_counter integer, rewards jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql
    AS $$

    SELECT
        plb.id AS player_loot_box_id,

        lb.id AS loot_box_id,
        lb.name AS loot_box_name,
        lb.description AS loot_box_description,
        lb.box_type AS loot_box_type,
        lb.tier AS loot_box_tier,
        lb.category AS loot_box_category,

        plb.amount,
        plb.total_opens,
        plb.last_opened_at,
        plb.current_streak,
        plb.pity_counter,

        get_loot_box_rewards_json(lb.id) AS rewards,

        plb.created_at,
        plb.updated_at

    FROM public.player_loot_boxes plb

    JOIN public.loot_boxes lb
        ON lb.id = plb.loot_box_id

    WHERE plb.player_id = p_player_id

    ORDER BY
        lb.tier ASC,
        lb.name ASC;

$$;


ALTER FUNCTION public.get_player_loot_boxes(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_loot_boxes_by_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_loot_boxes_by_status(p_player_id uuid, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'player_loot_box_id', plb.id,
            'loot_box_id', plb.loot_box_id,
            'loot_box_name', lb.name,
            'loot_box_description', lb.description,
            'loot_box_tier', lb.tier,
            'loot_box_type', lb.type,
            'status', plb.status,
            'obtained_at', plb.obtained_at,
            'opened_at', plb.opened_at,
            'expiry_at', plb.expiry_at,
            'times_opened', plb.times_opened,
            'rewards', plb.reward,
            'is_expired', (plb.expiry_at < NOW()),
            'hours_until_expiry', CASE 
                WHEN plb.expiry_at IS NOT NULL THEN 
                    EXTRACT(EPOCH FROM (plb.expiry_at - NOW())) / 3600
                ELSE NULL
            END,
            'open_cost_currency', lb.open_cost_currency,
            'open_cost_amount', lb.open_cost_amount
        )
        ORDER BY plb.obtained_at DESC  -- MOVED ORDER BY INSIDE jsonb_agg
    ) INTO result
    FROM player_loot_boxes plb
    JOIN loot_boxes lb ON plb.loot_box_id = lb.id
    WHERE plb.player_id = p_player_id
      AND (p_status IS NULL OR plb.status = p_status);
    
    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_loot_boxes_by_status(p_player_id uuid, p_status text) OWNER TO postgres;

--
-- Name: get_player_loot_boxes_by_status_table(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_loot_boxes_by_status_table(p_player_id uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(player_loot_box_id uuid, loot_box_id text, loot_box_name text, loot_box_tier text, loot_box_type text, status text, obtained_at timestamp without time zone, opened_at timestamp without time zone, expiry_at timestamp without time zone, times_opened integer, is_expired boolean, hours_until_expiry numeric, open_cost_currency text, open_cost_amount integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        plb.id as player_loot_box_id,
        plb.loot_box_id,
        lb.name as loot_box_name,
        lb.tier as loot_box_tier,
        lb.type as loot_box_type,
        plb.status,
        plb.obtained_at,
        plb.opened_at,
        plb.expiry_at,
        plb.times_opened,
        (plb.expiry_at < NOW()) as is_expired,
        CASE 
            WHEN plb.expiry_at IS NOT NULL THEN 
                EXTRACT(EPOCH FROM (plb.expiry_at - NOW())) / 3600
            ELSE NULL
        END as hours_until_expiry,
        lb.open_cost_currency,
        lb.open_cost_amount
    FROM player_loot_boxes plb
    JOIN loot_boxes lb ON plb.loot_box_id = lb.id
    WHERE plb.player_id = p_player_id
      AND (p_status IS NULL OR plb.status = p_status)
    ORDER BY plb.obtained_at DESC;
END;
$$;


