--
-- Name: get_player_main_quests(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_main_quests(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

WITH player AS (
    SELECT
        id,
        level
    FROM public.players
    WHERE id = p_player_id
),

player_unlock AS (
    SELECT
        COALESCE(current_main_quest_unlocked, 0) AS unlocked_quest_id
    FROM public.player_stats
    WHERE player_id = p_player_id
),

visible_quests AS (
    SELECT q.*
    FROM public.quests q
    JOIN player p
        ON true
    JOIN player_unlock pu
        ON true

    WHERE q.category = 'main'
      AND q.status = 'active'

      -- ============================================
      -- QUEST VISIBILITY
      -- ============================================
      AND (
          -- ==========================================
          -- 1. QUEST KHÔNG CÓ MAIN UNLOCK
          --    → LỌC THEO LEVEL
          -- ==========================================
          (
              q.quest_main_unlock_increment IS NULL
              AND p.level BETWEEN q.min_level AND q.max_level
          )

          OR

          -- ==========================================
          -- 2. QUEST CÓ MAIN UNLOCK
          --    → CHỈ LỌC THEO MAIN UNLOCK
          --    → BỎ QUA MIN_LEVEL / MAX_LEVEL
          -- ==========================================
          (
              q.quest_main_unlock_increment IS NOT NULL
              AND q.quest_main_unlock_increment = pu.unlocked_quest_id
          )
      )

      -- ============================================
      -- LOẠI QUEST ĐÃ HOÀN THÀNH + ĐÃ CLAIM
      -- ============================================
      AND NOT EXISTS (
          SELECT 1
          FROM public.quest_requirements qr

          LEFT JOIN public.quest_requirement_progress qrp
              ON qrp.quest_requirement_id = qr.id
             AND qrp.player_id = p_player_id

          WHERE qr.quest_id = q.id

          GROUP BY qr.quest_id

          HAVING COUNT(qr.id) > 0

             AND COUNT(
                 CASE
                     WHEN qrp.completed = true
                     THEN 1
                 END
             ) = COUNT(qr.id)

             AND EXISTS (
                 SELECT 1
                 FROM public.player_quest_progress pq
                 WHERE pq.player_id = p_player_id
                   AND pq.quest_id = q.id
                   AND pq.claimed = true
             )
      )
),

-- ================================================
-- QUEST REWARDS
-- ================================================
rewards AS (
    SELECT
        r.quest_id,

        jsonb_build_object(
            'reward_id', r.id,
            'item_id', r.item_id,
            'item_name', bi.name,
            'item_rarity', bi.rarity,
            'item_type', bi.type,
            'amount', r.amount,
            'reward_type', r.reward_type,
            'currency_type', r.currency_type,
            'currency_name', c.name,
            'experience_amount', r.experience_amount,
            'region_id', r.region_id,
            'description', r.description
        ) AS reward_json

    FROM public.quest_rewards r

    LEFT JOIN public.base_items bi
        ON r.item_id = bi.id

    LEFT JOIN public.currencies c
        ON r.currency_type = c.currency_type
)

-- ================================================
-- RETURN JSON
-- ================================================
SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(

            -- ======================================
            -- BASIC QUEST INFO
            -- ======================================
            'quest_id',
            q.id,

            'quest_name',
            q.name,

            'description',
            q.description,

            'type',
            q.type,

            'category',
            q.category,

            'difficulty',
            q.difficulty,

            'status',
            q.status,

            'min_level',
            q.min_level,

            'max_level',
            q.max_level,

            'story_id',
            q.story_id,

            'quest_nav_action',
            q.quest_nav_action,

            'quest_main_unlock_increment',
            q.quest_main_unlock_increment,

            -- ======================================
            -- QUEST BOSSES
            -- ======================================
            'quest_bosses',
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'boss_id',
                            qb.boss_id,

                            'order_index',
                            qb.order_index,

                            'is_required',
                            qb.is_required
                        )
                        ORDER BY qb.order_index ASC
                    )
                    FROM public.quest_bosses qb
                    WHERE qb.quest_id = q.id
                ),
                '[]'::jsonb
            ),

            -- ======================================
            -- REQUIREMENTS
            -- ======================================
            'requirements',
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requirement_id',
                            qr.id,

                            'requirement_type',
                            qr.requirement_type,

                            'target',
                            qr.target,

                            'meta',
                            qr.meta,

                            'progress',
                            COALESCE(qrp.progress, 0),

                            'completed',
                            COALESCE(qrp.completed, false)
                        )
                    )
                    FROM public.quest_requirements qr

                    LEFT JOIN public.quest_requirement_progress qrp
                        ON qrp.quest_requirement_id = qr.id
                       AND qrp.player_id = p_player_id

                    WHERE qr.quest_id = q.id
                ),
                '[]'::jsonb
            ),

            -- ======================================
            -- REWARDS
            -- ======================================
            'rewards',
            COALESCE(
                (
                    SELECT jsonb_agg(r.reward_json)
                    FROM rewards r
                    WHERE r.quest_id = q.id
                ),
                '[]'::jsonb
            ),

            -- ======================================
            -- COMPLETION STATE
            -- ======================================
            'is_completed',
            public.is_quest_completed(
                q.id,
                p_player_id
            ),

            -- ======================================
            -- CLAIM STATE
            -- ======================================
            'is_claimed',
            EXISTS (
                SELECT 1
                FROM public.player_quest_progress pq
                WHERE pq.player_id = p_player_id
                  AND pq.quest_id = q.id
                  AND pq.claimed = true
            )
        )

        ORDER BY q.created_at ASC
    ),

    '[]'::jsonb
)

FROM visible_quests q;

$$;


ALTER FUNCTION public.get_player_main_quests(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_messages_json(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_messages_json(p_player_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_alliance_id uuid;
    result jsonb;
BEGIN
    -- Lấy alliance_id từ alliance_members thay vì players.alliance
    SELECT am.alliance_id
    INTO v_alliance_id
    FROM public.alliance_members am
    WHERE am.player_id = p_player_id;

    IF v_alliance_id IS NULL THEN
        RETURN jsonb_build_array(
            jsonb_build_object(
                'id', gen_random_uuid(),
                'sender_id', NULL,
                'sender_username', 'Hệ thống',
                'sender_level', 0,
                'message_type', 'system',
                'content', 'Bạn chưa gia nhập liên minh',
                'channel_type', 'alliance',
                'alliance_id', NULL,
                'created_date', now(),
                'is_edited', false,
                'is_deleted', false,
                'metadata', '{}'::jsonb
            )
        );
    END IF;

    SELECT jsonb_agg(msg)
    INTO result
    FROM (
        SELECT jsonb_build_object(
            'id', cm.id,
            'sender_id', cm.sender_id,
            'sender_username', pl.username,
            'sender_level', pl.level,
            'message_type', cm.message_type,
            'content', cm.content,
            'channel_type', cm.channel_type,
            'alliance_id', cm.alliance_id,
            'created_date', cm.created_date,
            'is_edited', cm.is_edited,
            'is_deleted', cm.is_deleted,
            'metadata', cm.metadata
        ) AS msg
        FROM public.chat_messages cm
        JOIN public.players pl ON pl.id = cm.sender_id
        WHERE cm.channel_type = 'alliance'
          AND cm.alliance_id = v_alliance_id
          AND cm.is_deleted = false
        ORDER BY cm.created_date DESC
        LIMIT p_limit
    ) sub;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_messages_json(p_player_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_player_power(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_power(player_uuid uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result json;
BEGIN
    SELECT json_build_object(
        'player_id', player_uuid,
        'total_power', SUM(
            (current_attack * 1.2 +
             current_defense * 1.0 +
             current_health * 0.8 +
             current_speed * 0.5 +
             current_intelligence * 1.1 +
             current_leadership * 1.3)
            *
            (1 + "level" * 0.02 + star_level * 0.1 + awakening_level * 0.15)
            *
            (1 + bond_level * 0.03)
        ),
        'generals', json_agg(
            json_build_object(
                'general_id', general_id,
                'power', (
                    (current_attack * 1.2 +
                     current_defense * 1.0 +
                     current_health * 0.8 +
                     current_speed * 0.5 +
                     current_intelligence * 1.1 +
                     current_leadership * 1.3)
                    *
                    (1 + "level" * 0.02 + star_level * 0.1 + awakening_level * 0.15)
                    *
                    (1 + bond_level * 0.03)
                ),
                'level', "level",
                'star_level', star_level,
                'awakening_level', awakening_level,
                'bond_level', bond_level
            )
        )
    ) INTO result
    FROM public.player_generals
    WHERE player_id = player_uuid;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_player_power(player_uuid uuid) OWNER TO postgres;

--
-- Name: get_player_quests(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_quests(player_uuid uuid, quest_category text DEFAULT NULL::text) RETURNS TABLE(quest_id uuid, quest_name text, description text, type text, category text, difficulty text, status text, min_level integer, max_level integer, requirements jsonb, rewards jsonb, player_progress jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        q.id AS quest_id,
        q.name AS quest_name,
        q.description,
        q.type,
        q.category,
        q.difficulty,
        q.status,
        q.min_level,
        q.max_level,
        
        -- Requirements
        COALESCE(
            jsonb_agg(
                DISTINCT jsonb_build_object(
                    'requirement_id', qr.id,
                    'requirement_type', qr.requirement_type,
                    'target', qr.target,
                    'meta', qr.meta
                )
            ) FILTER (WHERE qr.id IS NOT NULL),
            '[]'
        ) AS requirements,
        
        -- Rewards
        COALESCE(
            jsonb_agg(
                DISTINCT jsonb_build_object(
                    'reward_id', r.id,
                    'item_id', r.item_id,
                    'amount', r.amount,
                    'reward_type', r.reward_type,
                    'currency_type', r.currency_type,
                    'experience_amount', r.experience_amount,
                    'description', r.description
                )
            ) FILTER (WHERE r.id IS NOT NULL),
            '[]'
        ) AS rewards,
        
        -- Player progress
        jsonb_build_object(
            'progress', pqp.progress,
            'target', pqp.target,
            'completed', pqp.completed,
            'completed_at', pqp.completed_at,
            'claimed', pqp.claimed
        ) AS player_progress

    FROM public.players pl
    CROSS JOIN public.quests q
    LEFT JOIN public.quest_requirements qr
        ON q.id = qr.quest_id
    LEFT JOIN public.quest_rewards r
        ON q.id = r.quest_id
    LEFT JOIN public.player_quest_progress pqp
        ON q.id = pqp.quest_id
        AND pqp.player_id = pl.id

    WHERE pl.id = player_uuid
      AND pl.level BETWEEN q.min_level AND q.max_level
      AND (quest_category IS NULL OR q.category = quest_category)  -- Lọc theo category nếu có

    GROUP BY q.id, pqp.progress, pqp.target, pqp.completed, pqp.completed_at, pqp.claimed
    ORDER BY q.name;
END;
$$;


ALTER FUNCTION public.get_player_quests(player_uuid uuid, quest_category text) OWNER TO postgres;

--
-- Name: get_player_quests2_json(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_quests2_json(player_uuid uuid, quest_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    -- gom tất cả quest của player thành 1 JSON array
    SELECT jsonb_agg(quest_row) INTO result
    FROM (
        SELECT
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'min_level', q.min_level,
                'max_level', q.max_level,

                -- requirements
                'requirements',
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'requirement_id', qr.id,
                            'requirement_type', qr.requirement_type,
                            'target', qr.target,
                            'meta', qr.meta
                        )
                    ) FILTER (WHERE qr.id IS NOT NULL),
                    '[]'::jsonb
                ),

                -- rewards
                'rewards',
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'reward_id', r.id,
                            'item_id', r.item_id,
                            'amount', r.amount,
                            'reward_type', r.reward_type,
                            'currency_type', r.currency_type,
                            'experience_amount', r.experience_amount,
                            'description', r.description
                        )
                    ) FILTER (WHERE r.id IS NOT NULL),
                    '[]'::jsonb
                ),

                -- player progress dựa trên quest_completion_log
                'player_progress',
                jsonb_build_object(
                    'progress', 0,                     -- không lưu progress realtime
                    'target', 1,                       -- mặc định 1
                    'completed', CASE WHEN qcl.id IS NOT NULL THEN true ELSE false END,
                    'completed_at', qcl.completed_at,
                    'claimed', CASE WHEN qcl.id IS NOT NULL THEN true ELSE false END
                )
            ) AS quest_row
        FROM public.players pl
        CROSS JOIN public.quests q
        LEFT JOIN public.quest_requirements qr
            ON q.id = qr.quest_id
        LEFT JOIN public.quest_rewards r
            ON q.id = r.quest_id
        LEFT JOIN public.quest_completion_log qcl
            ON q.id = qcl.quest_id
            AND qcl.player_id = pl.id
        WHERE pl.id = player_uuid
          AND pl.level BETWEEN q.min_level AND q.max_level
          AND (quest_category IS NULL OR q.category = quest_category)
        GROUP BY
            q.id,
            qcl.id,
            qcl.completed_at
        ORDER BY q.name
    ) t;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_quests2_json(player_uuid uuid, quest_category text) OWNER TO postgres;

--
-- Name: get_player_quests_json(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_quests_json(player_uuid uuid, quest_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(quest_row) INTO result
    FROM (
        SELECT
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'min_level', q.min_level,
                'max_level', q.max_level,

                -- requirements
                'requirements',
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'requirement_id', qr.id,
                            'requirement_type', qr.requirement_type,
                            'target', qr.target,
                            'meta', qr.meta
                        )
                    ) FILTER (WHERE qr.id IS NOT NULL),
                    '[]'::jsonb
                ),

                -- rewards
                'rewards',
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'reward_id', r.id,
                            'item_id', r.item_id,
                            'amount', r.amount,
                            'reward_type', r.reward_type,
                            'currency_type', r.currency_type,
                            'experience_amount', r.experience_amount,
                            'description', r.description
                        )
                    ) FILTER (WHERE r.id IS NOT NULL),
                    '[]'::jsonb
                ),

                -- player progress
                'player_progress',
                jsonb_build_object(
                    'progress', COALESCE(pqp.progress, 0),
                    'target', COALESCE(pqp.target, 1),
                    'completed', COALESCE(pqp.completed, false),
                    'completed_at', pqp.completed_at,
                    'claimed', COALESCE(pqp.claimed, false)
                )
            ) AS quest_row
        FROM public.players pl
        CROSS JOIN public.quests q
        LEFT JOIN public.quest_requirements qr
            ON q.id = qr.quest_id
        LEFT JOIN public.quest_rewards r
            ON q.id = r.quest_id
        LEFT JOIN public.player_quest_progress pqp
            ON q.id = pqp.quest_id
            AND pqp.player_id = pl.id
        WHERE pl.id = player_uuid
          AND pl.level BETWEEN q.min_level AND q.max_level
          AND (quest_category IS NULL OR q.category = quest_category)
        GROUP BY
            q.id,
            pqp.progress,
            pqp.target,
            pqp.completed,
            pqp.completed_at,
            pqp.claimed
        ORDER BY q.name
    ) t;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_quests_json(player_uuid uuid, quest_category text) OWNER TO postgres;

--
-- Name: get_player_region_building_upgrade_cost(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_region_building_upgrade_cost(p_building_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_building public.player_region_buildings%ROWTYPE;
    v_max_level int;
    v_result jsonb;
BEGIN
    -- Get player's building
    SELECT *
    INTO v_building
    FROM public.player_region_buildings
    WHERE id = p_building_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player region building not found: %', p_building_id;
    END IF;

    -- Get max level
    SELECT max_level
    INTO v_max_level
    FROM public.base_buildings
    WHERE type = v_building.building_type;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Building type not found: %', v_building.building_type;
    END IF;

    -- Already max level
    IF v_building.level >= v_max_level THEN
        RETURN jsonb_build_object(
            'building_id', v_building.id,
            'building_type', v_building.building_type,
            'current_level', v_building.level,
            'target_level', NULL,
            'max_level', v_max_level,
            'can_upgrade', false,
            'upgrade_time', NULL,
            'costs', '[]'::jsonb
        );
    END IF;

    SELECT jsonb_build_object(
        'building_id', v_building.id,
        'building_type', v_building.building_type,
        'current_level', v_building.level,

        -- Level kế tiếp
        'target_level', v_building.level + 1,

        'max_level', v_max_level,

        'can_upgrade',
            NOT v_building.upgrading,

        'upgrade_time',
            MAX(uc.upgrade_time),

        'costs',
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'resource_code', uc.resource_code,
                        'resource_amount', uc.resource_amount
                    )
                    ORDER BY uc.resource_code
                ) FILTER (
                    WHERE uc.resource_code IS NOT NULL
                ),
                '[]'::jsonb
            )
    )
    INTO v_result
    FROM public.building_upgrade_cost uc
    WHERE uc.building_type = v_building.building_type

      -- Player level nằm trong range
      AND v_building.level >= uc.current_level
      AND v_building.level < uc.target_level;

    -- Không tìm thấy range
    IF jsonb_array_length(v_result->'costs') = 0 THEN

        RETURN jsonb_build_object(
            'building_id', v_building.id,
            'building_type', v_building.building_type,
            'current_level', v_building.level,
            'target_level', v_building.level + 1,
            'max_level', v_max_level,
            'can_upgrade', false,
            'upgrade_time', NULL,
            'costs', '[]'::jsonb
        );

    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_player_region_building_upgrade_cost(p_building_id uuid) OWNER TO postgres;

--
-- Name: get_player_region_buildings(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_region_buildings(p_player_id uuid, p_region_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'building_type', lower(rb.building_type),
                'name', bb.name,
                'description', bb.description,
                'level', coalesce(prb.level, 0),
                'max_level', bb.max_level,
                'created_at', prb.created_at,
                'updated_at', now()
            )
        ),
        '[]'::jsonb
    )
    from public.region_buildings rb

    join public.base_buildings bb 
        on bb.type = rb.building_type

    join public.player_regions pr
        on pr.region_id = rb.region_id
       and pr.player_id = p_player_id

    left join public.player_region_buildings prb
        on prb.player_region_id = pr.id
       and prb.building_type = rb.building_type

    where rb.region_id = p_region_id;
$$;


ALTER FUNCTION public.get_player_region_buildings(p_player_id uuid, p_region_id text) OWNER TO postgres;

