--
-- Name: get_player_stats_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_stats_json(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json json;
BEGIN
    SELECT json_build_object(
        'player_id', ps.player_id,
        'name', ps.name,
        'level', p.level,
        'rank', public.get_player_streak_rank(ps.player_id),
        'winRate', ps.win_rate,
        'battlePoints', ps.battle_points,
        'totalBattles', ps.total_battles,
        'totalWins', ps.total_wins,
        'currentStreak', ps.current_streak,
        'maxStreak', ps.max_streak,
        'createdAt', ps.created_at,
        'updatedAt', ps.updated_at
    )
    INTO result_json
    FROM public.player_stats ps
    JOIN public.players p
        ON p.id = ps.player_id
    WHERE ps.player_id = p_player_id;

    RETURN result_json;
END;
$$;


ALTER FUNCTION public.get_player_stats_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_streak_rank(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_streak_rank(p_player_id uuid) RETURNS bigint
    LANGUAGE sql
    AS $$
    WITH ranked_players AS (
        SELECT
            ROW_NUMBER() OVER (
                ORDER BY
                    ps.current_streak DESC,
                    ps.max_streak DESC,
                    ps.win_rate DESC,
                    ps.total_wins DESC
            ) AS rank_position,
            ps.player_id
        FROM public.player_stats ps
    )

    SELECT COALESCE(
        (
            SELECT rank_position
            FROM ranked_players
            WHERE player_id = p_player_id
        ),
        0
    );
$$;


ALTER FUNCTION public.get_player_streak_rank(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_troop_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_troop_summary(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

WITH troop_summary AS (
    SELECT
        player_id,
        unit_type,
        SUM(quantity) AS total_all_regions,
        COUNT(DISTINCT region_id) AS region_count
    FROM public.region_troops
    WHERE player_id = p_player_id
      AND quantity > 0
    GROUP BY player_id, unit_type
)

SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(
            'player_id', rt.player_id,
            'unit_type', rt.unit_type,
            'region_id', rt.region_id,

            'troops_in_this_region', rt.quantity,

            'total_troops_all_regions',
            ts.total_all_regions,

            'number_of_regions_with_this_unit',
            ts.region_count,

            'location_type', rt.location_type,
            'status', rt.status
        )
        ORDER BY
            rt.unit_type,
            rt.region_id
    ),
    '[]'::jsonb
)

FROM public.region_troops rt

INNER JOIN troop_summary ts
    ON ts.player_id = rt.player_id
   AND ts.unit_type = rt.unit_type

WHERE rt.player_id = p_player_id
  AND rt.quantity > 0;

$$;


ALTER FUNCTION public.get_player_troop_summary(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_troop_summary(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_troop_summary(p_player_id uuid, p_unit_type text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

SELECT jsonb_build_object(

    'player_id',
    p_player_id,

    'unit_type',
    p_unit_type,

    'total_troops_all_regions',
    COALESCE(
        SUM(rt.quantity),
        0
    ),

    'number_of_regions_with_this_unit',
    COUNT(DISTINCT rt.region_id),

    'troops',
    COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'region_id', rt.region_id,
                'quantity', rt.quantity,
                'location_type', rt.location_type,
                'status', rt.status
            )
            ORDER BY rt.region_id
        ),
        '[]'::jsonb
    )

)

FROM public.region_troops rt

WHERE rt.player_id = p_player_id
  AND rt.unit_type = p_unit_type
  AND rt.quantity > 0;

$$;


ALTER FUNCTION public.get_player_troop_summary(p_player_id uuid, p_unit_type text) OWNER TO postgres;

--
-- Name: get_player_unit_detail(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_unit_detail(p_player_id uuid, p_unit_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT jsonb_build_object(
    'player_unit_id', vus.player_unit_id,
    'player_id', vus.player_id,
    'unit_id', vus.unit_id,
    'quantity', vus.quantity,
    'level', vus.level,
    'rank', vus.rank,

    'base_stats', jsonb_build_object(
        'attack', vus.base_attack,
        'defense', vus.base_defense,
        'speed', vus.base_speed,
        'hp', vus.base_hp
    ),

    'equipment_stats', jsonb_build_object(
        'attack', vus.equip_attack,
        'defense', vus.equip_defense,
        'speed', vus.equip_speed,
        'hp', vus.equip_hp
    ),

    'total_stats', jsonb_build_object(
        'attack', vus.total_attack,
        'defense', vus.total_defense,
        'speed', vus.total_speed,
        'hp', vus.total_hp
    ),

    -- tổng stack (quantity)
    'stack_total_stats', jsonb_build_object(
        'attack', vus.total_attack * vus.quantity,
        'defense', vus.total_defense * vus.quantity,
        'speed', vus.total_speed * vus.quantity,
        'hp', vus.total_hp * vus.quantity
    )
)
FROM v_player_unit_stats vus
WHERE vus.player_id = p_player_id
  AND vus.unit_id = p_unit_id;
$$;


ALTER FUNCTION public.get_player_unit_detail(p_player_id uuid, p_unit_id text) OWNER TO postgres;

--
-- Name: get_player_unit_equipment_full_json(uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_unit_equipment_full_json(p_player_id uuid, p_unit_id character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(
            jsonb_build_object(
                -- Slot trên unit
                'slot', s.slot,

                -- Equipment item object
                'equipment_item',
                jsonb_build_object(
                    'item_id', bi.id,
                    'name', bi.name,
                    'description', bi.description,
                    'type', bi.type,
                    'rarity', bi.rarity,
                    'quality', bi.quality,
                    'level_requirement', bi.level_requirement,
                    'stackable', bi.stackable,
                    'max_stack', bi.max_stack,
                    'base_value', bi.base_value,
                    'icon', bi.icon
                ),

                -- Stats object (nullable)
                'stats',
                CASE
                    WHEN ist.id IS NOT NULL THEN
                        jsonb_build_object(
                            'id', ist.id,
                            'base_item_id', ist.base_item_id,
                            'attack', ist.attack,
                            'defense', ist.defense,
                            'health', ist.health,
                            'mana', ist.mana,
                            'strength', ist.strength,
                            'agility', ist.agility,
                            'intelligence', ist.intelligence,
                            'speed', ist.speed,
                            'leadership', ist.leadership,
                            'critical_chance', ist.critical_chance,
                            'critical_damage', ist.critical_damage,
                            'dodge', ist.dodge,
                            'block', ist.block,
                            'resistance', ist.resistance,
                            'created_at', ist.created_at,
                            'updated_at', ist.updated_at
                        )
                    ELSE NULL
                END
            )
        )
        FROM player_units pu
        JOIN LATERAL (
            VALUES
                ('weapon_item_id', pu.weapon_item_id),
                ('armor_item_id', pu.armor_item_id),
                ('helmet_item_id', pu.helmet_item_id),
                ('cloak_item_id', pu.cloak_item_id),
                ('boots_item_id', pu.boots_item_id),
                ('shield_item_id', pu.shield_item_id),
                ('mount_item_id', pu.mount_item_id),
                ('ring1_item_id', pu.ring1_item_id),
                ('ring2_item_id', pu.ring2_item_id)
        ) AS s(slot, item_id)
            ON s.item_id IS NOT NULL
        LEFT JOIN base_items bi
            ON bi.id = s.item_id
        LEFT JOIN item_stats ist
            ON ist.base_item_id = bi.id
        WHERE pu.player_id = p_player_id
          AND pu.unit_id = p_unit_id
    );
END;
$$;


ALTER FUNCTION public.get_player_unit_equipment_full_json(p_player_id uuid, p_unit_id character varying) OWNER TO postgres;

--
-- Name: get_player_wallet(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_wallet(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    gold_amount NUMERIC := 0;
    diamond_amount NUMERIC := 0;
BEGIN
    -- Lấy gold
    SELECT amount INTO gold_amount
    FROM player_wallets
    WHERE player_id = p_player_id AND currency_type = 'gold'
    LIMIT 1;

    -- Lấy diamond
    SELECT amount INTO diamond_amount
    FROM player_wallets
    WHERE player_id = p_player_id AND currency_type = 'diamond'
    LIMIT 1;

    -- Trả về JSON
    RETURN jsonb_build_object(
        'gold', COALESCE(gold_amount, 0),
        'diamond', COALESCE(diamond_amount, 0)
    );
END;
$$;


ALTER FUNCTION public.get_player_wallet(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_weekly_quests_status_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_weekly_quests_status_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    week_start date := date_trunc('week', CURRENT_DATE)::date;
BEGIN
    ----------------------------------------------------------------
    -- 1️⃣ Reset progress weekly quest cũ (trước tuần hiện tại)
    ----------------------------------------------------------------
    UPDATE quest_requirement_progress qrp
    SET progress = 0,
        completed = false,
        completed_at = NULL,
        updated_at = now()
    FROM quest_requirements qr
    JOIN quests q ON q.id = qr.quest_id
    WHERE qrp.quest_requirement_id = qr.id
      AND q.category = 'weekly'
      AND qrp.player_id = p_player_id
      AND qrp.updated_at::date < week_start;

    ----------------------------------------------------------------
    -- 2️⃣ Build JSON quest trong tuần hiện tại
    ----------------------------------------------------------------
    WITH req_progress_week AS (
        SELECT 
            qr.id AS requirement_id,
            qr.quest_id,
            qr.requirement_type,
            qr.target,
            qr.meta,
            COALESCE(qrp.progress, 0) AS progress,
            COALESCE(qrp.completed, false) AS completed
        FROM quest_requirements qr
        LEFT JOIN quest_requirement_progress qrp
            ON qrp.quest_requirement_id = qr.id
            AND qrp.player_id = p_player_id
            AND qrp.updated_at::date >= week_start
    ),
    rewards AS (
        SELECT 
            r.quest_id,
            jsonb_build_object(
                'reward_id', r.id,
                'item_id', r.item_id,
                'item_name', bi.name,
                'item_rarity', bi.rarity,
                'amount', r.amount,
                'reward_type', r.reward_type,
                'currency_type', r.currency_type,
                'experience_amount', r.experience_amount,
                'description', r.description
            ) AS reward_json
        FROM quest_rewards r
        LEFT JOIN base_items bi ON r.item_id = bi.id
    ),
    quests_json AS (
        SELECT
            q.id AS quest_id,
            jsonb_build_object(
                'quest_id', q.id,
                'quest_name', q.name,
                'description', q.description,
                'type', q.type,
                'category', q.category,
                'difficulty', q.difficulty,
                'status', q.status,
                'min_level', q.min_level,
                'max_level', q.max_level,

                -- requirements trong tuần
                'requirements', COALESCE(
                    (SELECT jsonb_agg(jsonb_build_object(
                        'requirement_id', rp.requirement_id,
                        'requirement_type', rp.requirement_type,
                        'target', rp.target,
                        'meta', rp.meta,
                        'progress', rp.progress,
                        'completed', rp.completed
                    ))
                    FROM req_progress_week rp
                    WHERE rp.quest_id = q.id), '[]'::jsonb),

                -- rewards
                'rewards', COALESCE(
                    (SELECT jsonb_agg(r.reward_json)
                     FROM rewards r
                     WHERE r.quest_id = q.id), '[]'::jsonb),

                -- quest completed trong tuần
                'is_completed', COALESCE(
                    (SELECT bool_and(rp.completed)
                     FROM req_progress_week rp
                     WHERE rp.quest_id = q.id), false),

                -- quest claimed trong tuần
                'is_claimed', EXISTS (
                    SELECT 1
                    FROM player_quest_progress pq
                    WHERE pq.player_id = p_player_id
                      AND pq.quest_id = q.id
                      AND pq.updated_at::date >= week_start
                      AND pq.claimed = true
                )
            ) AS quest_json
        FROM quests q
        WHERE q.category = 'weekly'
          AND q.status = 'active'
    )
    SELECT jsonb_agg(qj.quest_json ORDER BY qj.quest_json->>'quest_name')
    INTO result
    FROM quests_json qj;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_player_weekly_quests_status_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_player_world_chat_read_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_world_chat_read_state(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

    SELECT jsonb_build_object(
        'is_read_last_message',
        CASE
            WHEN (
                SELECT cm.id
                FROM public.chat_messages cm
                WHERE cm.channel_type = 'world'
                  AND cm.is_deleted = false
                ORDER BY cm.created_date DESC
                LIMIT 1
            ) IS NULL THEN true

            WHEN rs.last_read_at IS NULL THEN false

            ELSE (
                SELECT cm.created_date
                FROM public.chat_messages cm
                WHERE cm.channel_type = 'world'
                  AND cm.is_deleted = false
                ORDER BY cm.created_date DESC
                LIMIT 1
            ) <= rs.last_read_at
        END,

        'last_read_at',
        rs.last_read_at
    )

    FROM public.player_chat_read_states rs

    WHERE rs.player_id = p_player_id
      AND rs.channel_type = 'world'
      AND rs.channel_key = 'world'

    UNION ALL

    SELECT jsonb_build_object(
        'is_read_last_message',
        NOT EXISTS (
            SELECT 1
            FROM public.chat_messages cm
            WHERE cm.channel_type = 'world'
              AND cm.is_deleted = false
        ),

        'last_read_at',
        NULL
    )

    WHERE NOT EXISTS (
        SELECT 1
        FROM public.player_chat_read_states rs
        WHERE rs.player_id = p_player_id
          AND rs.channel_type = 'world'
          AND rs.channel_key = 'world'
    )

    LIMIT 1;

$$;


ALTER FUNCTION public.get_player_world_chat_read_state(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_random_rewards_from_table(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_random_rewards_from_table(p_reward_table_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rewards JSONB := '[]'::JSONB;
    v_pool RECORD;
    v_item RECORD;
    v_drops_count INTEGER;
    v_total_weight INTEGER;
    v_random_point INTEGER;
    v_cumulative_weight INTEGER := 0;
    v_selected_item RECORD;
    i INTEGER;
BEGIN
    -- Lặp qua tất cả reward pools
    FOR v_pool IN (
        SELECT * FROM loot_box_reward_pools 
        WHERE reward_table_id = p_reward_table_id
        ORDER BY id
    ) LOOP
        -- Xác định số lượng drops từ pool này
        v_drops_count := floor(random() * (v_pool.max_drops - v_pool.min_drops + 1)) + v_pool.min_drops;
        
        -- Lặp để chọn v_drops_count items từ pool
        FOR i IN 1..v_drops_count LOOP
            -- Tính tổng weight của tất cả items trong pool
            SELECT COALESCE(SUM(weight), 0) INTO v_total_weight
            FROM loot_box_reward_items
            WHERE reward_pool_id = v_pool.id;
            
            IF v_total_weight = 0 THEN
                CONTINUE;
            END IF;
            
            -- Chọn random item dựa trên weight (cách đơn giản hơn)
            v_random_point := floor(random() * v_total_weight);
            v_cumulative_weight := 0;
            
            -- Tìm item dựa trên cumulative weight
            FOR v_item IN (
                SELECT * FROM loot_box_reward_items
                WHERE reward_pool_id = v_pool.id
                ORDER BY id
            ) LOOP
                v_cumulative_weight := v_cumulative_weight + v_item.weight;
                IF v_random_point < v_cumulative_weight THEN
                    v_selected_item := v_item;
                    EXIT;
                END IF;
            END LOOP;
            
            -- Thêm reward vào kết quả
            IF v_selected_item.id IS NOT NULL THEN
                v_rewards := v_rewards || jsonb_build_object(
                    'type', v_selected_item.reward_type,
                    'item_id', v_selected_item.item_id,
                    'currency_type', v_selected_item.currency_type,
                    'amount', floor(random() * (v_selected_item.amount_max - v_selected_item.amount_min + 1)) + v_selected_item.amount_min,
                    'rarity', v_selected_item.rarity,
                    'bound_type', v_selected_item.bound_type
                );
            END IF;
        END LOOP;
    END LOOP;
    
    -- Nếu không có rewards nào, tạo rewards mặc định
    IF jsonb_array_length(v_rewards) = 0 THEN
        v_rewards := jsonb_build_array(
            jsonb_build_object(
                'type', 'currency',
                'currency_type', 'gold',
                'amount', 500,
                'rarity', 'common'
            )
        );
    END IF;
    
    RETURN v_rewards;
END;
$$;


ALTER FUNCTION public.get_random_rewards_from_table(p_reward_table_id text) OWNER TO postgres;

