CREATE FUNCTION public.get_received_friend_requests_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(
            'relationship_id', fr.id,
            'friend_id', p.id,
            'username', p.username,
            'avatar', p.avatar,
            'level', p.level,
            'power', p.power,
            'status', p.status,
            'online', (p.status = 'online'),
            'alliance', p.alliance,
            'role_in_alliance', COALESCE(p.role_in_alliance, 'member'),
            'nickname', fr.nickname,
            'favorite', fr.favorite,
            'notes', fr.notes,
            'title', p.title,
            'specialization', p.specialization,
            'victory_points', p.victory_points,
            'win_rate', p.win_rate,
            'country', p.country,
            'last_login', p.last_login,
            'created_date', fr.created_date,
            'accepted_date', fr.accepted_date,
            'friendship_status', fr.status
        )
    ),
    '[]'::jsonb
)
FROM friend_relationships fr
JOIN players p ON p.id = fr.player_id
WHERE fr.friend_id = p_player_id
AND fr.status = 'pending';
$$;


