                'attack', v.equip_attack,
                'defense', v.equip_defense,
                'speed', v.equip_speed,
                'health', v.equip_hp
            ),

            'total_stats', jsonb_build_object(
                'attack', v.total_attack,
                'defense', v.total_defense,
