--
-- Name: get_region_defense(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_defense(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_build_object(
            'region_id', rd.region_id,
            'defense', json_build_object(
                'wall_level', rd.wall_level,
                'gate_health', rd.gate_health,
                'max_gate_health', 1000 * rd.wall_level,
                'watchtowers', rd.watchtowers,
                'defense_bonus', rd.defense_bonus,
                'total_defense_power', calculate_defense_power(
                    rd.wall_level, rd.gate_health, rd.watchtowers, rd.defense_bonus
                ),
                'defense_status', CASE 
                    WHEN rd.gate_health > 800 THEN 'Strong'
                    WHEN rd.gate_health > 400 THEN 'Moderate'
                    WHEN rd.gate_health > 0 THEN 'Weak'
                    ELSE 'Breached'
                END
            ),
            'upgrade_cost', json_build_object(
                'next_wall_level', rd.wall_level + 1,
                'gold_cost', 500 * rd.wall_level,
                'wood_cost', 300 * rd.wall_level,
                'time_hours', 8 * rd.wall_level
            )
        )
        FROM region_defense rd
        WHERE rd.region_id = region_id_param
    );
END;
$$;


