--
-- Name: get_region_detail_json(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_detail_json(p_player_id uuid, p_region_id text) RETURNS jsonb
    LANGUAGE sql
    AS $$
    SELECT row_to_json(t)
    FROM (
        SELECT
            r.id AS region_id,
            r.lord_name,
            r.created_at,
            r.updated_at,
            pr.id IS NOT NULL AS owned,
            pr.id AS player_region_id,
            pr.acquired_at,
            pr.is_active,
            pr.development_level,
            -- Tài nguyên của player trong region
            CASE
                WHEN pr.id IS NOT NULL THEN
                    (SELECT jsonb_agg(
                        jsonb_build_object(
                            'resource', rr.out_resource,
                            'amount', rr.out_amount,
                            'max_amount', rr.out_max_amount
                        )
                    )
                    FROM get_resources_by_player_region(p_player_id, r.id) rr)
                ELSE NULL
            END AS resources,
            -- Danh sách công trình
            CASE
                WHEN pr.id IS NOT NULL THEN
                    get_slots_by_region_and_player(r.id, p_player_id)
                ELSE '[]'::jsonb
            END AS slots
        FROM public.regions r
        LEFT JOIN public.player_regions pr
            ON pr.region_id = r.id
           AND pr.player_id = p_player_id
        WHERE r.id = p_region_id
    ) t;
$$;


ALTER FUNCTION public.get_region_detail_json(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: get_region_expansion_cost(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_expansion_cost(p_player_id uuid, p_region_id text, p_slot_index integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'player_id', p_player_id,
        'region_id', p_region_id,
        'slot_index', p_slot_index,
        'costs',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'resource_code', rec.cost_type,
                    'resource_amount', rec.cost_amount
                )
                ORDER BY rt.sort_order, rec.cost_type
            ),
            '[]'::jsonb
        )
    )
    INTO v_result
    FROM public.player_regions pr
    JOIN public.region_expansion_costs rec
        ON pr.region_id = rec.region_id
    JOIN public.resource_types rt
        ON rt.resource_code = rec.cost_type
    WHERE pr.player_id = p_player_id
      AND pr.region_id = p_region_id
      AND rec.slot_index = p_slot_index;

    RETURN v_result;
END;
$$;


