--
-- Name: get_region_generals_json(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_generals_json(p_region_id text, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(row_to_json(t))
        FROM (
            SELECT 
                -- Thông tin từ region_generals
                rg.id AS region_general_id,
                rg.region_id,
                rg.player_id,
                rg.general_id,
                rg.battle_role AS general_battle_role,
                rg.is_active,
                rg.stationed_at,
                rg.created_at,
                rg.updated_at,
                
                -- Thông tin từ generals
                g.id AS general_id,
                g.name AS general_name,
                g.title AS general_title,
                g.rarity AS general_rarity,
                g.element AS general_element,
                g.type AS general_type,
                g.level AS general_base_level,
                g.max_level AS general_max_level,
                g.base_attack,
                g.base_defense,
                g.base_health,
                g.base_speed,
                g.base_intelligence,
                g.base_leadership,
                g.current_attack,
                g.current_defense,
                g.current_health,
                g.current_speed,
                g.current_intelligence,
                g.current_leadership,
                g.status AS general_status,
                g.owner AS general_owner,
                g.location AS general_location,
                g.experience AS general_experience,
                g.required_exp,
                g.star_level AS general_star_level,
                g.max_star_level,
                g.awakening_level AS general_awakening,
                g.bond_level AS general_bond,
                g.favorite AS general_favorite,
                g.obtained_date,
                g.last_used,
                g.battle_count AS general_battle_count,
                g.win_rate AS general_win_rate,
                g.voice_actor,
                g.biography,
                g.image,
                g.thumbnail,
                g.is_vip AS general_is_vip,
                g.description,
                
                -- Thông tin từ player_generals
                pg.id AS player_general_id,
                pg.player_id AS pg_player_id,
                pg.general_id AS pg_general_id,
                pg.level AS player_general_level,
                pg.experience AS player_general_experience,
                pg.star_level AS player_general_star,
                pg.max_star_level AS pg_max_star,
                pg.awakening_level AS pg_awakening,
                pg.bond_level AS pg_bond,
                pg.current_attack AS pg_attack,
                pg.current_defense AS pg_defense,
                pg.current_health AS pg_health,
                pg.current_speed AS pg_speed,
                pg.current_intelligence AS pg_intelligence,
                pg.current_leadership AS pg_leadership,
                pg.favorite AS pg_favorite,
                pg.obtained_date AS pg_obtained_date,
                pg.last_used AS pg_last_used,
                pg.battle_count AS pg_battle_count,
                pg.win_rate AS pg_win_rate,
                pg.created_at AS pg_created_at,
                pg.updated_at AS pg_updated_at,
                pg.is_representative
            FROM region_generals rg
            INNER JOIN generals g ON rg.general_id = g.id
            INNER JOIN player_generals pg ON rg.player_id = pg.player_id AND rg.general_id = pg.general_id
            WHERE rg.region_id = p_region_id
              AND rg.player_id = p_player_id
        ) t
    );
END;
$$;


