--
-- Name: get_region_info(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_info(p_region_id text, p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result json;
BEGIN
    SELECT json_build_object(
        'regionName', r.lord_name,
        'description', r.description,

        -- warlord
        'warlordName', p.name,
        'warlordTitle', 'Lãnh chúa',

        -- population
        'population', pr.development_level * 1000,

        -- resources
        'gold', COALESCE(MAX(CASE WHEN rr.resource_code = 'gold' THEN rr.amount END), 0),
        'food', COALESCE(MAX(CASE WHEN rr.resource_code = 'food' THEN rr.amount END), 0),
        'wood', COALESCE(MAX(CASE WHEN rr.resource_code = 'wood' THEN rr.amount END), 0),
        'iron', COALESCE(MAX(CASE WHEN rr.resource_code = 'iron' THEN rr.amount END), 0),

        -- military
        'militaryPower', pr.development_level * 500,

        -- relation
        'relationStatus', 'Đã chiếm lĩnh'
    )
    INTO v_result
    FROM player_regions pr
    JOIN regions r ON r.id = pr.region_id
    JOIN players p ON p.id = pr.player_id
    LEFT JOIN region_resources rr ON rr.player_region_id = pr.id
    WHERE pr.region_id = p_region_id
      AND pr.player_id = p_player_id
    GROUP BY pr.id, r.lord_name, r.description, p.name, pr.development_level;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_region_info(p_region_id text, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_region_resources(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_resources(p_player_id uuid, p_region_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_id UUID;
    v_result JSONB;
BEGIN
    -- 1. Lấy player_region_id
    SELECT id
    INTO v_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Region not found'
        );
    END IF;

    -- 2. Lấy danh sách resource (kể cả 0)
    SELECT jsonb_agg(
        jsonb_build_object(
            'resource_code', rt.resource_code,
            'resource_name', rt.resource_name,
            'category', rt.resource_category,
            'amount', COALESCE(rr.amount,0),
            'max_amount', COALESCE(rr.max_amount,2500)
        )
        ORDER BY rt.sort_order
    )
    INTO v_result
    FROM resource_types rt
    LEFT JOIN region_resources rr
        ON rr.resource_code = rt.resource_code
       AND rr.player_region_id = v_region_id;

    RETURN json_build_object(
        'success', true,
        'region_id', p_region_id,
        'resources', COALESCE(v_result, '[]'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.get_region_resources(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: get_region_slots_with_buildings_ui(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_slots_with_buildings_ui(p_player_id uuid, p_region_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(slot_json)
        FROM (
            SELECT
                rs.id AS slot_id,
                pr.id AS player_region_id,
                pr.player_id,
                pr.region_id,
                rs.created_at,
                b.upgrade_finish_at AS completed_at,
                (b.upgrade_finish_at < now()) AS has_completed_upgrade,
                CASE
                    WHEN rs.occupied_building_id IS NULL THEN 'empty'
                    WHEN b.upgrading = true THEN 'building'
                    ELSE 'completed'
                END AS status,
                -- Building property
                CASE
                    WHEN b.id IS NOT NULL THEN jsonb_build_object(
                        'id', b.id,
                        'type', b.building_type,
                        'level', b.level,
                        'name', bb.name,
                        'description', bb.description,
                        'max_level', bb.max_level,
                        'created_at', b.created_at
                    )
                    ELSE NULL
                END AS building
            FROM region_slots rs
            JOIN player_regions pr
              ON pr.id = rs.player_region_id
             AND pr.player_id = p_player_id
             AND pr.region_id = p_region_id
            LEFT JOIN player_region_buildings b
              ON b.id = rs.occupied_building_id
            LEFT JOIN base_buildings bb
              ON bb.type = b.building_type
            ORDER BY rs.created_at
        ) AS slot_json
    );
END;
$$;


ALTER FUNCTION public.get_region_slots_with_buildings_ui(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: get_region_troop_summary_json(character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_troop_summary_json(p_region_id character varying, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_troops BIGINT;
    v_unit_types_count INTEGER;
    v_troops_by_unit JSONB;
    v_summary_stats JSONB;
BEGIN
    -- Get basic counts
    SELECT 
        COALESCE(SUM(rt.quantity), 0),
        COUNT(DISTINCT rt.unit_type)
    INTO v_total_troops, v_unit_types_count
    FROM public.region_troops rt
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id;
    
    -- Get troops by unit with details
    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'unit_id', u.id,
                'unit_name', u.name,
                'unit_type', u.type,
                'unit_rank', u.rank,
                'image_path', u.image_path,
                'description', u.description,
                'is_vip', u.is_vip,
                'is_special', u.is_special,
                'quantity', rt.quantity,
                'total_hp', rt.quantity * u.max_hp,
                'total_attack', rt.quantity * u.atk,
                'total_defense', rt.quantity * u.def,
                'unit_stats', JSONB_BUILD_OBJECT(
                    'level', u.level,
                    'max_hp', u.max_hp,
                    'attack', u.atk,
                    'defense', u.def,
                    'speed', u.speed,
                    'range', u.range
                ),
                'last_updated', rt.updated_at
            ) ORDER BY u.type, u.name
        ),
        '[]'::JSONB
    ) INTO v_troops_by_unit
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id;
    
    -- Get summary stats
    WITH stats AS (
        SELECT 
            COALESCE(SUM(rt.quantity * u.atk), 0) AS total_attack_power,
            COALESCE(SUM(rt.quantity * u.def), 0) AS total_defense_power,
            COALESCE(SUM(rt.quantity * u.max_hp), 0) AS total_hit_points,
            COALESCE(AVG(u.speed), 0) AS average_speed,
            (
                SELECT u2.name 
                FROM public.region_troops rt2
                JOIN public.units u2 ON rt2.unit_type = u2.id
                WHERE rt2.region_id = p_region_id 
                    AND rt2.player_id = p_player_id
                ORDER BY u2.atk DESC 
                LIMIT 1
            ) AS strongest_unit,
            (
                SELECT u2.name 
                FROM public.region_troops rt2
                JOIN public.units u2 ON rt2.unit_type = u2.id
                WHERE rt2.region_id = p_region_id 
                    AND rt2.player_id = p_player_id
                ORDER BY rt2.quantity DESC 
                LIMIT 1
            ) AS most_common_unit
        FROM public.region_troops rt
        JOIN public.units u ON rt.unit_type = u.id
        WHERE rt.region_id = p_region_id 
            AND rt.player_id = p_player_id
    )
    SELECT JSONB_BUILD_OBJECT(
        'total_attack_power', total_attack_power,
        'total_defense_power', total_defense_power,
        'total_hit_points', total_hit_points,
        'average_speed', average_speed,
        'strongest_unit', COALESCE(strongest_unit, 'None'),
        'most_common_unit', COALESCE(most_common_unit, 'None')
    ) INTO v_summary_stats
    FROM stats;
    
    -- Return the final JSON object
    RETURN JSONB_BUILD_OBJECT(
        'region_id', p_region_id,
        'player_id', p_player_id,
        'total_troops', v_total_troops,
        'unit_types_count', v_unit_types_count,
        'troops_by_unit', COALESCE(v_troops_by_unit, '[]'::JSONB),
        'summary_stats', COALESCE(v_summary_stats, '{}'::JSONB)
    );
END;
$$;


ALTER FUNCTION public.get_region_troop_summary_json(p_region_id character varying, p_player_id uuid) OWNER TO postgres;

--
-- Name: get_region_troop_totals_json(character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_region_troop_totals_json(p_region_id character varying, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_troops_json JSONB;
    v_summary_json JSONB;
    v_by_type_json JSONB;
    v_by_rank_json JSONB;
    v_result JSONB;
BEGIN
    -- First, get troops array (no aggregates here)
    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'player_unit_id', rt.id::TEXT,
                'unit_name', u.name,
                'player_rank', u.rank::TEXT,
                'unit_type', u.type::TEXT,
                'base_atk', u.atk,
                'base_def', u.def,
                'base_speed', u.speed,
                'quantity', rt.quantity,
                'is_special', u.is_vip,
                'join_date', rt.created_at,
                'player_level', 1,
                'player_max_hp', u.max_hp,
                'player_current_hp', u.max_hp,
                'experience', 0,
                'formation_position', NULL,
                'is_in_garrison', TRUE,
                'owned', TRUE,
                'image_path', u.image_path
            ) ORDER BY u.type, u.name
        ),
        '[]'::JSONB
    ) INTO v_troops_json
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
        AND rt.location_type = 'region'
        AND rt.location_id IS NULL;
    
    -- Get summary stats using separate calculations
    WITH troop_data AS (
        SELECT 
            rt.quantity,
            u.atk,
            u.def,
            u.max_hp,
            u.speed,
            u.is_vip,
            u.is_special,
            u.type
        FROM public.region_troops rt
        JOIN public.units u ON rt.unit_type = u.id
        WHERE rt.region_id = p_region_id 
            AND rt.player_id = p_player_id
            AND rt.location_type = 'region'
            AND rt.location_id IS NULL
    )
    SELECT JSONB_BUILD_OBJECT(
        'total_troops', COALESCE((SELECT SUM(quantity) FROM troop_data), 0),
        'total_unit_types', COALESCE((SELECT COUNT(DISTINCT type) FROM troop_data), 0),
        'total_attack_power', COALESCE((SELECT SUM(quantity * atk) FROM troop_data), 0),
        'total_defense_power', COALESCE((SELECT SUM(quantity * def) FROM troop_data), 0),
        'total_hit_points', COALESCE((SELECT SUM(quantity * max_hp) FROM troop_data), 0),
        'average_speed', COALESCE((SELECT AVG(speed) FROM troop_data), 0),
        'vip_troops_count', COALESCE((SELECT SUM(quantity) FROM troop_data WHERE is_vip), 0),
        'special_troops_count', COALESCE((SELECT SUM(quantity) FROM troop_data WHERE is_special), 0)
    ) INTO v_summary_json;
    
    -- Get by unit type using a temporary table approach
    CREATE TEMP TABLE IF NOT EXISTS temp_unit_type_agg AS
    SELECT 
        u.type::TEXT AS unit_type,
        SUM(rt.quantity) AS count,
        SUM(rt.quantity * u.atk) AS attack_power,
        SUM(rt.quantity * u.def) AS defense_power
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
        AND rt.location_type = 'region'
        AND rt.location_id IS NULL
    GROUP BY u.type;
    
    SELECT COALESCE(
        JSONB_OBJECT_AGG(
            unit_type,
            JSONB_BUILD_OBJECT(
                'count', count,
                'attack_power', attack_power,
                'defense_power', defense_power
            )
        ),
        '{}'::JSONB
    ) INTO v_by_type_json
    FROM temp_unit_type_agg;
    
    DROP TABLE IF EXISTS temp_unit_type_agg;
    
    -- Get by rank using a temporary table approach
    CREATE TEMP TABLE IF NOT EXISTS temp_rank_agg AS
    SELECT 
        u.rank::TEXT AS rank_name,
        SUM(rt.quantity) AS rank_count,
        ARRAY_AGG(DISTINCT u.type::TEXT) AS unit_types_array
    FROM public.region_troops rt
    JOIN public.units u ON rt.unit_type = u.id
    WHERE rt.region_id = p_region_id 
        AND rt.player_id = p_player_id
        AND rt.location_type = 'region'
        AND rt.location_id IS NULL
    GROUP BY u.rank;
    
    SELECT COALESCE(
        JSONB_OBJECT_AGG(
            rank_name,
            JSONB_BUILD_OBJECT(
                'count', rank_count,
                'unit_types', unit_types_array
            )
        ),
        '{}'::JSONB
    ) INTO v_by_rank_json
    FROM temp_rank_agg;
    
    DROP TABLE IF EXISTS temp_rank_agg;
    
    -- Build final result
    IF v_troops_json IS NULL THEN
        v_troops_json := '[]'::JSONB;
    END IF;
    
    IF v_summary_json IS NULL THEN
        v_summary_json := JSONB_BUILD_OBJECT(
            'total_troops', 0,
            'total_unit_types', 0,
            'total_attack_power', 0,
            'total_defense_power', 0,
            'total_hit_points', 0,
            'average_speed', 0,
            'vip_troops_count', 0,
            'special_troops_count', 0
        );
    END IF;
    
    IF v_by_type_json IS NULL THEN
        v_by_type_json := '{}'::JSONB;
    END IF;
    
    IF v_by_rank_json IS NULL THEN
        v_by_rank_json := '{}'::JSONB;
    END IF;
    
    v_result := JSONB_BUILD_OBJECT(
        'success', true,
        'region_id', p_region_id,
        'player_id', p_player_id,
        'troops', v_troops_json,
        'summary', v_summary_json,
        'by_unit_type', v_by_type_json,
        'by_rank', v_by_rank_json
    );
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Clean up temp tables if they exist
    DROP TABLE IF EXISTS temp_unit_type_agg;
    DROP TABLE IF EXISTS temp_rank_agg;
    
    RETURN JSONB_BUILD_OBJECT(
        'success', false,
        'message', 'Error retrieving troop data: ' || SQLERRM,
        'region_id', p_region_id,
        'player_id', p_player_id,
        'troops', '[]'::JSONB,
        'summary', JSONB_BUILD_OBJECT(
            'total_troops', 0,
            'total_unit_types', 0,
            'total_attack_power', 0,
            'total_defense_power', 0,
            'total_hit_points', 0,
            'average_speed', 0,
            'vip_troops_count', 0,
            'special_troops_count', 0
        ),
        'by_unit_type', '{}'::JSONB,
        'by_rank', '{}'::JSONB
    );
END;
$$;


ALTER FUNCTION public.get_region_troop_totals_json(p_region_id character varying, p_player_id uuid) OWNER TO postgres;

