CREATE FUNCTION public.get_region_troops(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_build_object(
            'region_id', rt.region_id,
            'player_id', rt.player_id,
            'troops', json_build_object(
                'infantry', rt.infantry,
                'cavalry', rt.cavalry,
                'archers', rt.archers,
                'siege', rt.siege,
                'navy', rt.navy,
                'total', rt.infantry + rt.cavalry + rt.archers + rt.siege + rt.navy
            ),
            'training_level', rt.training_level,
            'combat_power', calculate_combat_power(
                rt.infantry, rt.cavalry, rt.archers, rt.siege, rt.navy, rt.training_level
            )
        )
        FROM region_troops rt
        WHERE rt.region_id = region_id_param
    );
END;
$$;


