-- Name: get_regions_with_player_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_regions_with_player_status(p_player_id uuid) RETURNS TABLE(region_id text, lord_name text, player_region_id uuid, player_id uuid, development_level integer, resources integer, is_active boolean, username text, owned boolean)
    LANGUAGE sql
    AS $$
    SELECT
        r.id AS region_id,
        r.lord_name AS lord_name,
        pr.id AS player_region_id,
        pr.player_id,
        pr.development_level,
        pr.resources,
        pr.is_active,
        p.username,
        (pr.id IS NOT NULL) AS owned
    FROM public.regions r
    LEFT JOIN public.player_regions pr
        ON r.id = pr.region_id
        AND pr.player_id = p_player_id
    LEFT JOIN public.players p
        ON pr.player_id = p.id
    ORDER BY r.id;
$$;


