--
-- Name: get_required_exp(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_required_exp(p_player_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_level int;
    v_range RECORD;
    v_local_level int;
BEGIN
    -- lấy level hiện tại của player
    SELECT level
    INTO v_level
    FROM public.players
    WHERE id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player not found: %', p_player_id;
    END IF;

    -- tìm segment progression phù hợp
    SELECT *
    INTO v_range
    FROM public.level_progression_ranges
    WHERE v_level BETWEEN level_from AND level_to
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No progression config for level %', v_level;
    END IF;

    -- level nội bộ trong segment
    v_local_level := v_level - v_range.level_from + 1;

    RETURN FLOOR(
        v_range.base_exp
        * POWER(v_range.growth_rate, v_local_level - 1)
        * POWER(v_local_level, v_range.exponent)
    )::bigint;
END;
$$;


ALTER FUNCTION public.get_required_exp(p_player_id uuid) OWNER TO postgres;

--
-- Name: get_required_exp_by_level(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_required_exp_by_level(p_level integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
	DECLARE
	    v_range RECORD;
	    v_local_level int;
	BEGIN
	    SELECT *
	    INTO v_range
	    FROM public.level_progression_ranges
	    WHERE p_level BETWEEN level_from AND level_to
	    LIMIT 1;
	
	    IF NOT FOUND THEN
	        RAISE EXCEPTION 'No progression config for level %', p_level;
	    END IF;
	
	    v_local_level := p_level - v_range.level_from + 1;
	
	    RETURN FLOOR(
	        v_range.base_exp
	        * POWER(v_range.growth_rate, v_local_level - 1)
	        * POWER(v_local_level, v_range.exponent)
	    )::bigint;
	END;
	$$;


ALTER FUNCTION public.get_required_exp_by_level(p_level integer) OWNER TO postgres;

--
-- Name: get_resource_activity_progress(boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_resource_activity_progress(p_is_accumulate boolean, p_activity_id uuid, p_game_action text) RETURNS integer
    LANGUAGE sql
    AS $$
    SELECT CASE
        WHEN NOT p_is_accumulate THEN 1

        ELSE COALESCE(
            (
                SELECT CASE pav.value
                    WHEN 'collected_amount' THEN v.collected_amount
                    ELSE 0
                END
                FROM public.game_action_progress_values pav
                JOIN public.view_player_resource_activities v
                    ON v.id = p_activity_id
                WHERE pav.game_action_id = p_game_action
            ),
            0
        )
    END;
$$;


ALTER FUNCTION public.get_resource_activity_progress(p_is_accumulate boolean, p_activity_id uuid, p_game_action text) OWNER TO postgres;

--
-- Name: get_resource_logs_by_region(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_resource_logs_by_region(p_player_id uuid, p_region_id text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
    v_result jsonb;
BEGIN
    -- find player_region_id
    SELECT pr.id
    INTO v_player_region_id
    FROM public.player_regions pr
    WHERE pr.player_id = p_player_id
      AND pr.region_id = p_region_id
    LIMIT 1;

    -- return empty if region ownership not found
    IF v_player_region_id IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    -- fetch logs
    SELECT jsonb_agg(row_data)
    INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'id', rl.id,
            'created_at', rl.created_at,
            'resource_code', rl.resource_code,
            'resource_name', rt.resource_name,
            'resource_category', rt.resource_category,
            'amount', rl.amount,
            'description', rl.description,
            'action_type', rl.action_type,
            'metadata', rl.metadata
        ) AS row_data
        FROM public.resource_logs rl
        JOIN public.resource_types rt
            ON rl.resource_code = rt.resource_code
        WHERE rl.player_region_id = v_player_region_id
        ORDER BY rl.created_at DESC
        LIMIT p_limit
        OFFSET p_offset
    ) t;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_resource_logs_by_region(p_player_id uuid, p_region_id text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: get_resources_by_player_region(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_resources_by_player_region(p_player_id uuid, p_region_id text) RETURNS TABLE(out_resource public.resource_type, out_amount integer, out_max_amount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
BEGIN
    -- 1️⃣ Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % does not own region %', p_player_id, p_region_id;
    END IF;

    -- 2️⃣ Trả về tất cả resource của region
    RETURN QUERY
    SELECT 
        resource AS out_resource,
        amount AS out_amount,
        max_amount AS out_max_amount
    FROM region_resources
    WHERE player_region_id = v_player_region_id;
END;
$$;


ALTER FUNCTION public.get_resources_by_player_region(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: get_reward_full(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_reward_full(input_json jsonb) RETURNS jsonb
    LANGUAGE sql
    AS $$
SELECT jsonb_agg(
    jsonb_build_object(
        'rarity', COALESCE(r->>'rarity', i.rarity::text),

        'item_id', r->>'item_id',

        'item_name', COALESCE(i.name, c.name),

        'reward_id', COALESCE(r->>'reward_id', r->>'item_id'),

        'amount', (r->>'amount')::int,

        'bound_type', r->>'bound_type',

        'reward_type', r->>'reward_type',

        'currency_type', c.currency_type
    )
)
FROM jsonb_array_elements(input_json->'rewards') r
LEFT JOIN base_items i
    ON r->>'item_id' = i.id
    AND r->>'reward_type' = 'item'
LEFT JOIN currencies c
    ON r->>'item_id' = c.currency_type
    AND r->>'reward_type' = 'currency';
$$;


ALTER FUNCTION public.get_reward_full(input_json jsonb) OWNER TO postgres;

--
-- Name: get_reward_pity_by_count(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_reward_pity_by_count(p_loot_box_id text, p_pity_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rewards jsonb := '[]'::jsonb;
    t_item RECORD;
BEGIN
    -- Lấy tất cả các item từ pity counters phù hợp với pity_count
    FOR t_item IN
        SELECT rbi.*
        FROM public.loot_box_pity_systems ps
        JOIN public.loot_box_pity_counters pc ON ps.id = pc.pity_system_id
        JOIN public.loot_box_reward_items rbi ON rbi.rarity = pc.rarity
        WHERE ps.loot_box_id = p_loot_box_id
          AND ps.enabled = true
          AND p_pity_count >= pc.threshold
    LOOP
        v_rewards := v_rewards || jsonb_build_object(
            'item_id', t_item.item_id,   -- item_id thực tế
            'reward_type', 'item',
            'amount', 1,
            'rarity', t_item.rarity,
            'bound_type', t_item.bound_type,
            'source', 'pity'
        );
    END LOOP;

    RETURN v_rewards;
END;
$$;


ALTER FUNCTION public.get_reward_pity_by_count(p_loot_box_id text, p_pity_count integer) OWNER TO postgres;

--
-- Name: get_reward_streak_by_count(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_reward_streak_by_count(p_loot_box_id text, p_streak_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rewards jsonb := '[]'::jsonb;
    t_item RECORD;
BEGIN
    -- Lấy tất cả các item từ các streak tier phù hợp với streak_count
    FOR t_item IN
        SELECT rbi.*
        FROM public.loot_box_streak_bonus_tiers st
        JOIN public.loot_box_streak_bonuses sb ON st.streak_bonus_id = sb.id
        JOIN public.loot_box_streak_items si ON si.streak_tier_id = st.id
        JOIN public.loot_box_reward_items rbi ON rbi.id = si.reward_item_id
        WHERE sb.enabled = true
          AND sb.reward_table_id IN (
              SELECT id 
              FROM public.loot_box_reward_tables
              WHERE loot_box_id = p_loot_box_id
          )
          AND st.streak_count <= p_streak_count
    LOOP
        v_rewards := v_rewards || jsonb_build_object(
            'item_id', t_item.item_id,   -- <-- sửa ở đây
            'reward_type', 'item',
            'amount', 1,
            'rarity', t_item.rarity,
            'bound_type', t_item.bound_type,
            'source', 'streak'
        );
    END LOOP;

    RETURN v_rewards;
END;
$$;


ALTER FUNCTION public.get_reward_streak_by_count(p_loot_box_id text, p_streak_count integer) OWNER TO postgres;

--
-- Name: get_reward_streak_by_count_t(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_reward_streak_by_count_t(p_loot_box_id text, p_streak_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rewards jsonb := '[]'::jsonb;
    t_reward RECORD;
BEGIN
    -- Lấy tất cả reward thỏa streak_count <= p_streak_count
    FOR t_reward IN
        SELECT *
        FROM public.loot_box_streak_rewards
        WHERE loot_box_id = p_loot_box_id
          AND streak_count <= p_streak_count
        ORDER BY streak_count
    LOOP
        v_rewards := v_rewards || jsonb_build_object(
            'item_id', t_reward.item_id,
            'reward_type', t_reward.reward_type,
            'amount', COALESCE(t_reward.amount, 1),
            'rarity', COALESCE(t_reward.rarity, 'streak'),
            'bound_type', COALESCE(t_reward.bound_type, 'none')
        );
    END LOOP;

    RETURN v_rewards;
END;
$$;


ALTER FUNCTION public.get_reward_streak_by_count_t(p_loot_box_id text, p_streak_count integer) OWNER TO postgres;

--
-- Name: get_shop_item_transaction_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_shop_item_transaction_json(p_shop_item_id uuid) RETURNS TABLE(shop_item_id uuid, cost_ops jsonb, reward_ops jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH shop AS (
        SELECT id
        FROM economy_shop_item
        WHERE id = p_shop_item_id
    ),

    -- 1️⃣ COST: currency
    price_json AS (
        SELECT jsonb_agg(
            CASE 
                WHEN p.currency_type IS NOT NULL THEN
                    jsonb_build_object(
                        'type', 'currency',
                        'currency', p.currency_type,
                        'amount', p.amount
                    )
            END
        ) AS cost_ops
        FROM economy_shop_item_prices p
        WHERE p.shop_item_id = p_shop_item_id
    ),

    -- 2️⃣ REWARD: components (FULL)
    reward_json AS (
        SELECT jsonb_agg(
            CASE 
                WHEN c.base_item_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','item',
                        'id', c.base_item_id,
                        'quantity', c.quantity
                    )
                WHEN c.beauty_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','beauty',
                        'id', c.beauty_id,
                        'quantity', c.quantity
                    )
                WHEN c.general_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','hero',
                        'id', c.general_id,
                        'quantity', c.quantity
                    )
                WHEN c.gift_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','gift',
                        'id', c.gift_id,
                        'quantity', c.quantity
                    )
                WHEN c.loot_box_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','loot_box',
                        'id', c.loot_box_id,
                        'quantity', c.quantity
                    )
                WHEN c.unit_id IS NOT NULL THEN
                    jsonb_build_object(
                        'type','unit',
                        'id', c.unit_id,
                        'quantity', c.quantity
                    )
            END
        ) AS reward_ops
        FROM economy_shop_item_components c
        WHERE c.shop_item_id = p_shop_item_id
    )

    SELECT
        s.id AS shop_item_id,
        COALESCE(price_json.cost_ops, '[]'::jsonb)    AS cost_ops,
        COALESCE(reward_json.reward_ops, '[]'::jsonb) AS reward_ops
    FROM shop s
    LEFT JOIN price_json  ON TRUE
    LEFT JOIN reward_json ON TRUE;
END;
$$;


ALTER FUNCTION public.get_shop_item_transaction_json(p_shop_item_id uuid) OWNER TO postgres;

--
-- Name: get_shop_items_json(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_shop_items_json(p_type text DEFAULT NULL::text) RETURNS json
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(
      json_agg(item ORDER BY item.created_at DESC),  -- ✅ order inside json_agg
      '[]'::json
    )
  FROM (
    SELECT
      si.id,
      si.name,
      si.description,
      si.category,
      si.type,
      si.rarity,
      si.duration_days,
      si.stock,
      si.sales,
      si.revenue,
      si.status,
      si.vip_level_required,
      si.item_icon AS "itemIcon",
      si.created_at,
      si.updated_at,

      -- prices
      COALESCE(
        (
          SELECT json_agg(
            jsonb_build_object(
              'currency_type', p.currency_type,
              'amount', p.amount
            )
          )
          FROM public.economy_shop_item_prices p
          WHERE p.shop_item_id = si.id
        ),
        '[]'::json
      ) AS prices,

      -- components
      COALESCE(
        (
          SELECT json_agg(
            jsonb_build_object(
              'base_item_id', c.base_item_id,
              'quantity', c.quantity
            )
          )
          FROM public.economy_shop_item_components c
          WHERE c.shop_item_id = si.id
        ),
        '[]'::json
      ) AS components

    FROM public.economy_shop_item si
    WHERE si.status = 'active'
      AND (p_type IS NULL OR si.type = p_type)
  ) item;
$$;


ALTER FUNCTION public.get_shop_items_json(p_type text) OWNER TO postgres;

--
-- Name: get_slots_by_region_and_player(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_slots_by_region_and_player(p_region_id text, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(slot_data)
        FROM (
            SELECT
                s.slot_id,
                s.region_id,
                s.player_id,
                s.building_type,
                s.building_level,
                s.status,
                s.started_at,
                s.completed_at,
                s.created_at,
                s.updated_at,
                b.name AS building_name,
                b.description AS building_description,
                b.max_level AS building_max_level
            FROM public.slot s
            LEFT JOIN public.building b
                ON s.building_type = b.type
            WHERE s.region_id = p_region_id
              AND s.player_id = p_player_id
            ORDER BY s.slot_id
        ) AS slot_data
    );
END;
$$;


