--
-- Name: get_story_dialog(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_story_dialog(story_id_param text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', s.id,
            'background', s.background,
            'text', s.dialog_text,
            'soundEffect', s.sound_effect,
            'is_end_story', s.is_end_story,
            'is_failed_story', s.is_failed_story,
            'active_scene_name', s.active_scene_name,
            'failure_scene_name', s.failure_scene_name,
             'typing_style', s.typing_style,
            'speaker',
            jsonb_build_object(
                'name', c.name,
                'avatar', c.avatar,
                'color', c.color,
                'position', c.default_position
            ),

            'choices',
            COALESCE(
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'text', sc.choice_text,
                            'next_scene', 
                                CASE
                                    WHEN s.active_scene_name = sc.active_scene
                                         AND sc.scene_index IS NULL
                                    THEN s.scene_order
                                    ELSE sc.scene_index
                                END,
                            'active_scene', sc.active_scene,
                            'effect', '',
                            'stats_change', '{}'::jsonb,
                            'boss_battle_id', sc.boss_id
                        )
                        ORDER BY sc.choice_order
                    )
                    FROM public.story_choices sc
                    LEFT JOIN public.story_scenes ns
                        ON ns.id = sc.next_scene_id
                    WHERE sc.scene_id = s.id
                ),
                '[]'::jsonb
            )
        )
        ORDER BY s.scene_order
    )
    INTO result
    FROM public.story_scenes s
    INNER JOIN public.story_characters c
        ON c.id = s.speaker_id
    WHERE s.story_id = story_id_param;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_story_dialog(story_id_param text) OWNER TO postgres;

--
-- Name: get_table_columns(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_columns(target_table_name text) RETURNS TABLE(schema_name text, table_name text, column_name text, data_type text, udt_name text, is_nullable boolean, column_default text, ordinal_position integer)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    table_schema::text as schema_name,
    table_name::text,
    column_name::text,
    data_type::text,
    udt_name::text,
    case when is_nullable = 'YES' then true else false end as is_nullable,
    column_default::text,
    ordinal_position::int
  from information_schema.columns
  where table_schema = 'public'
    and table_name = target_table_name
  order by ordinal_position;
$$;


ALTER FUNCTION public.get_table_columns(target_table_name text) OWNER TO postgres;

--
-- Name: get_table_columns_diagrams(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_columns_diagrams(target_table_name text) RETURNS TABLE(column_name text, data_type text, is_nullable boolean, column_default text, character_maximum_length integer, is_primary_key boolean, is_foreign_key boolean, foreign_table text, foreign_column text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.column_name::text,
    c.data_type::text,
    c.is_nullable = 'YES' AS is_nullable,
    c.column_default::text,
    c.character_maximum_length::integer,  -- 👈 Ép kiểu sang integer
    EXISTS (
      SELECT 1 FROM information_schema.table_constraints tc
      JOIN information_schema.constraint_column_usage ccu 
        ON tc.constraint_name = ccu.constraint_name
      WHERE tc.constraint_type = 'PRIMARY KEY'
        AND tc.table_name = c.table_name
        AND ccu.column_name = c.column_name
    ) AS is_primary_key,
    EXISTS (
      SELECT 1 FROM information_schema.table_constraints tc
      JOIN information_schema.constraint_column_usage ccu 
        ON tc.constraint_name = ccu.constraint_name
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND tc.table_name = c.table_name
        AND ccu.column_name = c.column_name
    ) AS is_foreign_key,
    (
      SELECT ccu.table_name::text
      FROM information_schema.table_constraints tc
      JOIN information_schema.constraint_column_usage ccu 
        ON tc.constraint_name = ccu.constraint_name
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND tc.table_name = c.table_name
        AND ccu.column_name = c.column_name
      LIMIT 1
    ) AS foreign_table,
    (
      SELECT ccu.column_name::text
      FROM information_schema.table_constraints tc
      JOIN information_schema.constraint_column_usage ccu 
        ON tc.constraint_name = ccu.constraint_name
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND tc.table_name = c.table_name
        AND ccu.column_name = c.column_name
      LIMIT 1
    ) AS foreign_column
  FROM information_schema.columns c
  WHERE c.table_name = target_table_name
    AND c.table_schema = 'public'
  ORDER BY c.ordinal_position;
END;
$$;


ALTER FUNCTION public.get_table_columns_diagrams(target_table_name text) OWNER TO postgres;

--
-- Name: get_table_columns_json(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_columns_json(target_table_name text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_agg(
    json_build_object(
      'column_name', c.column_name,
      'data_type', c.data_type,
      'is_nullable', c.is_nullable = 'YES',
      'column_default', c.column_default,
      'is_primary_key', EXISTS (
        SELECT 1 FROM information_schema.table_constraints tc
        JOIN information_schema.constraint_column_usage ccu 
          ON tc.constraint_name = ccu.constraint_name
        WHERE tc.constraint_type = 'PRIMARY KEY'
          AND tc.table_name = c.table_name
          AND ccu.column_name = c.column_name
      ),
      'is_foreign_key', EXISTS (
        SELECT 1 FROM information_schema.table_constraints tc
        JOIN information_schema.constraint_column_usage ccu 
          ON tc.constraint_name = ccu.constraint_name
        WHERE tc.constraint_type = 'FOREIGN KEY'
          AND tc.table_name = c.table_name
          AND ccu.column_name = c.column_name
      ),
      'foreign_table', (
        SELECT ccu.table_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.constraint_column_usage ccu 
          ON tc.constraint_name = ccu.constraint_name
        WHERE tc.constraint_type = 'FOREIGN KEY'
          AND tc.table_name = c.table_name
          AND ccu.column_name = c.column_name
        LIMIT 1
      ),
      'foreign_column', (
        SELECT ccu.column_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.constraint_column_usage ccu 
          ON tc.constraint_name = ccu.constraint_name
        WHERE tc.constraint_type = 'FOREIGN KEY'
          AND tc.table_name = c.table_name
          AND ccu.column_name = c.column_name
        LIMIT 1
      )
    )
    ORDER BY c.ordinal_position
  ) INTO result
  FROM information_schema.columns c
  WHERE c.table_name = target_table_name
    AND c.table_schema = 'public';

  RETURN COALESCE(result, '[]'::json);
END;
$$;


ALTER FUNCTION public.get_table_columns_json(target_table_name text) OWNER TO postgres;

--
-- Name: get_table_ddl(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_ddl(p_schema text, p_table text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    ddl text := '';
BEGIN
    /* =======================
       CREATE TABLE
    ======================= */
    SELECT INTO ddl
        'CREATE TABLE ' || quote_ident(p_schema) || '.' || quote_ident(p_table) || E' (\n' ||
        string_agg(
            '  ' || quote_ident(a.attname) || ' ' ||
            pg_catalog.format_type(a.atttypid, a.atttypmod) ||
            CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END ||
            COALESCE(' DEFAULT ' || pg_get_expr(ad.adbin, ad.adrelid), ''),
            E',\n'
        ) ||
        E'\n);\n'
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = c.oid
    LEFT JOIN pg_attrdef ad
        ON ad.adrelid = c.oid AND ad.adnum = a.attnum
    WHERE n.nspname = p_schema
      AND c.relname = p_table
      AND a.attnum > 0
      AND NOT a.attisdropped
    GROUP BY c.relname;

    /* =======================
       CONSTRAINTS
    ======================= */
    ddl := ddl || (
        SELECT COALESCE(string_agg(
            'ALTER TABLE ' || quote_ident(p_schema) || '.' || quote_ident(p_table) ||
            ' ADD CONSTRAINT ' || quote_ident(conname) || ' ' ||
            pg_get_constraintdef(oid) || ';',
            E'\n'
        ) || E'\n', '')
        FROM pg_constraint
        WHERE conrelid = format('%I.%I', p_schema, p_table)::regclass
    );

    /* =======================
       INDEXES
    ======================= */
    ddl := ddl || (
        SELECT COALESCE(string_agg(
            pg_get_indexdef(indexrelid) || ';',
            E'\n'
        ), '')
        FROM pg_index
        WHERE indrelid = format('%I.%I', p_schema, p_table)::regclass
          AND NOT indisprimary
    );

    RETURN ddl;
END;
$$;


ALTER FUNCTION public.get_table_ddl(p_schema text, p_table text) OWNER TO postgres;

--
-- Name: get_table_relations_by_table(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_table_relations_by_table(target_table_name text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'constraint_name', constraint_name,
        'source_schema', source_schema,
        'source_table', source_table,
        'source_column', source_column,
        'target_schema', target_schema,
        'target_table', target_table,
        'target_column', target_column,
        'update_rule', update_rule,
        'delete_rule', delete_rule,
        'relation_type', relation_type
      )
      order by relation_type, source_table, source_column
    ),
    '[]'::jsonb
  )
  from (
    select
      con.conname::text as constraint_name,

      src_ns.nspname::text as source_schema,
      src_tbl.relname::text as source_table,
      src_col.attname::text as source_column,

      tgt_ns.nspname::text as target_schema,
      tgt_tbl.relname::text as target_table,
      tgt_col.attname::text as target_column,

      case con.confupdtype
        when 'a' then 'NO ACTION'
        when 'r' then 'RESTRICT'
        when 'c' then 'CASCADE'
        when 'n' then 'SET NULL'
        when 'd' then 'SET DEFAULT'
      end as update_rule,

      case con.confdeltype
        when 'a' then 'NO ACTION'
        when 'r' then 'RESTRICT'
        when 'c' then 'CASCADE'
        when 'n' then 'SET NULL'
        when 'd' then 'SET DEFAULT'
      end as delete_rule,

      case
        when src_tbl.relname = target_table_name then 'outgoing'
        when tgt_tbl.relname = target_table_name then 'incoming'
        else 'unknown'
      end as relation_type

    from pg_constraint con

    join pg_class src_tbl
      on src_tbl.oid = con.conrelid

    join pg_namespace src_ns
      on src_ns.oid = src_tbl.relnamespace

    join pg_class tgt_tbl
      on tgt_tbl.oid = con.confrelid

    join pg_namespace tgt_ns
      on tgt_ns.oid = tgt_tbl.relnamespace

    join lateral unnest(con.conkey) with ordinality as src_cols(attnum, ord)
      on true

    join lateral unnest(con.confkey) with ordinality as tgt_cols(attnum, ord)
      on src_cols.ord = tgt_cols.ord

    join pg_attribute src_col
      on src_col.attrelid = src_tbl.oid
     and src_col.attnum = src_cols.attnum

    join pg_attribute tgt_col
      on tgt_col.attrelid = tgt_tbl.oid
     and tgt_col.attnum = tgt_cols.attnum

    where con.contype = 'f'
      and src_ns.nspname = 'public'
      and tgt_ns.nspname = 'public'
      and (
        src_tbl.relname = target_table_name
        or tgt_tbl.relname = target_table_name
      )
  ) relations;
$$;


ALTER FUNCTION public.get_table_relations_by_table(target_table_name text) OWNER TO postgres;

--
-- Name: get_top_players_by_pure_power(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_top_players_by_pure_power(top_count integer DEFAULT 3) RETURNS TABLE(player_id uuid, username text, player_level integer, alliance text, total_generals bigint, total_power bigint, avg_general_level numeric, highest_star_level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id::UUID as player_id,
        p.username::TEXT,
        p.level::INTEGER as player_level,
        p.alliance::TEXT,
        COUNT(pg.id)::BIGINT as total_generals,
        SUM(pg.current_attack + pg.current_defense + pg.current_health + 
            pg.current_speed + pg.current_intelligence + pg.current_leadership)::BIGINT as total_power,
        ROUND(AVG(pg.level)::NUMERIC, 2) as avg_general_level,
        MAX(pg.star_level)::INTEGER as highest_star_level
    FROM 
        players p
    JOIN 
        player_generals pg ON p.id = pg.player_id
    GROUP BY 
        p.id, p.username, p.level, p.alliance
    ORDER BY 
        total_power DESC
    LIMIT top_count;
END;
$$;


ALTER FUNCTION public.get_top_players_by_pure_power(top_count integer) OWNER TO postgres;

--
-- Name: get_top_players_ranking(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_top_players_ranking(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
WITH ranked AS (
  SELECT
    p.id,
    p.username,
    p.level,
    p.status = 'online' AS online,
    COALESCE(p.country, 'GLOBAL') AS server,
    p.power,
    p.win_rate,
    p.wins,
    p.battles,

    -- win streak đơn giản (placeholder, có thể thay bằng bảng riêng)
    LEAST(p.wins, 10) AS win_streak,

    RANK() OVER (
      ORDER BY p.victory_points DESC, p.power DESC
    ) AS rank,

    -- reward gốc cho thắng
    LEAST(
      50000,
      GREATEST(
        50,
        (
          100
          * (1 + p.level / 50.0)
          * (1 + p.power / 1000000.0)
          * (1 + p.win_rate / 100.0)
        )::int
      )
    ) AS base_reward
  FROM players p
)

SELECT jsonb_agg(
  jsonb_build_object(
    'rank', rank,
    'name', username,
    'level', level,
    'online', online,
    'server', server,
    'power', power,
    'winRate', win_rate,
    'winStreak', win_streak,

    -- reward rules
    'winReward',
      CASE
        WHEN base_reward < 100 THEN 0
        ELSE base_reward
      END,

    'lossReward',
      CASE
        WHEN base_reward < 100 THEN 0
        ELSE FLOOR(base_reward * 0.1)
      END
  )
)
FROM ranked
WHERE rank <= p_limit;
$$;


ALTER FUNCTION public.get_top_players_ranking(p_limit integer) OWNER TO postgres;

--
-- Name: get_trainable_units_by_building(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_trainable_units_by_building(p_player_region_building_id uuid) RETURNS json
    LANGUAGE sql
    AS $$
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'unit_id', u.id,
        'unit_name', u.name,
        'imagePath', u.image_path,
        'required_building_level', ur.required_building_level,
        'training_rate_per_hour', but.training_rate_per_hour,
        'training_capacity', but.training_capacity,
        'efficiency_percent', but.efficiency_percent
      )
      ORDER BY ur.required_building_level, u.name
    ),
    '[]'::json
  )
  FROM player_region_buildings b
  JOIN building_unit_unlock_rules ur
    ON ur.building_type = b.building_type
   AND ur.required_building_level <= b.level
  JOIN building_unit_training but
    ON but.building_type = b.building_type
   AND but.level = b.level
   AND but.unit_type = ur.unit_type
  JOIN units u
    ON u.id = ur.unit_type
  WHERE b.id = p_player_region_building_id;
$$;


ALTER FUNCTION public.get_trainable_units_by_building(p_player_region_building_id uuid) OWNER TO postgres;

--
-- Name: get_training_queue_with_unit_info(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_training_queue_with_unit_info(p_player_region_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result json;
BEGIN

SELECT json_agg(
    json_build_object(
        'queue_id', q.id,
        'quantity', q.quantity,
        'started_at', q.started_at,
        'finish_at', q.finish_at,
        'status', q.status,

        'unit_id', u.id,
        'unit_name', u.name,
        'image_path', u.image_path,
        'unit_type', u.type,
        'rank', u.rank,
        'level', u.level,
        'atk', u.atk,
        'def', u.def,
        'speed', u.speed,
        'max_hp', u.max_hp,
        'range', u.range,
        'description', u.description
    )
    ORDER BY q.started_at
)
INTO v_result
FROM unit_training_queue q
JOIN units u
ON u.id = q.unit_type
WHERE q.player_region_building_id = p_player_region_building_id;

RETURN COALESCE(v_result, '[]'::json);

END;
$$;


ALTER FUNCTION public.get_training_queue_with_unit_info(p_player_region_building_id uuid) OWNER TO postgres;

--
-- Name: get_training_units_by_building_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_training_units_by_building_json(p_building_id uuid) RETURNS json
    LANGUAGE sql
    AS $$
  SELECT COALESCE(
    json_agg(
      json_build_object(
        'training_id', utq.id,
        'unit_id', u.id,
        'unit_name', u.name,
        'imagePath', u.image_path,
        'quantity', utq.quantity,
        'started_at', utq.started_at,
        'finish_at', utq.finish_at,
        'status',
          CASE
            WHEN utq.finish_at <= now() THEN 'completed'
            ELSE 'training'
          END
      )
    ),
    '[]'::json
  )
  FROM unit_training_queue utq
  JOIN units u ON u.id = utq.unit_type
  WHERE utq.player_region_building_id = p_building_id;
$$;


