--
-- Name: get_unit_training_cost(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_training_cost(p_unit_id character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'unit_id', p_unit_id,
        'costs',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'resource_code', utc.resource_code,
                    'resource_amount', utc.resource_amount
                )
                ORDER BY rt.sort_order, utc.resource_code
            ),
            '[]'::jsonb
        )
    )
    INTO v_result
    FROM public.unit_training_cost utc
    JOIN public.resource_types rt
        ON rt.resource_code = utc.resource_code
    WHERE utc.unit_id = p_unit_id;

    RETURN v_result;
END;
$$;


