CREATE FUNCTION public.get_units_with_player_status(p_player_id uuid) RETURNS jsonb
    LANGUAGE sql
    AS $$
    SELECT jsonb_agg(
        jsonb_build_object(
            'unit_id', u.id,
            'unit_name', u.name,
            'player_unit_id', pu.id,
            'quantity', pu.quantity,
            'level', pu.level,
            'current_hp', pu.current_hp,
            'experience', pu.experience,
            'weapon_item_id', pu.weapon_item_id,
            'armor_item_id', pu.armor_item_id,
            'accessory_item_id', pu.accessory_item_id,
            'formation_position', pu.formation_position,
            'is_in_garrison', pu.is_in_garrison,
            'owned', CASE WHEN pu.id IS NULL THEN false ELSE true END
        )
    )
    FROM public.units u
    LEFT JOIN public.player_units pu
        ON u.id = pu.unit_id
        AND pu.player_id = p_player_id;
$$;


