-- Name: get_user_profile_with_permissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_profile_with_permissions(user_uuid uuid) RETURNS TABLE(player_id uuid, user_id uuid, username text, email text, alliance_role text, status text, avatar text, join_date timestamp without time zone, last_login timestamp without time zone, location text, title text, specialization text, ip_address text, roles jsonb, permissions text[], is_admin boolean)
    LANGUAGE sql
    AS $$
    SELECT 
        -- Profile data
        p.id AS player_id,
        p.user_id,
        p.username,
        p.email,
        p.role_in_alliance AS alliance_role,
        p.status,
        p.avatar,
        p.registration_date AS join_date,
        p.last_login,
        p.country AS location,
        p.title,
        p.specialization,
        p.ip_address,
        
        -- Roles as JSON
        COALESCE(
            JSONB_AGG(
                DISTINCT JSONB_BUILD_OBJECT(
                    'role_id', r.id,
                    'role_name', r.name
                )
            ) FILTER (WHERE r.id IS NOT NULL),
            '[]'::JSONB
        ) AS roles,
        
        -- Permissions as array
        COALESCE(ARRAY_AGG(DISTINCT perm.name) FILTER (WHERE perm.name IS NOT NULL), '{}') AS permissions,
        
        -- Admin flag
        EXISTS (
            SELECT 1 FROM public.user_roles ur2 
            JOIN public.roles r2 ON ur2.role_id = r2.id 
            WHERE ur2.user_id = p.user_id AND r2.name = 'admin'
        ) AS is_admin
        
    FROM public.players p
    LEFT JOIN public.user_roles ur ON p.user_id = ur.user_id
    LEFT JOIN public.roles r ON ur.role_id = r.id
    LEFT JOIN public.role_permissions rp ON r.id = rp.role_id
    LEFT JOIN public.permissions perm ON rp.permission_id = perm.id
    WHERE p.user_id = user_uuid
    GROUP BY 
        p.id, p.user_id, p.username, p.email, p.role_in_alliance, p.status, 
        p.avatar, p.registration_date, p.last_login, p.country, p.title, 
        p.specialization, p.ip_address;
$$;


ALTER FUNCTION public.get_user_profile_with_permissions(user_uuid uuid) OWNER TO postgres;

