CREATE FUNCTION public.get_view_ddl(target_view_name text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    'CREATE OR REPLACE VIEW public.'
    || viewname
    || ' AS '
    || definition
  from pg_views
  where schemaname = 'public'
    and viewname = target_view_name
  limit 1;
$$;


