--
-- Name: get_vip_info(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_vip_info(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'vip_level', uv.vip_level,
        'total_recharged', uv.total_recharged,
        'current_tier_min_recharge', COALESCE(vt.min_recharge, 0),
        'next_tier_min_recharge', COALESCE(
            (SELECT min_recharge FROM vip_tiers WHERE level > uv.vip_level ORDER BY level LIMIT 1),
            uv.total_recharged
        ),
        'daily_gold', COALESCE(vt.daily_gold, 0),
        'daily_diamond', COALESCE(vt.daily_diamond, 0),
        'extra_energy', COALESCE(vt.extra_energy, 0),
        'can_claim_today', (uv.last_daily_reward_date IS DISTINCT FROM CURRENT_DATE),
        'description', COALESCE(vt.description, 'Không có cấp')
    ) INTO v_result
    FROM user_vip uv
    LEFT JOIN vip_tiers vt ON uv.vip_level = vt.level
    WHERE uv.user_id = p_user_id;
    
    -- Nếu không tìm thấy user, trả về null
    IF v_result IS NULL THEN
        RETURN jsonb_build_object(
            'error', true,
            'message', 'User not found'
        );
    END IF;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_vip_info(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_weekly_quests_for_player_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_weekly_quests_for_player_json(p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    result jsonb;
BEGIN
    WITH player AS (
        SELECT level
        FROM public.players
        WHERE id = p_player_id
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'quest_id', q.id,
            'quest_name', q.name,
            'description', q.description,
            'type', q.type,
            'category', q.category,
            'difficulty', q.difficulty,
            'min_level', q.min_level,
            'max_level', q.max_level,
            'target', q.completion_limit,
            'progress', COALESCE(pqp.progress, 0),
            'completed', COALESCE(pqp.completed, false),
            'claimed', COALESCE(pqp.claimed, false),
            'completed_at', pqp.completed_at
        )
    ) INTO result
    FROM public.quests q
    CROSS JOIN player
    LEFT JOIN public.player_quest_progress pqp
        ON pqp.quest_id = q.id
        AND pqp.player_id = p_player_id
        -- Lọc progress trong tuần hiện tại (ISO week)
        AND (
            pqp.completed_at IS NULL
            OR date_part('isoyear', pqp.completed_at) = date_part('isoyear', now())
            AND date_part('week', pqp.completed_at) = date_part('week', now())
        )
    WHERE q.category = 'weekly'
      AND q.min_level <= player.level
      AND q.max_level >= player.level
    ;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_weekly_quests_for_player_json(p_player_id uuid) OWNER TO postgres;

--
-- Name: give_gift_to_beauty(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.give_gift_to_beauty(p_player_id uuid, p_beauty_id text, p_gift_id text, p_amount integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_gift_points int;
    v_total_points int;
    v_current_points int;
    v_current_level int;
BEGIN
    -- 1. LOCK row gift
    PERFORM 1
    FROM public.player_gift_beauty
    WHERE player_id = p_player_id
      AND gift_id = p_gift_id
    FOR UPDATE;

    -- 2. Check đủ gift
    IF NOT EXISTS (
        SELECT 1
        FROM public.player_gift_beauty
        WHERE player_id = p_player_id
          AND gift_id = p_gift_id
          AND amount >= p_amount
    ) THEN
        RAISE EXCEPTION 'Not enough gift % for player %', p_gift_id, p_player_id;
    END IF;

    -- 3. Lấy intimacy points của gift
    SELECT intimacy_points
    INTO v_gift_points
    FROM public.gift_beauty
    WHERE id = p_gift_id
      AND is_active = true;

    IF v_gift_points IS NULL THEN
        RAISE EXCEPTION 'Gift % not found or inactive', p_gift_id;
    END IF;

    v_total_points := v_gift_points * p_amount;

    -- 4. Trừ gift
    UPDATE public.player_gift_beauty
    SET 
        amount = amount - p_amount,
        last_used_at = now()
    WHERE player_id = p_player_id
      AND gift_id = p_gift_id;

    -- 5. Tăng thân mật
    PERFORM public.add_intimacy_point_single(
        p_player_id,
        p_beauty_id,
        v_total_points
    );

    -- 6. Lấy trạng thái mới nhất
    SELECT intimacy_points, intimacy_level
    INTO v_current_points, v_current_level
    FROM public.player_beauties
    WHERE player_id = p_player_id
      AND beauty_id = p_beauty_id;

    -- 7. Log gift
    INSERT INTO public.player_beauty_gift_logs (
        player_id,
        beauty_id,
        gift_id,
        amount,
        intimacy_points_gained
    )
    VALUES (
        p_player_id,
        p_beauty_id,
        p_gift_id,
        p_amount,
        v_total_points
    );

    -- 8. Log activity (cho quest / trigger)
    INSERT INTO public.player_activities (
        player_id,
        activity_type
    )
    VALUES (
        p_player_id,
        'beauty.send_gift'
    );

    -- 9. Return JSON
    RETURN json_build_object(
        'success', true,
        'player_id', p_player_id,
        'beauty_id', p_beauty_id,
        'gift_id', p_gift_id,
        'gift_used', p_amount,
        'intimacy_points_gained', v_total_points,
        'current_intimacy_points', v_current_points,
        'current_intimacy_level', v_current_level
    );
END;
$$;


ALTER FUNCTION public.give_gift_to_beauty(p_player_id uuid, p_beauty_id text, p_gift_id text, p_amount integer) OWNER TO postgres;

--
-- Name: grant_rewards_from_json_full(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_rewards_from_json_full(p_player_id uuid, p_rewards jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    r record;
    v_result jsonb := '[]';
    v_temp jsonb;
    v_amount int;
BEGIN
    -- 1️⃣ Tạo bảng tạm từ JSON
    CREATE TEMP TABLE tmp_rewards AS
    SELECT
        reward->>'type' AS reward_type,
        reward->>'id' AS reward_id,
        COALESCE((reward->>'amount')::int, 1) AS amount,
        COALESCE((reward->>'probability')::numeric, 1.0) AS probability
    FROM jsonb_array_elements(p_rewards) AS reward;

    -- 2️⃣ Roll theo probability và duyệt từng reward
    FOR r IN
        SELECT * FROM tmp_rewards WHERE random() <= probability
    LOOP
        v_amount := r.amount;

        CASE r.reward_type
            WHEN 'loot_box' THEN
                PERFORM add_loot_box(p_player_id, r.reward_id, v_amount);

            WHEN 'beauty' THEN
                IF NOT EXISTS (SELECT 1 FROM player_beauties WHERE player_id = p_player_id AND beauty_id = r.reward_id) THEN
                    PERFORM add_beauty(p_player_id, r.reward_id);
                END IF;

            WHEN 'gift' THEN
                v_temp := add_gift_to_player(p_player_id, r.reward_id, v_amount);

            WHEN 'hero' THEN
                IF NOT EXISTS (SELECT 1 FROM player_generals WHERE player_id = p_player_id AND general_id = r.reward_id) THEN
                    PERFORM add_hero(p_player_id, r.reward_id);
                END IF;

            WHEN 'item' THEN
                v_temp := add_item(p_player_id, r.reward_id, v_amount);

            WHEN 'currency' THEN
                PERFORM add_player_currency(p_player_id, r.reward_id, v_amount);
			WHEN 'exp' THEN
    			PERFORM public.plus_exp_and_upgrade_level(p_player_id, v_amount);
			WHEN 'region' THEN
        		PERFORM public.open_new_region(p_player_id, r.reward_id);
            ELSE
                RAISE NOTICE 'Unknown reward type: %', r.reward_type;
        END CASE;

        v_result := v_result || jsonb_build_object(
            'type', r.reward_type,
            'id', r.reward_id,
            'amount', v_amount
        );
    END LOOP;

    -- 3️⃣ Xoá bảng tạm
    DROP TABLE tmp_rewards;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.grant_rewards_from_json_full(p_player_id uuid, p_rewards jsonb) OWNER TO postgres;

--
-- Name: handle_event_action(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_event_action(event_id_param uuid, action_param character varying, player_id_param uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_record RECORD;
    region_record RECORD;
    result_json JSON;
BEGIN
    SELECT * INTO event_record FROM region_events WHERE id = event_id_param;
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Event not found');
    END IF;
    
    -- Kiểm tra player có sở hữu vùng không
    SELECT * INTO region_record 
    FROM player_regions 
    WHERE region_id = event_record.region_id 
      AND player_id = player_id_param 
      AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'You do not own this region');
    END IF;
    
    -- Xử lý action theo loại sự kiện
    CASE event_record.event_type
        WHEN 'raid' THEN
            result_json := handle_raid_action(event_record, action_param, region_record);
        WHEN 'harvest' THEN
            result_json := handle_harvest_action(event_record, action_param, region_record);
        WHEN 'rebellion' THEN
            result_json := handle_rebellion_action(event_record, action_param, region_record);
        ELSE
            result_json := json_build_object('success', false, 'message', 'Action not available for this event');
    END CASE;
    
    -- Nếu action thành công, kết thúc sự kiện sớm
    IF (result_json->>'success')::boolean THEN
        UPDATE region_events SET end_time = NOW() WHERE id = event_id_param;
    END IF;
    
    RETURN result_json;
END;
$$;


ALTER FUNCTION public.handle_event_action(event_id_param uuid, action_param character varying, player_id_param uuid) OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_username text;
    v_player_id uuid;
BEGIN
    -- 1. Tạo username mặc định
    LOOP
        v_username :=
            'user_'
            || floor(random() * 1000000)::bigint
            || '_'
            || extract(epoch FROM clock_timestamp())::bigint
            || '_'
            || floor(random() * 1000)::int;

        EXIT WHEN NOT EXISTS (
            SELECT 1
            FROM public.players
            WHERE username = v_username
        );
    END LOOP;

    -- 2. Tạo player
    INSERT INTO public.players (
        user_id,
        username,
        name,
        email
    )
    VALUES (
        NEW.id,
        v_username,
        v_username,
        NEW.email
    )
    RETURNING id INTO v_player_id;

    -- 3. Tạo wallet mặc định
    INSERT INTO public.player_wallets (
        player_id,
        currency_type,
        amount
    )
    VALUES
        (v_player_id, 'gold', 100),
        (v_player_id, 'diamond', 100);

    -- 4. Tạo VIP mặc định
    INSERT INTO public.user_vip (
        user_id,
        vip_level,
        total_recharged
    )
    VALUES (
        v_player_id,
        0,
        0
    );

    -- 5. Tạo player stats mặc định
    INSERT INTO public.player_stats (
        player_id,
        name
    )
    VALUES (
        v_player_id,
        v_username
    );

    -- 6. Cấp toàn bộ unit không phải boss
    INSERT INTO public.player_units (
        player_id,
        unit_id,
        level,
        current_hp,
        experience,
        attack,
        defense,
        speed,
        max_hp,
        rank,
        is_special,
        join_date,
        is_in_garrison
    )
    SELECT
        v_player_id,
        u.id,
        u.level,
        u.max_hp,
        0,
        u.atk,
        u.def,
        u.speed,
        u.max_hp,
        u.rank,
        u.is_special,
        now(),
        true
    FROM public.units u
    WHERE u.is_boss_unit = false;

-- 7. Cấp tướng khởi đầu Đinh Bộ Lĩnh
INSERT INTO public.player_generals (
    id,
    player_id,
    general_id,
    level,
    experience,
    star_level,
    max_star_level,
    awakening_level,
    bond_level,
    current_attack,
    current_defense,
    current_health,
    current_speed,
    current_intelligence,
    current_leadership,
    favorite,
    obtained_date,
    battle_count,
    win_rate,
    is_representative
)
SELECT
    gen_random_uuid(),
    v_player_id,
    g.id,
    1,
    0,
    1,
    5,
    0,
    0,
    g.base_attack,
    g.base_defense,
    g.base_health,
    g.base_speed,
    g.base_intelligence,
    g.base_leadership,
    false,
    now(),
    0,
    0,
    true
 FROM public.generals g
WHERE g.id = 'dinh_bo_linh';

    -- 8. Gửi thông báo chào mừng
    INSERT INTO public.notifications (
        player_id,
        sender_type,
        title,
        content,
        notification_type,
        priority
    )
    VALUES (
        v_player_id,
        'system',
        'Chào mừng tân thủ!',
        'Chào mừng bạn đến với thế giới trò chơi 12 sứ quân. Chúc bạn chơi game vui vẻ! 😊',
        'system',
        'normal'
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

--
-- Name: handle_player_activity_full(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_player_activity_full() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_today date := CURRENT_DATE;
  current_week int := date_part('week', CURRENT_DATE);
BEGIN
  ------------------------------------------------------------------
  -- 0️⃣ KÍCH HOẠT ACTION ẢO / ACTION B
  ------------------------------------------------------------------
  INSERT INTO public.player_activities (
    player_id,
    activity_type,
    activity_subtype,
    related_id,
    metadata
  )
  SELECT
    NEW.player_id,
    aar.target_activity_type,
    'activated',
    NEW.related_id,
    aar.target_metadata
    || jsonb_build_object(
      'is_virtual', true,
      'activation_rule_id', aar.id::text,
      'activated_by', NEW.activity_type,
      'source_activity_id', NEW.id::text
    )
  FROM public.activity_activation_rules aar
  WHERE
    aar.enabled = true
    AND NEW.metadata @> aar.source_metadata_condition
    AND (
         (
           aar.source_match_type = 'exact'
           AND NEW.activity_type = aar.source_activity_type
         )
      OR (
           aar.source_match_type = 'prefix'
           AND NEW.activity_type LIKE aar.source_activity_type || '.%'
         )
      OR (
           aar.source_match_type = 'any_of'
           AND NEW.activity_type = ANY(aar.source_activity_types)
         )
    )
    AND (
      SELECT count(*)
      FROM public.player_activities pa
      WHERE
        pa.player_id = NEW.player_id
        AND pa.metadata @> aar.source_metadata_condition
        AND (
             (
               aar.source_match_type = 'exact'
               AND pa.activity_type = aar.source_activity_type
             )
          OR (
               aar.source_match_type = 'prefix'
               AND pa.activity_type LIKE aar.source_activity_type || '.%'
             )
          OR (
               aar.source_match_type = 'any_of'
               AND pa.activity_type = ANY(aar.source_activity_types)
             )
        )
    ) >= aar.required_count
    AND (
      aar.repeatable = true
      OR NOT EXISTS (
        SELECT 1
        FROM public.player_activities pa2
        WHERE
          pa2.player_id = NEW.player_id
          AND pa2.activity_type = aar.target_activity_type
          AND pa2.metadata @> aar.target_metadata
          AND pa2.metadata @> jsonb_build_object(
            'activation_rule_id', aar.id::text
          )
      )
    );

  ------------------------------------------------------------------
  -- 1️⃣ TẠO QUEST PROGRESS NẾU CHƯA TỒN TẠI (KẾT HỢP MAIN + DAILY/WEEKLY/EVENT)
  ------------------------------------------------------------------
  INSERT INTO quest_requirement_progress (
    player_id,
    quest_requirement_id,
    progress,
    completed,
    completed_at
  )
  SELECT
    NEW.player_id,
    qr.id,
    0,
    false,
    NULL
  FROM quest_requirements qr
  JOIN quests q
    ON qr.quest_id = q.id
  JOIN players p
    ON p.id = NEW.player_id
  WHERE
    qr.requirement_type = NEW.activity_type
    AND q.status = 'active'
    -- Điều kiện lọc kết hợp:
    AND (
        -- Nhánh 1: Main Quest (chỉ lấy những quest trong View, bỏ qua level)
        (
            q.category = 'main'
            AND EXISTS (
                SELECT 1 FROM vw_player_main_quests vq
                WHERE vq.id = q.id AND vq.player_id = NEW.player_id
            )
        )
        -- Nhánh 2: Các quest khác (Daily, Weekly, Alliance, Event...) vẫn check level bình thường
        OR (
            q.category <> 'main'
            AND p.level BETWEEN q.min_level AND q.max_level
        )
    )
  ON CONFLICT (player_id, quest_requirement_id)
  DO NOTHING;

  ------------------------------------------------------------------
  -- 2️⃣ TĂNG PROGRESS (KẾT HỢP MAIN + DAILY/WEEKLY/EVENT)
  ------------------------------------------------------------------
  UPDATE quest_requirement_progress qrp
  SET progress = qrp.progress + public.get_resource_activity_progress(
    qr.is_accumulate,
    NEW.id,
    NEW.activity_type
  )
  FROM quest_requirements qr
  JOIN quests q
    ON qr.quest_id = q.id
  JOIN players p
    ON p.id = NEW.player_id
  WHERE
    qrp.quest_requirement_id = qr.id
    AND qrp.player_id = NEW.player_id
    AND (
    qr.requirement_type = NEW.activity_type
        OR qr.requirement_type = concat_ws(
            '.',NEW.activity_type,NEW.metadata->>'resource_code'
        )
    )
    AND q.status = 'active'
    AND qrp.completed = false
    -- Điều kiện lọc kết hợp:
    AND (
        -- Nhánh 1: Main Quest (chỉ lấy những quest trong View, bỏ qua level)
        (
            q.category = 'main'
            AND EXISTS (
                SELECT 1 FROM vw_player_main_quests vq
                WHERE vq.id = q.id AND vq.player_id = NEW.player_id
            )
        )
        -- Nhánh 2: Các quest khác (Daily, Weekly, Alliance, Event...) vẫn check level
        OR (
            q.category <> 'main'
            AND p.level BETWEEN q.min_level AND q.max_level
        )
    )
    -- Điều kiện reset theo thời gian cho Daily/Weekly (Main và Event không reset)
    AND (
         (
           q.category = 'daily'
           AND (
             qrp.completed_at IS NULL
             OR qrp.completed_at::date < v_today
           )
         )
      OR (
           q.category = 'weekly'
           AND (
             qrp.completed_at IS NULL
             OR date_part('week', qrp.completed_at) < current_week
           )
         )
      OR q.category = 'event'
      OR (
           q.category = 'main'
           AND EXISTS (
               SELECT 1 FROM vw_player_main_quests vq
               WHERE vq.id = q.id AND vq.player_id = NEW.player_id
           )
      )
      OR q.category = 'alliance' -- Alliance thường không reset theo ngày/tuần
    );

  ------------------------------------------------------------------
  -- 3️⃣ ĐÁNH DẤU COMPLETED (ÁP DỤNG CHO TẤT CẢ QUEST)
  ------------------------------------------------------------------
  UPDATE quest_requirement_progress qrp
  SET
    completed = true,
    completed_at = now()
  FROM quest_requirements qr
  JOIN quests q
    ON qr.quest_id = q.id
  JOIN players p
    ON p.id = NEW.player_id
  WHERE
    qrp.quest_requirement_id = qr.id
    AND qrp.player_id = NEW.player_id
    AND qr.requirement_type = NEW.activity_type
    AND q.status = 'active'
    AND qrp.completed = false
    AND qrp.progress >= qr.target
    -- Cũng áp dụng điều kiện lọc kết hợp như Bước 1 & 2
    AND (
        (
            q.category = 'main'
            AND EXISTS (
                SELECT 1 FROM vw_player_main_quests vq
                WHERE vq.id = q.id AND vq.player_id = NEW.player_id
            )
        )
        OR (
            q.category <> 'main'
            AND p.level BETWEEN q.min_level AND q.max_level
        )
    );

  ------------------------------------------------------------------
  -- 4️⃣ TẠO ACHIEVEMENT REQUIREMENT PROGRESS NẾU CHƯA CÓ
  ------------------------------------------------------------------
  INSERT INTO public.player_achievement_tier_progress (
    player_id,
    requirement_id,
    progress,
    completed,
    reward_claimed,
    updated_at
  )
  SELECT
    NEW.player_id,
    ar.id,
    0,
    false,
    false,
    now()
  FROM public.achievement_requirements ar
  WHERE ar.requirement_type = NEW.activity_type
  ON CONFLICT (player_id, requirement_id)
  DO NOTHING;

  ------------------------------------------------------------------
  -- 5️⃣ TĂNG PROGRESS ACHIEVEMENT
  ------------------------------------------------------------------
  UPDATE public.player_achievement_tier_progress patp
  SET
    progress = patp.progress + 1,
    updated_at = now()
  FROM public.achievement_requirements ar
  WHERE
    patp.player_id = NEW.player_id
    AND patp.requirement_id = ar.id
    AND ar.requirement_type = NEW.activity_type
    AND patp.completed = false;

  ------------------------------------------------------------------
  -- 6️⃣ ĐÁNH DẤU REQUIREMENT COMPLETED
  ------------------------------------------------------------------
  UPDATE public.player_achievement_tier_progress patp
  SET
    completed = true,
    updated_at = now()
  FROM public.achievement_requirements ar
  WHERE
    patp.player_id = NEW.player_id
    AND patp.requirement_id = ar.id
    AND ar.requirement_type = NEW.activity_type
    AND patp.completed = false
    AND patp.progress >= ar.target;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_player_activity_full() OWNER TO postgres;

--
-- Name: handle_raid_action(record, character varying, record); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_raid_action(event_record record, action_param character varying, region_record record) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    troops_record RECORD;
BEGIN
    SELECT * INTO troops_record FROM region_troops WHERE region_id = event_record.region_id;
    
    CASE action_param
        WHEN 'defend' THEN
            IF troops_record.infantry < 100 THEN
                RETURN json_build_object('success', false, 'message', 'Not enough infantry to defend');
            END IF;
            
            -- Trừ quân
            UPDATE region_troops SET infantry = infantry - 50 WHERE region_id = event_record.region_id;
            
            RETURN json_build_object(
                'success', true,
                'message', 'Successfully defended against raid',
                'effects', json_build_object(
                    'troops_lost', 50,
                    'resources_saved', 'significant'
                )
            );
            
        WHEN 'negotiate' THEN
            IF region_record.gold < 200 THEN
                RETURN json_build_object('success', false, 'message', 'Not enough gold to negotiate');
            END IF;
            
            -- Trừ vàng
            UPDATE player_regions SET gold = gold - 200 WHERE region_id = event_record.region_id;
            
            RETURN json_build_object(
                'success', true,
                'message', 'Negotiated peace with raiders',
                'effects', json_build_object(
                    'gold_paid', 200,
                    'damage_prevented', 'complete'
                )
            );
            
        ELSE
            RETURN json_build_object('success', false, 'message', 'Invalid action');
    END CASE;
END;
$$;


ALTER FUNCTION public.handle_raid_action(event_record record, action_param character varying, region_record record) OWNER TO postgres;

