--
-- Name: increment_win_streak(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_win_streak(p_player_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.player_stats
    SET
        current_streak = current_streak + 1,
        max_streak = GREATEST(
            max_streak,
            current_streak + 1
        ),
        updated_at = NOW()
    WHERE player_id = p_player_id;
END;
$$;


