--
-- Name: insert_alliance_chat(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_alliance_chat(p_sender_id uuid, p_content text, p_alliance_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    -- Kiểm tra player có đang ở trong alliance
    SELECT COUNT(*) INTO v_count
    FROM public.players
    WHERE id = p_sender_id
      AND alliance = p_alliance_id::text;  -- ép kiểu UUID -> text

    IF v_count = 0 THEN
        RAISE EXCEPTION 'Player % is not in alliance %', p_sender_id, p_alliance_id;
    END IF;

    -- Insert tin nhắn
    INSERT INTO public.chat_messages(
        sender_id,
        message_type,
        content,
        channel_type,
        alliance_id,
        group_id
    ) VALUES (
        p_sender_id,
        'text',
        p_content,
        'alliance',
        p_alliance_id,
        NULL
    );
END;
$$;


ALTER FUNCTION public.insert_alliance_chat(p_sender_id uuid, p_content text, p_alliance_id uuid) OWNER TO postgres;

--
-- Name: insert_alliance_chat_safe(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_alliance_chat_safe(p_sender_id uuid, p_content text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_alliance_id uuid;
    v_sender_name text;
    v_member_role text;
BEGIN
    -- Kiểm tra player có tồn tại và lấy thông tin
    SELECT 
        p.username 
    INTO 
        v_sender_name
    FROM public.players p
    WHERE p.id = p_sender_id;

    IF v_sender_name IS NULL THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', 'Người chơi không tồn tại'
        );
    END IF;

    -- Kiểm tra player có trong alliance_members không
    SELECT 
        am.alliance_id, 
        am.role 
    INTO 
        v_alliance_id, 
        v_member_role
    FROM public.alliance_members am
    WHERE am.player_id = p_sender_id;

    -- Nếu không phải thành viên alliance nào
    IF v_alliance_id IS NULL THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', 'Bạn chưa gia nhập liên minh nào'
        );
    END IF;

    -- Kiểm tra alliance có tồn tại không
    IF NOT EXISTS (
        SELECT 1 FROM public.alliances a WHERE a.id = v_alliance_id
    ) THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', 'Liên minh không tồn tại hoặc đã bị giải tán'
        );
    END IF;

    -- Thêm tin nhắn vào alliance chat
    INSERT INTO public.chat_messages(
        sender_id,
        sender_name,
        message_type,
        content,
        channel_type,
        alliance_id,
        group_id,
        created_date,
        updated_date
    )
    VALUES (
        p_sender_id,
        v_sender_name,
        'text',
        p_content,
        'alliance',
        v_alliance_id,
        NULL,
        NOW(),
        NOW()
    );

    RETURN jsonb_build_object(
        'status', 'success',
        'message', 'Gửi tin nhắn thành công',
        'sender_name', v_sender_name,
        'alliance_id', v_alliance_id,
        'member_role', v_member_role
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', 'Lỗi khi gửi tin nhắn: ' || SQLERRM,
            'error_detail', SQLSTATE
        );
END;
$$;


ALTER FUNCTION public.insert_alliance_chat_safe(p_sender_id uuid, p_content text) OWNER TO postgres;

--
-- Name: insert_battle_result(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_battle_result(p_player_id uuid, p_battle_id uuid, p_result text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activity_type text;
    v_title text;
    v_color text;
BEGIN
    -- Map kết quả
    IF p_result = 'win' THEN
        v_activity_type := 'battle.win';
        v_title := 'Bạn đã thắng trận!';
        v_color := '#28a745';
    ELSIF p_result = 'loss' THEN
        v_activity_type := 'battle.loss';
        v_title := 'Bạn đã thua trận';
        v_color := '#dc3545';
    ELSIF p_result = 'draw' THEN
        v_activity_type := 'battle.draw';
        v_title := 'Trận chiến kết thúc hòa';
        v_color := '#6c757d';
    ELSE
        RAISE EXCEPTION 'Kết quả không hợp lệ: %, chỉ chấp nhận win/loss/draw', p_result;
    END IF;

    -- 1. Activity (logic game)
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        related_id,
        created_at
    )
    VALUES (
        p_player_id,
        v_activity_type,
        p_battle_id::text,
        now()
    );

    -- 2. Combat log (UI notify)
    INSERT INTO public.combat_logs (
        player_id,
        icon_name,
        title,
        color_code,
        log_type,
        battle_id,
        event_timestamp,
        is_read
    )
    VALUES (
        p_player_id,
        'battle_result',
        v_title,
        v_color,
        'system',
        p_battle_id,
        now(),
        false
    );
END;
$$;


ALTER FUNCTION public.insert_battle_result(p_player_id uuid, p_battle_id uuid, p_result text) OWNER TO postgres;

