    INSERT INTO public.chat_messages(
        sender_id,
        message_type,
        content,
        channel_type,
        alliance_id,
        group_id
    ) VALUES (
        p_sender_id,
        'text',
        p_content,
        'group',
        NULL,
        p_group_id
    );

    RETURN 'Insert successful';
END;
$$;


