--
-- Name: is_quest_completed(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_quest_completed(p_quest_id text, p_player_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT
        CASE
            WHEN COUNT(qr.id) = 0
                THEN false

            WHEN COUNT(qr.id) =
                 COUNT(
                     CASE
                         WHEN qrp.completed = true
                         THEN 1
                     END
                 )
                THEN true

            ELSE false
        END
    FROM public.quest_requirements qr
    LEFT JOIN public.quest_requirement_progress qrp
        ON qrp.quest_requirement_id = qr.id
       AND qrp.player_id = p_player_id
    WHERE qr.quest_id = p_quest_id;
$$;


ALTER FUNCTION public.is_quest_completed(p_quest_id text, p_player_id uuid) OWNER TO postgres;

--
-- Name: join_alliance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_alliance(p_player_id uuid, p_alliance_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count int;
    v_max int;
BEGIN
    -- check full
    SELECT members, max_members
    INTO v_count, v_max
    FROM alliances
    WHERE id = p_alliance_id;

    IF v_count >= v_max THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Alliance is full'
        );
    END IF;

    -- add member
    INSERT INTO alliance_members (alliance_id, player_id)
    VALUES (p_alliance_id, p_player_id);

    -- update count
    UPDATE alliances
    SET members = members + 1
    WHERE id = p_alliance_id;

    RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION public.join_alliance(p_player_id uuid, p_alliance_id uuid) OWNER TO postgres;

