-- Name: join_group(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_group(p_group_id uuid, p_player_id uuid, p_nickname text DEFAULT NULL::text) RETURNS public.chat_group_members
    LANGUAGE plpgsql
    AS $$
DECLARE
    member_record public.chat_group_members;
BEGIN
    INSERT INTO public.chat_group_members (
        group_id,
        player_id,
        role,
        nickname
    )
    VALUES (
        p_group_id,
        p_player_id,
        'member',
        p_nickname
    )
    ON CONFLICT (group_id, player_id)
    DO UPDATE SET
        nickname = COALESCE(EXCLUDED.nickname, chat_group_members.nickname)
    RETURNING * INTO member_record;

    RETURN member_record;
END;
$$;


