--
-- Name: limit_player_activities_batch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.limit_player_activities_batch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    record_count INTEGER;
    excess_count INTEGER;
BEGIN
    -- Đếm số bản ghi hiện có
    SELECT COUNT(*) INTO record_count FROM player_activities;
    
    -- Tính số bản ghi cần xóa
    excess_count := record_count - 4; -- Giữ lại 4 bản ghi + bản ghi mới = 5
    
    IF excess_count > 0 THEN
        -- Xóa các bản ghi cũ nhất
        DELETE FROM player_activities 
        WHERE id IN (
            SELECT id 
            FROM player_activities 
            ORDER BY created_at ASC 
            LIMIT excess_count
        );
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.limit_player_activities_batch() OWNER TO postgres;

--
-- Name: mark_chat_alliance_as_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_chat_alliance_as_read(p_player_id uuid, p_alliance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_last_message_id uuid;
    v_last_read_at timestamptz;
BEGIN
    -- Kiểm tra player có thuộc alliance hay không
    IF NOT EXISTS (
        SELECT 1
        FROM public.alliance_members am
        WHERE am.player_id = p_player_id
          AND am.alliance_id = p_alliance_id
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'alliance_id', p_alliance_id,
            'last_read_at', NULL,
            'last_message_id', NULL
        );
    END IF;

    -- Lấy tin nhắn alliance cuối cùng
    SELECT cm.id
    INTO v_last_message_id
    FROM public.chat_messages cm
    WHERE cm.alliance_id = p_alliance_id
      AND cm.channel_type = 'alliance'
      AND cm.is_deleted = false
    ORDER BY cm.created_date DESC
    LIMIT 1;

    -- Chưa có tin nhắn
    IF v_last_message_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'alliance_id', p_alliance_id,
            'last_read_at', NULL,
            'last_message_id', NULL
        );
    END IF;

    -- Insert nếu chưa có, update nếu đã có
    INSERT INTO public.player_chat_read_states (
        player_id,
        channel_type,
        channel_key,
        last_read_at
    )
    VALUES (
        p_player_id,
        'alliance',
        p_alliance_id::text,
        now()
    )
    ON CONFLICT (player_id, channel_type, channel_key)
    DO UPDATE SET
        last_read_at = now()
    RETURNING last_read_at
    INTO v_last_read_at;

    RETURN jsonb_build_object(
        'success', true,
        'alliance_id', p_alliance_id,
        'last_read_at', v_last_read_at,
        'last_message_id', v_last_message_id
    );
END;
$$;


ALTER FUNCTION public.mark_chat_alliance_as_read(p_player_id uuid, p_alliance_id uuid) OWNER TO postgres;

--
-- Name: mark_chat_group_as_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_chat_group_as_read(p_player_id uuid, p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_last_message_id uuid;
    v_last_read_at timestamptz;
BEGIN
    -- Kiểm tra player có phải member của group không
    IF NOT EXISTS (
        SELECT 1
        FROM public.chat_group_members gm
        WHERE gm.group_id = p_group_id
          AND gm.player_id = p_player_id
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'not_group_member'
        );
    END IF;

    -- Lấy tin nhắn cuối cùng của group
    SELECT cm.id
    INTO v_last_message_id
    FROM public.chat_messages cm
    WHERE cm.group_id = p_group_id
      AND cm.channel_type = 'group'
      AND cm.is_deleted = false
    ORDER BY cm.created_date DESC
    LIMIT 1;

    -- Group chưa có tin nhắn
    IF v_last_message_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'group_id', p_group_id,
            'last_message_id', NULL,
            'last_read_at', NULL
        );
    END IF;

    -- INSERT nếu chưa có read-state
    -- UPDATE nếu đã có
    INSERT INTO public.player_chat_read_states (
        player_id,
        channel_type,
        channel_key,
        last_read_at
    )
    VALUES (
        p_player_id,
        'group',
        p_group_id::text,
        now()
    )
    ON CONFLICT (player_id, channel_type, channel_key)
    DO UPDATE SET
        last_read_at = now()
    RETURNING last_read_at
    INTO v_last_read_at;

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'last_message_id', v_last_message_id,
        'last_read_at', v_last_read_at
    );
END;
$$;


ALTER FUNCTION public.mark_chat_group_as_read(p_player_id uuid, p_group_id uuid) OWNER TO postgres;

