--
-- Name: moon_gazing_with_beauty(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.moon_gazing_with_beauty(p_player_id uuid, p_beauty_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_current_time time := (
        CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )::time;

    v_current_points int;
    v_current_level int;
    v_intimacy_gain int := 10;
BEGIN
    -- 1. Kiểm tra giờ Việt Nam: 23:00 → trước 23:05
    IF NOT (
        v_current_time >= time '23:00:00'
        AND v_current_time < time '23:05:00'
    ) THEN
        RAISE EXCEPTION 'Chỉ có thể ngắm trăng từ 23:00 đến 23:05';
    END IF;

    -- 2. Tăng thân mật
    PERFORM public.add_intimacy_point_single(
        p_player_id,
        p_beauty_id,
        v_intimacy_gain
    );

    -- 3. Ghi hoạt động
    INSERT INTO public.player_activities (
        player_id,
        activity_type
    )
    VALUES (
        p_player_id,
        'beauty.moon'
    );

    -- 4. Lấy trạng thái mới
    SELECT intimacy_points, intimacy_level
    INTO v_current_points, v_current_level
    FROM public.player_beauties
    WHERE player_id = p_player_id
      AND beauty_id = p_beauty_id;

    -- 5. Return JSON
    RETURN json_build_object(
        'action', 'moon_gazing',
        'success', true,
        'intimacy_points_gained', v_intimacy_gain,
        'current_intimacy_points', v_current_points,
        'current_intimacy_level', v_current_level,
        'allowed_time', '23:00 - 23:05 (GMT+7)'
    );
END;
$$;


ALTER FUNCTION public.moon_gazing_with_beauty(p_player_id uuid, p_beauty_id text) OWNER TO postgres;

--
-- Name: move_troops_to_combat(uuid, character varying, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_troops_to_combat(p_battle_id uuid, p_region_id character varying, p_player_id uuid, p_battle_role character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_general_id text;
BEGIN
    -- Lấy tướng đảm nhiệm vai trò tương ứng trong khu vực
    SELECT rg.general_id
    INTO v_general_id
    FROM region_generals rg
    WHERE rg.region_id = p_region_id
      AND rg.player_id = p_player_id
      AND rg.battle_role = CASE p_battle_role
            WHEN 'attacker' THEN 'offense'
            WHEN 'defender' THEN 'defense'
        END;

    IF v_general_id IS NULL THEN
        RAISE EXCEPTION
            'No general assigned for battle role % in region %',
            p_battle_role,
            p_region_id;
    END IF;

    -- Đưa quân đủ điều kiện vào combat
    INSERT INTO combat_troops (
        battle_id,
        region_id,
        player_id,
        unit_type,
        original_quantity,
        current_quantity,
        lost_quantity,
        survived_quantity,
        battle_role,
        status,
        joined_at
    )
    SELECT
        p_battle_id,
        rt.region_id,
        rt.player_id,
        rt.unit_type,

        LEAST(
            rt.quantity,
            gum.base_capacity
                + (pg.level - 1) * gum.capacity_per_level
                + (pg.star_level - 1) * gum.capacity_per_star
        ) AS deploy_quantity,

        LEAST(
            rt.quantity,
            gum.base_capacity
                + (pg.level - 1) * gum.capacity_per_level
                + (pg.star_level - 1) * gum.capacity_per_star
        ) AS deploy_quantity,

        0,
        0,
        p_battle_role,
        'fighting',
        NOW()
    FROM region_troops rt
    JOIN player_generals pg
      ON pg.player_id = rt.player_id
     AND pg.general_id = v_general_id
    JOIN general_unit_masteries gum
      ON gum.general_id = pg.general_id
     AND gum.unit_id = rt.unit_type
    WHERE rt.region_id = p_region_id
      AND rt.player_id = p_player_id
      AND rt.quantity > 0;

    -- Trừ đúng số quân đã đưa vào combat
    UPDATE region_troops rt
    SET quantity = rt.quantity - ct.original_quantity
    FROM combat_troops ct
    WHERE ct.battle_id = p_battle_id
      AND ct.region_id = rt.region_id
      AND ct.player_id = rt.player_id
      AND ct.unit_type = rt.unit_type;

    IF NOT FOUND THEN
        RAISE NOTICE
            'No troops moved for player % in region %',
            p_player_id,
            p_region_id;
    END IF;
END;
$$;


ALTER FUNCTION public.move_troops_to_combat(p_battle_id uuid, p_region_id character varying, p_player_id uuid, p_battle_role character varying) OWNER TO postgres;

--
-- Name: notify_enter_battle(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_enter_battle(p_player_id uuid, p_battle_id uuid, p_opponent_id uuid, p_content text DEFAULT 'Chuẩn bị chiến đấu'::text, p_challenge_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO game_notifications (
    player_id,
    type,
    title,
    content,
    payload
  )
  VALUES (
    p_player_id,
    'challenge_enter_battle',
    'Vào chiến trường',
    p_content,
    jsonb_build_object(
      'battle_id', p_battle_id,
      'challenge_id', COALESCE(p_challenge_id::text, 'không có'),
      'opponent_id', p_opponent_id
    )
  );
END;
$$;


ALTER FUNCTION public.notify_enter_battle(p_player_id uuid, p_battle_id uuid, p_opponent_id uuid, p_content text, p_challenge_id uuid) OWNER TO postgres;

--
-- Name: open_loot_box(uuid, text, integer, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_loot_box(p_player_id uuid, p_loot_box_id text, p_trigger_count integer DEFAULT NULL::integer, p_is_first_time boolean DEFAULT NULL::boolean, p_pity_active boolean DEFAULT NULL::boolean, p_streak_active boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_multiplier numeric := 1.0;

    -- Rewards
    v_rewards jsonb := '[]'::jsonb;
    v_pools_selected jsonb := '[]'::jsonb;
    v_guaranteed jsonb := '[]'::jsonb;

    -- First-time
    v_first_time_result jsonb := '{}'::jsonb;
    v_first_time_rewards jsonb := '[]'::jsonb;
    v_first_time_amount integer;

    -- Pity
    v_pity_result jsonb := '{}'::jsonb;
    v_pity_rewards jsonb := '[]'::jsonb;
    v_pity_amount integer;

    -- Reward tables
    v_reward_tables jsonb := '[]'::jsonb;

    -- Loop
    t_table jsonb;
    t_pool RECORD;
    t_item RECORD;
    t_g RECORD;
    t_first_time_item jsonb;
    t_pity_item jsonb;

    -- Pool
    v_pool_count integer;

    -- Open count
    v_open_count integer;

    -- Guaranteed
    v_guaranteed_active boolean := false;

BEGIN

    -- =========================================================
    -- 0. Open count
    -- =========================================================

    v_open_count := COALESCE(
        p_trigger_count,
        public.get_loot_box_open_count(
            p_player_id,
            p_loot_box_id
        )
    );


    -- =========================================================
    -- 1. Check limit
    -- =========================================================

    PERFORM public.check_loot_box_limits(
        p_player_id,
        p_loot_box_id
    );


    -- =========================================================
    -- 2. Check requirements
    -- =========================================================

    PERFORM public.check_loot_box_requirements(
        p_player_id,
        p_loot_box_id
    );


    -- =========================================================
    -- 3. First-time bonus
    -- =========================================================

    IF p_is_first_time IS NULL THEN

        v_first_time_result := public.check_first_time_bonus(
            p_player_id,
            p_loot_box_id
        );

        p_is_first_time := COALESCE(
            (v_first_time_result ->> 'is_first_time')::boolean,
            false
        );

    ELSIF p_is_first_time THEN

        v_first_time_result := public.check_first_time_bonus(
            p_player_id,
            p_loot_box_id
        );

    END IF;


    IF p_is_first_time THEN
        v_first_time_rewards := COALESCE(
            v_first_time_result -> 'reward_items',
            '[]'::jsonb
        );
    END IF;


    -- =========================================================
    -- 4. Pity
    -- =========================================================

    IF p_pity_active IS NULL OR p_pity_active THEN

        v_pity_result := public.check_pity_system(
            p_player_id,
            p_loot_box_id
        );

        IF p_pity_active IS NULL THEN
            p_pity_active := COALESCE(
                (v_pity_result ->> 'active')::boolean,
                false
            );
        END IF;

    END IF;


    IF p_pity_active THEN
        v_pity_rewards := COALESCE(
            v_pity_result -> 'reward_items',
            '[]'::jsonb
        );
    END IF;


    -- =========================================================
    -- 5. Streak
    -- =========================================================

    p_streak_active := COALESCE(
        p_streak_active,
        false
    );


    -- =========================================================
    -- 6. Multiplier
    -- =========================================================

    IF p_is_first_time THEN
        v_multiplier := v_multiplier * 2.0;
    END IF;

    IF p_pity_active THEN
        v_multiplier := v_multiplier * 1.5;
    END IF;

    IF p_streak_active THEN
        v_multiplier := v_multiplier * 1.2;
    END IF;


    -- =========================================================
    -- 7. Select reward tables
    -- =========================================================

    v_reward_tables := jsonb_build_array();

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'table_id', out_reward_table_id,
                'table_name', out_reward_table_name,
                'distribution_type', out_distribution_type,
                'anti_duplicate', out_anti_duplicate,
                'duplicate_protection', out_duplicate_protection
            )
        ),
        '[]'::jsonb
    )
    INTO v_reward_tables
    FROM public.select_reward_tables(
        p_loot_box_id
    );


    -- =========================================================
    -- 8. Reward tables loop
    -- =========================================================

    FOR t_table IN
        SELECT value
        FROM jsonb_array_elements(v_reward_tables)
    LOOP

        SELECT 1 + floor(random() * 3)::int
        INTO v_pool_count;


        -- =====================================================
        -- 9. Reward pools
        -- =====================================================

        FOR t_pool IN
            SELECT *
            FROM public.select_reward_pools(
                t_table ->> 'table_id'
            )
            ORDER BY random()
            LIMIT v_pool_count
        LOOP

            v_pools_selected := v_pools_selected ||
                jsonb_build_array(
                    jsonb_build_object(
                        'table_id', t_table ->> 'table_id',
                        'table_name', t_table ->> 'table_name',
                        'pool_id', t_pool.pool_id,
                        'pool_name', t_pool.pool_name,
                        'min_drop', t_pool.min_drop_val,
                        'max_drop', t_pool.max_drop_val
                    )
                );


            -- =================================================
            -- 10. Reward items
            -- =================================================

            FOR t_item IN
                SELECT *
                FROM public.select_reward_items(
                    p_player_id,
                    t_pool.pool_id,
                    v_multiplier
                )
            LOOP

                v_rewards := v_rewards ||
                    jsonb_build_array(
                        jsonb_build_object(
                            'item_id', t_item.item_id,
                            'reward_type', t_item.reward_type,
                            'amount', t_item.amount,
                            'rarity', t_item.rarity,
                            'bound_type', t_item.bound_type,
                            'table_id', t_table ->> 'table_id',
                            'pool_id', t_pool.pool_id,
                            'guaranteed', false,
                            'pity', false,
                            'is_first_time', false
                        )
                    );

            END LOOP;

        END LOOP;

    END LOOP;


    -- =========================================================
    -- 11. First-time rewards
    -- =========================================================

    IF p_is_first_time THEN

        FOR t_first_time_item IN
            SELECT value
            FROM jsonb_array_elements(v_first_time_rewards)
        LOOP

            v_first_time_amount := floor(
                random() * (
                    (t_first_time_item ->> 'amount_max')::integer
                    -
                    (t_first_time_item ->> 'amount_min')::integer
                    + 1
                )
            )::integer
            +
            (t_first_time_item ->> 'amount_min')::integer;


            v_rewards := v_rewards ||
                jsonb_build_array(
                    jsonb_build_object(
                        'item_id',
                        t_first_time_item ->> 'item_id',

                        'reward_item_id',
                        t_first_time_item ->> 'reward_item_id',

                        'reward_type',
                        t_first_time_item ->> 'reward_type',

                        'amount',
                        v_first_time_amount,

                        'rarity',
                        t_first_time_item ->> 'rarity',

                        'bound_type',
                        t_first_time_item ->> 'bound_type',

                        'table_id',
                        null,

                        'pool_id',
                        null,

                        'guaranteed',
                        false,

                        'pity',
                        false,

                        'is_first_time',
                        true
                    )
                );

        END LOOP;

    END IF;


    -- =========================================================
    -- 12. Pity rewards
    -- =========================================================

    IF p_pity_active THEN

        FOR t_pity_item IN
            SELECT value
            FROM jsonb_array_elements(v_pity_rewards)
        LOOP

            v_pity_amount := floor(
                random() * (
                    (t_pity_item ->> 'amount_max')::integer
                    -
                    (t_pity_item ->> 'amount_min')::integer
                    + 1
                )
            )::integer
            +
            (t_pity_item ->> 'amount_min')::integer;


            v_rewards := v_rewards ||
                jsonb_build_array(
                    jsonb_build_object(
                        'item_id',
                        t_pity_item ->> 'item_id',

                        'reward_item_id',
                        t_pity_item ->> 'reward_item_id',

                        'reward_type',
                        t_pity_item ->> 'reward_type',

                        'amount',
                        v_pity_amount,

                        'rarity',
                        t_pity_item ->> 'rarity',

                        'bound_type',
                        t_pity_item ->> 'bound_type',

                        'table_id',
                        null,

                        'pool_id',
                        null,

                        'guaranteed',
                        false,

                        'pity',
                        true,

                        'is_first_time',
                        false
                    )
                );

        END LOOP;

    END IF;


    -- =========================================================
    -- 13. Guaranteed active
    -- =========================================================

    SELECT EXISTS (
        SELECT 1
        FROM public.loot_box_guaranteed_drops gd
        WHERE gd.loot_box_id = p_loot_box_id
          AND gd.open_count <= v_open_count
    )
    INTO v_guaranteed_active;


    -- =========================================================
    -- 14. Guaranteed rewards
    -- =========================================================

    FOR t_g IN
        SELECT
            rgr.reward_item_id,
            gd.loot_box_id,
            ri.item_id,
            ri.reward_type,
            ri.amount_min,
            ri.amount_max,
            ri.rarity,
            ri.bound_type,
            ri.currency_type
        FROM public.loot_box_guaranteed_drops gd
        JOIN public.loot_box_guaranteed_rewards rgr
            ON gd.id = rgr.guaranteed_drop_id
        JOIN public.loot_box_reward_items ri
            ON ri.id = rgr.reward_item_id
        WHERE gd.loot_box_id = p_loot_box_id
          AND gd.open_count <= v_open_count
    LOOP

        v_rewards := v_rewards ||
            jsonb_build_array(
                jsonb_build_object(
                    'item_id', t_g.item_id,
                    'reward_item_id', t_g.reward_item_id,
                    'reward_type', t_g.reward_type,
                    'amount', t_g.amount_min,
                    'rarity', t_g.rarity,
                    'bound_type', t_g.bound_type,
                    'table_id', null,
                    'pool_id', null,
                    'guaranteed', true,
                    'pity', false,
                    'is_first_time', false
                )
            );


        v_guaranteed := v_guaranteed ||
            jsonb_build_array(
                t_g.reward_item_id
            );

    END LOOP;


    -- =========================================================
    -- 15. Return
    -- =========================================================

    RETURN jsonb_build_object(
        'success', true,
        'loot_box_id', p_loot_box_id,
        'trigger_count', v_open_count,

        'first_time_bonus', p_is_first_time,
        'first_time_result', v_first_time_result,

        'pity_active', p_pity_active,
        'pity_result', v_pity_result,

        'streak_active', p_streak_active,
        'multiplier', v_multiplier,

        'is_guaranteed_active', v_guaranteed_active,

        'pools_selected', v_pools_selected,
        'guaranteed_rewards', v_guaranteed,

        'rewards', v_rewards
    );

END;
$$;


ALTER FUNCTION public.open_loot_box(p_player_id uuid, p_loot_box_id text, p_trigger_count integer, p_is_first_time boolean, p_pity_active boolean, p_streak_active boolean) OWNER TO postgres;

--
-- Name: open_loot_box_transaction(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_loot_box_transaction(p_player_id uuid, p_loot_box_id text, p_amount integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_open_result jsonb;
    v_grant_result jsonb;
    v_converted_rewards jsonb;
    v_all_rewards jsonb := '[]'::jsonb;
    v_reward_details jsonb;

    v_has_good_reward boolean;
    v_highest_rarity text;

    v_open_number bigint;

    -- Current guaranteed counter before this opening
    v_guaranteed_count integer;

    -- Counter used by open_loot_box for this opening
    v_current_guaranteed_count integer;

    i int;
BEGIN

    IF p_amount < 1 THEN
        RAISE EXCEPTION 'p_amount must be greater than 0';
    END IF;

    FOR i IN 1..p_amount LOOP

        -- =====================================================
        -- 1. Consume loot box
        -- =====================================================

        PERFORM subtract_loot_box(
            p_player_id,
            p_loot_box_id,
            1
        );


        -- =====================================================
        -- 2. Get current guaranteed counter
        -- =====================================================

        SELECT COALESCE(guaranteed_count, 0)
        INTO v_guaranteed_count
        FROM public.player_loot_boxes
        WHERE player_id = p_player_id
          AND loot_box_id = p_loot_box_id
        FOR UPDATE;

        /*
         * This is the counter for the CURRENT opening.
         *
         * Example:
         *
         * guaranteed_count = 9
         * current opening  = 10
         *
         * Therefore open_loot_box() must receive 10.
         */
        v_current_guaranteed_count :=
            v_guaranteed_count + 1;


        -- =====================================================
        -- 3. Open loot box
        -- =====================================================

        v_open_result := open_loot_box(
            p_player_id,
            p_loot_box_id,
            v_current_guaranteed_count
        );


        -- =====================================================
        -- 4. Check whether reward is rare+
        -- =====================================================

        v_has_good_reward := EXISTS (
            SELECT 1
            FROM jsonb_array_elements(
                COALESCE(
                    v_open_result->'rewards',
                    '[]'::jsonb
                )
            ) AS reward
            WHERE reward->>'rarity' IN (
                'rare',
                'epic',
                'legendary'
            )
        );


        -- =====================================================
        -- 5. Get highest rarity
        -- =====================================================

        SELECT CASE MAX(
            CASE reward->>'rarity'
                WHEN 'common'    THEN 1
                WHEN 'uncommon'  THEN 2
                WHEN 'rare'      THEN 3
                WHEN 'epic'      THEN 4
                WHEN 'legendary' THEN 5
                ELSE 0
            END
        )
            WHEN 5 THEN 'legendary'
            WHEN 4 THEN 'epic'
            WHEN 3 THEN 'rare'
            WHEN 2 THEN 'uncommon'
            WHEN 1 THEN 'common'
            ELSE NULL
        END
        INTO v_highest_rarity
        FROM jsonb_array_elements(
            COALESCE(
                v_open_result->'rewards',
                '[]'::jsonb
            )
        ) AS reward;


        -- =====================================================
        -- 6. Get opening number
        -- =====================================================

        SELECT COALESCE(MAX(open_number), 0) + 1
        INTO v_open_number
        FROM public.player_loot_box_opens
        WHERE player_id = p_player_id
          AND loot_box_id = p_loot_box_id;


        -- =====================================================
        -- 7. Save individual opening
        -- =====================================================

        INSERT INTO public.player_loot_box_opens (
            player_id,
            loot_box_id,
            open_number,
            has_good_reward,
            highest_rarity,
            rewards
        )
        VALUES (
            p_player_id,
            p_loot_box_id,
            v_open_number,
            v_has_good_reward,
            v_highest_rarity,
            v_open_result->'rewards'
        );


        -- =====================================================
        -- 8. Update loot box counters
        --
        -- total_opens:
        --     always +1
        --
        -- current_streak:
        --     rare+     -> +1
        --     otherwise -> 0
        --
        -- pity_counter:
        --     rare+     -> 0
        --     otherwise -> +1
        --
        -- guaranteed_count:
        --     rare+     -> 0
        --     otherwise -> +1
        -- =====================================================

        UPDATE public.player_loot_boxes
        SET
            total_opens = total_opens + 1,

            current_streak = CASE
                WHEN v_has_good_reward
                    THEN current_streak + 1
                ELSE 0
            END,

            pity_counter = CASE
                WHEN v_has_good_reward
                    THEN 0
                ELSE pity_counter + 1
            END,

            guaranteed_count = CASE
                WHEN v_has_good_reward
                    THEN 0
                ELSE guaranteed_count + 1
            END,

            last_opened_at = now(),
            updated_at = now()

        WHERE player_id = p_player_id
          AND loot_box_id = p_loot_box_id;


        -- =====================================================
        -- 9. Normalize rewards for grant
        -- =====================================================

        SELECT jsonb_agg(
            jsonb_build_object(
                'reward_type', reward->>'reward_type',
                'item_id', reward->>'item_id',
                'amount', (reward->>'amount')::int,
                'rarity', reward->>'rarity',
                'bound_type', reward->>'bound_type'
            )
        )
        INTO v_converted_rewards
        FROM jsonb_array_elements(
            COALESCE(
                v_open_result->'rewards',
                '[]'::jsonb
            )
        ) AS reward;


        v_all_rewards :=
            v_all_rewards || COALESCE(
                v_converted_rewards,
                '[]'::jsonb
            );

    END LOOP;


    -- =========================================================
    -- 10. Grant all rewards at once
    -- =========================================================

    v_grant_result := grant_rewards_from_json_full(
        p_player_id,
        v_all_rewards
    );


    -- =========================================================
    -- 11. Enrich reward information
    -- =========================================================

    v_reward_details := get_reward_full(
        jsonb_build_object(
            'rewards', v_all_rewards
        )
    );


    -- =========================================================
    -- 12. Return
    -- =========================================================

    RETURN jsonb_build_object(
        'success', true,
        'loot_box_id', p_loot_box_id,
        'opened', p_amount,
        'rewards', v_reward_details,
        'grant_result', v_grant_result
    );

END;
$$;


ALTER FUNCTION public.open_loot_box_transaction(p_player_id uuid, p_loot_box_id text, p_amount integer) OWNER TO postgres;

--
-- Name: open_new_region(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_new_region(p_player_id uuid, p_region_id text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
BEGIN
    -- 1️⃣ Check region tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM regions r
        WHERE r.id = p_region_id
    ) THEN
        RAISE EXCEPTION 'Khu vực % không tồn tại', p_region_id;
    END IF;

    -- 2️⃣ Check player đã sở hữu region chưa
    SELECT pr.id
    INTO v_player_region_id
    FROM player_regions pr
    WHERE pr.player_id = p_player_id
      AND pr.region_id = p_region_id;

    -- Đã sở hữu → thưởng 100 gold và không tạo activity/region mới
    IF v_player_region_id IS NOT NULL THEN
        PERFORM add_player_currency(
            p_player_id,
            'gold',
            100
        );

        RETURN v_player_region_id;
    END IF;

    -- 3️⃣ Chưa sở hữu → mở region mới
    INSERT INTO player_regions (
        player_id,
        region_id,
        is_active,
        development_level,
        resources
    )
    VALUES (
        p_player_id,
        p_region_id,
        true,
        0,
        0
    )
    RETURNING id INTO v_player_region_id;

    -- 4️⃣ Tạo activity region.open
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        related_id,
        metadata
    )
    VALUES (
        p_player_id,
        'region.open',
        v_player_region_id::text,
        jsonb_build_object(
            'region_id', p_region_id,
            'player_region_id', v_player_region_id
        )
    );

    -- 5️⃣ Return player_region id
    RETURN v_player_region_id;
END;
$$;


ALTER FUNCTION public.open_new_region(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: payment_create_new_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_create_new_account(p_player_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order_code text;
    v_order_type text := 'ACCOUNT_ACTIVATION';
    v_amount numeric(18,2);
BEGIN
    -- Lấy giá kích hoạt tài khoản
    SELECT price
    INTO v_amount
    FROM public.order_types
    WHERE code = v_order_type;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order type % does not exist', v_order_type;
    END IF;

    -- Kiểm tra player tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM public.players
        WHERE id = p_player_id
    ) THEN
        RAISE EXCEPTION 'Player % does not exist', p_player_id;
    END IF;

    -- Không cho tạo nhiều order activation đang chờ
    IF EXISTS (
        SELECT 1
        FROM public.payment_orders
        WHERE player_id = p_player_id
          AND order_type = v_order_type
          AND status IN ('INITIALIZING', 'PENDING')
    ) THEN
        RAISE EXCEPTION 'Player already has an active account activation order';
    END IF;

    -- Tạo order code
    v_order_code :=
        'DH' ||
        upper(
            substr(
                replace(gen_random_uuid()::text, '-', ''),
                1,
                20
            )
        );

    INSERT INTO public.payment_orders (
        player_id,
        order_code,
        order_type,
        amount,
        currency,
        status,
        description
    )
    VALUES (
        p_player_id,
        v_order_code,
        v_order_type,
        v_amount,
        'VND',
        'INITIALIZING',
        'Thanh toán kích hoạt tài khoản'
    );

    RETURN v_order_code;
END;
$$;


ALTER FUNCTION public.payment_create_new_account(p_player_id uuid) OWNER TO postgres;

--
-- Name: payment_create_order_by_email(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_create_order_by_email(p_email text, p_order_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_player_id uuid;
    v_activated boolean;
    v_order_code text;
BEGIN
    IF p_order_type <> 'ACCOUNT_ACTIVATION' THEN
        RAISE EXCEPTION 'Không hỗ trợ tạo đơn hàng loại %', p_order_type;
    END IF;

    SELECT
        p.id,
        p.activated
    INTO
        v_player_id,
        v_activated
    FROM auth.users u
    JOIN public.players p
        ON p.user_id = u.id
    WHERE lower(u.email) = lower(trim(p_email));

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Không tìm thấy tài khoản người chơi với email %',
            p_email;
    END IF;

    IF v_activated THEN
        RAISE EXCEPTION 'Tài khoản người chơi đã được kích hoạt rồi!';
    END IF;

    -- Có order cũ → dùng lại order đó
    SELECT po.order_code
    INTO v_order_code
    FROM public.payment_orders po
    WHERE po.player_id = v_player_id
      AND po.order_type = p_order_type
    ORDER BY po.created_at DESC
    LIMIT 1;

    IF FOUND THEN
        RETURN v_order_code;
    END IF;

    -- Chưa có order → tạo mới
    RETURN public.payment_create_new_account(v_player_id);
END;
$$;


ALTER FUNCTION public.payment_create_order_by_email(p_email text, p_order_type text) OWNER TO postgres;

--
-- Name: payment_get_billing_information(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_get_billing_information(p_email text, p_action_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'playerId', p.id,
        'email', u.email,
        'username', p.username,
        'actionType', p_action_type,
        'orderType', ot.code,
        'amount', ot.price,
        'formattedAmount',
            to_char(ot.price, 'FM999G999G999G999G990'),
        'currency', 'VND',
        'description', ot.name,
        'activated', p.activated
    )
    INTO v_result
    FROM auth.users u
    JOIN public.players p
        ON p.user_id = u.id
    JOIN public.order_types ot
        ON ot.code = p_action_type
    WHERE u.email = p_email;

    IF v_result IS NULL THEN
        RAISE EXCEPTION 'Không tìm thấy thông tin thanh toán';
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.payment_get_billing_information(p_email text, p_action_type text) OWNER TO postgres;

--
-- Name: payment_handle_sepay_ipn(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_handle_sepay_ipn(p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order_code text;
    v_amount numeric(18,2);
    v_transaction_id text;
    v_player_id uuid;
    v_order_type text;
    v_updated_count integer;
BEGIN
    v_order_code :=
        p_payload->'order'->>'order_invoice_number';

    v_amount :=
        (p_payload->'transaction'->>'transaction_amount')::numeric(18,2);

    v_transaction_id :=
        p_payload->'transaction'->>'transaction_id';

    -- Chỉ xử lý transaction APPROVED
    IF p_payload->'transaction'->>'transaction_status' <> 'APPROVED' THEN
        RETURN false;
    END IF;

    -- Lấy thông tin order
    SELECT
        player_id,
        order_type
    INTO
        v_player_id,
        v_order_type
    FROM public.payment_orders
    WHERE order_code = v_order_code
      AND amount <= v_amount
      AND status <> 'COMPLETED'
    FOR UPDATE;

    -- Không tìm thấy order hợp lệ
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    -- Hoàn tất order
    UPDATE public.payment_orders
    SET
        status = 'COMPLETED',
        provider_transaction_id = v_transaction_id,
        completed_at = now(),
        updated_at = now(),
        metadata = p_payload
    WHERE order_code = v_order_code
      AND amount <= v_amount
      AND status <> 'COMPLETED';

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    -- Chỉ xử lý nghiệp vụ khi UPDATE thành công đúng 1 record
    IF v_updated_count = 1 THEN

        -- Kích hoạt tài khoản
        IF v_order_type = 'ACCOUNT_ACTIVATION' THEN

            UPDATE public.players
            SET
                activated = true
            WHERE id = v_player_id
              AND activated = false;

        END IF;

        RETURN true;
    END IF;

    RETURN false;
END;
$$;


ALTER FUNCTION public.payment_handle_sepay_ipn(p_payload jsonb) OWNER TO postgres;

