--
-- Name: plus_exp_and_upgrade_level(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.plus_exp_and_upgrade_level(p_player_id uuid, p_exp bigint) RETURNS TABLE(new_level integer, current_exp bigint, leveled_up boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_level int;
    v_exp bigint;
    v_required bigint;
    v_leveled_up boolean := false;
BEGIN
    SELECT level, exp
    INTO v_level, v_exp
    FROM public.players
    WHERE id = p_player_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player not found: %', p_player_id;
    END IF;

    v_exp := v_exp + p_exp;

    LOOP
        v_required := public.get_required_exp_by_level(v_level);

        EXIT WHEN v_exp < v_required;

        v_exp := v_exp - v_required;
        v_level := v_level + 1;
        v_leveled_up := true;
    END LOOP;

    UPDATE public.players
    SET
        level = v_level,
        exp = v_exp
    WHERE id = p_player_id;

    RETURN QUERY
    SELECT v_level, v_exp, v_leveled_up;
END;
$$;


ALTER FUNCTION public.plus_exp_and_upgrade_level(p_player_id uuid, p_exp bigint) OWNER TO postgres;

--
-- Name: preview_all_resources(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_all_resources(p_player_id uuid, p_region_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_region_resource RECORD;
    v_resource_code VARCHAR;
    v_preview NUMERIC;
    v_result JSONB := '[]'::JSONB;
    v_item JSONB;
BEGIN
    -- 1. Lấy tất cả building trong region
    FOR v_building IN
        SELECT prb.*
        FROM player_region_buildings prb
        JOIN player_regions pr ON pr.id = prb.player_region_id
        WHERE pr.player_id = p_player_id
          AND pr.region_id = p_region_id
    LOOP
        -- 2. Lấy resource code building sản xuất
        SELECT resource_code
        INTO v_resource_code
        FROM building_production
        WHERE building_type = v_building.building_type
          AND level = v_building.level
        LIMIT 1;

        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        -- 3. Lấy region resource (không insert)
        SELECT * INTO v_region_resource
        FROM region_resources
        WHERE player_region_id = v_building.player_region_id
          AND resource_code = v_resource_code;

        IF NOT FOUND THEN
            v_region_resource.amount := 0;
            v_region_resource.max_amount := 2500;
            v_region_resource.last_collected_at := now() - interval '1 hour';
        END IF;

        -- 4. Tính preview collect
        SELECT (bp.production_rate_per_hour * COALESCE(bp.efficiency_percent,100)/100 *
                EXTRACT(EPOCH FROM (NOW() - v_region_resource.last_collected_at))/3600)
        INTO v_preview
        FROM building_production bp
        WHERE bp.building_type = v_building.building_type
          AND bp.level = v_building.level
          AND bp.resource_code = v_resource_code
        LIMIT 1;

        -- 5. Giới hạn max_amount
        v_preview := LEAST(
            v_preview,
            COALESCE(v_region_resource.max_amount,0) - COALESCE(v_region_resource.amount,0)
        );
        v_preview := GREATEST(v_preview,0);

        -- 6. Build JSON item
        v_item := jsonb_build_object(
            'player_building_id', v_building.id,
            'building_type', v_building.building_type,
            'resource_code', v_resource_code,
            'current_amount', COALESCE(v_region_resource.amount,0),
            'max_amount', COALESCE(v_region_resource.max_amount,0),
            'preview_collect', v_preview
        );

        v_result := v_result || jsonb_build_array(v_item);
    END LOOP;

    RETURN v_result::JSON;
END;
$$;


ALTER FUNCTION public.preview_all_resources(p_player_id uuid, p_region_id text) OWNER TO postgres;

--
-- Name: preview_building_resource(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_building_resource(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_region_resource RECORD;
    v_resource_code VARCHAR;
    v_collected NUMERIC;
BEGIN
    -- 1. Lấy building + region
    SELECT prb.*, pr.id AS region_id
    INTO v_building
    FROM player_region_buildings prb
    JOIN player_regions pr ON pr.id = prb.player_region_id
    WHERE prb.id = p_player_building_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;

    -- 2. Lấy resource code building sản xuất
    SELECT resource_code
    INTO v_resource_code
    FROM building_production
    WHERE building_type = v_building.building_type
      AND level = v_building.level
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building does not produce any resource'
        );
    END IF;

    -- 3. Lấy region resource
    SELECT * INTO v_region_resource
    FROM region_resources
    WHERE player_region_id = v_building.player_region_id
      AND resource_code = v_resource_code;

    IF NOT FOUND THEN
        -- giả lập nếu chưa có record
        v_region_resource.amount := 0;
        v_region_resource.max_amount := 2500; -- có thể set default
        v_region_resource.last_collected_at := now() - interval '1 hour';
    END IF;

    -- 4. Tính lượng collect được (preview)
    SELECT (bp.production_rate_per_hour * COALESCE(bp.efficiency_percent,100)/100 *
            EXTRACT(EPOCH FROM (NOW() - v_region_resource.last_collected_at))/3600)
    INTO v_collected
    FROM building_production bp
    WHERE bp.building_type = v_building.building_type
      AND bp.level = v_building.level
      AND bp.resource_code = v_resource_code
    LIMIT 1;

    -- 5. Giới hạn max_amount
    IF COALESCE(v_region_resource.max_amount,0) > 0 THEN
        v_collected := LEAST(v_collected, v_region_resource.max_amount - COALESCE(v_region_resource.amount,0));
    END IF;

    -- 6. Trả JSON
    RETURN json_build_object(
        'success', true,
        'player_building_id', p_player_building_id,
        'resource_code', v_resource_code,
        'current_amount', COALESCE(v_region_resource.amount,0),
        'max_amount', COALESCE(v_region_resource.max_amount,0),
        'preview_collect', COALESCE(v_collected,0)
    );
END;
$$;


ALTER FUNCTION public.preview_building_resource(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: preview_combat_casualties(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_combat_casualties(p_battle_id uuid, p_unit_results jsonb) RETURNS TABLE(unit_type character varying, unit_name character varying, current_quantity integer, new_quantity integer, lost_quantity integer, hp_percent double precision, status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unit_record RECORD;
    v_current_quantity INTEGER;
    v_new_quantity INTEGER;
    v_lost_quantity INTEGER;
    v_hp_percent FLOAT;
    v_status TEXT;
    v_unit_name VARCHAR(100);
BEGIN
    FOR v_unit_record IN
        SELECT
            value->>'unit_type' AS unit_type_val,
            (value->>'hp_percent')::FLOAT AS hp_percent
        FROM jsonb_array_elements(p_unit_results)
    LOOP
        -- Lấy thông tin hiện tại
        SELECT 
            ct.current_quantity,
            ct.unit_name
        INTO 
            v_current_quantity,
            v_unit_name
        FROM combat_troops ct
        WHERE ct.battle_id = p_battle_id
          AND ct.unit_type = v_unit_record.unit_type_val
        LIMIT 1;

        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        -- Chuyển % HP về số thập phân
        v_hp_percent := v_unit_record.hp_percent / 100.0;

        -- Tính quân còn lại
        v_new_quantity := ROUND(v_current_quantity * v_hp_percent);

        IF v_hp_percent <= 0 THEN
            v_new_quantity := 0;
            v_status := 'defeated';
        ELSIF v_new_quantity = 0 THEN
            v_new_quantity := 1;
            v_status := 'fighting';
        ELSE
            v_status := 'fighting';
        END IF;

        v_lost_quantity := v_current_quantity - v_new_quantity;

        -- Trả kết quả
        unit_type := v_unit_record.unit_type_val;
        unit_name := v_unit_name;
        current_quantity := v_current_quantity;
        new_quantity := v_new_quantity;
        lost_quantity := v_lost_quantity;
        hp_percent := v_unit_record.hp_percent;
        status := v_status;

        RETURN NEXT;
    END LOOP;

    RETURN;
END;
$$;


ALTER FUNCTION public.preview_combat_casualties(p_battle_id uuid, p_unit_results jsonb) OWNER TO postgres;

--
-- Name: process_rewards_to_player(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_rewards_to_player(p_player_id uuid, p_rewards jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reward JSONB;
    v_currency_type TEXT;
    v_amount INTEGER;
    v_current_balance NUMERIC;
    v_new_balance NUMERIC;
    v_transaction_id TEXT;
    i INTEGER;
BEGIN
    -- Lặp qua tất cả rewards
    FOR i IN 0..jsonb_array_length(p_rewards)-1 LOOP
        v_reward := p_rewards->i;
        
        IF v_reward->>'type' = 'currency' THEN
            -- Xử lý currency rewards
            v_currency_type := v_reward->>'currency_type';
            v_amount := (v_reward->>'amount')::INTEGER;
            
            -- Thêm vào wallet
            INSERT INTO player_wallets (player_id, currency_type, amount)
            VALUES (p_player_id, v_currency_type, v_amount)
            ON CONFLICT (player_id, currency_type)
            DO UPDATE SET amount = player_wallets.amount + EXCLUDED.amount;
            
            -- Lấy số dư sau khi cập nhật
            SELECT amount INTO v_new_balance
            FROM player_wallets
            WHERE player_id = p_player_id AND currency_type = v_currency_type;
            
            v_current_balance := v_new_balance - v_amount;
            
            -- Tạo transaction ID và ghi log
            v_transaction_id := 'tx_reward_' || replace(gen_random_uuid()::text, '-', '_');
            
            INSERT INTO currency_transactions (
                id, player_id, transaction_type, currency_type, amount,
                balance_before, balance_after, source, description
            ) VALUES (
                v_transaction_id,
                p_player_id, 'reward', v_currency_type, v_amount,
                v_current_balance, v_new_balance,
                'loot_box_reward',
                'Nhận từ loot box'
            );
            
        ELSIF v_reward->>'type' = 'item' THEN
            -- Xử lý item rewards (đơn giản log lại)
            RAISE NOTICE 'Item reward: % x%', v_reward->>'item_id', v_reward->>'amount';
            -- Trong thực tế, bạn sẽ INSERT vào bảng player_inventory ở đây
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION public.process_rewards_to_player(p_player_id uuid, p_rewards jsonb) OWNER TO postgres;

--
-- Name: proclaim_emperor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.proclaim_emperor(p_player_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_has_proclaimed boolean;
    v_region_count int;
    v_general_count int;
    v_beauty_count int;
BEGIN
    -- Kiểm tra player_stats
    SELECT has_proclaimed_emperor
    INTO v_has_proclaimed
    FROM public.player_stats
    WHERE player_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không tìm thấy thông tin người chơi.';
    END IF;

    -- Đã xưng đế
    IF v_has_proclaimed = true THEN
        RAISE EXCEPTION 'Người chơi đã xưng đế.';
    END IF;

    -- Tối thiểu 8 khu vực đang sở hữu
    SELECT COUNT(*)
    INTO v_region_count
    FROM public.player_regions
    WHERE player_id = p_player_id
      AND is_active = true;

    IF v_region_count < 8 THEN
        RAISE EXCEPTION
            'Cần sở hữu ít nhất 8 khu vực. Hiện tại đang sở hữu % khu vực.',
            v_region_count;
    END IF;

    -- Tối thiểu 5 tướng
    SELECT COUNT(*)
    INTO v_general_count
    FROM public.player_generals
    WHERE player_id = p_player_id;

    IF v_general_count < 5 THEN
        RAISE EXCEPTION
            'Cần sở hữu ít nhất 5 tướng. Hiện tại đang sở hữu % tướng.',
            v_general_count;
    END IF;

    -- Tối thiểu 3 mỹ nhân
    SELECT COUNT(*)
    INTO v_beauty_count
    FROM public.player_beauties
    WHERE player_id = p_player_id;

    IF v_beauty_count < 3 THEN
        RAISE EXCEPTION
            'Cần sở hữu ít nhất 3 mỹ nhân. Hiện tại đang sở hữu % mỹ nhân.',
            v_beauty_count;
    END IF;

    -- Trừ 1 Nam Quốc Ấn
    PERFORM public.subtract_execute(
        p_player_id,
        '[
            {
                "type": "item",
                "item_id": "sword_basic",
                "quantity": 1
            }
        ]'::jsonb
    );

    -- Đánh dấu đã xưng đế
    UPDATE public.player_stats
    SET has_proclaimed_emperor = true
    WHERE player_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không thể cập nhật trạng thái xưng đế.';
    END IF;
END;
$$;


ALTER FUNCTION public.proclaim_emperor(p_player_id uuid) OWNER TO postgres;

--
-- Name: remove_friend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_friend(p_player_id uuid, p_friend_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_deleted boolean;
BEGIN
  DELETE FROM friend_relationships
  WHERE (player_id = p_player_id AND friend_id = p_friend_id)
     OR (player_id = p_friend_id AND friend_id = p_player_id);

  v_deleted := FOUND;

  RETURN jsonb_build_object(
    'success', v_deleted,
    'message', CASE
      WHEN v_deleted THEN 'Friend removed'
      ELSE 'No friendship found'
    END
  );
END;
$$;


ALTER FUNCTION public.remove_friend(p_player_id uuid, p_friend_id uuid) OWNER TO postgres;

--
-- Name: remove_item(uuid, character varying, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_item(p_player_id uuid, p_item_id character varying, p_quantity integer DEFAULT 1, p_check boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_quantity int;
BEGIN
  SELECT quantity
  INTO v_quantity
  FROM player_items
  WHERE player_id = p_player_id
    AND item_id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item not found';
  END IF;

  IF p_check AND v_quantity < p_quantity THEN
    RAISE EXCEPTION 'Not enough items to remove';
  END IF;

  IF v_quantity <= p_quantity THEN
    DELETE FROM player_items
    WHERE player_id = p_player_id
      AND item_id = p_item_id;
  ELSE
    UPDATE player_items
    SET quantity = quantity - p_quantity
    WHERE player_id = p_player_id
      AND item_id = p_item_id;
  END IF;
END;
$$;


ALTER FUNCTION public.remove_item(p_player_id uuid, p_item_id character varying, p_quantity integer, p_check boolean) OWNER TO postgres;

--
-- Name: remove_player_from_alliance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_player_from_alliance(p_player_id uuid, p_target_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alliance_id uuid;
    v_is_leader boolean;
BEGIN
    -- tìm alliance của requester
    SELECT alliance_id
    INTO v_alliance_id
    FROM alliance_members
    WHERE player_id = p_player_id;

    IF v_alliance_id IS NULL THEN
        RETURN json_build_object('success', false, 'error', 'Not in alliance');
    END IF;

    -- check leader
    SELECT (leader = p_player_id)
    INTO v_is_leader
    FROM alliances
    WHERE id = v_alliance_id;

    -- nếu không phải leader thì chỉ được leave chính mình
    IF NOT v_is_leader AND p_player_id != p_target_player_id THEN
        RETURN json_build_object('success', false, 'error', 'No permission');
    END IF;

    -- xóa member
    DELETE FROM alliance_members
    WHERE alliance_id = v_alliance_id
    AND player_id = p_target_player_id;

    -- update count
    UPDATE alliances
    SET members = members - 1
    WHERE id = v_alliance_id;

    RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION public.remove_player_from_alliance(p_player_id uuid, p_target_player_id uuid) OWNER TO postgres;

--
-- Name: report_activity_completed(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_activity_completed(p_player_id uuid, p_activity_type text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_count int;
BEGIN
    -- Ghi log activity
    INSERT INTO public.player_activities (
        player_id,
        activity_type
    )
    VALUES (
        p_player_id,
        p_activity_type
    );

    -- Đếm tổng số lần activity này đã hoàn thành
    SELECT COUNT(*)
    INTO v_total_count
    FROM public.player_activities
    WHERE player_id = p_player_id
      AND activity_type = p_activity_type;

    -- Return kết quả
    RETURN json_build_object(
        'success', true,
        'player_id', p_player_id,
        'activity_type', p_activity_type,
        'completed_count', v_total_count,
        'message', 'Activity completed'
    );
END;
$$;


ALTER FUNCTION public.report_activity_completed(p_player_id uuid, p_activity_type text) OWNER TO postgres;

--
-- Name: request_join_alliance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_join_alliance(p_player_id uuid, p_alliance_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_requires_approval boolean;
BEGIN
    -- check setting
    SELECT (requirements->>'approvalRequired')::boolean
    INTO v_requires_approval
    FROM alliances
    WHERE id = p_alliance_id;

    IF NOT v_requires_approval THEN
        -- auto join nếu không cần duyệt
        INSERT INTO alliance_members (alliance_id, player_id)
        VALUES (p_alliance_id, p_player_id);

        RETURN json_build_object('success', true, 'autoJoined', true);
    END IF;

    INSERT INTO alliance_join_requests (alliance_id, player_id)
    VALUES (p_alliance_id, p_player_id);

    RETURN json_build_object('success', true, 'pending', true);
END;
$$;


