--
-- Name: resolve_combat_result(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_combat_result(p_battle_id uuid, p_winner_id uuid, p_loser_id uuid, p_unit_results_win jsonb, p_unit_results_loss jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles;
    v_result jsonb;
    v_win_result jsonb;
    v_loss_result jsonb;
    v_winner_region_id text;
    v_loser_region_id text;
BEGIN
    -- Lock battle tránh resolve nhiều lần
    SELECT *
    INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id
    FOR UPDATE;

    IF v_battle.id IS NULL THEN
        RAISE EXCEPTION 'Battle % not found', p_battle_id;
    END IF;

    -- Chỉ resolve trận đang đánh
    IF v_battle.status <> 'in_progress' THEN
        RAISE EXCEPTION
            'Battle % is not in progress. Current status: %',
            p_battle_id,
            v_battle.status;
    END IF;

    -- Xác định region của winner và loser từ battle
    IF p_winner_id = v_battle.player1_id THEN
        v_winner_region_id := v_battle.player1_region_id;
        v_loser_region_id := v_battle.player2_region_id;
    ELSE
        v_winner_region_id := v_battle.player2_region_id;
        v_loser_region_id := v_battle.player1_region_id;
    END IF;

    -- =========================
    -- Apply damage phe thắng
    -- =========================
    SELECT jsonb_agg(row_to_json(t))
    INTO v_win_result
    FROM public.update_combat_casualties(
        p_battle_id,
        p_winner_id,
        p_unit_results_win
    ) t;

    -- =========================
    -- Apply damage phe thua
    -- =========================
    SELECT jsonb_agg(row_to_json(t))
    INTO v_loss_result
    FROM public.update_combat_casualties(
        p_battle_id,
        p_loser_id,
        p_unit_results_loss
    ) t;

    -- Xóa unit đã chết hoàn toàn
    DELETE FROM public.combat_troops ct
    WHERE ct.battle_id = p_battle_id
      AND NOT EXISTS (
          SELECT 1
          FROM (
              SELECT jsonb_array_elements(COALESCE(p_unit_results_win, '[]'::jsonb)) AS item
              UNION ALL
              SELECT jsonb_array_elements(COALESCE(p_unit_results_loss, '[]'::jsonb))
          ) r
          WHERE r.item->>'unit_type' = ct.unit_type
            AND ct.player_id IN (p_winner_id, p_loser_id)
      );

    -- =========================
    -- Trả quân còn sống phe thắng
    -- =========================
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        v_winner_region_id,
        p_winner_id
    );

    -- =========================
    -- Trả quân còn sống phe thua
    -- =========================
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        v_loser_region_id,
        p_loser_id
    );

    -- =========================
    -- Đóng trận
    -- =========================
    UPDATE public.battles
    SET
        status = 'completed',
        winner_id = CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.players p
                WHERE p.id = p_winner_id
            )
            THEN p_winner_id
            ELSE winner_id
        END,
        ended_at = now()
    WHERE id = p_battle_id;

    -- =========================
    -- Combat logs
    -- =========================

    IF EXISTS (
        SELECT 1
        FROM public.players
        WHERE id = p_winner_id
    ) THEN
        INSERT INTO public.combat_logs (
            player_id,
            icon_name,
            title,
            color_code,
            log_type,
            battle_id,
            damage_dealt,
            damage_received,
            resources_gained,
            resources_lost,
            territory_changed,
            victory_points_changed
        )
        VALUES (
            p_winner_id,
            'battle_result',
            'Bạn đã thắng trận!',
            '#28a745',
            'system',
            p_battle_id,
            0,
            0,
            NULL,
            NULL,
            0,
            0
        );
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.players
        WHERE id = p_loser_id
    ) THEN
        INSERT INTO public.combat_logs (
            player_id,
            icon_name,
            title,
            color_code,
            log_type,
            battle_id,
            damage_dealt,
            damage_received,
            resources_gained,
            resources_lost,
            territory_changed,
            victory_points_changed
        )
        VALUES (
            p_loser_id,
            'battle_result',
            'Bạn đã thua trận',
            '#dc3545',
            'system',
            p_battle_id,
            0,
            0,
            NULL,
            NULL,
            0,
            0
        );
    END IF;
    -- =========================
    -- Player activities
    -- =========================

    IF EXISTS (
        SELECT 1
        FROM public.players
        WHERE id = p_winner_id
    ) THEN
        INSERT INTO public.player_activities (
            player_id,
            activity_type,
            related_id,
            metadata
        )
        VALUES (
            p_winner_id,
            'battle.win',
            p_battle_id::text,
            '{}'::jsonb
        );
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.players
        WHERE id = p_loser_id
    ) THEN
        INSERT INTO public.player_activities (
            player_id,
            activity_type,
            related_id,
            metadata
        )
        VALUES (
            p_loser_id,
            'battle.loss',
            p_battle_id::text,
            '{}'::jsonb
        );
    END IF;
    -- =========================
    -- Response
    -- =========================
    v_result := jsonb_build_object(
        'battle_id', p_battle_id,
        'status', 'completed',
        'winner_id', p_winner_id,
        'loser_id', p_loser_id,
        'winner_result', COALESCE(v_win_result, '[]'::jsonb),
        'loser_result', COALESCE(v_loss_result, '[]'::jsonb)
    );

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.resolve_combat_result(p_battle_id uuid, p_winner_id uuid, p_loser_id uuid, p_unit_results_win jsonb, p_unit_results_loss jsonb) OWNER TO postgres;

--
-- Name: resolve_combat_result(uuid, jsonb, jsonb, uuid, uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_combat_result(p_battle_id uuid, p_unit_results_win jsonb, p_unit_results_loss jsonb, p_winner_id uuid, p_loss_id uuid, p_winner_region_id character varying, p_loss_region_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN

    -- 1. Apply damage phe thắng
    PERFORM public.update_combat_casualties(
        p_battle_id,
        p_winner_id,
        p_unit_results_win
    );


    -- 2. Apply damage phe thua
    PERFORM public.update_combat_casualties(
        p_battle_id,
        p_loss_id,
        p_unit_results_loss
    );


    -- 3. Trả quân còn sống phe thắng
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        p_winner_region_id,
        p_winner_id
    );


    -- 4. Trả quân còn sống phe thua
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        p_loss_region_id,
        p_loss_id
    );


    -- 5. Return kết quả
    SELECT jsonb_build_object(
        'battle_id', p_battle_id,
        'winner_id', p_winner_id,
        'loser_id', p_loss_id,
        'status', 'resolved'
    )
    INTO v_result;


    RETURN v_result;
END;
$$;


ALTER FUNCTION public.resolve_combat_result(p_battle_id uuid, p_unit_results_win jsonb, p_unit_results_loss jsonb, p_winner_id uuid, p_loss_id uuid, p_winner_region_id character varying, p_loss_region_id character varying) OWNER TO postgres;

--
-- Name: resolve_combat_result(uuid, uuid, uuid, character varying, character varying, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_combat_result(p_battle_id uuid, p_winner_id uuid, p_loser_id uuid, p_winner_region_id character varying, p_loser_region_id character varying, p_unit_results_win jsonb, p_unit_results_loss jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle public.battles;
    v_result jsonb;
    v_win_result jsonb;
    v_loss_result jsonb;
BEGIN

    -- Lock battle tránh resolve nhiều lần
    SELECT *
    INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id
    FOR UPDATE;


    IF v_battle.id IS NULL THEN
        RAISE EXCEPTION 'Battle % not found', p_battle_id;
    END IF;


    -- Chỉ resolve trận đang đánh
    IF v_battle.status <> 'in_progress' THEN
        RAISE EXCEPTION 
            'Battle % is not in progress. Current status: %',
            p_battle_id,
            v_battle.status;
    END IF;


    -- =========================
    -- Apply damage phe thắng
    -- =========================
    SELECT jsonb_agg(row_to_json(t))
    INTO v_win_result
    FROM public.update_combat_casualties(
        p_battle_id,
        p_winner_id,
        p_unit_results_win
    ) t;


    -- =========================
    -- Apply damage phe thua
    -- =========================
    SELECT jsonb_agg(row_to_json(t))
    INTO v_loss_result
    FROM public.update_combat_casualties(
        p_battle_id,
        p_loser_id,
        p_unit_results_loss
    ) t;


    -- =========================
    -- Trả quân còn sống phe thắng
    -- =========================
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        p_winner_region_id,
        p_winner_id
    );


    -- =========================
    -- Trả quân còn sống phe thua
    -- =========================
    PERFORM public.rollback_troops_from_combat(
        p_battle_id,
        p_loser_region_id,
        p_loser_id
    );


    -- =========================
    -- Đóng trận
    -- =========================
    UPDATE public.battles
    SET
        status = 'completed',
        winner_id = p_winner_id,
        ended_at = now()
    WHERE id = p_battle_id;


    -- Response
    v_result := jsonb_build_object(
        'battle_id', p_battle_id,
        'status', 'completed',
        'winner_id', p_winner_id,
        'loser_id', p_loser_id,
        'winner_result', COALESCE(v_win_result, '[]'::jsonb),
        'loser_result', COALESCE(v_loss_result, '[]'::jsonb)
    );
    UPDATE public.battles
SET
    status = 'completed',
    winner_id = p_winner_id,
    ended_at = now()
WHERE id = p_battle_id;


    RETURN v_result;

END;
$$;


