--
-- Name: resolve_region_battle_casualties(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_region_battle_casualties(p_player_id uuid, p_region_id text, p_combat_result jsonb) RETURNS TABLE(unit_id text, unit_type_id uuid, old_quantity integer, lost_quantity integer, new_quantity integer, casualty_percent numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unit_record RECORD;
    v_casualty_percent numeric;
    v_old_quantity integer;
    v_lost_quantity integer;
    v_new_quantity integer;
    v_unit_type_id uuid;
BEGIN
    -- Duyệt qua từng unit trong player_units
    FOR v_unit_record IN 
        SELECT 
            (value->>'id')::text as unit_id,
            (value->>'casualty')::numeric as casualty_percent
        FROM jsonb_array_elements(p_combat_result->'player_units')
    LOOP
        -- Chỉ xử lý nếu có thiệt hại > 0
        IF v_unit_record.casualty_percent > 0 THEN
            -- Lấy unit_type_id từ bảng unit_types dựa trên unit_id
            -- Giả sử có mapping unit_id -> unit_type_id
            SELECT unit_type_id INTO v_unit_type_id
            FROM unit_mapping
            WHERE unit_code = v_unit_record.unit_id;
            
            -- Lấy số lượng hiện tại
            SELECT quantity INTO v_old_quantity
            FROM region_troops
            WHERE player_id = p_player_id
              AND region_id = p_region_id
              AND unit_type = v_unit_type_id
              AND quantity > 0;
            
            IF FOUND THEN
                -- Tính toán thiệt hại
                v_casualty_percent := v_unit_record.casualty_percent;
                v_lost_quantity := CEIL(v_old_quantity * v_casualty_percent / 100.0);
                v_new_quantity := v_old_quantity - v_lost_quantity;
                
                -- Cập nhật
                UPDATE region_troops
                SET
                    quantity = v_new_quantity,
                    total_lost = total_lost + v_lost_quantity,
                    updated_at = CURRENT_TIMESTAMP
                WHERE player_id = p_player_id
                  AND region_id = p_region_id
                  AND unit_type = v_unit_type_id;
                
                -- Trả về kết quả
                RETURN QUERY
                SELECT 
                    v_unit_record.unit_id,
                    v_unit_type_id,
                    v_old_quantity,
                    v_lost_quantity,
                    v_new_quantity,
                    v_casualty_percent;
            END IF;
        END IF;
    END LOOP;
    
    -- Xóa các đơn vị có quantity = 0
    DELETE FROM region_troops
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND quantity = 0;
    
    -- Nếu không có unit nào bị thiệt hại, trả về thông báo
    IF NOT FOUND THEN
        RETURN QUERY
        SELECT 
            'no_casualty'::text,
            NULL::uuid,
            0,
            0,
            0,
            0.0;
    END IF;
END;
$$;


ALTER FUNCTION public.resolve_region_battle_casualties(p_player_id uuid, p_region_id text, p_combat_result jsonb) OWNER TO postgres;

--
-- Name: resolve_region_battle_casualties(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_region_battle_casualties(p_player_id uuid, p_region_id text, p_casualty_percent numeric) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- clamp input an toàn
    IF p_casualty_percent < 0 THEN
        p_casualty_percent := 0;
    ELSIF p_casualty_percent > 100 THEN
        p_casualty_percent := 100;
    END IF;

    -- áp tổn thất sau trận lên toàn bộ quân trong region
    UPDATE region_troops
    SET
        quantity = FLOOR(quantity * (1 - p_casualty_percent / 100.0)),
        total_lost = total_lost + CEIL(quantity * p_casualty_percent / 100.0),
        updated_at = CURRENT_TIMESTAMP
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND quantity > 0;

END;
$$;


ALTER FUNCTION public.resolve_region_battle_casualties(p_player_id uuid, p_region_id text, p_casualty_percent numeric) OWNER TO postgres;

--
-- Name: rollback_troops_from_combat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rollback_troops_from_combat(p_battle_id uuid, p_player_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Trả quân về region_troops
    INSERT INTO region_troops (
        region_id,
        player_id,
        unit_type,
        quantity,
        total_trained,
        total_lost,
        status,
        location_type,
        attack_power,
        defense_power,
        health_points,
        movement_speed,
        created_at,
        updated_at,
        last_used_in_battle_at,
        is_combat_ready
    )
    SELECT
        ct.region_id,
        ct.player_id,
        ct.unit_type,
        ct.current_quantity,
        0,
        ct.lost_quantity,
        'idle',
        'region',
        ct.attack_power,
        ct.defense_power,
        ct.health_points,
        ct.movement_speed,
        NOW(),
        NOW(),
        NOW(),
        true
    FROM combat_troops ct
    WHERE ct.battle_id = p_battle_id
      AND ct.player_id = p_player_id
      AND ct.current_quantity > 0
    ON CONFLICT (region_id, player_id, unit_type)
    DO UPDATE
    SET
        quantity = region_troops.quantity + EXCLUDED.quantity,
        total_lost = region_troops.total_lost + EXCLUDED.total_lost,
        updated_at = NOW(),
        last_used_in_battle_at = NOW(),
        is_combat_ready = true;

    -- Xóa toàn bộ quân khỏi combat_troops
    DELETE FROM combat_troops
    WHERE battle_id = p_battle_id
      AND player_id = p_player_id;
END;
$$;


ALTER FUNCTION public.rollback_troops_from_combat(p_battle_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: rollback_troops_from_combat(uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rollback_troops_from_combat(p_battle_id uuid, p_region_id character varying, p_player_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Trả quân còn sống từ combat về region
    INSERT INTO region_troops (
        region_id,
        player_id,
        unit_type,
        quantity,
        total_trained,
        total_lost,
        status,
        location_type,
        created_at,
        updated_at
    )
    SELECT
        ct.region_id,
        ct.player_id,
        ct.unit_type,
        ct.current_quantity,
        0,
        0,
        'idle',
        'region',
        NOW(),
        NOW()
    FROM combat_troops ct
    WHERE ct.battle_id = p_battle_id
      AND ct.region_id = p_region_id
      AND ct.player_id = p_player_id
      AND ct.current_quantity > 0
    ON CONFLICT (region_id, player_id, unit_type)
    DO UPDATE
    SET
        quantity = region_troops.quantity + EXCLUDED.quantity,
        updated_at = NOW();


    -- Xóa quân khỏi combat sau khi hoàn trả
    DELETE FROM combat_troops
    WHERE battle_id = p_battle_id
      AND region_id = p_region_id
      AND player_id = p_player_id;

END;
$$;


ALTER FUNCTION public.rollback_troops_from_combat(p_battle_id uuid, p_region_id character varying, p_player_id uuid) OWNER TO postgres;

--
-- Name: select_reward_items(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_items(p_player_id uuid, p_pool_id text, p_multiplier numeric DEFAULT 1.0) RETURNS TABLE(item_id text, reward_type text, amount integer, rarity text, bound_type text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item RECORD;
    v_amount int;
    v_min int;
    v_max int;
BEGIN
    FOR v_item IN
        SELECT *
        FROM public.loot_box_reward_items
        WHERE reward_pool_id = p_pool_id
    LOOP
        v_min := v_item.amount_min;
        v_max := v_item.amount_max;

        v_amount := floor((v_min + random() * (v_max - v_min + 1)) * p_multiplier);
		  -- Xử lý khi item_id là NULL
        IF v_item.item_id IS NULL THEN
            -- Gán currency_type vào item_id
            item_id := v_item.currency_type;  -- Giả sử có cột currency_type
            reward_type := 'currency';  -- Đổi reward_type thành currency
        ELSE
            item_id := v_item.item_id;
            reward_type := v_item.reward_type;
        END IF;        
        reward_type := v_item.reward_type;
        amount := v_amount;
        rarity := v_item.rarity;
        bound_type := v_item.bound_type;

        RETURN NEXT;  -- Không có tham số
    END LOOP;
END;
$$;


ALTER FUNCTION public.select_reward_items(p_player_id uuid, p_pool_id text, p_multiplier numeric) OWNER TO postgres;

--
-- Name: select_reward_pools(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_pools(p_reward_table_id text) RETURNS TABLE(pool_id text, pool_name text, min_drop_val integer, max_drop_val integer, weight_val integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id,
        p.name,
        p.min_drops,
        p.max_drops,
        p.weight
    FROM public.loot_box_reward_pools p
    WHERE p.reward_table_id = p_reward_table_id
    ORDER BY random() * p.weight DESC
    LIMIT 1;
END;
$$;


ALTER FUNCTION public.select_reward_pools(p_reward_table_id text) OWNER TO postgres;

--
-- Name: select_reward_pools_random(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_pools_random(p_reward_table_id text) RETURNS TABLE(pool_id text, pool_name text, min_drop_val integer, max_drop_val integer, weight numeric, guaranteed_flag boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Weighted random selection trick: -log(random()) / weight
    RETURN QUERY
    SELECT
        rp.id AS pool_id,
        rp.pool_name,
        rp.min_drop_val,
        rp.max_drop_val,
        rp.weight,
        rp.guaranteed_flag
    FROM public.loot_box_reward_pools rp
    WHERE rp.reward_table_id = p_reward_table_id
    ORDER BY -ln(random()) / rp.weight;
END;
$$;


ALTER FUNCTION public.select_reward_pools_random(p_reward_table_id text) OWNER TO postgres;

