-- Name: select_reward_tables(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_tables(p_loot_box_id text) RETURNS TABLE(out_reward_table_id text, out_reward_table_name text, out_distribution_type text, out_anti_duplicate boolean, out_duplicate_protection numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        r.id AS out_reward_table_id,
        r.name AS out_reward_table_name,
        r.distribution_type AS out_distribution_type,
        r.anti_duplicate AS out_anti_duplicate,
        r.duplicate_protection AS out_duplicate_protection
    FROM public.loot_box_reward_tables r
    WHERE r.loot_box_id = p_loot_box_id
    ORDER BY random()
    LIMIT 3;
END;
$$;


ALTER FUNCTION public.select_reward_tables(p_loot_box_id text) OWNER TO postgres;

--
-- Name: select_reward_tables(uuid, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_tables(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_active boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    WITH all_tables AS (
        SELECT
            r.id AS table_id,
            r.name AS table_name,
            r.distribution_type,
            r.anti_duplicate,
            r.duplicate_protection,
            COALESCE(f.enabled, false) AS first_time_enabled
        FROM public.loot_box_reward_tables r
        LEFT JOIN public.loot_box_first_time_bonuses f
            ON r.id = f.reward_table_id
        WHERE r.loot_box_id = p_loot_box_id
    ),

    priority_tables AS (
        SELECT *
        FROM all_tables
        WHERE
            (p_is_first_time AND first_time_enabled)
            OR
            (p_pity_active AND distribution_type = 'pity')
    ),

    normal_tables AS (
        SELECT *
        FROM all_tables
        WHERE table_id NOT IN (
            SELECT table_id
            FROM priority_tables
        )
    ),

    random_normal_tables AS (
        SELECT *
        FROM normal_tables
        ORDER BY random()
        LIMIT GREATEST(
            0,
            3 - (SELECT COUNT(*) FROM priority_tables)
        )
    ),

    selected_tables AS (
        SELECT *
        FROM priority_tables

        UNION ALL

        SELECT *
        FROM random_normal_tables
    )

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'table_id', table_id,
                'table_name', table_name,
                'distribution_type', distribution_type,
                'anti_duplicate', anti_duplicate,
                'duplicate_protection', duplicate_protection,
                'first_time_enabled', first_time_enabled
            )
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM selected_tables;

    IF v_result = '[]'::jsonb THEN
        RAISE EXCEPTION
            'No reward tables available for loot box: %',
            p_loot_box_id;
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.select_reward_tables(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_active boolean) OWNER TO postgres;

--
-- Name: select_reward_tables(uuid, text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_reward_tables(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_active boolean, p_streak_active boolean) RETURNS TABLE(out_reward_table_id text, out_reward_table_name text, out_distribution_type text, out_anti_duplicate boolean, out_duplicate_protection numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH all_tables AS (
        SELECT 
            r.id AS col_table_id,
            r.name AS col_table_name,
            r.distribution_type AS col_distribution_type,
            r.anti_duplicate AS col_anti_duplicate,
            r.duplicate_protection AS col_duplicate_protection,
            f.enabled AS first_time_enabled,
            s.enabled AS streak_enabled
        FROM public.loot_box_reward_tables r
        LEFT JOIN public.loot_box_first_time_bonuses f
               ON r.id = f.reward_table_id
        LEFT JOIN public.loot_box_streak_bonuses s
               ON r.id = s.reward_table_id
        WHERE r.loot_box_id = p_loot_box_id
    ),
    priority_tables AS (
        SELECT *
        FROM all_tables
        WHERE (p_is_first_time AND first_time_enabled = TRUE)
           OR (p_pity_active AND col_distribution_type = 'pity')
           OR (p_streak_active AND streak_enabled = TRUE)
    ),
    normal_tables AS (
        SELECT *
        FROM all_tables
        WHERE col_table_id NOT IN (SELECT col_table_id FROM priority_tables)
    ),
    selected_tables AS (
        SELECT *
        FROM (
            SELECT * FROM priority_tables
            UNION ALL
            SELECT * FROM normal_tables
        ) AS unioned_tables
        ORDER BY random()
        LIMIT GREATEST(0, 3 - (SELECT COUNT(*) FROM priority_tables))
    )
    SELECT 
        col_table_id       AS out_reward_table_id,
        col_table_name     AS out_reward_table_name,
        col_distribution_type AS out_distribution_type,
        col_anti_duplicate AS out_anti_duplicate,
        col_duplicate_protection AS out_duplicate_protection
    FROM selected_tables;
END;
$$;


ALTER FUNCTION public.select_reward_tables(p_player_id uuid, p_loot_box_id text, p_is_first_time boolean, p_pity_active boolean, p_streak_active boolean) OWNER TO postgres;

