--
-- Name: start_unit_training(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_unit_training(p_player_region_building_id uuid, p_unit_type text, p_quantity integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_building_type varchar(50);
  v_building_level int;

  v_rate numeric(12,2);
  v_capacity int;
  v_efficiency numeric(5,2);

  v_batches int;
  v_time_per_batch interval;
  v_total_time interval;
  v_finish_at timestamptz;
  v_training_id uuid;
BEGIN
  -- 1️⃣ Validate
  IF p_quantity <= 0 THEN
    RAISE EXCEPTION 'Quantity must be > 0';
  END IF;

  -- 2️⃣ Check building (không upgrading)
  SELECT building_type, level
  INTO v_building_type, v_building_level
  FROM player_region_buildings
  WHERE id = p_player_region_building_id
    AND upgrading = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Building not found or upgrading';
  END IF;

  -- 3️⃣ Lấy rule đào tạo (TEXT = TEXT)
  SELECT
    training_rate_per_hour,
    training_capacity,
    efficiency_percent
  INTO
    v_rate,
    v_capacity,
    v_efficiency
  FROM building_unit_training
  WHERE building_type = v_building_type
    AND level = v_building_level
    AND unit_type = p_unit_type;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Training rule not found';
  END IF;

  -- 4️⃣ Tính thời gian
  v_batches := CEIL(p_quantity::numeric / v_capacity);

  v_time_per_batch :=
    (v_capacity / (v_rate * (v_efficiency / 100))) * interval '1 hour';

  v_total_time := v_batches * v_time_per_batch;
  v_finish_at := now() + v_total_time;

  -- 5️⃣ Insert training (song song, không cộng dồn)
  INSERT INTO unit_training_queue (
    player_region_building_id,
    unit_type,
    quantity,
    finish_at,
    status
  )
  VALUES (
    p_player_region_building_id,
    p_unit_type,
    p_quantity,
    v_finish_at,
    'training'
  )
  RETURNING id INTO v_training_id;

  -- 6️⃣ Return JSON
  RETURN json_build_object(
    'training_id', v_training_id,
    'building_id', p_player_region_building_id,
    'unit_type', p_unit_type,
    'quantity', p_quantity,
    'finish_at', v_finish_at,
    'status', 'training'
  );
END;
$$;


ALTER FUNCTION public.start_unit_training(p_player_region_building_id uuid, p_unit_type text, p_quantity integer) OWNER TO postgres;

--
-- Name: submit_battle_result(uuid, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_battle_result(p_player_id uuid, p_battle_id uuid, p_result text, p_winner_loss_percent numeric DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_battle RECORD;
    v_opponent_id uuid;
    v_final_winner uuid;
BEGIN
    -- 1️⃣ Lock battle
    SELECT *
    INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Battle không tồn tại';
    END IF;

    -- 2️⃣ Nếu đã xử lý rồi → return luôn
    IF v_battle.status = 'completed' THEN
        RETURN json_build_object(
            'status', 'already_processed',
            'winner_id', v_battle.winner_id
        );
    END IF;

    -- 3️⃣ Validate trạng thái
    IF v_battle.status <> 'in_progress' THEN
        RAISE EXCEPTION 'Battle chưa bắt đầu hoặc không hợp lệ';
    END IF;

    -- 4️⃣ Xác định đối thủ
    IF p_player_id = v_battle.player1_id THEN
        v_opponent_id := v_battle.player2_id;
    ELSIF p_player_id = v_battle.player2_id THEN
        v_opponent_id := v_battle.player1_id;
    ELSE
        RAISE EXCEPTION 'Player không thuộc trận này';
    END IF;

    -- 5️⃣ Xác định winner theo client
    IF p_result = 'win' THEN
        v_final_winner := p_player_id;
    ELSIF p_result = 'loss' THEN
        v_final_winner := v_opponent_id;
    ELSIF p_result = 'draw' THEN
        v_final_winner := NULL;
    ELSE
        RAISE EXCEPTION 'Kết quả không hợp lệ';
    END IF;

    -- clamp % thiệt hại an toàn
    IF p_winner_loss_percent < 0 THEN
        p_winner_loss_percent := 0;
    ELSIF p_winner_loss_percent > 100 THEN
        p_winner_loss_percent := 100;
    END IF;

    -- 6️⃣ Update battle state
    UPDATE public.battles
    SET 
        winner_id = v_final_winner,
        status = 'completed',
        ended_at = now()
    WHERE id = p_battle_id;

    -- 7️⃣ Apply casualty + insert result

    IF v_final_winner IS NULL THEN
        -- DRAW
        PERFORM public.resolve_region_battle_casualties(
            v_battle.player1_id,
            v_battle.region_id,
            100
        );

        PERFORM public.resolve_region_battle_casualties(
            v_battle.player2_id,
            v_battle.region_id,
            100
        );

        PERFORM public.insert_battle_result(v_battle.player1_id, p_battle_id, 'draw');
        PERFORM public.insert_battle_result(v_battle.player2_id, p_battle_id, 'draw');

    ELSE
        -- WIN/LOSS CASE

        -- winner loss %
        PERFORM public.resolve_region_battle_casualties(
            v_final_winner,
            v_battle.region_id,
            p_winner_loss_percent
        );

        -- loser full wipe
        PERFORM public.resolve_region_battle_casualties(
            v_opponent_id,
            v_battle.region_id,
            100
        );

        IF v_final_winner = v_battle.player1_id THEN
            PERFORM public.insert_battle_result(v_battle.player1_id, p_battle_id, 'win');
            PERFORM public.insert_battle_result(v_battle.player2_id, p_battle_id, 'loss');
        ELSE
            PERFORM public.insert_battle_result(v_battle.player2_id, p_battle_id, 'win');
            PERFORM public.insert_battle_result(v_battle.player1_id, p_battle_id, 'loss');
        END IF;
    END IF;

    -- 8️⃣ Return result
    RETURN json_build_object(
        'status', 'processed',
        'winner_id', v_final_winner,
        'winner_loss_percent', p_winner_loss_percent
    );

END;
$$;


ALTER FUNCTION public.submit_battle_result(p_player_id uuid, p_battle_id uuid, p_result text, p_winner_loss_percent numeric) OWNER TO postgres;

--
-- Name: subtract_execute(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_execute(p_player_id uuid, p_ops jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    op jsonb;
BEGIN
    -- Validate input
    IF jsonb_typeof(p_ops) <> 'array' THEN
        RAISE EXCEPTION 'p_ops must be a JSON array';
    END IF;

    FOR op IN
        SELECT * FROM jsonb_array_elements(p_ops)
    LOOP
        -- Validate type
        IF NOT (op ? 'type') THEN
            RAISE EXCEPTION 'Missing type in operation: %', op;
        END IF;

        CASE op->>'type'

            -- 💰 Currency
            WHEN 'currency' THEN
                IF NOT (op ? 'currency' AND op ? 'amount') THEN
                    RAISE EXCEPTION 'Invalid currency operation: %', op;
                END IF;

                PERFORM subtract_player_currency(
                    p_player_id,
                    op->>'currency',
                    (op->>'amount')::numeric
                );

            -- 🎒 Item
            WHEN 'item' THEN
                IF NOT (op ? 'item_id' AND op ? 'quantity') THEN
                    RAISE EXCEPTION 'Invalid item operation: %', op;
                END IF;

                PERFORM subtract_item(
                    p_player_id,
                    op->>'item_id',
                    (op->>'quantity')::int
                );

            ELSE
                RAISE EXCEPTION 'Unsupported operation type: %', op->>'type';
        END CASE;
    END LOOP;
END;
$$;


ALTER FUNCTION public.subtract_execute(p_player_id uuid, p_ops jsonb) OWNER TO postgres;

--
-- Name: subtract_item(uuid, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_item(p_player_id uuid, p_item_id character varying, p_quantity integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_available int;
BEGIN
    IF p_quantity <= 0 THEN
        RAISE EXCEPTION 'Quantity must be greater than 0';
    END IF;

    -- Lock inventory row
    PERFORM 1
    FROM player_items
    WHERE player_id = p_player_id
      AND item_id = p_item_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Player % does not own item %',
            p_player_id, p_item_id;
    END IF;

    -- Check từ VIEW (nguồn chân lý)
    SELECT available_quantity
    INTO v_available
    FROM view_player_available_items
    WHERE player_id = p_player_id
      AND item_id = p_item_id;

    IF v_available IS NULL OR v_available < p_quantity THEN
        RAISE EXCEPTION
            'Insufficient available item % for player %: have %, need %',
            p_item_id, p_player_id, COALESCE(v_available, 0), p_quantity;
    END IF;

    UPDATE player_items
    SET quantity = quantity - p_quantity
    WHERE player_id = p_player_id
      AND item_id = p_item_id;

    RETURN v_available - p_quantity;
END;
$$;


ALTER FUNCTION public.subtract_item(p_player_id uuid, p_item_id character varying, p_quantity integer) OWNER TO postgres;

--
-- Name: subtract_loot_box(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_loot_box(p_player_id uuid, p_loot_box_id text, p_amount integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id uuid;
BEGIN

    UPDATE player_loot_boxes
    SET
        amount = amount - p_amount,
        updated_at = now()
    WHERE player_id = p_player_id
    AND loot_box_id = p_loot_box_id
    AND amount >= p_amount
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
        RAISE EXCEPTION 
        'Not enough loot boxes or loot box not found for player % and loot_box %',
        p_player_id, p_loot_box_id;
    END IF;

    RETURN v_id;

END;
$$;


ALTER FUNCTION public.subtract_loot_box(p_player_id uuid, p_loot_box_id text, p_amount integer) OWNER TO postgres;

--
-- Name: subtract_player_currency(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_player_currency(p_player_id uuid, p_currency_type text, p_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_amount numeric;
BEGIN
    -- Lấy số dư hiện tại và khóa dòng để tránh race condition
    SELECT amount INTO current_amount
    FROM public.player_wallets
    WHERE player_id = p_player_id AND currency_type = p_currency_type
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player % does not have currency %', p_player_id, p_currency_type;
    END IF;

    -- Kiểm tra đủ tiền
    IF current_amount < p_amount THEN
        RAISE EXCEPTION 'Insufficient % balance for player %: have %, need %', 
            p_currency_type, p_player_id, current_amount, p_amount;
    END IF;

    -- Trừ tiền
    UPDATE public.player_wallets
    SET amount = amount - p_amount,
        last_updated = CURRENT_TIMESTAMP
    WHERE player_id = p_player_id AND currency_type = p_currency_type;

    RETURN current_amount - p_amount;
END;
$$;


ALTER FUNCTION public.subtract_player_currency(p_player_id uuid, p_currency_type text, p_amount numeric) OWNER TO postgres;

--
-- Name: subtract_resource_by_player_region(uuid, text, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource_code character varying, p_amount integer) RETURNS TABLE(out_resource_code character varying, out_amount integer, out_max_amount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
BEGIN
    -- 1️⃣ Validate input
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be positive: %', p_amount;
    END IF;

    -- 2️⃣ Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % does not own region %', p_player_id, p_region_id;
    END IF;

    -- 3️⃣ Trừ trực tiếp + check đủ resource (atomic)
    UPDATE region_resources
    SET 
        amount = amount - p_amount,
        updated_at = now()
    WHERE player_region_id = v_player_region_id
      AND resource_code = p_resource_code
      AND amount >= p_amount
    RETURNING 
        resource_code,
        amount,
        max_amount
    INTO out_resource_code, out_amount, out_max_amount;

    -- 4️⃣ Nếu không update được → lỗi
    IF NOT FOUND THEN
        RAISE EXCEPTION 
            'Not enough resource or resource not found: %', 
            p_resource_code;
    END IF;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.subtract_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource_code character varying, p_amount integer) OWNER TO postgres;

--
-- Name: subtract_resource_by_player_region(uuid, text, public.resource_type, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.subtract_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource public.resource_type, p_amount integer) RETURNS TABLE(out_resource public.resource_type, out_amount integer, out_max_amount integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
    v_current_amount int;
BEGIN
    -- 1️⃣ Validate input
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount to subtract must be positive: %', p_amount;
    END IF;

    -- 2️⃣ Lấy player_region_id
    SELECT id
    INTO v_player_region_id
    FROM player_regions
    WHERE player_id = p_player_id
      AND region_id = p_region_id
      AND is_active = true;

    IF v_player_region_id IS NULL THEN
        RAISE EXCEPTION 'Player % does not own region %', p_player_id, p_region_id;
    END IF;

    -- 3️⃣ Lấy số lượng hiện tại
    SELECT amount
    INTO v_current_amount
    FROM region_resources
    WHERE player_region_id = v_player_region_id
      AND resource = p_resource;

    IF v_current_amount IS NULL THEN
        RAISE EXCEPTION 'Resource % does not exist for player region %', p_resource, p_region_id;
    END IF;

    -- 4️⃣ Kiểm tra không trừ quá số lượng hiện có
    IF v_current_amount < p_amount THEN
        RAISE EXCEPTION 'Cannot subtract % from % (only % available)', p_amount, p_resource, v_current_amount;
    END IF;

    -- 5️⃣ Trừ resource
    UPDATE region_resources
    SET
        amount = amount - p_amount,
        updated_at = now()
    WHERE player_region_id = v_player_region_id
      AND resource = p_resource
    RETURNING resource AS out_resource,
              amount AS out_amount,
              max_amount AS out_max_amount
    INTO out_resource, out_amount, out_max_amount;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.subtract_resource_by_player_region(p_player_id uuid, p_region_id text, p_resource public.resource_type, p_amount integer) OWNER TO postgres;

--
-- Name: talk_with_beauty(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.talk_with_beauty(p_player_id uuid, p_beauty_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_remaining_gold numeric;
    v_intimacy_gain int;
    v_current_points int;
    v_current_level int;
BEGIN
    -- 1. Random thân mật 1 -> 10
    v_intimacy_gain := FLOOR(random() * 10 + 1);

    -- 2. Trừ 50 vàng
    v_remaining_gold := public.subtract_player_currency(
        p_player_id,
        'gold',
        50
    );

    -- 3. Tăng thân mật
    PERFORM public.add_intimacy_point_single(
        p_player_id,
        p_beauty_id,
        v_intimacy_gain
    );

    -- 4. Lấy trạng thái mới
    SELECT intimacy_points, intimacy_level
    INTO v_current_points, v_current_level
    FROM public.player_beauties
    WHERE player_id = p_player_id
      AND beauty_id = p_beauty_id;

    -- 5. Log activity (fix luôn hardcode)
    INSERT INTO public.player_activities (
        player_id,
        activity_type
    )
    VALUES (
        p_player_id,
        'beauty.chat'
    );

    -- 6. Return JSON
    RETURN json_build_object(
        'action', 'talk_with_beauty',
        'success', true,
        'cost_gold', 50,
        'remaining_gold', v_remaining_gold,
        'intimacy_points_gained', v_intimacy_gain,
        'current_intimacy_points', v_current_points,
        'current_intimacy_level', v_current_level
    );
END;
$$;


ALTER FUNCTION public.talk_with_beauty(p_player_id uuid, p_beauty_id text) OWNER TO postgres;

--
-- Name: test_loop_reward_tables(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.test_loop_reward_tables(p_tables jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    t_table RECORD;
    v_result jsonb := '[]'::jsonb;
BEGIN

    FOR t_table IN
        SELECT *
        FROM jsonb_to_recordset(p_tables) AS x(
            table_id text,
            table_name text,
            anti_duplicate boolean,
            distribution_type text,
            first_time_enabled boolean,
            duplicate_protection numeric
        )
    LOOP

        -- Debug
        RAISE NOTICE 'Table: %, Name: %, Type: %',
            t_table.table_id,
            t_table.table_name,
            t_table.distribution_type;

        -- Ví dụ xử lý
        v_result := v_result || jsonb_build_object(
            'table_id', t_table.table_id,
            'table_name', t_table.table_name,
            'distribution_type', t_table.distribution_type,
            'anti_duplicate', t_table.anti_duplicate
        );

    END LOOP;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.test_loop_reward_tables(p_tables jsonb) OWNER TO postgres;

--
-- Name: train_troops(uuid, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.train_troops(p_player_region_building_id uuid, p_unit_id character varying, p_quantity integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player_region_id uuid;
    v_building_type varchar;
    v_level int;
    v_rate numeric;
    v_finish timestamptz;
BEGIN

    IF p_quantity <= 0 THEN
        RETURN 'Số lượng quân không hợp lệ';
    END IF;


    -- Lấy building info
    SELECT
        player_region_id,
        building_type,
        level
    INTO
        v_player_region_id,
        v_building_type,
        v_level
    FROM public.player_region_buildings
    WHERE id = p_player_region_building_id;

    IF NOT FOUND THEN
        RETURN 'Không tìm thấy công trình';
    END IF;


    -- Lấy tốc độ đào tạo
    SELECT training_rate_per_hour
    INTO v_rate
    FROM public.building_unit_training
    WHERE building_type = v_building_type
      AND level = v_level
      AND unit_type = p_unit_id;

    IF v_rate IS NULL OR v_rate <= 0 THEN
        RETURN 'Công trình không đào tạo được loại quân này';
    END IF;


    /*
     * Kiểm tra toàn bộ chi phí
     */
    IF EXISTS (
        SELECT 1
        FROM public.unit_training_cost utc
        LEFT JOIN public.region_resources rr
            ON rr.player_region_id = v_player_region_id
            AND rr.resource_code = utc.resource_code
        WHERE utc.unit_id = p_unit_id
          AND COALESCE(rr.amount, 0)
              < utc.resource_amount * p_quantity
    ) THEN
        RETURN 'Không đủ tài nguyên để đào tạo quân';
    END IF;


    /*
     * Trừ toàn bộ chi phí.
     * Mỗi resource chỉ UPDATE một lần.
     */
    UPDATE public.region_resources rr
    SET
        amount = rr.amount - (utc.resource_amount * p_quantity),
        updated_at = now()
    FROM public.unit_training_cost utc
    WHERE utc.unit_id = p_unit_id
      AND rr.player_region_id = v_player_region_id
      AND rr.resource_code = utc.resource_code;


    -- Tính thời gian hoàn thành
    v_finish :=
        now()
        + (p_quantity / v_rate) * interval '1 hour';


    -- Tạo training queue
    INSERT INTO public.unit_training_queue (
        player_region_building_id,
        unit_type,
        quantity,
        finish_at
    )
    VALUES (
        p_player_region_building_id,
        p_unit_id,
        p_quantity,
        v_finish
    );


    RETURN
        'Đã bắt đầu đào tạo '
        || p_quantity
        || ' quân '
        || p_unit_id;

END;
$$;


ALTER FUNCTION public.train_troops(p_player_region_building_id uuid, p_unit_id character varying, p_quantity integer) OWNER TO postgres;

--
-- Name: transaction_execute(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transaction_execute(p_player_id uuid, p_ops jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    op jsonb;
    sql text;
BEGIN
    FOR op IN SELECT * FROM jsonb_array_elements(p_ops)
    LOOP
        IF op ? 'amount' THEN
            -- add_gold / subtract_gold
            sql := format(
                'SELECT %I(%L, %s)',
                op->>'func',
                p_player_id,
                (op->>'amount')::int
            );
        ELSIF op ? 'quantity' THEN
            -- item, loot box
            sql := format(
                'SELECT %I(%L, %L, %s)',
                op->>'func',
                p_player_id,
                op->>'target_id',
                (op->>'quantity')::int
            );
        ELSE
            -- hero / beauty / loot box without quantity
            sql := format(
                'SELECT %I(%L, %L)',
                op->>'func',
                p_player_id,
                op->>'target_id'
            );
        END IF;

        EXECUTE sql;
    END LOOP;
END;
$$;


ALTER FUNCTION public.transaction_execute(p_player_id uuid, p_ops jsonb) OWNER TO postgres;

--
-- Name: transfer_region_resources(uuid, text, text, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_region_resources(p_player_id uuid, p_from_region_id text, p_to_region_id text, p_resource_code character varying, p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_player_region_id uuid;
    v_to_player_region_id uuid;

    v_from_amount integer;

    v_transfer_fee integer;
    v_total_deduct integer;

BEGIN

    -- Validate amount
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Transfer amount must be greater than 0';
    END IF;


    -- Không chuyển cùng khu vực
    IF p_from_region_id = p_to_region_id THEN
        RAISE EXCEPTION 'Source and destination region cannot be same';
    END IF;


    -- Kiểm tra resource tồn tại
    IF NOT EXISTS (
        SELECT 1
        FROM public.resource_types
        WHERE resource_code = p_resource_code
    ) THEN
        RAISE EXCEPTION
            'Resource % does not exist',
            p_resource_code;
    END IF;


    -- Lấy region nguồn
    SELECT id
    INTO v_from_player_region_id
    FROM public.player_regions
    WHERE player_id = p_player_id
      AND region_id = p_from_region_id
    LIMIT 1;


    IF v_from_player_region_id IS NULL THEN
        RAISE EXCEPTION
            'Source region not found';
    END IF;


    -- Lấy region đích
    SELECT id
    INTO v_to_player_region_id
    FROM public.player_regions
    WHERE player_id = p_player_id
      AND region_id = p_to_region_id
    LIMIT 1;


    IF v_to_player_region_id IS NULL THEN
        RAISE EXCEPTION
            'Destination region not found';
    END IF;


    /*
       Tính phí vận chuyển 30%
    */
    v_transfer_fee := CEIL(p_amount * 0.30);

    v_total_deduct := p_amount + v_transfer_fee;


    /*
       Lock resource nguồn
    */
    SELECT amount
    INTO v_from_amount
    FROM public.region_resources
    WHERE player_region_id = v_from_player_region_id
      AND resource_code = p_resource_code
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Resource % not found in source region',
            p_resource_code;
    END IF;


    -- Kiểm tra đủ tài nguyên
    IF v_from_amount < v_total_deduct THEN
        RAISE EXCEPTION
            'Not enough %.
             Available %, required % including transport fee',
            p_resource_code,
            v_from_amount,
            v_total_deduct;
    END IF;



    /*
       Trừ nguồn
    */
    UPDATE public.region_resources
    SET
        amount = amount - v_total_deduct,
        updated_at = now()
    WHERE player_region_id = v_from_player_region_id
      AND resource_code = p_resource_code;



    /*
       Cộng vào đích
       Nếu chưa có resource thì tạo mới
    */
    INSERT INTO public.region_resources (
        player_region_id,
        resource_code,
        amount,
        max_amount,
        last_collected_at
    )
    VALUES (
        v_to_player_region_id,
        p_resource_code,
        p_amount,
        0,
        now()
    )
    ON CONFLICT (player_region_id, resource_code)
    DO UPDATE
    SET
        amount = region_resources.amount + EXCLUDED.amount,
        updated_at = now();



    RETURN jsonb_build_object(
        'success', true,
        'from_region_id', p_from_region_id,
        'to_region_id', p_to_region_id,
        'resource_code', p_resource_code,
        'transfer_amount', p_amount,
        'transport_fee', v_transfer_fee,
        'total_deducted', v_total_deduct
    );

END;
$$;


ALTER FUNCTION public.transfer_region_resources(p_player_id uuid, p_from_region_id text, p_to_region_id text, p_resource_code character varying, p_amount integer) OWNER TO postgres;

--
-- Name: unequip_general_item_by_player(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unequip_general_item_by_player(p_player_id uuid, p_general_id text, p_slot_name text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_player_general_id uuid;
    v_slot_column text;
BEGIN
    -- 1. Resolve player_general_id
    SELECT id
    INTO v_player_general_id
    FROM player_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id;

    IF v_player_general_id IS NULL THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', format('General % does not belong to player %', p_general_id, p_player_id)
        );
    END IF;

    -- 2. Map slot_name → column in equipment_items
    v_slot_column := CASE lower(p_slot_name)
        WHEN 'weapon' THEN 'weapon_id'
        WHEN 'armor' THEN 'armor_id'
        WHEN 'helmet' THEN 'helmet_id'
        WHEN 'cloak' THEN 'cloak_id'
        WHEN 'boots' THEN 'boots_id'
        WHEN 'ring' THEN 'ring_id'
        WHEN 'shield' THEN 'shield_id'
        ELSE NULL
    END;

    IF v_slot_column IS NULL THEN
        RETURN jsonb_build_object(
            'status', 'error',
            'message', format('Unsupported slot name: %', p_slot_name)
        );
    END IF;

    -- 3. Unequip: set slot to NULL
    EXECUTE format(
        'UPDATE equipment_items
         SET %I = NULL,
             updated_at = now()
         WHERE player_general_id = $1',
        v_slot_column
    )
    USING v_player_general_id;

    RETURN jsonb_build_object('status', 'success');

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('status', 'error', 'message', SQLERRM);

END;
$_$;


ALTER FUNCTION public.unequip_general_item_by_player(p_player_id uuid, p_general_id text, p_slot_name text) OWNER TO postgres;

--
-- Name: unequip_item(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unequip_item(p_player_id uuid, p_general_id uuid, p_item_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    hero_id uuid;
    removed_item jsonb;
BEGIN
    -- Lấy player_general_id dựa trên player_id và general_id
    SELECT id INTO hero_id
    FROM public.player_generals
    WHERE player_id = p_player_id
      AND general_id = p_general_id
    LIMIT 1;

    IF hero_id IS NULL THEN
        RAISE EXCEPTION 'No hero found for player % with general %', p_player_id, p_general_id;
    END IF;

    -- Lấy JSON của item trước khi xóa
    SELECT to_jsonb(ei.*) INTO removed_item
    FROM public.equipment_items ei
    WHERE ei.id = p_item_id
      AND ei.player_general_id = hero_id
    LIMIT 1;

    -- Xóa item
    DELETE FROM public.equipment_items
    WHERE id = p_item_id
      AND player_general_id = hero_id;

    -- Trả về JSON của item đã bị remove
    RETURN COALESCE(removed_item, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.unequip_item(p_player_id uuid, p_general_id uuid, p_item_id character varying) OWNER TO postgres;

--
-- Name: unequip_item_from_unit(uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unequip_item_from_unit(p_player_id uuid, p_unit_id character varying, p_slot text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_player_unit player_units;
    v_item_id varchar;
BEGIN
    -- 1️⃣ Lock unit
    SELECT *
    INTO v_player_unit
    FROM player_units
    WHERE player_id = p_player_id
      AND unit_id = p_unit_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player does not own this unit';
    END IF;

    -- 2️⃣ Validate slot hợp lệ (anti SQL injection)
    IF p_slot NOT IN (
        'weapon_item_id',
        'armor_item_id',
        'helmet_item_id',
        'cloak_item_id',
        'boots_item_id',
        'shield_item_id',
        'mount_item_id',
        'accessory_item_id',
        'ring1_item_id',
        'ring2_item_id'
    ) THEN
        RAISE EXCEPTION 'Invalid slot %', p_slot;
    END IF;

    -- 3️⃣ Lấy item hiện tại trong slot
    EXECUTE format(
        'SELECT %I FROM player_units WHERE id = $1',
        p_slot
    )
    INTO v_item_id
    USING v_player_unit.id;

    IF v_item_id IS NULL THEN
        RAISE EXCEPTION 'Slot % is already empty', p_slot;
    END IF;

    -- 4️⃣ Set slot = NULL
    EXECUTE format(
        'UPDATE player_units SET %I = NULL WHERE id = $1',
        p_slot
    )
    USING v_player_unit.id;

    -- 5️⃣ (Optional) Trả item về inventory
    UPDATE player_items
    SET quantity = quantity + 1
    WHERE player_id = p_player_id
      AND item_id = v_item_id;

END;
$_$;


ALTER FUNCTION public.unequip_item_from_unit(p_player_id uuid, p_unit_id character varying, p_slot text) OWNER TO postgres;

--
-- Name: unlock_general_skill(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unlock_general_skill(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_general_id text;
    v_max_level int;
    v_player_general_skill_id uuid;
    v_ops jsonb := '[]'::jsonb;
    v_cost RECORD;
BEGIN

    -- =========================================================
    -- 1. Kiểm tra tướng thuộc player
    -- =========================================================
    SELECT
        pg.general_id
    INTO
        v_general_id
    FROM public.player_generals pg
    WHERE pg.id = p_player_general_id
      AND pg.player_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tướng không tồn tại hoặc không thuộc về người chơi';
    END IF;


    -- =========================================================
    -- 2. Kiểm tra skill thuộc đúng tướng
    -- =========================================================
    SELECT
        gs.max_level
    INTO
        v_max_level
    FROM public.general_skills gs
    WHERE gs.id = p_general_skill_id
      AND gs.general_id = v_general_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Kỹ năng không thuộc về tướng này';
    END IF;


    -- =========================================================
    -- 3. Kiểm tra skill đã unlock chưa
    -- =========================================================
    IF EXISTS (
        SELECT 1
        FROM public.player_general_skills pgs
        WHERE pgs.player_general_id = p_player_general_id
          AND pgs.general_skill_id = p_general_skill_id
    ) THEN
        RAISE EXCEPTION
            'Kỹ năng này đã được mở khóa';
    END IF;


    -- =========================================================
    -- 4. Lấy chi phí unlock (target_level = 1)
    -- =========================================================
    FOR v_cost IN
        SELECT
            currency_type,
            item_id,
            amount
        FROM public.general_skill_costs
        WHERE general_skill_id = p_general_skill_id
          AND target_level = 1
        ORDER BY id
    LOOP

        -- Phí currency
        IF v_cost.currency_type IS NOT NULL THEN

            v_ops := v_ops || jsonb_build_array(
                jsonb_build_object(
                    'type', 'currency',
                    'currency', v_cost.currency_type,
                    'amount', v_cost.amount
                )
            );

        -- Phí item
        ELSIF v_cost.item_id IS NOT NULL THEN

            v_ops := v_ops || jsonb_build_array(
                jsonb_build_object(
                    'type', 'item',
                    'item_id', v_cost.item_id,
                    'quantity', v_cost.amount
                )
            );

        END IF;

    END LOOP;


    -- =========================================================
    -- 5. Trừ toàn bộ chi phí
    -- =========================================================
    IF jsonb_array_length(v_ops) > 0 THEN
        PERFORM public.subtract_execute(
            p_player_id,
            v_ops
        );
    END IF;


    -- =========================================================
    -- 6. Tạo skill cho player
    -- =========================================================
    INSERT INTO public.player_general_skills (
        player_general_id,
        general_skill_id,
        level,
        max_level,
        is_unlocked
    )
    VALUES (
        p_player_general_id,
        p_general_skill_id,
        1,
        v_max_level,
        true
    )
    RETURNING id
    INTO v_player_general_skill_id;


    -- =========================================================
    -- 7. Trả kết quả
    -- =========================================================
    RETURN jsonb_build_object(
        'success', true,
        'player_general_skill_id', v_player_general_skill_id,
        'player_general_id', p_player_general_id,
        'general_skill_id', p_general_skill_id,
        'level', 1,
        'max_level', v_max_level,
        'is_unlocked', true,
        'costs', v_ops
    );

END;
$$;


ALTER FUNCTION public.unlock_general_skill(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) OWNER TO postgres;

--
-- Name: unlock_main_quest_by_condition(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unlock_main_quest_by_condition(p_player_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_current_unlock    integer;
    v_next_unlock       integer;
    v_all_completed     boolean;
    v_next_quest_count  integer;
    v_row_count         integer;
BEGIN
    -- 1. Lấy tiến trình mở khóa hiện tại
    SELECT current_main_quest_unlocked
    INTO v_current_unlock
    FROM player_stats
    WHERE player_id = p_player_id;

    IF v_current_unlock IS NULL THEN
        RAISE EXCEPTION 'Không tìm thấy thông tin người chơi.';
    END IF;

    -- 2. Kiểm tra tất cả main quest đang mở
    --    đã hoàn thành + nhận thưởng
    SELECT NOT EXISTS (
        SELECT 1
        FROM quests q
        LEFT JOIN player_quest_progress pqp
            ON pqp.player_id = p_player_id
           AND pqp.quest_id = q.id
        WHERE q.category = 'main'
          AND q.status = 'active'
          AND q.quest_main_unlock_increment <= v_current_unlock
          AND (
              pqp.completed IS NOT TRUE
              OR pqp.claimed IS NOT TRUE
          )
    )
    INTO v_all_completed;

    -- Chưa hoàn thành hết → không tăng
    IF NOT v_all_completed THEN
        RETURN v_current_unlock;
    END IF;

    -- 3. Xác định mốc tiếp theo
    v_next_unlock := v_current_unlock + 1;

    -- 4. Kiểm tra còn quest ở mốc tiếp theo không
    SELECT COUNT(*)
    INTO v_next_quest_count
    FROM quests q
    WHERE q.category = 'main'
      AND q.status = 'active'
      AND q.quest_main_unlock_increment = v_next_unlock;

    -- Hết quest → không tăng nữa
    IF v_next_quest_count = 0 THEN
        RETURN v_current_unlock;
    END IF;

    -- 5. Mở mốc tiếp theo
    UPDATE player_stats
    SET current_main_quest_unlocked = v_next_unlock,
        updated_at = now()
    WHERE player_id = p_player_id;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;

    -- 6. Chỉ xóa progress quest cũ nếu mở khóa thành công
    IF v_row_count = 1 THEN
        DELETE FROM player_quest_progress
        WHERE player_id = p_player_id
          AND quest_id IN (
              SELECT q.id
              FROM quests q
              WHERE q.category = 'main'
                AND q.quest_main_unlock_increment <= v_current_unlock
          );
    END IF;

    -- 7. Trả về mốc mở khóa mới
    RETURN v_next_unlock;
END;
$$;


ALTER FUNCTION public.unlock_main_quest_by_condition(p_player_id uuid) OWNER TO postgres;

