-- Name: update_alliance_member_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_alliance_member_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE alliances
        SET members = members + 1
        WHERE id = NEW.alliance_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE alliances
        SET members = members - 1
        WHERE id = OLD.alliance_id;
    END IF;

    RETURN NULL;
END;
$$;


