--
-- Name: update_combat_casualties(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_combat_casualties(p_unit_results jsonb) RETURNS TABLE(unit_type character varying, old_quantity integer, new_quantity integer, lost_quantity integer, hp_percent double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unit_record RECORD;
    v_current_quantity INTEGER;
    v_new_quantity INTEGER;
    v_lost_quantity INTEGER;
    v_hp_percent FLOAT;
    v_status TEXT;
    v_found BOOLEAN := FALSE;
    v_unit_count INTEGER;
BEGIN
    -- Validate input
    IF p_unit_results IS NULL OR jsonb_array_length(p_unit_results) = 0 THEN
        RAISE NOTICE 'No unit results provided';
        RETURN;
    END IF;

    FOR v_unit_record IN
        SELECT
            value->>'unit_type' AS unit_type_val,
            (value->>'hp_percent')::FLOAT AS hp_percent
        FROM jsonb_array_elements(p_unit_results)
    LOOP
        -- Validate hp_percent
        IF v_unit_record.hp_percent < 0 OR v_unit_record.hp_percent > 100 THEN
            RAISE NOTICE 'Invalid hp_percent: % for unit_type: %', 
                v_unit_record.hp_percent, v_unit_record.unit_type_val;
            CONTINUE;
        END IF;

        -- Kiểm tra có bao nhiêu unit với unit_type này (không cần battle_id)
        SELECT COUNT(*)
        INTO v_unit_count
        FROM combat_troops ct
        WHERE ct.unit_type = v_unit_record.unit_type_val;

        IF v_unit_count = 0 THEN
            RAISE NOTICE 'Unit type % not found', 
                v_unit_record.unit_type_val;
            CONTINUE;
        END IF;

        -- Lấy tổng số lượng hiện tại của tất cả unit có cùng unit_type (không cần battle_id)
        SELECT COALESCE(SUM(ct.current_quantity), 0)
        INTO v_current_quantity
        FROM combat_troops ct
        WHERE ct.unit_type = v_unit_record.unit_type_val;

        v_found := TRUE;

        -- Chuyển % HP về số thập phân
        v_hp_percent := v_unit_record.hp_percent / 100.0;

        -- Tính số lượng còn lại = tổng current * % HP
        v_new_quantity := ROUND(v_current_quantity * v_hp_percent);

        -- Logic đảm bảo
        IF v_hp_percent <= 0 THEN
            v_new_quantity := 0;
            v_status := 'defeated';
        ELSIF v_new_quantity = 0 THEN
            v_new_quantity := 1;
            v_status := 'fighting';
        ELSE
            v_status := 'fighting';
        END IF;

        -- Tính số quân mất = current - new
        v_lost_quantity := v_current_quantity - v_new_quantity;

        -- Cập nhật dữ liệu cho TẤT CẢ unit có cùng unit_type (không cần battle_id)
        UPDATE combat_troops ct
        SET
            current_quantity = v_new_quantity,
            lost_quantity = COALESCE(ct.lost_quantity, 0) + v_lost_quantity,
            survived_quantity = v_new_quantity,
            status = v_status,
            updated_at = CURRENT_TIMESTAMP,
            resolved_at = CASE
                WHEN v_new_quantity = 0 THEN CURRENT_TIMESTAMP
                ELSE ct.resolved_at
            END
        WHERE ct.unit_type = v_unit_record.unit_type_val;

        -- Trả kết quả
        unit_type := v_unit_record.unit_type_val;
        old_quantity := v_current_quantity;
        new_quantity := v_new_quantity;
        lost_quantity := v_lost_quantity;
        hp_percent := v_unit_record.hp_percent;

        RETURN NEXT;
    END LOOP;

    IF NOT v_found THEN
        RAISE NOTICE 'No valid units found to update';
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION public.update_combat_casualties(p_unit_results jsonb) OWNER TO postgres;

--
-- Name: update_combat_casualties(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_combat_casualties(p_battle_id uuid, p_unit_results jsonb) RETURNS TABLE(unit_type character varying, old_quantity integer, new_quantity integer, lost_quantity integer, hp_percent double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unit_record RECORD;
    v_current_quantity INTEGER;
    v_new_quantity INTEGER;
    v_lost_quantity INTEGER;
    v_hp_percent FLOAT;
    v_status TEXT;
    v_found BOOLEAN := FALSE;
    v_unit_count INTEGER;
BEGIN
    IF p_unit_results IS NULL OR jsonb_array_length(p_unit_results) = 0 THEN
        RAISE NOTICE 'No unit results provided';
        RETURN;
    END IF;

    FOR v_unit_record IN
        SELECT
            value->>'unit_type' AS unit_type_val,
            (value->>'hp_percent')::FLOAT AS hp_percent
        FROM jsonb_array_elements(p_unit_results)
    LOOP
        IF v_unit_record.hp_percent < 0 OR v_unit_record.hp_percent > 100 THEN
            RAISE NOTICE 'Invalid hp_percent: % for unit_type: %',
                v_unit_record.hp_percent, v_unit_record.unit_type_val;
            CONTINUE;
        END IF;

        SELECT COUNT(*)
        INTO v_unit_count
        FROM combat_troops ct
        WHERE ct.battle_id = p_battle_id
          AND ct.unit_type = v_unit_record.unit_type_val;

        IF v_unit_count = 0 THEN
            RAISE NOTICE 'Unit type % not found in battle %',
                v_unit_record.unit_type_val, p_battle_id;
            CONTINUE;
        END IF;

        SELECT COALESCE(SUM(ct.current_quantity), 0)
        INTO v_current_quantity
        FROM combat_troops ct
        WHERE ct.battle_id = p_battle_id
          AND ct.unit_type = v_unit_record.unit_type_val;

        v_found := TRUE;

        v_hp_percent := v_unit_record.hp_percent / 100.0;

        v_new_quantity := ROUND(v_current_quantity * v_hp_percent);

        IF v_hp_percent <= 0 THEN
            v_new_quantity := 0;
            v_status := 'defeated';
        ELSIF v_new_quantity = 0 THEN
            v_new_quantity := 1;
            v_status := 'fighting';
        ELSE
            v_status := 'fighting';
        END IF;

        v_lost_quantity := v_current_quantity - v_new_quantity;

        UPDATE combat_troops ct
        SET
            current_quantity = v_new_quantity,
            lost_quantity = COALESCE(ct.lost_quantity, 0) + v_lost_quantity,
            survived_quantity = v_new_quantity,
            status = v_status,
            updated_at = CURRENT_TIMESTAMP,
            resolved_at = CASE
                WHEN v_new_quantity = 0 THEN CURRENT_TIMESTAMP
                ELSE ct.resolved_at
            END
        WHERE ct.battle_id = p_battle_id
          AND ct.unit_type = v_unit_record.unit_type_val;

        unit_type := v_unit_record.unit_type_val;
        old_quantity := v_current_quantity;
        new_quantity := v_new_quantity;
        lost_quantity := v_lost_quantity;
        hp_percent := v_unit_record.hp_percent;

        RETURN NEXT;
    END LOOP;

    IF NOT v_found THEN
        RAISE NOTICE 'No valid units found to update';
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION public.update_combat_casualties(p_battle_id uuid, p_unit_results jsonb) OWNER TO postgres;

--
-- Name: update_combat_casualties(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_combat_casualties(p_battle_id uuid, p_player_id uuid, p_unit_results jsonb) RETURNS TABLE(unit_type character varying, old_quantity integer, new_quantity integer, lost_quantity integer, hp_percent double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_unit_record RECORD;
    v_current_quantity INTEGER;
    v_new_quantity INTEGER;
    v_lost_quantity INTEGER;
BEGIN

    IF p_unit_results IS NULL 
       OR jsonb_array_length(p_unit_results) = 0 THEN
        RETURN;
    END IF;


    FOR v_unit_record IN
        SELECT
            value->>'unit_type' AS unit_type_val,
            (value->>'hp_percent')::FLOAT AS hp_percent_val
        FROM jsonb_array_elements(p_unit_results)
    LOOP

        -- validate hp
        IF v_unit_record.hp_percent_val < 0 
           OR v_unit_record.hp_percent_val > 100 THEN

            RAISE NOTICE 'Invalid hp_percent % for unit %',
                v_unit_record.hp_percent_val,
                v_unit_record.unit_type_val;

            CONTINUE;
        END IF;


        -- lấy quân đúng player trong battle
        SELECT COALESCE(SUM(ct.current_quantity), 0)
        INTO v_current_quantity
        FROM public.combat_troops ct
        WHERE ct.battle_id = p_battle_id
          AND ct.player_id = p_player_id
          AND ct.unit_type = v_unit_record.unit_type_val;


        IF v_current_quantity = 0 THEN
            RAISE NOTICE 'Unit % not found for player % in battle %',
                v_unit_record.unit_type_val,
                p_player_id,
                p_battle_id;

            CONTINUE;
        END IF;


        -- tính số quân còn lại
        v_new_quantity := ROUND(
            v_current_quantity * (v_unit_record.hp_percent_val / 100.0)
        );


        IF v_new_quantity < 0 THEN
            v_new_quantity := 0;
        END IF;


        v_lost_quantity := v_current_quantity - v_new_quantity;


        -- update combat state
        UPDATE public.combat_troops AS ct
        SET
            current_quantity = v_new_quantity,
            lost_quantity = ct.lost_quantity + v_lost_quantity,
            survived_quantity = v_new_quantity,

            status = CASE
                WHEN v_new_quantity = 0 THEN 'defeated'
                ELSE 'fighting'
            END,

            updated_at = CURRENT_TIMESTAMP,

            resolved_at = CASE
                WHEN v_new_quantity = 0 THEN CURRENT_TIMESTAMP
                ELSE ct.resolved_at
            END

        WHERE ct.battle_id = p_battle_id
          AND ct.player_id = p_player_id
          AND ct.unit_type = v_unit_record.unit_type_val;


        -- return result
        unit_type := v_unit_record.unit_type_val;
        old_quantity := v_current_quantity;
        new_quantity := v_new_quantity;
        lost_quantity := v_lost_quantity;
        hp_percent := v_unit_record.hp_percent_val;

        RETURN NEXT;

    END LOOP;

END;
$$;


ALTER FUNCTION public.update_combat_casualties(p_battle_id uuid, p_player_id uuid, p_unit_results jsonb) OWNER TO postgres;

