--
-- Name: upgrade_building(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upgrade_building(p_player_building_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_building RECORD;
    v_base_building RECORD;
    v_attr RECORD;

    v_cost_result jsonb;
    v_cost jsonb;

    v_upgrade_time int;
    v_player_region_id uuid;

    v_resource_code text;
    v_resource_amount int;
    v_current_amount int;
BEGIN

    -- 1. Lock building
    SELECT *
    INTO v_building
    FROM public.player_region_buildings
    WHERE id = p_player_building_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building not found'
        );
    END IF;


    -- 2. Check đang upgrading
    IF v_building.upgrading THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building is already upgrading',
            'level', v_building.level,
            'upgrade_finish_at', v_building.upgrade_finish_at
        );
    END IF;


    -- 3. Lấy base building
    SELECT *
    INTO v_base_building
    FROM public.base_buildings
    WHERE type = v_building.building_type;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building type not found'
        );
    END IF;


    -- 4. Check max level
    IF v_building.level >= v_base_building.max_level THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building is already at max level',
            'level', v_building.level,
            'max_level', v_base_building.max_level
        );
    END IF;


    -- 5. Lấy upgrade cost
    v_cost_result :=
        public.get_player_region_building_upgrade_cost(
            p_player_building_id
        );

    IF COALESCE(
        jsonb_array_length(v_cost_result->'costs'),
        0
    ) = 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Upgrade cost not found',
            'level', v_building.level,
            'target_level', v_building.level + 1
        );
    END IF;


    -- 6. Lấy upgrade time
    SELECT *
    INTO v_attr
    FROM public.building_attribute_detail
    WHERE building_type = v_building.building_type
      AND level = v_building.level;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Building attribute detail not found',
            'level', v_building.level
        );
    END IF;

    v_upgrade_time :=
        COALESCE(v_attr.build_time_seconds, 0);


    -- 7. Player region
    v_player_region_id :=
        v_building.player_region_id;


    -- =====================================================
    -- 8. VALIDATE RESOURCE
    -- =====================================================

    FOR v_cost IN
        SELECT value
        FROM jsonb_array_elements(
            v_cost_result->'costs'
        )
    LOOP

        v_resource_code :=
            v_cost->>'resource_code';

        v_resource_amount :=
            (v_cost->>'resource_amount')::int;


        SELECT amount
        INTO v_current_amount
        FROM public.region_resources
        WHERE player_region_id = v_player_region_id
          AND resource_code = v_resource_code
        FOR UPDATE;


        -- Không có resource record
        IF NOT FOUND THEN
            RETURN json_build_object(
                'success', false,
                'message', 'Resource not found',
                'resource_code', v_resource_code
            );
        END IF;


        -- Không đủ resource
        IF v_current_amount < v_resource_amount THEN
            RETURN json_build_object(
                'success', false,
                'message', 'Insufficient resource',
                'resource_code', v_resource_code,
                'required', v_resource_amount,
                'available', v_current_amount
            );
        END IF;

    END LOOP;


    -- =====================================================
    -- 9. CONSUME RESOURCE
    -- =====================================================

    FOR v_cost IN
        SELECT value
        FROM jsonb_array_elements(
            v_cost_result->'costs'
        )
    LOOP

        v_resource_code :=
            v_cost->>'resource_code';

        v_resource_amount :=
            (v_cost->>'resource_amount')::int;


        UPDATE public.region_resources
        SET amount = amount - v_resource_amount
        WHERE player_region_id = v_player_region_id
          AND resource_code = v_resource_code;

    END LOOP;


    -- =====================================================
    -- 10. START UPGRADE
    -- =====================================================

    UPDATE public.player_region_buildings
    SET
        upgrading = TRUE,
        upgrade_finish_at =
            now()
            + (v_upgrade_time || ' seconds')::interval
    WHERE id = p_player_building_id
    RETURNING
        id,
        level,
        upgrading,
        upgrade_finish_at
    INTO v_building;


    -- =====================================================
    -- 11. RETURN
    -- =====================================================

    RETURN json_build_object(
        'success', true,
        'message', 'Upgrade started successfully',
        'building_id', v_building.id,
        'level', v_building.level,
        'target_level', v_building.level + 1,
        'upgrading', v_building.upgrading,
        'upgrade_finish_at', v_building.upgrade_finish_at,
        'costs', v_cost_result->'costs'
    );

END;
$$;


ALTER FUNCTION public.upgrade_building(p_player_building_id uuid) OWNER TO postgres;

--
-- Name: upgrade_general_level(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upgrade_general_level(p_player_id uuid, p_general_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.player_generals
    SET 
        level = level + 1,
        updated_at = now()
    WHERE player_id = p_player_id 
      AND general_id = p_general_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tướng "%" không tồn tại hoặc không thuộc sở hữu của player', p_general_id;
    END IF;
END;
$$;


ALTER FUNCTION public.upgrade_general_level(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: upgrade_general_level_full(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upgrade_general_level_full(p_player_id uuid, p_general_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data jsonb;
    v_tx jsonb;
    v_new_level INTEGER;
BEGIN
    -- Bước 1: Lấy dữ liệu upgrade
    v_data := get_general_upgrade_transaction_data(p_player_id, p_general_id);
    
    -- Bước 2: Lấy transaction_data
    v_tx := v_data->'transaction_data';
    
    -- Bước 3: Thực hiện transaction (trừ tiền)
    PERFORM execute_transaction(
        (v_tx->>'p_player_id')::uuid,
        v_tx->'p_cost_ops',
        '[]'::jsonb  -- Chưa có reward, chỉ trừ tiền
    );
    
    -- Bước 4: Gọi function có sẵn để tăng level
    PERFORM upgrade_general_level(p_player_id, p_general_id);
    
    -- Bước 5: Lấy level mới
    SELECT level INTO v_new_level
    FROM public.player_generals
    WHERE player_id = p_player_id 
      AND general_id = p_general_id;
    INSERT INTO public.player_activities (
    player_id,
    activity_type,
    related_id,
    metadata
)
VALUES (
    p_player_id,
    'hero.level_up',
    p_general_id,
    jsonb_build_object(
        'general_id', p_general_id,
        'new_level', v_new_level
    )
);
    -- Bước 6: Trả về kết quả
    RETURN jsonb_build_object(
        'success', true,
        'general_id', p_general_id,
        'new_level', v_new_level,
        'required_exp', v_data->>'required_exp'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'general_id', p_general_id
        );
END;
$$;


ALTER FUNCTION public.upgrade_general_level_full(p_player_id uuid, p_general_id text) OWNER TO postgres;

--
-- Name: upgrade_general_skill(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upgrade_general_skill(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_general_id text;
    v_skill_level int;
    v_max_level int;
    v_target_level int;
    v_ops jsonb := '[]'::jsonb;
    v_cost RECORD;
BEGIN

    -- =========================================================
    -- 1. Kiểm tra tướng thuộc player
    -- =========================================================
    SELECT
        pg.general_id
    INTO
        v_general_id
    FROM public.player_generals pg
    WHERE pg.id = p_player_general_id
      AND pg.player_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Tướng không tồn tại hoặc không thuộc về người chơi';
    END IF;


    -- =========================================================
    -- 2. Kiểm tra skill thuộc đúng tướng
    -- =========================================================
    SELECT
        gs.max_level
    INTO
        v_max_level
    FROM public.general_skills gs
    WHERE gs.id = p_general_skill_id
      AND gs.general_id = v_general_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Kỹ năng không thuộc về tướng này';
    END IF;


    -- =========================================================
    -- 3. Lấy skill của player
    -- =========================================================
    SELECT
        pgs.level
    INTO
        v_skill_level
    FROM public.player_general_skills pgs
    WHERE pgs.player_general_id = p_player_general_id
      AND pgs.general_skill_id = p_general_skill_id
      AND pgs.is_unlocked = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Kỹ năng chưa được mở khóa';
    END IF;


    -- =========================================================
    -- 4. Kiểm tra đã đạt max level chưa
    -- =========================================================
    IF v_skill_level >= v_max_level THEN
        RAISE EXCEPTION
            'Kỹ năng đã đạt cấp độ tối đa';
    END IF;


    -- =========================================================
    -- 5. Xác định level tiếp theo
    -- =========================================================
    v_target_level := v_skill_level + 1;


    -- =========================================================
    -- 6. Lấy chi phí nâng cấp
    -- =========================================================
    FOR v_cost IN
        SELECT
            currency_type,
            item_id,
            amount
        FROM public.general_skill_costs
        WHERE general_skill_id = p_general_skill_id
          AND target_level = v_target_level
        ORDER BY id
    LOOP

        -- Currency
        IF v_cost.currency_type IS NOT NULL THEN

            v_ops := v_ops || jsonb_build_array(
                jsonb_build_object(
                    'type', 'currency',
                    'currency', v_cost.currency_type,
                    'amount', v_cost.amount
                )
            );

        -- Item
        ELSIF v_cost.item_id IS NOT NULL THEN

            v_ops := v_ops || jsonb_build_array(
                jsonb_build_object(
                    'type', 'item',
                    'item_id', v_cost.item_id,
                    'quantity', v_cost.amount
                )
            );

        END IF;

    END LOOP;


    -- =========================================================
    -- 7. Kiểm tra có khai báo chi phí hay chưa
    -- =========================================================
    IF jsonb_array_length(v_ops) = 0 THEN
        RAISE EXCEPTION
            'Chưa cấu hình chi phí nâng kỹ năng lên cấp %',
            v_target_level;
    END IF;


    -- =========================================================
    -- 8. Trừ chi phí
    -- =========================================================
    PERFORM public.subtract_execute(
        p_player_id,
        v_ops
    );


    -- =========================================================
    -- 9. Upgrade skill
    -- =========================================================
    UPDATE public.player_general_skills
    SET
        level = v_target_level
    WHERE player_general_id = p_player_general_id
      AND general_skill_id = p_general_skill_id;

 -- 10. Insert player activity
    INSERT INTO public.player_activities (
        player_id,
        activity_type,
        related_id,
        metadata
    )
    VALUES (
        p_player_id,
        'hero.upgrade_skill',
        p_general_skill_id::text,
        jsonb_build_object(
            'player_general_id', p_player_general_id,
            'general_skill_id', p_general_skill_id,
            'previous_level', v_skill_level,
            'level', v_target_level,
            'max_level', v_max_level
        )
    );

    -- =========================================================
    -- 10. Trả kết quả
    -- =========================================================
    RETURN jsonb_build_object(
        'success', true,
        'player_general_skill_id', (
            SELECT id
            FROM public.player_general_skills
            WHERE player_general_id = p_player_general_id
              AND general_skill_id = p_general_skill_id
        ),
        'player_general_id', p_player_general_id,
        'general_skill_id', p_general_skill_id,
        'previous_level', v_skill_level,
        'level', v_target_level,
        'max_level', v_max_level,
        'is_unlocked', true,
        'costs', v_ops
    );

END;
$$;


ALTER FUNCTION public.upgrade_general_skill(p_player_id uuid, p_player_general_id uuid, p_general_skill_id uuid) OWNER TO postgres;

--
-- Name: upgrade_wall(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upgrade_wall(region_id_param text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    defense_record RECORD;
    player_region_record RECORD;
    gold_cost integer;
    wood_cost integer;
BEGIN
    SELECT * INTO defense_record FROM region_defense WHERE region_id = region_id_param;
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Region defense not found');
    END IF;
    
    SELECT * INTO player_region_record 
    FROM player_regions 
    WHERE region_id = region_id_param AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Region not found or not active');
    END IF;
    
    gold_cost := 500 * defense_record.wall_level;
    wood_cost := 300 * defense_record.wall_level;
    
    IF player_region_record.gold < gold_cost OR player_region_record.wood < wood_cost THEN
        RETURN json_build_object('success', false, 'message', 'Not enough resources');
    END IF;
    
    -- Trừ tài nguyên
    UPDATE player_regions 
    SET gold = gold - gold_cost,
        wood = wood - wood_cost
    WHERE region_id = region_id_param;
    
    -- Nâng cấp tường
    UPDATE region_defense 
    SET wall_level = wall_level + 1,
        gate_health = 1000 * (wall_level + 1)
    WHERE region_id = region_id_param
    RETURNING wall_level, gate_health INTO defense_record;
    
    RETURN json_build_object(
        'success', true,
        'message', 'Wall upgraded successfully',
        'new_defense', json_build_object(
            'wall_level', defense_record.wall_level,
            'gate_health', defense_record.gate_health,
            'cost', json_build_object('gold', gold_cost, 'wood', wood_cost)
        )
    );
END;
$$;


ALTER FUNCTION public.upgrade_wall(region_id_param text) OWNER TO postgres;

--
-- Name: use_item(uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.use_item(p_player_id uuid, p_item_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_effect public.base_item_effects%ROWTYPE;
    v_result jsonb;
    v_remaining integer;
BEGIN
    -- Lấy effect của item
    SELECT *
    INTO v_effect
    FROM public.base_item_effects
    WHERE item_id = p_item_id
    ORDER BY sort_order
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Vật phẩm này không có effect';
    END IF;

    -- Mở khóa kỹ năng
    IF v_effect.effect_type = 'unlock_skill' THEN

        v_result := public.add_general_skill(
            p_player_id,
            v_effect.params->>'hero_id',
            v_effect.target_id::uuid
        );

        -- Chỉ trừ item sau khi effect thực hiện thành công
        v_remaining := public.subtract_item(
            p_player_id,
            p_item_id,
            1
        );

        RETURN jsonb_build_object(
            'success', true,
            'itemId', p_item_id,
            'remaining', v_remaining,
            'effect', v_effect.effect_type,
            'result', v_result
        );
    END IF;

    RAISE EXCEPTION 'Effect "%" chưa được hỗ trợ',
        v_effect.effect_type;
END;
$$;


ALTER FUNCTION public.use_item(p_player_id uuid, p_item_id character varying) OWNER TO postgres;

--
-- Name: walk_garden_with_beauty(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.walk_garden_with_beauty(p_player_id uuid, p_beauty_id text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_remaining_gold numeric;
    v_intimacy_gain int := 10;
    v_current_points int;
    v_current_level int;
BEGIN
    -- 1. Trừ 100 vàng (tự chặn âm + lock)
    v_remaining_gold := public.subtract_player_currency(
        p_player_id,
        'gold',
        100
    );

    -- 2. Tăng thân mật cho mỹ nhân
    PERFORM public.add_intimacy_point_single(
        p_player_id,
        p_beauty_id,
        v_intimacy_gain
    );

    -- 3. Ghi lại hoạt động vào player_activities
    INSERT INTO public.player_activities (
        player_id,
        activity_type
    )
    VALUES (
        p_player_id,
        'beauty.garden'
    );

    -- 4. Lấy trạng thái mới
    SELECT intimacy_points, intimacy_level
    INTO v_current_points, v_current_level
    FROM public.player_beauties
    WHERE player_id = p_player_id
      AND beauty_id = p_beauty_id;

    -- 5. Return result
    RETURN json_build_object(
        'action', 'walk_garden',
        'success', true,
        'cost_gold', 100,
        'remaining_gold', v_remaining_gold,
        'intimacy_points_gained', v_intimacy_gain,
        'current_intimacy_points', v_current_points,
        'current_intimacy_level', v_current_level
    );
END;
$$;


ALTER FUNCTION public.walk_garden_with_beauty(p_player_id uuid, p_beauty_id text) OWNER TO postgres;

--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    -- Reset the role on every FOR..LOOP batch execution.
                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)
                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above
                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.
                    -- The flow is:
                    --   1. run batch with conn role
                    --   2. set_config working_role
                    --   3. execute walrus
                    --   4. reset role (revert)
                    --   5. repeat
                    perform set_config('role', null, true);

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


ALTER FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


ALTER FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text) OWNER TO supabase_realtime_admin;

--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


ALTER FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) OWNER TO supabase_realtime_admin;

--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


