    created_date timestamp with time zone DEFAULT now() NOT NULL,
    updated_date timestamp with time zone,
    is_edited boolean DEFAULT false NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_date timestamp with time zone,
    reply_to_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    alliance_id uuid,
    group_id uuid,
    sender_name text,
    CONSTRAINT chat_messages_channel_type_check CHECK ((channel_type = ANY (ARRAY['world'::text, 'alliance'::text, 'group'::text, 'private'::text]))),
    CONSTRAINT chat_messages_message_type_check CHECK ((message_type = ANY (ARRAY['text'::text, 'image'::text, 'system'::text, 'trade'::text, 'item'::text]))),
    CONSTRAINT valid_channel_check CHECK ((((channel_type = 'private'::text) AND (recipient_id IS NOT NULL)) OR ((channel_type = 'alliance'::text) AND (alliance_id IS NOT NULL)) OR ((channel_type = 'group'::text) AND (group_id IS NOT NULL)) OR (channel_type = 'world'::text)))
);


