CREATE TABLE public.combat_troops (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    battle_id uuid NOT NULL,
    region_id character varying(50) NOT NULL,
    player_id uuid NOT NULL,
    unit_type character varying(50) NOT NULL,
    original_quantity integer NOT NULL,
    current_quantity integer NOT NULL,
    lost_quantity integer DEFAULT 0 NOT NULL,
    survived_quantity integer DEFAULT 0 NOT NULL,
    battle_role character varying(20) NOT NULL,
    status character varying(20) DEFAULT 'fighting'::character varying NOT NULL,
    joined_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    resolved_at timestamp without time zone,
    returned_to_region boolean DEFAULT false NOT NULL,
    returned_at timestamp without time zone,
    return_quantity integer,
    recovery_quantity integer DEFAULT 0 NOT NULL,
    CONSTRAINT combat_troops_quantity_check CHECK (((current_quantity >= 0) AND (lost_quantity >= 0) AND (survived_quantity >= 0) AND (original_quantity = (lost_quantity + current_quantity)))),
    CONSTRAINT combat_troops_role_check CHECK (((battle_role)::text = ANY ((ARRAY['attacker'::character varying, 'defender'::character varying])::text[]))),
    CONSTRAINT combat_troops_status_check CHECK (((status)::text = ANY ((ARRAY['fighting'::character varying, 'defeated'::character varying, 'withdrawn'::character varying, 'recovering'::character varying, 'returned'::character varying])::text[])))
);


