    accepted_date timestamp with time zone,
    nickname text,
    favorite boolean DEFAULT false NOT NULL,
    notes text,
    CONSTRAINT friend_relationships_no_self CHECK ((player_id <> friend_id)),
    CONSTRAINT friend_relationships_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'blocked'::text, 'rejected'::text])))
);


ALTER TABLE public.friend_relationships OWNER TO postgres;

--
-- Name: friend_list_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.friend_list_view AS
 SELECT f.id AS relationship_id,
    p.id AS player_id,
    p.username AS name,
        CASE
            WHEN (p.title = 'Commander'::text) THEN '👑'::text
            WHEN (p.title = 'General'::text) THEN '⚔️'::text
            WHEN (p.title = 'Legend'::text) THEN '🛡️'::text
            WHEN (p.title = 'Strategist'::text) THEN '🏹'::text
            ELSE '👤'::text
        END AS avatar,
    p.level,
    (p.status = 'online'::text) AS online,
    p.last_login AS last_online,
    ((p.status = 'online'::text) AND (p.last_login > (now() - '00:10:00'::interval))) AS is_playing,
    f.nickname,
    f.favorite,
    f.notes
   FROM (public.friend_relationships f
     JOIN public.players p ON ((f.friend_id = p.id)))
  WHERE (f.status = 'accepted'::text);


ALTER VIEW public.friend_list_view OWNER TO postgres;

--
-- Name: friend_requests_received; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.friend_requests_received AS
 SELECT fr.id AS request_id,
    fr.player_id AS requester_id,
    p.username AS requester_name,
        CASE
            WHEN (p.title = 'Commander'::text) THEN '👑'::text
            WHEN (p.title = 'General'::text) THEN '⚔️'::text
            WHEN (p.title = 'Legend'::text) THEN '🛡️'::text
            WHEN (p.title = 'Strategist'::text) THEN '🏹'::text
            WHEN (p.specialization = 'Archer'::text) THEN '🎯'::text
            WHEN (p.specialization = 'Warrior'::text) THEN '⚜️'::text
            WHEN (p.specialization = 'Mage'::text) THEN '🔮'::text
            WHEN (p.specialization = 'Knight'::text) THEN '🛡️'::text
            ELSE '👤'::text
        END AS avatar,
    p.level,
    p.victory_points,
    p.win_rate,
    p.specialization,
    p.alliance,
    fr.created_date,
        CASE
            WHEN (EXTRACT(epoch FROM (now() - fr.created_date)) < (60)::numeric) THEN 'vừa xong'::text
            WHEN (EXTRACT(epoch FROM (now() - fr.created_date)) < (3600)::numeric) THEN (floor((EXTRACT(epoch FROM (now() - fr.created_date)) / (60)::numeric)) || ' phút trước'::text)
            WHEN (EXTRACT(epoch FROM (now() - fr.created_date)) < (86400)::numeric) THEN (floor((EXTRACT(epoch FROM (now() - fr.created_date)) / (3600)::numeric)) || ' giờ trước'::text)
            ELSE (floor((EXTRACT(epoch FROM (now() - fr.created_date)) / (86400)::numeric)) || ' ngày trước'::text)
        END AS time_ago,
    fr.friend_id AS receiver_id
   FROM (public.friend_relationships fr
     JOIN public.players p ON ((fr.player_id = p.id)))
  WHERE (fr.status = 'pending'::text);


ALTER VIEW public.friend_requests_received OWNER TO postgres;

