--
-- Name: loot_box_pity_full; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.loot_box_pity_full AS
 SELECT id,
    loot_box_id,
    enabled,
    reset_on_rare_drop,
    ( SELECT json_agg(json_build_object('id', c.id, 'threshold', c.threshold, 'items', ( SELECT json_agg(i.*) AS json_agg
                   FROM public.loot_box_pity_items i
                  WHERE (i.pity_counter_id = c.id)))) AS json_agg
           FROM public.loot_box_pity_counters c
          WHERE (c.pity_system_id = s.id)) AS counters
   FROM public.loot_box_pity_systems s;


