--
-- Name: player_achievements_view_full; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.player_achievements_view_full AS
 WITH requirement_targets AS (
         SELECT achievement_requirements.achievement_id,
            sum(achievement_requirements.target) AS target_progress
           FROM public.achievement_requirements
          GROUP BY achievement_requirements.achievement_id
        ), latest_progress AS (
         SELECT ar.achievement_id,
            patp.player_id,
            sum(COALESCE(patp.progress, 0)) AS player_progress,
            max(pa.unlocked_at) AS unlocked_at,
            bool_or(COALESCE(patp.reward_claimed, false)) AS achievement_reward_claimed
           FROM ((public.achievement_requirements ar
             LEFT JOIN public.player_achievement_tier_progress patp ON ((patp.requirement_id = ar.id)))
             LEFT JOIN public.player_achievements pa ON ((((pa.achievement_id)::text = (ar.achievement_id)::text) AND (pa.player_id = patp.player_id))))
          GROUP BY ar.achievement_id, patp.player_id
        )
 SELECT a.id AS achievement_id,
    a.name,
    a.description,
    a.type,
    a.category,
    a.tier,
    a.rarity,
    a.difficulty,
    a.points,
    COALESCE(rt.target_progress, (0)::bigint) AS target_progress,
    lp.player_id,
    COALESCE(lp.player_progress, (0)::bigint) AS player_progress,
        CASE
            WHEN (COALESCE(rt.target_progress, (0)::bigint) = 0) THEN (0)::numeric
            ELSE round((((COALESCE(lp.player_progress, (0)::bigint))::numeric / (rt.target_progress)::numeric) * (100)::numeric), 2)
        END AS progress_percentage,
        CASE
            WHEN (lp.unlocked_at IS NOT NULL) THEN 'unlocked'::text
            ELSE 'locked'::text
        END AS status,
    lp.unlocked_at,
    COALESCE(lp.achievement_reward_claimed, false) AS reward_claimed,
    a.hidden,
    a.secret,
    a.repeatable,
    a.icon,
    a.image,
    rwr.current_requirement
   FROM (((public.achievements a
     LEFT JOIN latest_progress lp ON (((a.id)::text = (lp.achievement_id)::text)))
     LEFT JOIN requirement_targets rt ON (((a.id)::text = (rt.achievement_id)::text)))
     LEFT JOIN LATERAL ( SELECT json_build_object('requirement_id', ar.id, 'display_text', ar.display_text, 'target', ar.target, 'player_progress', COALESCE(patp.progress, 0), 'completed', COALESCE(patp.completed, false), 'reward_claimed', COALESCE(patp.reward_claimed, false), 'rewards', COALESCE(( SELECT json_agg(json_build_object('item_id', r.item_id, 'name', bi.name, 'description', bi.description, 'svg_icon', NULL::unknown, 'base_item_rarity', bi.rarity, 'quantity', r.quantity, 'probability', r.probability, 'currency_type', r.currency_type)) AS json_agg
                   FROM (public.achievement_rewards r
                     LEFT JOIN public.base_items bi ON (((bi.id)::text = (r.item_id)::text)))
                  WHERE (r.requirement_id = ar.id)), '[]'::json)) AS current_requirement
           FROM (public.achievement_requirements ar
             LEFT JOIN public.player_achievement_tier_progress patp ON (((patp.requirement_id = ar.id) AND (patp.player_id = lp.player_id))))
          WHERE (((ar.achievement_id)::text = (a.id)::text) AND (COALESCE(patp.reward_claimed, false) = false))
          ORDER BY
                CASE
                    WHEN ((COALESCE(patp.completed, false) = true) AND (COALESCE(patp.reward_claimed, false) = false)) THEN 0
                    ELSE 1
                END, ar.sort_order
         LIMIT 1) rwr ON (true))
  WHERE (a.status = 'active'::public.achievement_status);


ALTER VIEW public.player_achievements_view_full OWNER TO postgres;

