--
-- Name: server_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.server_summary AS
 SELECT s.id,
    s.name,
    s.type,
    s.status,
    s.region,
    s.player_count,
    s.max_players,
    s.cpu,
    s.memory,
    count(a.id) AS active_alerts,
    count(
        CASE
            WHEN (a.level = ANY (ARRAY['error'::public.alert_level, 'critical'::public.alert_level])) THEN 1
            ELSE NULL::integer
        END) AS critical_alerts
   FROM (public.servers s
     LEFT JOIN public.system_alerts a ON ((((s.id)::text = (a.server_id)::text) AND (a.acknowledged = false))))
  GROUP BY s.id, s.name, s.type, s.status, s.region, s.player_count, s.max_players, s.cpu, s.memory;


ALTER VIEW public.server_summary OWNER TO postgres;

