--
-- Name: simple_player_friends; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.simple_player_friends AS
 SELECT fr.player_id,
    p.username AS player_username,
    fr.friend_id,
    friend.username AS friend_username,
    fr.status AS friendship_status,
    fr.favorite,
    fr.nickname
   FROM ((public.friend_relationships fr
     JOIN public.players p ON ((fr.player_id = p.id)))
     JOIN public.players friend ON ((fr.friend_id = friend.id)))
  WHERE (fr.status = 'accepted'::text);


ALTER VIEW public.simple_player_friends OWNER TO postgres;

