--
-- Name: table_relations_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.table_relations_view AS
 SELECT (con.conname)::text AS constraint_name,
    (src_ns.nspname)::text AS source_schema,
    (src_tbl.relname)::text AS source_table,
    (src_col.attname)::text AS source_column,
    (tgt_ns.nspname)::text AS target_schema,
    (tgt_tbl.relname)::text AS target_table,
    (tgt_col.attname)::text AS target_column,
        CASE con.confupdtype
            WHEN 'a'::"char" THEN 'NO ACTION'::text
            WHEN 'r'::"char" THEN 'RESTRICT'::text
            WHEN 'c'::"char" THEN 'CASCADE'::text
            WHEN 'n'::"char" THEN 'SET NULL'::text
            WHEN 'd'::"char" THEN 'SET DEFAULT'::text
            ELSE NULL::text
        END AS update_rule,
        CASE con.confdeltype
            WHEN 'a'::"char" THEN 'NO ACTION'::text
            WHEN 'r'::"char" THEN 'RESTRICT'::text
            WHEN 'c'::"char" THEN 'CASCADE'::text
            WHEN 'n'::"char" THEN 'SET NULL'::text
            WHEN 'd'::"char" THEN 'SET DEFAULT'::text
            ELSE NULL::text
        END AS delete_rule
   FROM ((((((((pg_constraint con
     JOIN pg_class src_tbl ON ((src_tbl.oid = con.conrelid)))
     JOIN pg_namespace src_ns ON ((src_ns.oid = src_tbl.relnamespace)))
     JOIN pg_class tgt_tbl ON ((tgt_tbl.oid = con.confrelid)))
     JOIN pg_namespace tgt_ns ON ((tgt_ns.oid = tgt_tbl.relnamespace)))
     JOIN LATERAL unnest(con.conkey) WITH ORDINALITY src_cols(attnum, ord) ON (true))
     JOIN LATERAL unnest(con.confkey) WITH ORDINALITY tgt_cols(attnum, ord) ON ((src_cols.ord = tgt_cols.ord)))
     JOIN pg_attribute src_col ON (((src_col.attrelid = src_tbl.oid) AND (src_col.attnum = src_cols.attnum))))
     JOIN pg_attribute tgt_col ON (((tgt_col.attrelid = tgt_tbl.oid) AND (tgt_col.attnum = tgt_cols.attnum))))
  WHERE ((con.contype = 'f'::"char") AND (src_ns.nspname = 'public'::name) AND (tgt_ns.nspname = 'public'::name));


ALTER VIEW public.table_relations_view OWNER TO postgres;

