--
-- Name: v_economy_stats_full; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_economy_stats_full AS
 SELECT total_revenue AS "totalRevenue",
    daily_revenue AS "dailyRevenue",
    weekly_revenue AS "weeklyRevenue",
    monthly_revenue AS "monthlyRevenue",
    active_players AS "activePlayers",
    average_spend AS "averageSpend",
    currency_in_circulation AS "currencyInCirculation",
    total_transactions AS "totalTransactions",
    fraud_attempts AS "fraudAttempts",
    successful_transactions AS "successfulTransactions",
    revenue_growth AS "revenueGrowth",
    ( SELECT json_agg(json_build_object('name', sub.name, 'revenue', sub.revenue, 'sales', sub.sales)) AS json_agg
           FROM ( SELECT b.name,
                    b.revenue,
                    b.sales
                   FROM public.economy_base_item b
                  ORDER BY b.revenue DESC
                 LIMIT 4) sub) AS "popularItems"
   FROM public.economy_stats s
  ORDER BY last_updated DESC
 LIMIT 1;


ALTER VIEW public.v_economy_stats_full OWNER TO postgres;

--
-- Name: v_player_general_equipment_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_player_general_equipment_stats AS
 SELECT pg.id AS player_general_id,
    COALESCE(sum(ist.attack), (0)::bigint) AS equip_attack,
    COALESCE(sum(ist.defense), (0)::bigint) AS equip_defense,
    COALESCE(sum(ist.health), (0)::bigint) AS equip_health,
    COALESCE(sum(ist.speed), (0)::bigint) AS equip_speed,
    COALESCE(sum(ist.intelligence), (0)::bigint) AS equip_intelligence,
    COALESCE(sum(ist.leadership), (0)::bigint) AS equip_leadership,
    COALESCE(sum(ist.critical_chance), (0)::numeric) AS equip_critical_chance,
    COALESCE(sum(ist.critical_damage), (0)::numeric) AS equip_critical_damage,
    COALESCE(sum(ist.dodge), (0)::numeric) AS equip_dodge,
    COALESCE(sum(ist.block), (0)::numeric) AS equip_block
   FROM (((public.player_generals pg
     LEFT JOIN public.equipment_items ei ON (((ei.player_general_id = pg.id) AND (ei.is_equipped = true))))
     LEFT JOIN LATERAL ( SELECT unnest(ARRAY[ei.weapon_id, ei.armor_id, ei.helmet_id, ei.cloak_id, ei.boots_id, ei.ring_id, ei.shield_id]) AS item_id) eq ON (true))
     LEFT JOIN public.item_stats ist ON (((ist.base_item_id)::text = (eq.item_id)::text)))
  GROUP BY pg.id;


ALTER VIEW public.v_player_general_equipment_stats OWNER TO postgres;

