    NULL::bigint AS total_hp;


ALTER VIEW public.v_player_unit_stats OWNER TO postgres;

--
-- Name: v_player_unit_combat_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_player_unit_combat_stats AS
 SELECT pus.player_unit_id AS entity_id,
    pus.player_id AS owner_id,
    pus.unit_id,
    false AS is_hero,
    pus.level,
    pus.rank,
    rt.quantity,
    rt.region_id,
    pus.base_attack,
    pus.base_defense,
    pus.base_speed,
    pus.base_hp,
    pus.equip_attack,
    pus.equip_defense,
    pus.equip_speed,
    pus.equip_hp,
    pus.total_attack,
    pus.total_defense,
    pus.total_speed,
    pus.total_hp
   FROM (public.v_player_unit_stats pus
     JOIN public.region_troops rt ON (((rt.player_id = pus.player_id) AND ((rt.unit_type)::text = (pus.unit_id)::text) AND (rt.is_combat_ready = true) AND (rt.quantity > 0) AND ((rt.location_type)::text = 'region'::text))));


