  ORDER BY m.created_date;


ALTER VIEW public.view_chat_world OWNER TO postgres;

--
-- Name: view_player_available_items; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_player_available_items AS
 SELECT pi.player_id,
    pi.item_id,
    bi.name,
    bi.type,
    bi.rarity,
    bi.quality,
    bi.stackable,
    bi.max_stack,
    pi.quantity AS total_quantity,
    COALESCE(eq.equipped_count, (0)::bigint) AS equipped_quantity,
    (pi.quantity - COALESCE(eq.equipped_count, (0)::bigint)) AS available_quantity
   FROM ((public.player_items pi
     JOIN public.base_items bi ON (((bi.id)::text = (pi.item_id)::text)))
     LEFT JOIN ( SELECT pg.player_id,
            equipped_items.item_id,
            count(*) AS equipped_count
           FROM (( SELECT equipment_items.player_general_id,
                    equipment_items.weapon_id AS item_id
                   FROM public.equipment_items
                  WHERE (equipment_items.weapon_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.armor_id
                   FROM public.equipment_items
                  WHERE (equipment_items.armor_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.helmet_id
                   FROM public.equipment_items
                  WHERE (equipment_items.helmet_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.cloak_id
                   FROM public.equipment_items
                  WHERE (equipment_items.cloak_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.boots_id
                   FROM public.equipment_items
                  WHERE (equipment_items.boots_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.ring_id
                   FROM public.equipment_items
                  WHERE (equipment_items.ring_id IS NOT NULL)
                UNION ALL
                 SELECT equipment_items.player_general_id,
                    equipment_items.shield_id
                   FROM public.equipment_items
                  WHERE (equipment_items.shield_id IS NOT NULL)) equipped_items
             JOIN public.player_generals pg ON ((pg.id = equipped_items.player_general_id)))
          GROUP BY pg.player_id, equipped_items.item_id) eq ON (((eq.player_id = pi.player_id) AND ((eq.item_id)::text = (pi.item_id)::text))))
  WHERE ((pi.quantity - COALESCE(eq.equipped_count, (0)::bigint)) > 0);


ALTER VIEW public.view_player_available_items OWNER TO postgres;

--
-- Name: view_player_item_inventory_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_player_item_inventory_status AS
 WITH equipped_items AS (
         SELECT pg.player_id,
            x.item_id,
            (count(*))::integer AS equipped_quantity
           FROM ((public.equipment_items ei_1
             JOIN public.player_generals pg ON ((pg.id = ei_1.player_general_id)))
             CROSS JOIN LATERAL ( VALUES (ei_1.weapon_id), (ei_1.armor_id), (ei_1.helmet_id), (ei_1.cloak_id), (ei_1.boots_id), (ei_1.ring_id), (ei_1.shield_id)) x(item_id))
          WHERE ((ei_1.is_equipped = true) AND (x.item_id IS NOT NULL) AND (pg.player_id IS NOT NULL))
          GROUP BY pg.player_id, x.item_id
        )
 SELECT pi.player_id,
    pi.item_id,
    bi.name,
    bi.description,
    bi.type,
    bi.rarity,
    bi.quality,
    bi.level_requirement,
    bi.stackable,
    bi.max_stack,
    bi.icon,
    bi.svg_icon,
    bi.is_tradable,
    bi.is_sellable,
    bi.is_destroyable,
    bi.is_quest_item,
    bi.status,
    pi.quantity AS total_quantity,
    COALESCE(ei.equipped_quantity, 0) AS equipped_quantity,
    GREATEST((pi.quantity - COALESCE(ei.equipped_quantity, 0)), 0) AS available_quantity,
        CASE
            WHEN (COALESCE(ei.equipped_quantity, 0) > 0) THEN true
            ELSE false
        END AS has_equipped,
        CASE
            WHEN (GREATEST((pi.quantity - COALESCE(ei.equipped_quantity, 0)), 0) > 0) THEN true
            ELSE false
        END AS has_available,
    pi.condition,
    pi.acquired_at,
    pi.metadata,
    ist.attack,
    ist.defense,
    ist.health,
    ist.mana,
    ist.strength,
    ist.agility,
    ist.intelligence,
    ist.speed,
    ist.leadership,
    ist.critical_chance,
    ist.critical_damage,
    ist.dodge,
    ist.block,
    ist.resistance
   FROM (((public.player_items pi
     JOIN public.base_items bi ON (((bi.id)::text = (pi.item_id)::text)))
     LEFT JOIN equipped_items ei ON (((ei.player_id = pi.player_id) AND ((ei.item_id)::text = (pi.item_id)::text))))
     LEFT JOIN public.item_stats ist ON (((ist.base_item_id)::text = (pi.item_id)::text)))
  WHERE (pi.quantity > 0);


ALTER VIEW public.view_player_item_inventory_status OWNER TO postgres;

--
-- Name: view_player_resource_activities; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_player_resource_activities WITH (security_invoker='true') AS
 SELECT pa.id,
    pa.player_id,
    pa.activity_type,
    pa.activity_subtype,
    pa.related_id,
    m.building_type,
    m.resource_code,
    m.building_level,
    m.collected_amount,
    m.player_region_id,
    ((pa.activity_type || '.'::text) || m.resource_code) AS action_type,
    pa.created_at
   FROM (public.player_activities pa
     LEFT JOIN LATERAL jsonb_to_record(pa.metadata) m(building_type text, resource_code text, building_level integer, collected_amount integer, player_region_id uuid) ON (true))
  WHERE (pa.activity_type = 'resource.collect'::text);


ALTER VIEW public.view_player_resource_activities OWNER TO postgres;

