--
-- Name: vw_player_main_quests; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_player_main_quests AS
 WITH player AS (
         SELECT players.id,
            players.level
           FROM public.players
        ), player_unlock AS (
         SELECT player_stats.player_id,
            COALESCE(player_stats.current_main_quest_unlocked, 0) AS unlocked_quest_id
           FROM public.player_stats
        ), visible_quests AS (
         SELECT pu.player_id,
            q.id,
            q.name,
            q.description,
            q.type,
            q.category,
            q.difficulty,
            q.status,
            q.completion_limit,
            q.created_at,
            q.updated_at,
            q.min_level,
            q.max_level,
            q.event_id,
            q.quest_nav_action,
            q.story_id,
            q.quest_main_unlock_increment
           FROM ((public.quests q
             JOIN player p ON (true))
             JOIN player_unlock pu ON (true))
          WHERE ((q.category = 'main'::text) AND (q.status = 'active'::text) AND (((q.quest_main_unlock_increment IS NOT NULL) AND ((pu.unlocked_quest_id = 1) OR (q.id = (pu.unlocked_quest_id)::text))) OR ((q.quest_main_unlock_increment IS NULL) AND ((p.level >= q.min_level) AND (p.level <= q.max_level)))) AND ((NOT (EXISTS ( SELECT 1
                   FROM public.story_choice_quests scq
                  WHERE (scq.quest_id = q.id)))) OR (EXISTS ( SELECT 1
                   FROM (public.story_choice_quests scq
                     JOIN public.player_story_history psh ON ((psh.choice_id = scq.choice_id)))
                  WHERE ((scq.quest_id = q.id) AND (psh.player_id = pu.player_id))))) AND (NOT (EXISTS ( SELECT 1
                   FROM (public.quest_requirements qr
                     LEFT JOIN public.quest_requirement_progress qrp ON ((((qrp.quest_requirement_id)::text = (qr.id)::text) AND (qrp.player_id = pu.player_id))))
                  WHERE (qr.quest_id = q.id)
                  GROUP BY qr.quest_id
                 HAVING ((count(qr.id) > 0) AND (count(
                        CASE
                            WHEN (qrp.completed = true) THEN 1
                            ELSE NULL::integer
                        END) = count(qr.id)) AND (EXISTS ( SELECT 1
                           FROM public.player_quest_progress pq
                          WHERE ((pq.player_id = pu.player_id) AND (pq.quest_id = q.id) AND (pq.claimed = true)))))))))
        )
 SELECT player_id,
    id,
    name,
    description,
    type,
    category,
    difficulty,
    status,
    completion_limit,
    created_at,
    updated_at,
    min_level,
    max_level,
    event_id,
    quest_nav_action,
    story_id,
    quest_main_unlock_increment
   FROM visible_quests;


ALTER VIEW public.vw_player_main_quests OWNER TO postgres;

