 body -->\n    <path d="M15,25 Q20,15 35,15 L40,20 Q45,30 40,40 L35,55 Q25,50 20,45 L15,35 Z" fill="url(#leatherGradient)" stroke="#5D4037" stroke-width="1.5"/>\n    \n    <!-- Boot cuff -->\n    <path d="M15,25 L35,15 L40,20 L20,30 Z" fill="url(#leatherLight)" stroke="#5D4037" stroke-width="1.2"/>\n    \n    <!-- Boot opening -->\n    <ellipse cx="27" cy="22" rx="10" ry="4" fill="url(#leatherLight)" stroke="#5D4037" stroke-width="1"/>\n    \n    <!-- Speed lines effect -->\n    <path d="M45,30 Q55,25 65,20" stroke="url(#speedEffect)" stroke-width="3" stroke-linecap="round" opacity="0.7">\n      <animate attributeName="opacity" values="0.7;0.3;0.7" dur="2s" repeatCount="indefinite"/>\n    </path>\n    \n    <!-- Stitching details -->\n    <path d="M20,30 Q25,25 30,22" fill="none" stroke="#5D4037" stroke-width="1.5" stroke-dasharray="2,2"/>\n    <path d="M25,40 Q30,35 35,33" fill="none" stroke="#5D4037" stroke-width="1.2" stroke-dasharray="1.5,1.5"/>\n    \n    <!-- Lace holes -->\n    <g fill="#5D4037">\n      <circle cx="22" cy="28" r="1.2"/>\n      <circle cx="27" cy="26" r="1.2"/>\n      <circle cx="32" cy="24" r="1.2"/>\n    </g>\n    \n    <!-- Highlight for 3D effect -->\n    <path d="M20,25 Q25,18 32,18 L35,22 Q30,25 25,28 Z" fill="url(#highlight)" opacity="0.6"/>\n  </g>\n  \n  <!-- Speed wings symbol -->\n  <g transform="translate(60, 75)" filter="url(#uncommonGlow)">\n    <!-- Left wing -->\n    <path d="M-15,0 Q-25,-8 -20,-15 Q-10,-20 0,-10 Q5,-15 10,-10 Q15,-5 10,0 Z" fill="#27AE60" fill-opacity="0.7" stroke="#229954" stroke-width="1"/>\n    \n    <!-- Right wing -->\n    <path d="M15,0 Q25,-8 20,-15 Q10,-20 0,-10 Q-5,-15 -10,-10 Q-15,-5 -10,0 Z" fill="#27AE60" fill-opacity="0.7" stroke="#229954" stroke-width="1"/>\n    \n    <!-- Center circle -->\n    <circle cx="0" cy="0" r="5" fill="#27AE60" stroke="#1D8348" stroke-width="1"/>\n    \n    <!-- Animated speed effect -->\n    <g>\n      <path d="M0,0 L10,0" stroke="#27AE60" stroke-width="2" stroke-linecap="round" opacity="0">\n        <animate attributeName="opacity" values="0;0.8;0" dur="1.5s" repeatCount="indefinite" begin="0s"/>\n        <animate attributeName="x2" values="10;20;10" dur="1.5s" repeatCount="indefinite" begin="0s"/>\n      </path>\n      <path d="M0,0 L-10,0" stroke="#27AE60" stroke-width="2" stroke-linecap="round" opacity="0">\n        <animate attributeName="opacity" values="0;0.8;0" dur="1.5s" repeatCount="indefinite" begin="0.3s"/>\n        <animate attributeName="x2" values="-10;-20;-10" dur="1.5s" repeatCount="indefinite" begin="0.3s"/>\n      </path>\n    </g>\n  </g>\n  \n  <!-- Rarity border -->\n  <rect x="20" y="20" width="80" height="80" rx="10" fill="none" stroke="#27AE60" stroke-width="2" stroke-opacity="0.5"/>\n  \n  <!-- Level indicator -->\n  <g font-family="Arial, sans-serif" font-weight="bold">\n    <circle cx="100" cy="100" r="10" fill="#2C3E50" fill-opacity="0.8"/>\n    <text x="100" y="104" text-anchor="middle" font-size="8" fill="white">5</text>\n  </g>\n  \n  <!-- Rarity indicator -->\n  <rect x="15" y="15" width="25" height="14" rx="3" fill="#27AE60" fill-opacity="0.9"/>\n  <text x="27.5" y="25" text-anchor="middle" font-family="Arial, sans-serif" font-size="8" font-weight="bold" fill="white">U</text>\n</svg>
