20260805041427	{"CREATE OR REPLACE FUNCTION public.get_player_battle_history(p_player_id uuid)\nRETURNS SETOF public.battles\nLANGUAGE sql\nSTABLE\nAS $$\nSELECT *\nFROM public.battles\nWHERE player1_id = p_player_id\n   OR player2_id = p_player_id\nORDER BY COALESCE(ended_at, started_at, created_at) DESC;\n$$;"}	create_get_player_battle_history	c2202lm.pmquan@aptech.vn	\N	\N
20260805041759	{"DROP FUNCTION IF EXISTS public.get_player_battle_history(uuid);\n\nCREATE FUNCTION public.get_player_battle_history(p_player_id uuid)\nRETURNS TABLE (\n    battle public.battles,\n    player1_name text,\n    player2_name text\n)\nLANGUAGE sql\nSTABLE\nAS $$\nSELECT\n    b,\n    p1.name,\n    p2.name\nFROM public.battles b\nLEFT JOIN public.players p1 ON p1.id = b.player1_id\nLEFT JOIN public.players p2 ON p2.id = b.player2_id\nWHERE b.player1_id = p_player_id\n   OR b.player2_id = p_player_id\nORDER BY COALESCE(b.ended_at, b.started_at, b.created_at) DESC;\n$$;"}	replace_get_player_battle_history_with_player_names	c2202lm.pmquan@aptech.vn	\N	\N
20260805043257	{"DROP FUNCTION IF EXISTS public.get_player_battle_history(uuid);\nCREATE FUNCTION public.get_player_battle_history(p_player_id uuid)\nRETURNS jsonb\nLANGUAGE sql\nSTABLE\nAS $function$\nSELECT COALESCE(jsonb_agg(jsonb_build_object('battle',to_jsonb(b),'player1_username',p1.username,'player2_username',p2.username) ORDER BY COALESCE(b.ended_at,b.started_at,b.created_at) DESC),'[]'::jsonb)\nFROM public.battles b\nLEFT JOIN public.players p1 ON p1.id=b.player1_id\nLEFT JOIN public.players p2 ON p2.id=b.player2_id\nWHERE b.player1_id=p_player_id OR b.player2_id=p_player_id;\n$function$;"}	replace_get_player_battle_history_json	c2202lm.pmquan@aptech.vn	\N	\N
\.


