--
-- Name: consumables_with_effects _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.consumables_with_effects AS
 SELECT bi.id,
    bi.name,
    bi.description,
    bi.type,
    bi.rarity,
    bi.quality,
    bi.level_requirement,
    bi.stackable,
    bi.max_stack,
    bi.base_value,
    bi.icon,
    bi.is_tradable,
    bi.is_sellable,
    bi.is_destroyable,
    bi.is_quest_item,
    bi.status,
    bi.created_at,
    bi.updated_at,
    ci.cooldown,
    array_agg(json_build_object('type', ce.effect_type, 'duration', ce.duration, 'value', ce.value, 'target', ce.target, 'attribute', ce.attribute_affected, 'order', ce.effect_order) ORDER BY ce.effect_order) AS effects
   FROM ((public.base_items bi
     JOIN public.consumable_items ci ON (((bi.id)::text = (ci.id)::text)))
     LEFT JOIN public.consumable_effects ce ON (((ci.id)::text = (ce.consumable_id)::text)))
  GROUP BY bi.id, ci.id;


--
-- Name: v_player_unit_stats _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.v_player_unit_stats AS
 SELECT pu.id AS player_unit_id,
    pu.player_id,
    pu.unit_id,
    pu.quantity,
    pu.level,
    pu.rank,
    pu.attack AS base_attack,
    pu.defense AS base_defense,
    pu.speed AS base_speed,
    pu.max_hp AS base_hp,
    COALESCE(sum(ist.attack), (0)::bigint) AS equip_attack,
    COALESCE(sum(ist.defense), (0)::bigint) AS equip_defense,
    COALESCE(sum(ist.speed), (0)::bigint) AS equip_speed,
    COALESCE(sum(ist.health), (0)::bigint) AS equip_hp,
    (pu.attack + COALESCE(sum(ist.attack), (0)::bigint)) AS total_attack,
    (pu.defense + COALESCE(sum(ist.defense), (0)::bigint)) AS total_defense,
    (pu.speed + COALESCE(sum(ist.speed), (0)::bigint)) AS total_speed,
    (pu.max_hp + COALESCE(sum(ist.health), (0)::bigint)) AS total_hp
   FROM ((public.player_units pu
     LEFT JOIN LATERAL ( SELECT unnest(ARRAY[pu.weapon_item_id, pu.armor_item_id, pu.helmet_item_id, pu.cloak_item_id, pu.boots_item_id, pu.shield_item_id, pu.accessory_item_id, pu.ring1_item_id, pu.ring2_item_id, pu.mount_item_id]) AS item_id) eq ON (true))
     LEFT JOIN public.item_stats ist ON (((ist.base_item_id)::text = (eq.item_id)::text)))
  GROUP BY pu.id;


