--
-- Name: generals Admins can delete generals; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can delete generals" ON public.generals FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role_id = 'admin'::text)))));


--
-- Name: generals Admins can insert generals; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can insert generals" ON public.generals FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role_id = 'admin'::text)))));


--
-- Name: generals Admins can update generals; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can update generals" ON public.generals FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role_id = 'admin'::text))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role_id = 'admin'::text)))));


--
-- Name: admin_activities Admins can view all activities; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can view all activities" ON public.admin_activities FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.user_roles ur
  WHERE ((ur.user_id = auth.uid()) AND (ur.role_id = ANY (ARRAY['admin'::text, 'moderator'::text]))))));


