--

CREATE POLICY "Players can view alliance messages" ON public.chat_messages FOR SELECT USING (((channel_type = 'alliance'::text) AND (channel_id IN ( SELECT (players.alliance)::uuid AS alliance
   FROM public.players
  WHERE (players.id = auth.uid())))));


