--
-- Name: player_region_buildings Users can CRUD own player_region_buildings; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can CRUD own player_region_buildings" ON public.player_region_buildings TO authenticated USING ((EXISTS ( SELECT 1
   FROM (public.player_regions pr
     JOIN public.players p ON ((p.id = pr.player_id)))
  WHERE ((pr.id = player_region_buildings.player_region_id) AND (p.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM (public.player_regions pr
     JOIN public.players p ON ((p.id = pr.player_id)))
  WHERE ((pr.id = player_region_buildings.player_region_id) AND (p.user_id = auth.uid())))));


