  WHERE ((p.id = region_generals.player_id) AND (p.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.players p
  WHERE ((p.id = region_generals.player_id) AND (p.user_id = auth.uid())))));


--
-- Name: unit_training_queue Users can update own unit_training_queue; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can update own unit_training_queue" ON public.unit_training_queue FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM ((public.player_region_buildings prb
     JOIN public.player_regions pr ON ((pr.id = prb.player_region_id)))
     JOIN public.players p ON ((p.id = pr.player_id)))
  WHERE ((prb.id = unit_training_queue.player_region_building_id) AND (p.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM ((public.player_region_buildings prb
     JOIN public.player_regions pr ON ((pr.id = prb.player_region_id)))
     JOIN public.players p ON ((p.id = pr.player_id)))
  WHERE ((prb.id = unit_training_queue.player_region_building_id) AND (p.user_id = auth.uid())))));


